-- 先运行 bible_cuv_schema.sql 建表（已运行过可跳过），再按序号运行。
-- 可重复运行（冲突自动跳过）。本文件 5200 节。
-- ============================================================
-- 本文件为 bible_jpn_data_05.sql 的第 a 半（原文件超过 SQL Editor 体积上限，故拆分）。
-- 运行顺序：01a → 01b → 02a → 02b → … → 06b。可重复运行（冲突自动跳过）。
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '以西结书', 26, 16, 39, 'わたしはあなたを彼らの手に委ねる。彼らはあなたの祭儀台を壊し、高台を打ち壊し、あなたの着ている物をはぎ取り、あなたの美しい品々を奪い取り、あなたを丸裸にしておく。'),
('JPN', '以西结书', 26, 16, 40, '彼らは集団をあおってあなたを襲わせ、石であなたを打ち殺し、剣であなたを八つ裂きにする。'),
('JPN', '以西结书', 26, 16, 41, 'そのうえ、あなたの家々を火で焼き、多くの女たちの目の前であなたにさばきを下す。こうして、わたしはあなたの淫行をやめさせる。あなたはもう報酬を支払わなくなる。'),
('JPN', '以西结书', 26, 16, 42, 'わたしはあなたに対する憤りを収めるので、わたしのねたみはあなたから離れる。わたしは安んじて、二度と怒ることはない。'),
('JPN', '以西结书', 26, 16, 43, 'あなたが、自分の若かった日々を思い出さず、かえって、これらすべてのことでわたしを怒らせたので、見よ、わたしもまた、あなたの頭上にあなたの行いを返す──神である主のことば──。あなたはすべての忌み嫌うべきわざに、淫らな行いを加えなかったか。'),
('JPN', '以西结书', 26, 16, 44, '見よ。ことわざを用いる者は、あなたについてこういうことわざを用いる。「あの母にして、この娘あり」と。'),
('JPN', '以西结书', 26, 16, 45, 'あなたは、自分の夫と子どもを嫌った母の娘。自分たちの夫や子どもを嫌った姉妹があなたの姉妹。あなたがたの母はヒッタイト人、あなたがたの父はアモリ人であった。'),
('JPN', '以西结书', 26, 16, 46, 'あなたの姉は、その娘たちと一緒にあなたの北に住んでいるサマリアであり、あなたの妹は、その娘たちと一緒にあなたの南に住んでいるソドムである。'),
('JPN', '以西结书', 26, 16, 47, 'あなたは彼女たちの道に歩み、彼女たちのした忌み嫌うべきわざをまねなかっただろうか。ほんのわずかの間に、あなたはすべての道において彼女たちよりも堕落してしまった。'),
('JPN', '以西结书', 26, 16, 48, 'わたしは生きている──神である主のことば──。あなたの妹ソドムとその娘たちさえ、あなたと、あなたの娘たちがしたほどのことを決してしなかった。'),
('JPN', '以西结书', 26, 16, 49, 'だが、あなたの妹ソドムの咎はこのようだった。彼女とその娘たちは高慢で、飽食で、安逸を貪り、乏しい人や貧しい人に援助をしなかった。'),
('JPN', '以西结书', 26, 16, 50, '彼女たちは高ぶって、わたしの前で忌み嫌うべきことをしたので、わたしはこれを見たとき、彼女たちを取り除いた。'),
('JPN', '以西结书', 26, 16, 51, 'サマリアも、あなたの罪の半分ほども罪深くはなかった。あなたが彼女たち以上に多くの忌み嫌うべきことをしたので、あなたのしたすべての忌み嫌うべきことが、あなたの姉妹たちを正しいとした。'),
('JPN', '以西结书', 26, 16, 52, 'あなたも、あなたの姉妹たちをかばった恥辱を負え。あなたが彼女たちよりも忌み嫌うべきことをして、罪が重かったため、彼女たちはあなたよりも正しいとされた。あなたも恥じて、あなたの姉妹たちを正しいとした恥辱を負え。'),
('JPN', '以西结书', 26, 16, 53, 'わたしは彼女たちを元どおりにする。ソドムとその娘たち、サマリアとその娘たち、また彼女たちの中にいるあなたを元どおりにする。'),
('JPN', '以西结书', 26, 16, 54, 'こうして、あなたは自分自身の恥辱を負い、あなたが彼女たちを慰めたときにしたすべてのことによって、辱めを受ける。'),
('JPN', '以西结书', 26, 16, 55, 'あなたの姉妹たち、ソドムとその娘たちは元のところに帰り、サマリアとその娘たちも元のところに帰り、あなたとあなたの娘たちも元のところに帰って来る。'),
('JPN', '以西结书', 26, 16, 56, 'あなたは、高ぶっていたときには、あなたの妹ソドムを悪いうわさの種にしていたではないか。'),
('JPN', '以西结书', 26, 16, 57, 'しかしそれは、あなたの悪がさらけ出される前のことであって、今はアラムの娘たちや、その周りのすべての者、およびペリシテ人の娘たちのそしりの的となっている。彼女たちはあなたを四方から侮っている。'),
('JPN', '以西结书', 26, 16, 58, 'あなたは、自分の淫らな行いと忌み嫌うべきわざの報いを受けている──主のことば。'),
('JPN', '以西结书', 26, 16, 59, 'まことに、神である主はこう言われる。わたしは、あなたがしたとおりのことをあなたに返す。あなたは誓いを蔑んで、契約を破ったのだ。'),
('JPN', '以西结书', 26, 16, 60, 'だが、わたしは、あなたが若かった日々にあなたと結んだ契約を覚えて、あなたと永遠の契約を立てる。'),
('JPN', '以西结书', 26, 16, 61, 'わたしがあなたの姉と妹を選び取って、あなたとの契約には含まれていないものの、わたしが彼女たちをあなたの娘としてあなたに与えるとき、あなたは自分の生き方を思い出し、恥じることになる。'),
('JPN', '以西结书', 26, 16, 62, 'わたしがあなたとの契約を新たにするとき、あなたは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 16, 63, 'こうして、わたしが、あなたの行ったすべてのことについてあなたを赦すとき、あなたはそれらを思い出して恥を見、もう自分の恥辱のために口を開くことはない──神である主のことば。』」'),
('JPN', '以西结书', 26, 17, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 17, 2, '「人の子よ。イスラエルの家に謎をかけ、たとえを語れ。'),
('JPN', '以西结书', 26, 17, 3, '『神である主はこう言われる。大きな翼、長い羽、色とりどりの豊かな羽毛の大鷲が、レバノンに飛んで来て、杉のこずえを取り去り、'),
('JPN', '以西结书', 26, 17, 4, 'その若枝の先を摘み取り、それをカナンの地へ運び、商人の町に置いた。'),
('JPN', '以西结书', 26, 17, 5, 'また、その地の種も取って来て、肥えた土地に植え、豊かな水のそばに柳のように植えた。'),
('JPN', '以西结书', 26, 17, 6, 'それは生長し、丈は低いが、よく生い茂るぶどうの木となった。その枝は鷲の方に向き、根は鷲の下に張り、こうして、ぶどうの木となって、枝を作り、若枝を出した。'),
('JPN', '以西结书', 26, 17, 7, 'さて、大きな翼と豊かな羽毛を持つもう一羽の大鷲がいた。すると、このぶどうの木は、潤いを得るために根をその鷲の方に向けて伸ばし、その枝を、自分が植わっているところからその鷲の方に伸ばした。'),
('JPN', '以西结书', 26, 17, 8, 'このぶどうの木は、枝を伸ばし、実を結んで見事なぶどうの木となるように、水の豊かな良い地に植えられていた。』'),
('JPN', '以西结书', 26, 17, 9, '言え。『神である主はこう言われる。それはうまく育つであろうか。その根は抜き取られ、その実は摘み取られ、芽の付いた若枝はことごとく枯れないだろうか。それは枯れる。それを根こそぎ引き抜くのに、大きな力や多くの人々を必要としない。'),
('JPN', '以西结书', 26, 17, 10, '見よ。それは植えられたが、うまく育つだろうか。東風がそれに吹きつけると、すっかり枯れてしまわないだろうか。その芽を出した苗床で、それは枯れてしまう。』」'),
('JPN', '以西结书', 26, 17, 11, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 17, 12, '「さあ、反逆の家に言え。『これらがどういうことなのか、あなたがたは知らないのか。』こう言え。『見よ。バビロンの王がエルサレムに来て、そこの王とその首長たちを捕らえ、バビロンの自分のところへ連れて行った。'),
('JPN', '以西结书', 26, 17, 13, 'そして彼は王族の一人を選んで、その者と契約を結び、忠誠を誓わせた。彼はこの国のおもだった者たちも連れ去っていた。'),
('JPN', '以西结书', 26, 17, 14, 'それは、この王国を低くして立ち上がれないようにし、その契約を守らせて存続させるためであった。'),
('JPN', '以西结书', 26, 17, 15, 'ところが、彼はバビロンの王に反逆し、使者をエジプトに送り、馬と軍勢を得ようとした。そんなことをして、うまく行くだろうか。助かるだろうか。契約を破って助かるであろうか。'),
('JPN', '以西结书', 26, 17, 16, 'わたしは生きている──神である主のことば──。彼は、自分を王位に就けた王との誓いを自ら蔑み、また、自ら契約を破ったので、その王の住む場所、バビロンで必ず死ぬ。'),
('JPN', '以西结书', 26, 17, 17, '戦争になって、多くの者を絶ち滅ぼそうとして、塁が築かれ包囲壁が設けられるときでも、ファラオは決して大軍勢と大集団で彼をかばうことはない。'),
('JPN', '以西结书', 26, 17, 18, '彼は誓いを蔑み、契約を破った。彼は誓っていながら、これらすべてのことをしたのだ。彼は助からない。'),
('JPN', '以西结书', 26, 17, 19, 'それゆえ、神である主はこう言われる。わたしは生きている。彼が蔑んだわたしの誓い、彼が破ったわたしの契約、これを必ず彼の頭上に返す。'),
('JPN', '以西结书', 26, 17, 20, 'わたしは彼の上にわたしの網をかけ、彼はわたしの罠にかかる。わたしは彼をバビロンへ連れて行き、そこで、わたしの信頼を裏切ったことについて彼をさばく。'),
('JPN', '以西结书', 26, 17, 21, '彼の軍隊の逃れた者もみな剣に倒れ、残された者も四方に散らされる。このとき、あなたがたは、主であるわたしが語ったことを知る。』」'),
('JPN', '以西结书', 26, 17, 22, '神である主はこう言われる。「わたしは高い杉のこずえを取り去り、そのうちから柔らかい若枝の先を摘み取り、わたし自ら、それを高くそびえる山に植える。'),
('JPN', '以西结书', 26, 17, 23, 'わたしがそれをイスラエルの高い山に植えると、それは枝を伸ばし、実を結び、見事な杉の木となる。その下にはあらゆる種類の鳥が宿り、その枝の陰に住む。'),
('JPN', '以西结书', 26, 17, 24, 'このとき、野のすべての木は、主であるわたしが高い木を低くし、低い木を高くし、生木を枯らし、枯れ木に芽を出させることを知る。主であるわたしが語り、わたしが行う。」'),
('JPN', '以西结书', 26, 18, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 18, 2, '「あなたがたは、イスラエルの地について、『父が酸いぶどうを食べると、子どもの歯が浮く』という、このことわざを繰り返し言っているが、いったいどういうことか。'),
('JPN', '以西结书', 26, 18, 3, 'わたしは生きている──神である主のことば──。あなたがたがイスラエルでこのことわざを用いることは、もう決してない。'),
('JPN', '以西结书', 26, 18, 4, '見よ、すべてのたましいは、わたしのもの。父のたましいも子のたましいも、わたしのもの。罪を犯したたましいが死ぬ。'),
('JPN', '以西结书', 26, 18, 5, '人が正しい者であるなら、公正と義を行う。'),
('JPN', '以西结书', 26, 18, 6, '丘の上で食事をせず、イスラエルの家の偶像を仰ぎ見ず、隣人の妻を汚さず、月のさわりのある女に近寄らず、'),
('JPN', '以西结书', 26, 18, 7, 'だれも虐げず、質物を返し、物をかすめ取らず、飢えている者に自分の食物を与え、裸の者に衣服を着せ、'),
('JPN', '以西结书', 26, 18, 8, '利息をつけて貸さず、高利を取らず、不正から手を引き、人と人との間を正しくさばき、'),
('JPN', '以西结书', 26, 18, 9, 'わたしの掟に従って歩み、わたしの定めを守って真実を行う。このような人が正しい人であり、この人は必ず生きる──神である主のことば。'),
('JPN', '以西结书', 26, 18, 10, 'しかし、彼が子を生み、その子が無法者で、人の血を流し、先に述べたことの一つにでも違反する場合、'),
('JPN', '以西结书', 26, 18, 11, 'すなわち、それらすべてのことをしようともせず、かえって丘の上で食事をし、隣人の妻を汚し、'),
('JPN', '以西结书', 26, 18, 12, '乏しい人や貧しい人を虐げ、物をかすめ取り、質物を返さず、偶像を仰ぎ見、忌み嫌うべきことをし、'),
('JPN', '以西结书', 26, 18, 13, '利息をつけて貸し、高利を取ったなら、こういう者ははたして生きるだろうか。彼は生きられない。これらすべての忌み嫌うべきことをしたのだから、必ず死ぬ。その血の責任は彼自身にある。'),
('JPN', '以西结书', 26, 18, 14, 'ただし、彼が子を生み、その子が父の行ったすべての罪を見て反省し、そのようなことを行わない場合には、'),
('JPN', '以西结书', 26, 18, 15, 'すなわち、丘の上で食事をせず、イスラエルの家の偶像を仰ぎ見ず、隣人の妻を汚さず、'),
('JPN', '以西结书', 26, 18, 16, 'だれも虐げず、質物をとどめておかず、物をかすめ取らず、飢えている者に自分の食物を与え、裸の者に衣服を着せ、'),
('JPN', '以西结书', 26, 18, 17, '貧しい者を苦しめることから手を引き、利息や高利を取らず、わたしの定めを行い、わたしの掟に従って歩むなら、そのような人は自分の父の咎のゆえに死ぬことはなく、必ず生きる。'),
('JPN', '以西结书', 26, 18, 18, '彼の父は虐げを行い、兄弟の物をかすめ取り、良くないことを自分の民の中で行ったのだから、確かに自分の咎のゆえに死ぬ。'),
('JPN', '以西结书', 26, 18, 19, 'あなたがたは『なぜ、その子は父の咎を負わなくてよいのか』と言う。その子は、公正と義を行い、わたしのすべての掟を守り行ったのだから、必ず生きる。'),
('JPN', '以西结书', 26, 18, 20, '罪を犯したたましいが死ぬのであり、子は父の咎について負い目がなく、父も子の咎について負い目がない。正しい人の義はその人の上にあり、悪しき者の悪はその者の上にある。'),
('JPN', '以西结书', 26, 18, 21, 'しかし、悪しき者でも、自分が犯したすべての罪から立ち返り、わたしのすべての掟を守り、公正と義を行うなら、その人は必ず生きる。死ぬことはない。'),
('JPN', '以西结书', 26, 18, 22, '彼が行ったすべての背きは覚えられることがなく、彼が行った正しいことのゆえに、彼は生きる。'),
('JPN', '以西结书', 26, 18, 23, 'わたしは悪しき者の死を喜ぶだろうか──神である主のことば──。彼がその生き方から立ち返って生きることを喜ばないだろうか。'),
('JPN', '以西结书', 26, 18, 24, 'しかし、正しい人が正しい行いから離れ、不正を行い、悪しき者がするようなあらゆる忌み嫌うべきことをするなら、彼は生きるだろうか。彼が行ったどの正しいことも覚えられず、彼が犯した不信と陥った罪のゆえに、彼は死ななければならない。'),
('JPN', '以西结书', 26, 18, 25, 'あなたがたは『主の道は公正でない』と言っている。さあ聞け。イスラエルの家よ、わたしの道は公正でないのか。公正でないのはあなたがたの道ではないのか。'),
('JPN', '以西结书', 26, 18, 26, '正しい人が自分の正しい行いから離れ、不正を行うなら、彼はそれゆえに死ぬ。自分が行った不正によって死ぬ。'),
('JPN', '以西结书', 26, 18, 27, 'しかし、悪しき者でも、自分がしている悪事から立ち返り、公正と義を行うなら、彼は自分のたましいを生かす。'),
('JPN', '以西结书', 26, 18, 28, '彼は反省して、自分のすべての背きから立ち返ったのだから、必ず生き、死ぬことはない。'),
('JPN', '以西结书', 26, 18, 29, 'しかし、イスラエルの家は『主の道は公正でない』と言う。イスラエルの家よ、わたしの道は公正でないのか。公正でないのはあなたがたの道ではないのか。'),
('JPN', '以西结书', 26, 18, 30, 'それゆえ、イスラエルの家よ、わたしはあなたがたを、それぞれその生き方にしたがってさばく──神である主のことば──。立ち返り、あなたがたのすべての背きから身を翻せ。不義に引き込まれることがないようにせよ。'),
('JPN', '以西结书', 26, 18, 31, 'あなたがたが行ったすべての背きを、あなたがたの中から放り出せ。このようにして、新しい心と新しい霊を得よ。イスラエルの家よ、なぜ、あなたがたは死のうとするのか。'),
('JPN', '以西结书', 26, 18, 32, 'わたしは、だれが死ぬのも喜ばない──神である主のことば──。だから立ち返って、生きよ。」'),
('JPN', '以西结书', 26, 19, 1, '「あなたはイスラエルの君主たちのためにこの哀歌を唱えよ。'),
('JPN', '以西结书', 26, 19, 2, 'あなたの母は何であったのか。雌獅子だ。彼女は雄獅子の間に伏し、若い獅子の間で子獅子を養った。'),
('JPN', '以西结书', 26, 19, 3, '雌獅子は子獅子のうちの一頭を取り上げた。それは若い獅子となり、獲物をかみ裂くことを習い、人を食い滅ぼすようになった。'),
('JPN', '以西结书', 26, 19, 4, '諸国の民はその獅子のうわさを聞いた。その獅子は落とし穴で捕らえられた。彼らはこれに鉤をつけ、エジプトの地へ引いて行った。'),
('JPN', '以西结书', 26, 19, 5, '雌獅子は待ちくたびれて、自分の望みが消え失せたことを知ったとき、子獅子のうちのほかの一頭を取り、若い獅子と定めた。'),
('JPN', '以西结书', 26, 19, 6, 'これも雄獅子の間を歩き回り、若い獅子となって、獲物をかみ裂くことを習い、人を食い滅ぼすようになった。'),
('JPN', '以西结书', 26, 19, 7, 'この獅子は、やもめたちを犯し、町々を廃墟とした。その吼える声のために、地とそこに満ちているものは、おののいた。'),
('JPN', '以西结书', 26, 19, 8, 'そこで、諸国の民は周りの州から攻め上り、その獅子に彼らの網を打ちかけた。その獅子は彼らの落とし穴で捕らえられた。'),
('JPN', '以西结书', 26, 19, 9, '彼らはそれに鉤をかけて檻に入れ、バビロンの王のもとに引いて行った。彼らはそれを砦に閉じ込め、二度とその声がイスラエルの山々に聞こえないようにした。'),
('JPN', '以西结书', 26, 19, 10, 'あなたの母は、水のほとりに植えられた、あなたのぶどう園のぶどうの木のようだった。水が豊かなために実りが良く、枝も茂った。'),
('JPN', '以西结书', 26, 19, 11, 'その強い枝は王の杖となり、その背丈は茂みの中でひときわ高く、多くの小枝をつけて、際立って見えた。'),
('JPN', '以西结书', 26, 19, 12, 'しかし、激しい憤りをもってそれは引き抜かれ、地に投げ捨てられ、東風はその実を枯らした。その強い枝も折られて枯れ、火がそれを焼き尽くした。'),
('JPN', '以西结书', 26, 19, 13, '今や、それは荒野に、乾いた、潤いのない地に移し植えられ、'),
('JPN', '以西结书', 26, 19, 14, '火がその枝から出て、その若枝と実を焼き尽くした。もう、それには王の杖となる強い枝がなくなった。」これは悲しみの歌、哀歌となった。'),
('JPN', '以西结书', 26, 20, 1, '第七年の第五の月の十日、イスラエルの長老たちの何人かが、主に尋ねるために来て、私の前に座った。'),
('JPN', '以西结书', 26, 20, 2, 'そのとき、私に次のような主のことばがあった。'),
('JPN', '以西结书', 26, 20, 3, '「人の子よ、イスラエルの長老たちにこう告げよ。『神である主はこう言われる。あなたがたが来たのは、わたしに尋ねるためなのか。わたしは生きている。わたしは決してあなたがたの求めに応じない──神である主のことば。』'),
('JPN', '以西结书', 26, 20, 4, 'あなたは彼らをさばくのか。人の子よ、あなたはさばくのか。彼らの先祖たちの、忌み嫌うべきわざを彼らに告げ知らせよ。'),
('JPN', '以西结书', 26, 20, 5, '彼らに言え。『神である主はこう言われる。わたしがイスラエルを選んだとき、わたしはヤコブの家の子孫に誓い、エジプトの地でわたしを彼らに知らせた。彼らに誓って、わたしがあなたがたの神、主であると言った。'),
('JPN', '以西结书', 26, 20, 6, 'その日、わたしは彼らをエジプトの地から導き出して、わたしが彼らのために探しておいた乳と蜜の流れる地、どの地よりも麗しい地に入れることを彼らに誓った。'),
('JPN', '以西结书', 26, 20, 7, 'わたしは彼らに言った。「それぞれ、その目の慕う忌まわしいものを投げ捨てよ。エジプトの偶像で身を汚すな。わたしがあなたがたの神、主である」と。'),
('JPN', '以西结书', 26, 20, 8, 'しかし、彼らはわたしに逆らい、わたしに聞き従おうとはしなかった。それぞれ、その目の慕う忌まわしいものを投げ捨てず、エジプトの偶像を捨てなかった。そこでわたしは、エジプトの地のただ中でわたしの憤りを彼らの上に注ぎ、彼らにわたしの怒りを出し尽くそうと思った。'),
('JPN', '以西结书', 26, 20, 9, 'しかし、わたしはわたしの名のことを思い、彼らが住んでいる国々の目の前でわたしの名が汚されないようにした。国々の目の前で彼らをエジプトの地から導き出す、と知らせていたからだ。'),
('JPN', '以西结书', 26, 20, 10, 'こうしてわたしは、エジプトの地から彼らを導き出し、荒野に導き入れ、'),
('JPN', '以西结书', 26, 20, 11, 'わたしの掟を彼らに与え、わたしの定めを告げ知らせた。人は、それらを行うなら、それらによって生きるからである。'),
('JPN', '以西结书', 26, 20, 12, 'わたしはまた、彼らにわたしの安息日を与えて、わたしと彼らとの間のしるしとし、わたしが彼らを聖なる者とする主であることを、彼らが知るようにした。'),
('JPN', '以西结书', 26, 20, 13, 'しかし、イスラエルの家は荒野でわたしに逆らった。彼らはわたしの掟に従って歩まず、わたしの定めを忌み嫌った。人は、それらを行うなら、それらによって生きるのに。さらに、彼らはわたしの安息日を甚だしく汚した。そこでわたしは、荒野でわたしの憤りを彼らの上に注ぎ、彼らを絶ち滅ぼそうと考えた。'),
('JPN', '以西结书', 26, 20, 14, 'しかし、わたしはわたしの名のことを思い、彼らを導き出すのを見ていた国々の目の前で、わたしの名が汚されないようにした。'),
('JPN', '以西结书', 26, 20, 15, 'だがわたしは、わたしが与えた、乳と蜜の流れる地、どの地よりも麗しい地に、彼らを導き入れない、と荒野で彼らに誓った。'),
('JPN', '以西结书', 26, 20, 16, 'それは、彼らがわたしの定めを忌み嫌い、わたしの掟に歩まず、わたしの安息日を汚したからだ。それほど彼らの心は偶像を慕っていた。'),
('JPN', '以西结书', 26, 20, 17, 'それでも、わたしは彼らをあわれんで滅ぼさず、荒野で彼らを滅ぼし尽くさなかった。'),
('JPN', '以西结书', 26, 20, 18, 'わたしは荒野で彼らの子どもたちに言った。「あなたがたの父たちの掟に従って歩むな。彼らの慣わしを守るな。彼らの偶像で身を汚すな。'),
('JPN', '以西结书', 26, 20, 19, 'わたしがあなたがたの神、主である。わたしの掟に従って歩み、わたしの定めを守り行え。'),
('JPN', '以西结书', 26, 20, 20, 'また、わたしの安息日を聖なるものとせよ。これをわたしとあなたがたとの間のしるしとし、わたしがあなたがたの神、主であることを知れ」と。'),
('JPN', '以西结书', 26, 20, 21, 'しかし、子どもたちはわたしに逆らった。彼らはわたしの掟に従って歩まず、わたしの定めを忌み嫌った。人は、それらを行うなら、それらによって生きるのに。さらに、彼らはわたしの安息日を汚した。そこで、わたしは、荒野でわたしの憤りを彼らの上に注ぎ、彼らにわたしの怒りを出し尽くそうと思った。'),
('JPN', '以西结书', 26, 20, 22, 'しかし、わたしは手を引いた。わたしの名のことを思い、彼らを導き出すのを見ていた国々の目の前で、わたしの名が汚されないようにした。'),
('JPN', '以西结书', 26, 20, 23, 'だがわたしは、彼らを諸国の間に散らし、国々に追い散らす、と荒野で彼らに誓った。'),
('JPN', '以西结书', 26, 20, 24, '彼らがわたしの定めを行わず、わたしの掟を忌み嫌い、わたしの安息日を汚し、彼らの心が父たちの偶像を慕ったからである。'),
('JPN', '以西结书', 26, 20, 25, 'わたしもまた、良くない掟と、それによっては生きられない定めを彼らに与えた。'),
('JPN', '以西结书', 26, 20, 26, '彼らがすべての初子に火の中を通らせたとき、わたしはそのささげ物で彼らを汚した。それは、わたしが彼らを滅ぼすため、わたしが主であることを彼らが知るためである。』'),
('JPN', '以西结书', 26, 20, 27, 'それゆえ、人の子よ、イスラエルの家にこう告げよ。『神である主はこう言われる。あなたがたの先祖は次のことにおいても、わたしの信頼を裏切ることにより、わたしを冒瀆している。'),
('JPN', '以西结书', 26, 20, 28, 'わたしが、彼らに与えると誓った地に彼らを連れて行くと、彼らは高い丘や茂った木を見て、どこででもいけにえを献げた。彼らはそこで主の怒りを引き起こすささげ物を献げ、そこで芳ばしい香りを供え、そこで注ぎのぶどう酒を注いだ。'),
('JPN', '以西结书', 26, 20, 29, 'それで、わたしは彼らに言った。「あなたがたが通う高き所とは何なのか」と。今日でもその名はバマと呼ばれている。』'),
('JPN', '以西结书', 26, 20, 30, 'それゆえ、イスラエルの家に言え。『神である主はこう言われる。あなたがたは父たちの生き方をまねて自分自身を汚し、彼らの忌まわしいものを慕って姦淫を犯そうとするのか。'),
('JPN', '以西结书', 26, 20, 31, 'しかも、ささげ物を供え、幼子に火の中を通らせて、今日まであらゆる偶像で身を汚してきた。イスラエルの家よ。わたしはどうして、あなたがたの求めに応じられるだろうか。わたしは生きている──神である主のことば──。わたしは決してあなたがたの求めに応じない。'),
('JPN', '以西结书', 26, 20, 32, 'あなたがたが、「私たちは、木や石を拝んでいる異邦の民、国々の諸族のようになろう」と言っている、その霊の思いは決して実現しない。'),
('JPN', '以西结书', 26, 20, 33, 'わたしは生きている──神である主のことば──。わたしは必ず、力強い手と伸ばした腕、ほとばしる憤りをもって、あなたがたを治める。'),
('JPN', '以西结书', 26, 20, 34, 'わたしは、力強い手と伸ばした腕、ほとばしる憤りをもって、あなたがたを諸国の民の中から導き出し、その散らされている国々からあなたがたを集める。'),
('JPN', '以西结书', 26, 20, 35, 'わたしはあなたがたを国々の民の荒野に連れて行き、そこで顔と顔を合わせて、あなたがたをさばく。'),
('JPN', '以西结书', 26, 20, 36, 'わたしは、あなたがたの先祖をエジプトの地の荒野でさばいたように、あなたがたをさばく──神である主のことば──。'),
('JPN', '以西结书', 26, 20, 37, 'わたしはまた、あなたがたにむちの下を通らせ、あなたがたを契約のくびきの下に連れて行き、'),
('JPN', '以西结书', 26, 20, 38, 'あなたがたの中から、わたしに背く反逆者をより分ける。わたしは彼らをその寄留している地から導き出すが、彼らはイスラエルの地に入ることはできない。そのときあなたがたは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 20, 39, 'さあ、イスラエルの家よ、神である主はこう言われる。それぞれ自分の偶像のところに行って仕えるがよい。後には必ず、あなたがたはわたしに聞くようになる。あなたがたは二度と、自分たちのささげ物や偶像で、わたしの聖なる名を汚さなくなる。'),
('JPN', '以西结书', 26, 20, 40, 'わたしの聖なる山、イスラエルの高い山の上で──神である主のことば──そこで、この地にいるイスラエルの全家、そのすべてがわたしに仕えるからだ。そこで、わたしは彼らを喜んで受け入れ、そこで、あなたがたのすべての聖なるものとともに、あなたがたの奉納物と最上のささげ物を求める。'),
('JPN', '以西结书', 26, 20, 41, 'わたしが諸国の民の中からあなたがたを導き出し、その散らされている国々からあなたがたを集めるとき、わたしは、あなたがたを芳ばしい香りとともに喜んで受け入れる。こうしてわたしは、国々の民が見ている前で、あなたがたのうちに、わたしが聖であることを示す。'),
('JPN', '以西结书', 26, 20, 42, 'わたしが、あなたがたの父祖たちに与えると誓った地、イスラエルの地にあなたがたを導き入れるとき、あなたがたは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 20, 43, 'あなたがたはそこで、自分の身を汚した自分たちの生き方と、すべての行いを思い起こし、自分たちの行ったすべての悪のゆえに、自分自身を嫌うようになる。'),
('JPN', '以西结书', 26, 20, 44, 'わたしが、あなたがたの悪しき生き方や、腐敗した行いによってでなく、ただわたしの名のためにあなたがたに報いるとき、イスラエルの家よ、あなたがたはわたしが主であることを知る──神である主のことば。』」'),
('JPN', '以西结书', 26, 20, 45, 'さらに、私に次のような主のことばがあった。'),
('JPN', '以西结书', 26, 20, 46, '「人の子よ。顔を右の方に向け、南に向かって語りかけ、ネゲブの野の森に向かって預言し、'),
('JPN', '以西结书', 26, 20, 47, 'ネゲブの森に言え。『主のことばを聞け。神である主はこう言われる。見よ、わたしはおまえのうちに火をつける。その火はおまえのうちの、すべての生木とすべての枯れ木を焼き尽くす。その燃える炎は消されず、南から北まで地の面すべてが焼かれる。'),
('JPN', '以西结书', 26, 20, 48, 'そのとき、すべての肉なる者は、主であるわたしが燃やしたのを見る。その火は消えることがない。』」'),
('JPN', '以西结书', 26, 20, 49, 'そのとき、私は叫んだ。「ああ、神、主よ。彼らは私について、『彼は、たとえを言っているだけではないか』と言っています。」'),
('JPN', '以西结书', 26, 21, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 21, 2, '「人の子よ。エルサレムに顔を向け、聖所に向かって語りかけよ。イスラエルの地に向かって預言せよ。'),
('JPN', '以西结书', 26, 21, 3, 'イスラエルの地に言え。『主はこう言われる。今、わたしはおまえを敵とする。わたしは剣をさやから抜き、おまえのうちの、正しい者も悪い者も絶ち滅ぼす。'),
('JPN', '以西结书', 26, 21, 4, 'おまえのうちの、正しい者も悪い者も絶ち滅ぼすため、わたしの剣はさやを離れ、南から北まですべての肉なる者を敵とする。'),
('JPN', '以西结书', 26, 21, 5, 'このとき、すべての肉なる者は、主であるわたしが剣をさやから抜いたことを知る。剣は二度とさやに収められることはない。』'),
('JPN', '以西结书', 26, 21, 6, '人の子よ、あなたは、うめけ。彼らが見ているところで、腰が砕けるほど激しくうめけ。'),
('JPN', '以西结书', 26, 21, 7, '彼らがあなたに、『何のために、あなたはうめくのか』と言うなら、そのとき、あなたは言え。『この知らせのためだ。それが来ると、すべての者は心が萎え、すべての手は力無く垂れ下がり、みな意気消沈し、どの膝も震える。今、それが来る。それは実現する──神である主のことば。』」'),
('JPN', '以西结书', 26, 21, 8, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 21, 9, '「人の子よ、預言せよ。『主はこう言われる。剣、一振りの剣が研がれ、磨かれている。'),
('JPN', '以西结书', 26, 21, 10, '虐殺のために研がれ、稲妻のようにそれは磨かれた。それとも、われわれは喜ぶべきか。すべての木を退ける、わが子の杖を。'),
('JPN', '以西结书', 26, 21, 11, 'その剣は磨かれて手に握られ、研がれ、磨かれて殺す者の手に渡される。』'),
('JPN', '以西结书', 26, 21, 12, '人の子よ、わめけ。泣き叫べ。それがわたしの民の上に下り、イスラエルのすべての君主たちに下るからだ。彼らはわたしの民とともに剣に投げ込まれる。だから、あなたはももを打って嘆け。'),
('JPN', '以西结书', 26, 21, 13, '試みのとき、退ける杖さえなかったら、どうなるか──神である主のことば。'),
('JPN', '以西结书', 26, 21, 14, '人の子よ、あなたは預言せよ。手を打ち鳴らせ。剣を二倍、三倍にして、人を刺し殺す剣とし、彼らを貫く大いなる殺戮の剣とせよ。'),
('JPN', '以西结书', 26, 21, 15, 'それは、彼らの心が震えおののいて、つまずき倒れる者が増えるようにするためだ。わたしは彼らのすべての門に、殺戮の剣を置く。ああ、剣は稲妻のようにされ、屠るために磨かれる。'),
('JPN', '以西结书', 26, 21, 16, '剣は顔を右に向け、左に向けて切りまくれ。おまえの顔の向くところを。'),
('JPN', '以西结书', 26, 21, 17, 'わたしもまた、手を打ち鳴らし、わたしの憤りを収める。主であるわたしが語るのだ。」'),
('JPN', '以西结书', 26, 21, 18, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 21, 19, '「人の子よ。あなたは、バビロンの王の剣が来るように、二つの道を備えよ。その二つの道はともに一つの国から出るようにし、町に向かう道の始まりにそれぞれの道しるべを刻みつけよ。'),
('JPN', '以西结书', 26, 21, 20, '剣が、アンモン人のラバ、あるいはユダ、すなわち城壁のあるエルサレムに行くように、道を備えよ。'),
('JPN', '以西结书', 26, 21, 21, 'バビロンの王は道の分かれ目、その二つの道の始まりに立って占いをする。彼は矢を振り混ぜ、テラフィムに伺いを立てて、肝を調べる。'),
('JPN', '以西结书', 26, 21, 22, '彼の右の手に、エルサレムについての占いが現れる。それは、彼が城壁崩しを配置し、口を開いて叫び、ときの声をあげて、城壁崩しを門に向かわせ、塁を築き、包囲壁を設けるというものである。'),
('JPN', '以西结书', 26, 21, 23, 'しかしこれは、厳かな誓いをしているエルサレムの民の目には、むなしい占いと映る。だが、バビロンの王は彼らに自分たちの咎を思い起こさせることになり、こうして彼らは捕らえられる。'),
('JPN', '以西结书', 26, 21, 24, 'それゆえ、神である主はこう言われる。あなたがたの背きはあらわにされ、あなたがたのすべての行いに罪が現れて、あなたがたの咎がわたしに思い起こされる。あなたがた自身が思い起こされるゆえに、あなたがたは彼らの手に捕らえられるのだ。'),
('JPN', '以西结书', 26, 21, 25, '汚れた悪者、イスラエルの君主よ。あなたの日、最後の刑罰の時が来た。'),
('JPN', '以西结书', 26, 21, 26, '神である主はこう言われる。かぶり物を取り、冠を外せ。すべてがすっかり変わる。低い者を高くし、高い者を低くせよ。'),
('JPN', '以西结书', 26, 21, 27, '荒廃だ。荒廃だ。廃墟をわたしはもたらす。これは、さばきを執行する者が来て、わたしがさばきの権威を授けるまで、起こったことのないような出来事だ。'),
('JPN', '以西结书', 26, 21, 28, '人の子よ、あなたは預言せよ。こう言え。『神である主は、アンモン人と彼らのそしりについてこう言う。剣、一振りの剣が、虐殺のために抜き放たれた。絶ち滅ぼすために、稲妻のように研ぎ澄まされて。'),
('JPN', '以西结书', 26, 21, 29, 'おまえのためにむなしい幻があり、おまえのためにまやかしの占いがなされても、その剣は汚れた悪者どもの首に当てられ、彼らの日、最後の刑罰の時が来る。'),
('JPN', '以西结书', 26, 21, 30, '剣をさやに収めよ。おまえが創造された場所、おまえの出身地で、わたしはおまえをさばく。'),
('JPN', '以西结书', 26, 21, 31, 'わたしはおまえの上にわたしの憤りを注ぎ、激しい怒りの火を吹きつけ、滅ぼすことにたけた残忍な者たちの手に、おまえを渡す。'),
('JPN', '以西结书', 26, 21, 32, 'おまえは火の薪となり、おまえの血はその国の中で流され、おまえはもう思い出されることはない。主であるわたしが語ったからだ。』」'),
('JPN', '以西结书', 26, 22, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 22, 2, '「人の子よ、あなたはさばくのか。この流血の都をさばくのか。それなら、この都にその忌み嫌うべきわざを残らず告げ知らせて、'),
('JPN', '以西结书', 26, 22, 3, 'このように言え。『神である主はこう言われる。自らのただ中で血を流して自分の刑罰の時を招き、自らのために偶像を造って自分を汚す都よ。'),
('JPN', '以西结书', 26, 22, 4, 'おまえは自分が流した血で咎を負う者となり、自分が造った偶像で身を汚し、自分の日を近づかせ、自分の年を来させた。だから、わたしはおまえを国々のそしりの的とし、すべての国の笑いぐさとする。'),
('JPN', '以西结书', 26, 22, 5, 'おまえの近くにいる者も遠くにいる者も、名を汚されて大いに混乱したおまえをあざ笑う。'),
('JPN', '以西结书', 26, 22, 6, '見よ。イスラエルの君主たちは、おまえの中でそれぞれ力をふるい、人の血を流している。'),
('JPN', '以西结书', 26, 22, 7, 'おまえの中で父や母は軽んじられ、おまえのただ中で寄留者は抑圧され、おまえの中にいるみなしごややもめは虐げられている。'),
('JPN', '以西结书', 26, 22, 8, 'おまえはわたしの聖なるものを蔑み、わたしの安息日を汚した。'),
('JPN', '以西结书', 26, 22, 9, 'おまえの中には、血を流そうと他人を中傷する者がいて、ある者は丘の上で食事をし、おまえのただ中で淫らなことをした。'),
('JPN', '以西结书', 26, 22, 10, 'おまえの中では父の裸があらわにされ、おまえの中では月のさわりのある女が犯された。'),
('JPN', '以西结书', 26, 22, 11, 'ある者は隣人の妻と忌み嫌うべきことをし、またある者は淫らなことをして嫁を汚し、ある者はおまえの中で、自分の父の娘である自分の姉妹を辱めた。'),
('JPN', '以西结书', 26, 22, 12, 'おまえの中では、血を流すために賄賂が使われ、おまえは利息と高利を取り、隣人を抑圧して利得を貪った。おまえはわたしを忘れた──神である主のことば。'),
('JPN', '以西结书', 26, 22, 13, '見よ。おまえが得た不正な利得と、おまえの中で流された血のために、わたしは手を打ち鳴らす。'),
('JPN', '以西结书', 26, 22, 14, 'わたしがおまえをさばく日に、おまえの心は耐えられるだろうか。おまえの手は強くあり得るだろうか。主であるわたしが語り、事を行う。'),
('JPN', '以西结书', 26, 22, 15, 'わたしはおまえを諸国の間に散らし、国々に追い散らし、おまえの汚れをすっかり取り除く。'),
('JPN', '以西结书', 26, 22, 16, '国々の民が見ている前で、おまえはおまえ自身によって汚される。そのときおまえは、わたしが主であることを知る。』」'),
('JPN', '以西结书', 26, 22, 17, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 22, 18, '「人の子よ、イスラエルの家はわたしにとって金かすとなった。彼らはみな、炉の中の青銅、すず、鉄、鉛であり、銀の金かすとなった。」'),
('JPN', '以西结书', 26, 22, 19, 'それゆえ、神である主はこう言われる。「あなたがたはみな金かすとなったから、今、わたしはあなたがたをエルサレムの中に集める。'),
('JPN', '以西结书', 26, 22, 20, '銀、青銅、鉄、鉛、すずが炉の中に集められるのは、火を吹きつけて溶かすためだ。そのように、わたしは怒りと憤りをもってあなたがたを集め、そこに入れて溶かす。'),
('JPN', '以西结书', 26, 22, 21, 'わたしがあなたがたを集め、あなたがたに向かって激しい怒りの火を吹きつけると、あなたがたは町の中で溶ける。'),
('JPN', '以西结书', 26, 22, 22, '銀が炉の中で溶かされるように、あなたがたも町の中で溶かされる。このとき、あなたがたは、主であるわたしがあなたがたの上に憤りを注いだことを知る。」'),
('JPN', '以西结书', 26, 22, 23, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 22, 24, '「人の子よ、この都に言え。『おまえは憤りの日にきよめられず、雨も降らない地である。'),
('JPN', '以西结书', 26, 22, 25, 'そのただ中には預言者たちの陰謀がある。彼らは、獲物をかみ裂きながら吼えたける雄獅子のように人々を食らい、富と宝を奪い取り、その町にやもめの数を増やした。'),
('JPN', '以西结书', 26, 22, 26, 'その祭司たちはわたしのおしえを冒瀆し、わたしの聖なるものを冒し、聖なるものと俗なるものとを分けず、汚れたものと、きよいものとの違いを教えなかった。また、彼らはわたしの安息日をないがしろにした。こうして、わたしは彼らの間で汚されている。'),
('JPN', '以西结书', 26, 22, 27, 'その町の高官たちは、獲物をかみ裂く狼のようだ。人々の血を流し、たましいを滅ぼして、自分の利得を貪っている。'),
('JPN', '以西结书', 26, 22, 28, 'その町の預言者たちはむなしい幻を見、まやかしの占いをして、漆喰で上塗りをし、主が語っていないのに「神である主はこう言われる」と言っている。'),
('JPN', '以西结书', 26, 22, 29, '民衆も虐げを行い、物をかすめ、窮する人や貧しい人を苦しめ、寄留者を不法に虐げた。'),
('JPN', '以西结书', 26, 22, 30, 'この地を滅ぼすことがないように、わたしは、この地のために、わたしの前で石垣を築き、破れ口に立つ者を彼らの間に探し求めたが、見つからなかった。'),
('JPN', '以西结书', 26, 22, 31, 'それで、わたしは彼らの上に激しい憤りを注ぎ、激しい怒りの火で彼らを滅ぼし尽くし、彼らの頭上に彼らの生き方を返した──神である主のことば。』」'),
('JPN', '以西结书', 26, 23, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 23, 2, '「人の子よ、かつて二人の女がいた。同じ母の娘であった。'),
('JPN', '以西结书', 26, 23, 3, '彼女たちはエジプトで淫行をした。若いときに淫行をした。その地で彼女たちの胸は抱きしめられ、その処女の乳房はもてあそばれた。'),
('JPN', '以西结书', 26, 23, 4, 'その名は、姉はオホラ、妹はオホリバ。二人はわたしのものとなり、息子や娘たちを産んだ。彼女たちの名のオホラはサマリアのこと、オホリバはエルサレムのことである。'),
('JPN', '以西结书', 26, 23, 5, 'オホラは、わたしのものであったのに、姦通し、その愛人アッシリアに、青い衣を着た軍人たちに欲情を抱いた。'),
('JPN', '以西结书', 26, 23, 6, '彼らは総督や長官で、すべて若く魅惑的な男たちであり、馬に乗る騎兵であった。'),
('JPN', '以西结书', 26, 23, 7, 'オホラは彼らと姦通した。彼らはみなアッシリアの選り抜きの者であった。彼女は、自分が欲情を抱いた者たちのすべての偶像で身を汚した。'),
('JPN', '以西结书', 26, 23, 8, '彼女はエジプト以来の淫行をやめようとしなかった。それは、彼女が若いとき、エジプト人が彼女と寝て、その処女の乳房をもてあそび、彼女に情欲を注いだからである。'),
('JPN', '以西结书', 26, 23, 9, 'それでわたしは、彼女が欲情を抱く愛人たちの手、アッシリア人の手に彼女を渡した。'),
('JPN', '以西结书', 26, 23, 10, '彼らはオホラの裸をさらけ出し、その息子や娘たちを奪い取り、彼女を剣で殺してしまった。こうして彼女にさばきが下され、彼女は女たちの語りぐさとなった。'),
('JPN', '以西结书', 26, 23, 11, '妹のオホリバはこれを見たが、姉よりいっそう恋情を募らせ、その淫行は姉の淫行よりひどかった。'),
('JPN', '以西结书', 26, 23, 12, '彼女は隣のアッシリア人の総督や長官に欲情を抱いた。彼らはみな完全に武装した、馬に乗る騎兵であり、若く魅惑的な男たちであった。'),
('JPN', '以西结书', 26, 23, 13, 'わたしは彼女が身を汚すのを見たが、二人とも同じやり方であった。'),
('JPN', '以西结书', 26, 23, 14, 'オホリバは淫行を増し加え、壁に彫られた人々に目を留めた。すなわち、朱で描かれているカルデア人の肖像で、'),
('JPN', '以西结书', 26, 23, 15, '腰に帯を締め、頭には垂れるほどのターバンを着け、みな士官のように見えた。彼らは、出生地をカルデアとするバビロン人の姿をしていた。'),
('JPN', '以西结书', 26, 23, 16, '彼女は一目見て、彼らに欲情を抱き、使者たちをカルデアの彼らのもとに遣わした。'),
('JPN', '以西结书', 26, 23, 17, 'バビロン人は、彼女のもとに来て愛の床につき、彼女を情欲で汚した。彼女が彼らによって汚れるに及んで、彼女の心は彼らから離れ去った。'),
('JPN', '以西结书', 26, 23, 18, '彼女は自分の淫行をさらけ出し、自分の裸をあらわにした。そのためわたしの心は、かつて彼女の姉から離れ去ったように、彼女からも離れ去った。'),
('JPN', '以西结书', 26, 23, 19, 'しかし彼女は、かつてエジプトの地で淫行をした、あの若かった日々を思い出して、淫行を重ねた。'),
('JPN', '以西结书', 26, 23, 20, '彼女は、ろばのようなからだを持ち、馬のような精力を持つ彼らの側女になりたいと憧れた。'),
('JPN', '以西结书', 26, 23, 21, 'このように、エジプト人があなたの若い乳房をもてあそび、あなたの胸を抱きしめたあの若いときの淫らな行いを、あなたはしきりに望んだのだ。」'),
('JPN', '以西结书', 26, 23, 22, 'それゆえ、オホリバよ、神である主はこう言われる。「見よ。わたしは、あなたの心がすでに離れ去ったあなたの愛人たちを、あなたに対して駆り立てて、周りからあなたを攻めに来るようにする。'),
('JPN', '以西结书', 26, 23, 23, '彼らはバビロン人、すべてのカルデア人、ペコデやショアやコアの人々、それに加えてアッシリアのすべての人々である。すべての若く魅惑的な男たち、総督、長官、士官、名士たち、馬に乗る者たちである。'),
('JPN', '以西结书', 26, 23, 24, '彼らは、軍馬、戦車、車をもって、また民の大集団を率いてあなたに立ち向かい、大盾、盾、かぶとを着けて周りからあなたを攻める。わたしが彼らにさばきを委ねるので、彼らは自分たちのさばきにしたがって、あなたをさばく。'),
('JPN', '以西结书', 26, 23, 25, 'わたしがあなたに、わたしのねたみを向けるので、彼らは激しい憤りをもって、あなたに事を行う。彼らはあなたの鼻と耳を切り取り、残りの者は剣に倒れる。彼らはあなたの息子や娘たちを連れ去り、残りの者は火で焼き尽くされる。'),
('JPN', '以西结书', 26, 23, 26, '彼らはあなたの着ている物をはぎ取り、あなたの美しい品々を奪い取る。'),
('JPN', '以西结书', 26, 23, 27, 'わたしはあなたの淫らな行いと、エジプトの地以来の淫行をやめさせ、あなたが彼らを仰ぎ見ず、もうエジプトを思い出さないようにする。」'),
('JPN', '以西结书', 26, 23, 28, '神である主はこう言われる。「見よ。わたしは、あなたが憎む者の手、あなたの心が離れ去った者の手にあなたを渡す。'),
('JPN', '以西结书', 26, 23, 29, '彼らは憎しみをもってあなたを取り扱う。すなわち、あなたの労苦の実をことごとく奪い取り、あなたを丸裸のまま捨て去る。こうして、あなたの淫行と淫乱と姦淫の恥は暴かれる。'),
('JPN', '以西结书', 26, 23, 30, 'これらのことがなされるのは、あなたが異邦の民を慕って姦淫をし、彼らの偶像であなたの身を汚したからである。'),
('JPN', '以西结书', 26, 23, 31, 'あなたが姉の道を歩んだので、わたしは彼女の杯をあなたの手に渡す。」'),
('JPN', '以西结书', 26, 23, 32, '神である主はこう言われる。あなたは姉の杯、深くて大きい杯を飲む。物笑いと嘲りがたっぷり入った杯を。'),
('JPN', '以西结书', 26, 23, 33, 'あなたは酔いと悲しみに満たされる。恐怖と荒廃の杯、これがあなたの姉サマリアの杯。'),
('JPN', '以西结书', 26, 23, 34, 'あなたはこれを飲み、飲み干して、杯のかけらまでかみ、自分の乳房をかき裂く。わたしがこれを語ったからだ。──神である主のことば。'),
('JPN', '以西结书', 26, 23, 35, 'それゆえ、神である主はこう言われる。「あなたはわたしを忘れ、わたしをあなたのうしろに投げやったから、あなたも自分の淫らな行いと、淫行の責めを負え。」'),
('JPN', '以西结书', 26, 23, 36, '主は私に言われた。「人の子よ、あなたはオホラとオホリバをさばくのか。それなら彼女たちに、その忌み嫌うべきわざを告げ知らせよ。'),
('JPN', '以西结书', 26, 23, 37, '彼女たちは姦通し、その手は血に染まっている。彼女たちは自分たちの偶像と姦通し、わたしのために産んだ子どもさえも火の中を通らせ、食物として偶像に引き渡した。'),
('JPN', '以西结书', 26, 23, 38, 'しかも、彼女たちはわたしに対して、こんなことまでした。同じ日にわたしの聖所を汚し、わたしの安息日を汚したのだ。'),
('JPN', '以西结书', 26, 23, 39, '彼女たちは、自分たちの偶像のために自分の子どもを殺し、その同じ日にわたしの聖所に来て、これを冒した。なんと、このようなことをわたしの家の中で行ったのだ。'),
('JPN', '以西结书', 26, 23, 40, 'さらに、あなたがたは人を送って、遠くから来る人々を招いた。使者が送られて彼らが来ると、あなたは彼らのために身を洗い、目の縁を塗り、飾り物で身を飾り、'),
('JPN', '以西结书', 26, 23, 41, '豪奢な寝台に横たわり、その前に食卓を整えて、その上にわたしの香と油を置いた。'),
('JPN', '以西结书', 26, 23, 42, 'そこでは、安逸を貪る群衆の騒ぎがあった。大勢の男たちのところに、荒野から大酒飲みが連れ込まれ、彼らは、彼女たちの腕に腕輪をはめ、頭に輝かしい冠をかぶらせた。'),
('JPN', '以西结书', 26, 23, 43, 'わたしは、姦通で疲れきった彼女について考えた。彼らは今、その女と姦淫をしている。'),
('JPN', '以西结书', 26, 23, 44, '彼らは遊女のもとに行くように、彼女のもとに行った。彼らは、淫らな女たち、オホラとオホリバのもとに行ったのだ、と。'),
('JPN', '以西结书', 26, 23, 45, 'しかし、正しい人たちは、姦通した女に下す罰と殺人を犯した女に下す罰で彼女たちをさばく。彼女たちが姦通の者であり、その手が血に染まっているからだ。」'),
('JPN', '以西结书', 26, 23, 46, 'まことに、神である主はこう言われる。「一つの集団を彼らに向けて攻め上らせ、彼女たちを人々にとって、おののきのもと、また餌食とせよ。'),
('JPN', '以西结书', 26, 23, 47, '集団は彼女たちを石で打ち殺し、剣で切り倒し、その息子や娘たちを殺し、その家々を火で焼き払う。'),
('JPN', '以西结书', 26, 23, 48, 'わたしはこの地から淫らな行いを取り除く。すべての女たちは自分自身を戒め、あなたがたがしたような淫らな行いをしなくなる。'),
('JPN', '以西结书', 26, 23, 49, 'あなたがたの淫らな行いの報いはあなたがたの上に下り、あなたがたは自分たちの偶像に対する罪責を負わなければならない。このとき、あなたがたは、わたしが神、主であることを知る。」'),
('JPN', '以西结书', 26, 24, 1, '第九年の第十の月の十日、私に次のような主のことばがあった。'),
('JPN', '以西结书', 26, 24, 2, '「人の子よ。この日、ちょうどこの日の日付を書き記せ。ちょうどこの日に、バビロンの王がエルサレムに攻め寄せたからだ。'),
('JPN', '以西结书', 26, 24, 3, 'あなたは、反逆の家に一つのたとえを語って言え。『神である主はこう言われる。鍋を火にかけよ。これを据え、水をこれに注ぎ入れよ。'),
('JPN', '以西结书', 26, 24, 4, 'これに肉片、ももと肩の良い肉片をみな一緒に入れ、選り抜きの骨でこれを満たせ。'),
('JPN', '以西结书', 26, 24, 5, '選り抜きの羊を取れ。鍋の下には薪を積み、よく沸騰させて、その中の骨も煮よ。'),
('JPN', '以西结书', 26, 24, 6, 'それゆえ、神である主はこう言う。ああ、流血の都、さびついている鍋。そのさびは落とせない。一切れずつそれを取り出せ。くじで決めてはならない。'),
('JPN', '以西结书', 26, 24, 7, '彼女の血は、まだそこにある。彼女はそれを裸岩の上に流し、地面に流して、土をかぶせようとはしなかった。'),
('JPN', '以西结书', 26, 24, 8, 'わたしが、憤りを募らせ、復讐するために、その血を裸岩の上に流して、おおわれないようにしたのだ。'),
('JPN', '以西结书', 26, 24, 9, 'それゆえ、神である主はこう言う。ああ、流血の都。わたしもこれに薪を積み上げよう。'),
('JPN', '以西结书', 26, 24, 10, '薪を増やし、火を燃え立たせ、肉をよく煮、香料を混ぜ、骨を焦がせ。'),
('JPN', '以西结书', 26, 24, 11, '鍋を空にして炭火にかけ、その銅を熱くして、その中の汚れを溶かし、さびがなくなるようにせよ。'),
('JPN', '以西结书', 26, 24, 12, 'しかし、その骨折りは無駄であった。そのひどいさびはそれから落ちず、そのさびは、なお火の中にあった。'),
('JPN', '以西结书', 26, 24, 13, 'あなたの汚れは淫らな行いだ。それでわたしはあなたをきよめようとしたが、あなたはきよくなろうともしなかった。あなたは、わたしがあなたに対する憤りを収めるまで、自分の汚れから決してきよくならない。'),
('JPN', '以西结书', 26, 24, 14, '主であるわたしは言った。それは必ず起こる。わたしはそれを行ってなおざりにせず、惜しまず、思い直しもしない。あなたの生き方と行いにしたがって、あなたはさばかれる──神である主のことば。』」'),
('JPN', '以西结书', 26, 24, 15, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 24, 16, '「人の子よ、見よ、わたしは一打ちで、あなたの目の喜びを取り去る。嘆くな。泣くな。涙を流すな。'),
('JPN', '以西结书', 26, 24, 17, '死者のためにうめけ。しかし、喪に服してはならない。頭にターバンを巻き付け、足に履き物をはけ。口ひげをおおってはならない。人々からのパンを食べてはならない。」'),
('JPN', '以西结书', 26, 24, 18, 'その朝、私は民に語ったが、夕方、私の妻が死んだ。翌朝、私は命じられたとおりにした。'),
('JPN', '以西结书', 26, 24, 19, 'すると、民は私に尋ねた。「あなたがしているこれらのことは、私たちにとって何を意味するのか、説明してくれませんか。」'),
('JPN', '以西结书', 26, 24, 20, 'そこで私は彼らに答えた。次のような主のことばが私にあった、と。'),
('JPN', '以西结书', 26, 24, 21, '「イスラエルの家に言え。『神である主はこう言われる。見よ。あなたがたの力の誇りであり、あなたがたの目が喜び、あなたがたの心が大切にするわたしの聖所を、わたしは汚す。あなたがたが見捨てた息子や娘たちは、剣で倒れる。'),
('JPN', '以西结书', 26, 24, 22, 'あなたがたは、わたしがするとおりにすることになる。あなたがたは自分の口ひげをおおわず、人々からのパンを食べなくなる。'),
('JPN', '以西结书', 26, 24, 23, '頭にターバンを巻き、足に履き物をはき、嘆かず泣かない。ただ、自分たちの咎のゆえに朽ち果て、互いに嘆き合うようになる。'),
('JPN', '以西结书', 26, 24, 24, 'エゼキエルはあなたがたのためのしるしとなり、彼がしたとおりを、あなたがたもするようになる。このことが起こるとき、あなたがたは、わたしが神、主であることを知る。』'),
('JPN', '以西结书', 26, 24, 25, '人の子よ。彼らが力とするもの、栄えに満ちた喜び、目の喜ぶもの、心に慕うもの、彼らの息子や娘たちを、わたしが取り去る日、'),
('JPN', '以西结书', 26, 24, 26, 'その日、逃れた者が、この知らせを告げにあなたのもとにやって来る。'),
('JPN', '以西结书', 26, 24, 27, 'その日、あなたの口は逃れて来た者に開かれ、あなたは語る。もう黙っていてはならない。こうして、あなたが彼らのしるしとなるとき、彼らは、わたしが主であることを知る。」'),
('JPN', '以西结书', 26, 25, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 25, 2, '「人の子よ。アンモン人に顔を向け、彼らに預言せよ。'),
('JPN', '以西结书', 26, 25, 3, 'あなたはアンモン人に言え。『神である主のことばを聞け。神である主はこう言われる。わたしの聖所が冒されたとき、イスラエルの地が荒れ果てたとき、ユダの家が捕囚となって行ったとき、おまえは、あはは、と言って嘲った。'),
('JPN', '以西结书', 26, 25, 4, 'それゆえ、わたしはおまえを東の人々に渡して、彼らの所有とする。彼らはおまえのうちに宿営を張り、おまえのうちに住まいをつくり、おまえの産物を食べ、おまえの乳を飲むようになる。'),
('JPN', '以西结书', 26, 25, 5, 'わたしがラバをらくだの牧場とし、アンモン人の地を羊の檻とするとき、おまえたちは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 25, 6, 'まことに、神である主はこう言われる。おまえは手を打ち、足を踏み鳴らし、イスラエルの地を心の底から嘲り、喜んだ。'),
('JPN', '以西结书', 26, 25, 7, 'それゆえ、わたしはおまえに手を伸ばし、おまえを異邦の民に略奪の対象として与える。わたしは、おまえを諸国の民から断ち切り、国々の間から滅ぼし、根絶やしにする。そのときおまえは、わたしが主であることを知る。』」'),
('JPN', '以西结书', 26, 25, 8, '神である主はこう言われる。「モアブとセイルは『見よ、ユダの家は異邦の民と変わらない』と言った。'),
('JPN', '以西结书', 26, 25, 9, 'それゆえ、わたしはモアブの山地の町々、その国の誉れであるベテ・ハ・エシモテ、バアル・メオン、キルヤタイムの町々をことごとく開け放ち、'),
('JPN', '以西结书', 26, 25, 10, 'アンモン人と一緒に東の人々に渡してその所有とし、国々の間でアンモン人が記憶されないようにする。'),
('JPN', '以西结书', 26, 25, 11, 'わたしがモアブにさばきを下すとき、彼らは、わたしが主であることを知る。」'),
('JPN', '以西结书', 26, 25, 12, '神である主はこう言われる。「エドムはユダの家に復讐を企て、復讐を果たして、咎ある者となった。'),
('JPN', '以西结书', 26, 25, 13, 'それゆえ──神である主はこう言われる──わたしはエドムに手を伸ばし、そこから人も家畜も断って、そこを廃墟にする。テマンからデダンに至るまで人々は剣で倒れる。'),
('JPN', '以西结书', 26, 25, 14, 'わたしは、わたしの民イスラエルの手によってエドムに復讐する。わたしの怒りと憤りのままに彼らがエドムに事を行うとき、エドムはわたしが復讐するということを知る──神である主のことば。」'),
('JPN', '以西结书', 26, 25, 15, '神である主はこう言われる。「ペリシテ人は復讐を企て、心の底から嘲ってひどい復讐をし、いつまでも敵意をもって滅ぼそうとした。'),
('JPN', '以西结书', 26, 25, 16, 'それゆえ──神である主はこう言われる──見よ。わたしはペリシテ人に手を伸ばし、クレタ人を断ち切り、海辺の残った者を滅ぼす。'),
('JPN', '以西结书', 26, 25, 17, 'わたしは激しい憤りで彼らを懲らしめ、彼らに大いなる復讐をする。わたしが彼らに復讐するとき、彼らは、わたしが主であることを知る。」'),
('JPN', '以西结书', 26, 26, 1, '第十一年の、その月の一日、私に次のような主のことばがあった。'),
('JPN', '以西结书', 26, 26, 2, '「人の子よ。ツロはエルサレムについて、『あはは。国々の民の門は壊され、私に明け渡された。私は豊かになり、エルサレムは廃墟となった』と言った。'),
('JPN', '以西结书', 26, 26, 3, 'それゆえ──神である主はこう言われる──ツロよ、わたしはおまえを敵とする。海が波をうねらせるように、多くの国々をおまえに向けて攻め上らせる。'),
('JPN', '以西结书', 26, 26, 4, '彼らはツロの城壁を荒らし、そのやぐらを壊す。わたしはそのちりを払い去って、そこを裸岩にする。'),
('JPN', '以西结书', 26, 26, 5, 'ツロは海の中の網干し場となる。わたしが語ったからだ。──神である主のことば──ツロは諸国の餌食となり、'),
('JPN', '以西结书', 26, 26, 6, 'それに属する沿岸側の町々も剣で滅ぼされる。そのとき彼らは、わたしが主であることを知る。」'),
('JPN', '以西结书', 26, 26, 7, 'まことに、神である主はこう言われる。「見よ。わたしは、王の王、バビロンの王ネブカドネツァルを、馬、戦車、騎兵、そして大軍勢とともに、北からツロに連れて来る。'),
('JPN', '以西结书', 26, 26, 8, '彼はその沿岸側の町々を剣で滅ぼし、おまえに向かって塁を築き、城壁崩しを設け、大盾を立て、'),
('JPN', '以西结书', 26, 26, 9, '破城槌でおまえの城壁を突き崩し、やぐらを斧で打ち壊す。'),
('JPN', '以西结书', 26, 26, 10, '彼の馬の数があまりにも多いため、その土煙がおまえをおおう。打ち破られた町に入る者のように、彼がおまえの城門に入るとき、騎兵と車両と戦車の響きに、おまえの城壁は揺れ動く。'),
('JPN', '以西结书', 26, 26, 11, '彼は、馬のひづめでおまえの大通りをすべて踏みにじり、剣でおまえの民を殺し、おまえの巨大な石柱も地に倒れる。'),
('JPN', '以西结书', 26, 26, 12, '彼らはおまえの財宝を略奪し、商品をかすめ奪い、城壁を破壊し、住み心地のよい家を打ち壊し、石や木や土までも、水の中に投げ込む。'),
('JPN', '以西结书', 26, 26, 13, 'わたしはおまえの騒がしい歌をやめさせる。おまえの竪琴の音も、もう聞かれない。'),
('JPN', '以西结书', 26, 26, 14, 'わたしはおまえを裸岩とする。おまえは網干し場となり、二度と建て直されない。主であるわたしが語ったからだ。──神である主のことば。」'),
('JPN', '以西结书', 26, 26, 15, '神である主はツロにこう言われる。「刺された者がうめき、おまえの中で虐殺が行われるとき、おまえが崩れ落ちるその響きに、島々は揺れ動かないだろうか。'),
('JPN', '以西结书', 26, 26, 16, '海の君主たちはみな、その王座から降り、上着を脱ぎ捨て、あや織りの衣服を脱ぐ。彼らは戦慄を身にまとって地面に座り、おまえのことで絶えず身震いし、啞然とする。'),
('JPN', '以西结书', 26, 26, 17, '彼らはおまえについて哀歌を唱えて言う。海に住む者よ、おまえはどうして海から消え失せたのか。その町と住民は海で最も強く、ほめそやされた町であったのに。その町の住民すべてに、恐怖がもたらされた。'),
('JPN', '以西结书', 26, 26, 18, '今、島々はおまえが崩れ落ちる日に身震いし、海の島々はおまえの退却を見てうろたえる。」'),
('JPN', '以西结书', 26, 26, 19, 'まことに、神である主はこう言われる。「わたしがおまえを廃墟の町とし、住む者のない町々のようにするとき、大水をおまえの上に湧き上がらせ、豊かな水がおまえをおおうとき、'),
('JPN', '以西结书', 26, 26, 20, 'わたしはおまえを、穴に下った者たちとともに昔の民のもとに下らせ、穴に下った者たちとともに、昔から廃墟であったような地下の国に住まわせる。わたしが誉れを与える生ける者の地に、おまえが住めないようにするためだ。'),
('JPN', '以西结书', 26, 26, 21, 'わたしはおまえを恐怖のもととする。おまえはもう存在しなくなり、人がおまえを尋ねても、永久におまえを見つけることはない──神である主のことば。」'),
('JPN', '以西结书', 26, 27, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 27, 2, '「人の子よ、ツロについて哀歌を唱えよ。'),
('JPN', '以西结书', 26, 27, 3, 'あなたはツロに言え。『海の出入り口に住み、多くの島々の民と取り引きをする者よ、神である主はこう言われる。ツロよ、おまえは、「私は美の極みだ」と言った。'),
('JPN', '以西结书', 26, 27, 4, 'おまえの領土は海の真ん中にあり、おまえを築いた者は、おまえを最高に美しく仕上げた。'),
('JPN', '以西结书', 26, 27, 5, '彼らはセニルのもみの木でおまえのすべての船板を作り、レバノンの杉を使って、おまえの帆柱を作った。'),
('JPN', '以西结书', 26, 27, 6, 'バシャンの樫の木でおまえの櫂を作り、キティムの島々の檜に象牙をはめ込んで、おまえの甲板を作った。'),
('JPN', '以西结书', 26, 27, 7, 'エジプトのあや織りの亜麻布が、おまえの帆であり、おまえの旗じるしであった。エリシャの島々からの青色と紫色の布が、おまえの覆いであった。'),
('JPN', '以西结书', 26, 27, 8, 'シドンとアルワデの住民が、おまえの漕ぎ手であった。ツロよ、おまえのうちの熟練者が、おまえの船員であった。'),
('JPN', '以西结书', 26, 27, 9, 'ゲバルの長老と、その熟練者が、おまえのうちにあって破損を修理し、海のすべての船とその水夫たちが、おまえのうちにあっておまえに商品を持ち込んだ。'),
('JPN', '以西结书', 26, 27, 10, 'ペルシア、ルデ、プテの人々は、おまえの軍隊の戦士であり、おまえに盾とかぶとを掛け、彼らはおまえに輝きを添えた。'),
('JPN', '以西结书', 26, 27, 11, 'アルワデとヘレクの人々はおまえの周りの城壁の上に、またガマデ人はおまえのやぐらの中にいて、周りの城壁に丸い小盾を掛け、おまえを最高に美しく仕上げた。'),
('JPN', '以西结书', 26, 27, 12, 'タルシシュは、おまえがあらゆる財宝に富んでいたので、おまえと商いをし、銀、鉄、すず、鉛をおまえの商品と交換した。'),
('JPN', '以西结书', 26, 27, 13, 'ヤワン、トバル、メシェクはおまえと取り引きをし、人間と青銅の器具をおまえの商品と交換した。'),
('JPN', '以西结书', 26, 27, 14, 'ベテ・トガルマは馬、軍馬、らばをおまえの商品と交換した。'),
('JPN', '以西结书', 26, 27, 15, 'デダン人はおまえと取り引きをし、多くの島々はおまえの支配する市場であり、彼らは象牙と黒檀をおまえに貢ぎとして持って来た。'),
('JPN', '以西结书', 26, 27, 16, 'アラムは、おまえの事業が多岐にわたったので、おまえと商いをし、トルコ石、紫色の布、あや織物、白亜麻布、珊瑚、紅玉をおまえの商品と交換した。'),
('JPN', '以西结书', 26, 27, 17, 'ユダとイスラエルの地もおまえと取り引きをし、ミニテの小麦、きび、蜜、香油、乳香をおまえの商品と交換した。'),
('JPN', '以西结书', 26, 27, 18, 'おまえの事業が多岐にわたり、あらゆる財宝に富んでいたので、ダマスコも、ヘルボンのぶどう酒とツァハルの羊毛でおまえと商いをした。'),
('JPN', '以西结书', 26, 27, 19, 'ダンとヤワンもおまえの商品と交換した。その商品の中にはウザルからの銑鉄、桂枝、菖蒲があった。'),
('JPN', '以西结书', 26, 27, 20, 'デダンは鞍に敷く織り布でおまえと取り引きをした。'),
('JPN', '以西结书', 26, 27, 21, 'アラビア人、ケダルの君主たちもみな、おまえの御用商人であり、子羊、雄羊、やぎで商いをした。'),
('JPN', '以西结书', 26, 27, 22, 'シェバとラアマの商人たちはおまえと取り引きをし、あらゆる上等の香料、宝石、また金をおまえの商品と交換した。'),
('JPN', '以西结书', 26, 27, 23, 'ハラン、カンネ、エデン、それにシェバの商人たち、アッシュルとキルマデはおまえと取り引きをした。'),
('JPN', '以西结书', 26, 27, 24, 'おまえの市場で、彼らは豪華な衣服、青色の衣、あや織物、固く撚った綱でしっかり留められた多彩な敷き物をもって、おまえと取り引きをした。'),
('JPN', '以西结书', 26, 27, 25, 'タルシシュ船がおまえの商品を運んだ。おまえは大海のただ中で満ちあふれて、大いに栄えた。'),
('JPN', '以西结书', 26, 27, 26, 'おまえの漕ぎ手はおまえを大海原に連れ出したが、東風が大海のただ中でおまえを打ち破った。'),
('JPN', '以西结书', 26, 27, 27, 'おまえの財宝、貨物、商品、おまえの水夫、船員、修繕工、おまえの商品を商う者、おまえの中にいるすべての戦士、おまえの間にいる全集団も、おまえが崩れ落ちる日には大海のただ中に沈んでしまう。'),
('JPN', '以西结书', 26, 27, 28, 'おまえの船員の叫び声に海辺は身震いする。'),
('JPN', '以西结书', 26, 27, 29, '櫂を取る者、水夫、海の船員はみな、船から降りて陸に立ち、'),
('JPN', '以西结书', 26, 27, 30, 'おまえのために大声をあげて激しく泣き、頭にちりをかぶり、灰の中を転げ回る。'),
('JPN', '以西结书', 26, 27, 31, '彼らはおまえのために頭を剃り、粗布をまとい、おまえのために心を痛めて泣き、痛々しく嘆く。'),
('JPN', '以西结书', 26, 27, 32, '泣き声をあげて哀歌を歌い、おまえのために悲しんで歌う。だれがツロのように海の真ん中で滅ぼされただろうか。'),
('JPN', '以西结书', 26, 27, 33, '諸方の海から得たおまえの貨物が陸揚げされ、おまえは多くの国々の民を満ち足らせた。その豊かな財宝と商品で地の王たちを富ませた。'),
('JPN', '以西结书', 26, 27, 34, 'おまえが海で打ち破られ、おまえの商品とおまえの全集団が、おまえとともに海の深みに沈むとき、'),
('JPN', '以西结书', 26, 27, 35, '島々の住民はみな、おまえのことで啞然とし、その王たちはおぞ気立ち、慌てふためく。'),
('JPN', '以西结书', 26, 27, 36, '国々の民の商人たちはおまえを嘲り、おまえは恐怖のもととなり、とこしえに消え去る。』」'),
('JPN', '以西结书', 26, 28, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 28, 2, '「人の子よ、ツロの君主に言え。神である主はこう言われる。あなたの心は高ぶり、『私は神だ。海の真ん中で神の座に着いている』と言った。あなたは自分の心を神のように見なしたが、あなたは人であって、神ではない。'),
('JPN', '以西结书', 26, 28, 3, 'あなたはダニエルよりも知恵があり、どんな秘密もあなたに隠されていない。'),
('JPN', '以西结书', 26, 28, 4, 'あなたは自分の知恵と英知によって富を築き、金や銀を宝物倉に蓄えた。'),
('JPN', '以西结书', 26, 28, 5, '商いに多くの知恵を使って富を増し、あなたの心は富のゆえに高ぶった。'),
('JPN', '以西结书', 26, 28, 6, 'それゆえ、神である主はこう言う。あなたは自分の心を神の心のように見なした。'),
('JPN', '以西结书', 26, 28, 7, 'それゆえ、わたしは諸国の中で最も横暴な他国人を連れて来て、あなたを攻めさせる。あなたの知恵の麗しさに向かって彼らは剣を抜き、あなたのまばゆい輝きを汚し、'),
('JPN', '以西结书', 26, 28, 8, 'あなたを滅びの穴に投げ入れる。あなたは海のただ中で刺し殺された者の死を遂げる。'),
('JPN', '以西结书', 26, 28, 9, 'それでもあなたは、自分を殺す者の前で『私は神だ』と言うのか。あなたを刺し殺す者たちの手の中にあって、あなたは、人であり、神ではない。'),
('JPN', '以西结书', 26, 28, 10, 'あなたは他国人の手によって無割礼の者として死ぬ。わたしがこれを語ったからだ。──神である主のことば。」'),
('JPN', '以西结书', 26, 28, 11, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 28, 12, '「人の子よ。ツロの王について哀歌を唱えて、彼に言え。神である主はこう言われる。あなたは全きものの典型であった。知恵に満ち、美の極みであった。'),
('JPN', '以西结书', 26, 28, 13, 'あなたは神の園、エデンにいて、あらゆる宝石に取り囲まれていた。赤めのう、トパーズ、ダイヤモンド、緑柱石、縞めのう、碧玉、サファイア、トルコ石、エメラルド。あなたのタンバリンと笛は金で作られ、これらはあなたが創造された日に整えられた。'),
('JPN', '以西结书', 26, 28, 14, 'わたしは、油注がれた守護者ケルビムとしてあなたを任命した。あなたは神の聖なる山にいて、火の石の間を歩いていた。'),
('JPN', '以西结书', 26, 28, 15, 'あなたの行いは、あなたが創造された日から、あなたに不正が見出されるまでは、完全だった。'),
('JPN', '以西结书', 26, 28, 16, 'あなたの商いが繁盛すると、あなたのうちに暴虐が満ち、こうしてあなたは罪ある者となった。そこで、わたしはあなたを汚れたものとして神の山から追い出した。守護者ケルビムよ。わたしは火の石の間からあなたを消え失せさせた。'),
('JPN', '以西结书', 26, 28, 17, 'あなたの心は自分の美しさに高ぶり、まばゆい輝きのために自分の知恵を腐らせた。そこで、わたしはあなたを地に放り出し、王たちの前で見せ物とした。'),
('JPN', '以西结书', 26, 28, 18, 'あなたは不正な商いで不義を重ね、あなたの聖所を汚した。わたしはあなたのうちから火を出し、あなたを焼き尽くした。こうして、すべての者が見ている前で、わたしはあなたを地上の灰とした。'),
('JPN', '以西结书', 26, 28, 19, '国々の民のうちであなたを知る者はみな、あなたのことで啞然とした。あなたは恐怖をもたらすものとなり、とこしえに消え失せる。」'),
('JPN', '以西结书', 26, 28, 20, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 28, 21, '「人の子よ。シドンに顔を向け、それに預言せよ。'),
('JPN', '以西结书', 26, 28, 22, '神である主はこう言われる。シドンよ。わたしはおまえを敵とし、おまえのうちでわたしの栄光を現す。わたしがシドンにさばきを下し、わたしが聖であることをそこに示すとき、彼らは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 28, 23, 'わたしはそこに疫病を、その通りには流血を送り込む。四方から攻める剣のため、刺し殺された者がそのただ中に倒れる。そのとき彼らは、わたしが主であることを知る。」'),
('JPN', '以西结书', 26, 28, 24, '「イスラエルの家には、彼らを侮ったすべての周囲の者たちが突き刺す茨も、痛みを与えるとげも再び臨むことはない。そのとき彼らは、わたしが神、主であることを知る。」'),
('JPN', '以西结书', 26, 28, 25, '神である主はこう言われる。「わたしがイスラエルの家を、散らされていた諸国の民の中から集めるとき、わたしは国々の目の前で、わたしが聖であることを示す。彼らは、わたしがわたしのしもべヤコブに与えた土地に住む。'),
('JPN', '以西结书', 26, 28, 26, 'そこに安らかに住み、家々を建て、ぶどう畑を作る。彼らは安らかに住む。周囲から彼らを侮るすべての者にわたしがさばきを下すとき、彼らは、わたしが彼らの神、主であることを知る。」'),
('JPN', '以西结书', 26, 29, 1, '第十年の第十の月の十二日、私に次のような主のことばがあった。'),
('JPN', '以西结书', 26, 29, 2, '「人の子よ。エジプトの王ファラオに顔を向け、彼とエジプト全体に預言し、'),
('JPN', '以西结书', 26, 29, 3, 'こう告げよ。神である主はこう言われる。エジプトの王ファラオよ、わたしはあなたに敵対する。あなたは、自分の川の中に横たわる巨獣で、『川は私のもの。私がこれを造ったのだ』と言っている。'),
('JPN', '以西结书', 26, 29, 4, 'わたしはあなたのあごに鉤をかけ、あなたの川の魚をあなたの鱗につけ、あなたと、その鱗についたすべての川の魚を、川の中から引き上げる。'),
('JPN', '以西结书', 26, 29, 5, 'わたしは、あなたとあなたの川のすべての魚を荒野に投げ捨てる。あなたは野に倒れ、集められることも、一緒にされることもない。わたしがあなたを地の獣と空の鳥の餌食とするとき、'),
('JPN', '以西结书', 26, 29, 6, 'エジプトの住民はみな、わたしが主であることを知る。彼らがイスラエルの家にとって葦の杖にすぎなかったからだ。'),
('JPN', '以西结书', 26, 29, 7, '彼らがあなたの手をつかむと、あなたは折れて、彼らの肩をみな砕いた。彼らがあなたに寄りかかると、あなたはくずおれて、彼らの腰をみな痛めさせた。'),
('JPN', '以西结书', 26, 29, 8, 'それゆえ、神である主はこう言う。わたしは剣をあなたの上にもたらし、人も家畜も、あなたのうちから絶ち滅ぼす。'),
('JPN', '以西结书', 26, 29, 9, 'こうして、エジプトの地は荒れ果てて廃墟となる。そのとき彼らは、わたしが主であることを知る。エジプトは『川は私のもの。私がこれを造ったのだ』と言った。'),
('JPN', '以西结书', 26, 29, 10, 'それゆえ、わたしは、あなたとあなたの川を敵とし、エジプトの地を、ミグドルからセベネ、さらにクシュの国境に至るまで、すっかり干上がった廃墟にする。'),
('JPN', '以西结书', 26, 29, 11, '人の足もそこを通らず、家畜の足もそこを通らず、四十年の間だれも住むことがない。'),
('JPN', '以西结书', 26, 29, 12, 'わたしはエジプトの地を、荒れ果てた国々の間で荒れ果てさせ、その町々は四十年の間、廃墟の町々の間で荒れ果てる。わたしはエジプト人を諸国の間に散らし、国々に追いやる。」'),
('JPN', '以西结书', 26, 29, 13, 'まことに、神である主はこう言われる。「四十年の終わりになって、わたしはエジプト人を、散らされていた諸国の民の中から集め、'),
('JPN', '以西结书', 26, 29, 14, 'エジプトを回復させる。彼らをその出身地、パテロスの地に帰らせる。彼らはそこで、取るに足りない王国となる。'),
('JPN', '以西结书', 26, 29, 15, 'どの王国にも劣り、二度と諸国の上に自分を高くすることはない。彼らが諸国を支配しないように、わたしは彼らを小さくする。'),
('JPN', '以西结书', 26, 29, 16, 'イスラエルの家にとっては、もう頼みとはならなくなる。これに助けを求めたときの咎を思い起こさせることになる。このとき彼らは、わたしが神、主であることを知る。」'),
('JPN', '以西结书', 26, 29, 17, '第二十七年の第一の月の一日、私に次のような主のことばがあった。'),
('JPN', '以西结书', 26, 29, 18, '「人の子よ。バビロンの王ネブカドネツァルは、ツロに対して自分の軍隊を大いに働かせた。それで、皆の頭ははげ、皆の肩はすりむけた。だが、彼にも彼の軍隊にも、ツロからはその労役に対する報いがなかった。'),
('JPN', '以西结书', 26, 29, 19, 'それゆえ──神である主はこう言われる──わたしはバビロンの王ネブカドネツァルにエジプトの地を与える。彼はその富を取り上げ、物を分捕り、かすめ奪う。それが彼の軍隊への報いとなる。'),
('JPN', '以西结书', 26, 29, 20, '彼の働きへの報酬として、わたしは彼にエジプトの地を与える。彼らがわたしのためにこれを行ったからである──神である主のことば。'),
('JPN', '以西结书', 26, 29, 21, 'その日、わたしはイスラエルの家のために、一つの角を生えさせる。そして、彼らの間であなたに口を開かせる。そのとき彼らは、わたしが主であることを知る。」'),
('JPN', '以西结书', 26, 30, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 30, 2, '「人の子よ、預言せよ。神である主はこう言われる。泣き叫べ。『ああ、その日』と。'),
('JPN', '以西结书', 26, 30, 3, 'その日は近い。主の日は近い。その日は暗雲の日、諸国の終わりの時だ。'),
('JPN', '以西结书', 26, 30, 4, '剣はエジプトに下る。エジプトで刺された者が倒れ、その富が奪われ、その基が破壊されるとき、クシュに戦慄が走る。'),
('JPN', '以西结书', 26, 30, 5, 'クシュ、プテ、ルデ、あらゆる混血の民、クブ、そしてその同盟国の人々も、彼らとともに剣に倒れる。'),
('JPN', '以西结书', 26, 30, 6, '──主はこう言われる──エジプトを支える者は倒れ、その強い誇りは地に落ち、ミグドルからセベネに至るまでみな剣に倒れる──神である主のことば──。'),
('JPN', '以西结书', 26, 30, 7, 'エジプトは荒れ果てた国々の間で荒れ果て、その町々は廃墟の町々の間で荒れ果てる。'),
('JPN', '以西结书', 26, 30, 8, 'わたしがエジプトに火をつけ、これを助ける者たちがみな砕かれるとき、彼らは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 30, 9, 'その日、わたしのもとから使者たちが船で出て行き、安穏としているクシュ人を脅かす。エジプトの日に、彼らの間に戦慄が走る。今、その日が来ようとしている。」'),
('JPN', '以西结书', 26, 30, 10, '神である主はこう言われる。「わたしはバビロンの王ネブカドネツァルによって、エジプトの富を終わらせる。'),
('JPN', '以西结书', 26, 30, 11, '彼とその民、すなわち諸国の中で最も横暴な者たちが、その地を滅ぼすために動員される。彼らは剣を抜いてエジプトを攻め、刺し殺された者でその地を満たす。'),
('JPN', '以西结书', 26, 30, 12, 'わたしはナイル川を干上がらせ、その国を悪人どもの手に売り渡し、その国とそこにあるすべての物を他国人の手によって荒れ果てさせる。主であるわたしがこれを語る。」'),
('JPN', '以西结书', 26, 30, 13, '神である主はこう言われる。「わたしは偶像を滅ぼし、メンフィスから偽りの神々を取り除く。エジプトの地には、もう君主が立たなくなる。わたしはエジプトの地に恐れを臨ませる。'),
('JPN', '以西结书', 26, 30, 14, 'わたしはパテロスを荒らし、ツォアンに火をつけ、テーベにさばきを下す。'),
('JPN', '以西结书', 26, 30, 15, 'わたしはエジプトの砦シンにわたしの憤りを注ぎ、テーベの群衆を絶ち滅ぼす。'),
('JPN', '以西结书', 26, 30, 16, 'わたしはエジプトに火をつける。シンは苦しみに悶え、テーベは砕かれ、そしてメンフィスは白昼の敵に襲われる。'),
('JPN', '以西结书', 26, 30, 17, 'オンとピ・ベセテの若い男たちは剣に倒れ、その町々は捕らえられて行く。'),
('JPN', '以西结书', 26, 30, 18, 'わたしがエジプトのくびきを砕き、その強い誇りが絶たれるとき、タフパンヘスでは日は暗くなり、雲がそこをおおい、その娘たちは捕らえられて行く。'),
('JPN', '以西结书', 26, 30, 19, 'わたしがエジプトにさばきを下すとき、彼らは、わたしが主であることを知る。」'),
('JPN', '以西结书', 26, 30, 20, '第十一年の第一の月の七日、私に次のような主のことばがあった。'),
('JPN', '以西结书', 26, 30, 21, '「人の子よ、わたしはエジプトの王ファラオの片腕を砕いた。見よ。それは巻かれず、手当てをされず、包帯を当てて巻かれることなく、良くなって剣を取ることもできない。」'),
('JPN', '以西结书', 26, 30, 22, 'それゆえ、神である主はこう言われる。「わたしはエジプトの王ファラオに敵対し、丈夫な腕も砕かれた腕も、その両腕を砕く。そして、その手から剣を落とす。'),
('JPN', '以西结书', 26, 30, 23, 'わたしはエジプト人を諸国の間に散らし、国々に追いやる。'),
('JPN', '以西结书', 26, 30, 24, 'わたしはバビロンの王の腕を強くし、わたしの剣をその手に渡す。しかし、ファラオの腕は砕く。彼は刺された者がうめくように、バビロンの王の前でうめく。'),
('JPN', '以西结书', 26, 30, 25, 'わたしはバビロンの王の腕を強くし、ファラオの腕が垂れ下がるようにする。わたしがバビロンの王の手にわたしの剣を渡し、彼が手をエジプトの地に伸ばすとき、彼らは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 30, 26, 'わたしがエジプト人を諸国の間に散らし、国々に追いやるとき、彼らは、わたしが主であることを知る。」'),
('JPN', '以西结书', 26, 31, 1, '第十一年の第三の月の一日、私に次のような主のことばがあった。'),
('JPN', '以西结书', 26, 31, 2, '「人の子よ、エジプトの王ファラオと彼の大軍に言え。あなたの偉大さはだれに比べられるだろうか。'),
('JPN', '以西结书', 26, 31, 3, '見よ、アッシリア。それはレバノンの杉。美しい枝、濃い陰をつくる森、その丈は高く、そのこずえは雲の中。'),
('JPN', '以西结书', 26, 31, 4, '水がそれを育て、湧き出る水がこれを高くした。幾筋もの川が、それが植わっている周りに流れ、その流れは野のすべての木々に送られた。'),
('JPN', '以西结书', 26, 31, 5, 'その丈は野のどの木よりも高くなり、送られる豊かな水によって、小枝は茂り、大枝は伸びた。'),
('JPN', '以西结书', 26, 31, 6, '小枝には空のあらゆる鳥が巣を作り、大枝の下では野のあらゆる獣が子を産み、その木陰には多くの国々がみな住んだ。'),
('JPN', '以西结书', 26, 31, 7, 'それは大きくなり、枝も伸びて美しかった。豊かな水にその根を下ろしていたからだ。'),
('JPN', '以西结书', 26, 31, 8, '神の園の杉の木も、これとは比べ物にならない。もみの木も、この小枝とは比べられない。すずかけの木も、この若枝のようではなく、神の園にあるどの木も、その美しさにはかなわない。'),
('JPN', '以西结书', 26, 31, 9, 'わたしがその枝を茂らせ、美しく仕立てたので、神の園にあるエデンのすべての木々は、これを羨んだ。」'),
('JPN', '以西结书', 26, 31, 10, 'それゆえ、神である主はこう言われる。「それが高くそびえ、こずえを雲の中に伸ばし、その高さゆえにおごり高ぶったので、'),
('JPN', '以西结书', 26, 31, 11, 'わたしはこれを、諸国のうちの力ある者の手に渡した。その者はこれを厳しく罰し、わたしも、その悪行に応じてこれを追い出した。'),
('JPN', '以西结书', 26, 31, 12, 'こうして、諸国の中で最も横暴な他国人が、これを切り倒して投げ捨てた。山々に、またあらゆる谷間にその枝は落ち、大枝はこの地のすべての谷川で折られた。地のあらゆる民はその木陰から出て行き、これを見捨てた。'),
('JPN', '以西结书', 26, 31, 13, 'その倒された幹には空のあらゆる鳥が住み、その大枝のそばには野のあらゆる獣がいるようになる。'),
('JPN', '以西结书', 26, 31, 14, 'このことすべては、水のほとりのどんな木も、その丈を高くして、こずえを雲の中に伸ばさないようにするためであり、すべて、水に潤う木が高ぶってそびえないようにするためである。まことに、これらはみな、人の子らの間で、穴に下る者たちとともに、地下の国、死に渡された。」'),
('JPN', '以西结书', 26, 31, 15, '神である主はこう言われる。「彼がよみに下る日に、わたしは人を喪に服させた。彼のゆえに深淵をおおい、川をせき止め、豊かな水を干上がらせたのである。わたしが彼のゆえにレバノンを憂いに沈ませたので、野のすべての木も彼のゆえにしおれた。'),
('JPN', '以西结书', 26, 31, 16, 'わたしが彼を穴に下る者たちとともによみに下らせたとき、わたしはその落ちる音で諸国を震えさせた。すると、地下の国では、エデンのあらゆる木、レバノンの選り抜きの良い木、水に潤うすべての木が慰められた。'),
('JPN', '以西结书', 26, 31, 17, '彼とともに、それらもよみに下った。剣で刺し殺された者、そして諸国の間にあって彼の陰に住み、彼の腕となった者たちがいるところである。'),
('JPN', '以西结书', 26, 31, 18, 'あなたは栄えと偉大さにおいて、エデンの木々のどれに最も似ているだろうか。あなたはエデンの木々とともに、地下の国に落とされる。剣で刺し殺された者とともに、無割礼の者たちの間に横たわるようになる。これは、ファラオとそのすべての大軍のことである──神である主のことば。」'),
('JPN', '以西结书', 26, 32, 1, '第十二年の第十二の月の一日、私に次のような主のことばがあった。'),
('JPN', '以西结书', 26, 32, 2, '「人の子よ。エジプトの王ファラオについて哀歌を唱えて彼に言え。『あなたは自分を国々の若獅子だと思っている。しかし、あなたは大海の巨獣のようだ。川の中で暴れ回り、足で水をかき混ぜ、その豊かな流れを濁らせる。'),
('JPN', '以西结书', 26, 32, 3, '──神である主はこう言われる──わたしは、多くの民族の群れを集め、あなたの上にわたしの網を広げる。彼らはあなたを地引き網で引き上げる。'),
('JPN', '以西结书', 26, 32, 4, 'わたしはあなたを地に投げ捨て、野に放り出す。空のあらゆる鳥をあなたの上に舞い降りさせ、全地の獣をあなたで満腹させる。'),
('JPN', '以西结书', 26, 32, 5, 'あなたの肉を山々にまき散らし、あなたの屍で谷を満たし、'),
('JPN', '以西结书', 26, 32, 6, 'その地を、あなたからあふれ流れる血で、山々に至るまで潤す。谷川もあなたの血で満たされる。'),
('JPN', '以西结书', 26, 32, 7, 'あなたが吹き消されるとき、わたしは空をおおい、星を暗くする。太陽を雲でおおい、月が光を放たないようにする。'),
('JPN', '以西结书', 26, 32, 8, 'わたしは空に輝くすべての光をあなたの上で暗くし、あなたの地を闇でおおう。──神である主のことば──'),
('JPN', '以西结书', 26, 32, 9, 'わたしが諸国の間で、あなたの知らない国々にあなたの破滅の知らせをもたらすとき、わたしは多くの国々の民の心を苛立たせる。'),
('JPN', '以西结书', 26, 32, 10, 'わたしは多くの国々の民をあなたのことで茫然とさせる。彼らの王たちも、わたしが彼らの前でわたしの剣を振りかざすとき、あなたのことでおぞ気立つ。あなたが崩れ落ちる日に、彼らはみな自分のいのちを思い、その震えは止まらない。'),
('JPN', '以西结书', 26, 32, 11, 'まことに、神である主はこう言う。バビロンの王の剣があなたに下る。'),
('JPN', '以西结书', 26, 32, 12, 'わたしは、勇士の剣であなたの大軍を倒す。彼らはみな最も横暴な異邦の民だ。彼らはエジプトの誇りを踏みにじり、その大軍はみな滅ぼし尽くされる。'),
('JPN', '以西结书', 26, 32, 13, 'わたしはあらゆる家畜を、豊かな水のほとりから消し去る。人の足は二度とこれを濁さず、家畜のひづめもこれを濁さない。'),
('JPN', '以西结书', 26, 32, 14, 'そのとき、わたしはこの水を澄ませ、その川を油のように流れさせる。──神である主のことば──'),
('JPN', '以西结书', 26, 32, 15, 'わたしがエジプトの地に荒廃をもたらし、わたしがそこの全住民を打ち、その地がそこに満ちるすべてを失って荒れ果てるとき、彼らは、わたしが主であることを知る。』'),
('JPN', '以西结书', 26, 32, 16, 'これは、人々が悲しんで歌う哀歌である。国々の娘たちはこれを悲しんで歌う。エジプトとその大軍すべてのために、彼女たちはこの哀歌を悲しんで歌う──神である主のことば。」'),
('JPN', '以西结书', 26, 32, 17, '第十二年の、その月の十五日、私に次のような主のことばがあった。'),
('JPN', '以西结书', 26, 32, 18, '「人の子よ、エジプトの大軍のために嘆け。その民と力強い国々の娘たちを、穴に下る者たちとともに地下の国に下らせよ。'),
('JPN', '以西结书', 26, 32, 19, '『あなたは麗しさの点でだれよりもまさっているというのか。下って行って、無割礼の者たちとともに横たわれ。』'),
('JPN', '以西结书', 26, 32, 20, '彼らは、剣で刺し殺された者たちの間に倒れる。その国は剣に渡された。その国とその大軍すべてを引きずり降ろせ。'),
('JPN', '以西结书', 26, 32, 21, '勇敢な勇士たちは、国を助けた者たちとともに、よみの中から彼について語る。『彼らは下って来て、剣で刺し殺された者、無割礼の者たちとともに横たわった』と。'),
('JPN', '以西结书', 26, 32, 22, 'そこにはアッシリアとその全集団がいる。周りには彼らの墓があり、みな、刺し殺された者、剣に倒れた者である。'),
('JPN', '以西结书', 26, 32, 23, 'アッシリアの墓は穴の奥の方にあり、その集団はその墓の周りにいる。彼らはみな、刺し殺された者、剣に倒れた者で、生ける者の地に恐怖をもたらした者たちである。'),
('JPN', '以西结书', 26, 32, 24, 'エラムとその大軍がその墓の周りにいる。彼らはみな、刺し殺された者、剣に倒れた者で、無割礼のまま地下の国に下った者、生ける者の地に恐怖をもたらした者たちで、穴に下る者とともに自らの恥辱を負っている。'),
('JPN', '以西结书', 26, 32, 25, 'その寝床は刺し殺された者たちの間に置かれ、その大軍すべてもその墓の周りにいる。みな、無割礼の者、剣で刺し殺された者である。彼らの恐怖が、生ける者の地にあり、穴に下る者とともに自らの恥辱を負っている。彼らは刺し殺された者たちの間に置かれる。'),
('JPN', '以西结书', 26, 32, 26, 'そこにはメシェクとトバルがおり、その大軍のすべてもその墓の周りにいる。みな、無割礼の者、剣で刺し殺された者で、生ける者の地に恐怖をもたらしたからである。'),
('JPN', '以西结书', 26, 32, 27, '無割礼の者として倒れた勇士たちとともに彼らは横たわることはできない。勇士たちは武具を持ってよみに下り、剣は頭の下に置かれている。咎が彼らの骨の上にある。勇士たちのもたらした恐怖が、生ける者の地にあったからである。'),
('JPN', '以西结书', 26, 32, 28, 'しかしあなたは、無割礼の者たちの間で砕かれ、剣で刺し殺された者たちとともに横たわる。'),
('JPN', '以西结书', 26, 32, 29, 'そこにはエドムとその王たち、そのすべての族長たちがいる。彼らは、その勇敢さにもかかわらず、剣で刺し殺された者たちとともに、無割礼の者たち、および穴に下る者たちとともに横たわる。'),
('JPN', '以西结书', 26, 32, 30, 'そこには北のすべての君主たち、すべてのシドン人がいる。彼らの勇敢さは恐怖をもたらしたが、恥を見、刺し殺された者たちとともに下ったのである。それで無割礼の彼らは、剣で刺し殺された者たちとともに横たわり、穴に下る者たちとともに自分たちの恥辱を負っている。'),
('JPN', '以西结书', 26, 32, 31, 'ファラオは彼らを見て、剣で刺し殺された自分の大軍、ファラオとその全軍勢のことで慰められる──神である主のことば──。'),
('JPN', '以西结书', 26, 32, 32, 'わたしが生ける者の地に恐怖をもたらしたので、ファラオとその大軍は、無割礼の者たちの間で、剣で刺し殺された者たちとともに横たわる──神である主のことば。」'),
('JPN', '以西结书', 26, 33, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 33, 2, '「人の子よ、あなたの民の者たちにこう告げよ。『わたしがある地に剣をもたらすとき、その国の民は自分たちの中から一人を取り、自分たちの見張りとする。'),
('JPN', '以西结书', 26, 33, 3, 'さて、その人が、剣がその地に来るのを見て角笛を吹き鳴らし、民に警告を与えた場合、'),
('JPN', '以西结书', 26, 33, 4, '角笛の音を聞いた者が警告を聞き入れないなら、剣が来てその者を討ち取るときに、その血の責任はその者の頭上にある。'),
('JPN', '以西结书', 26, 33, 5, '角笛の音を聞きながら警告を聞き入れなければ、その血の責任は彼自身にある。しかし、警告を聞き入れていれば、その者は自分のいのちを救う。'),
('JPN', '以西结书', 26, 33, 6, 'しかし、見張りが、剣の来るのを見ながら角笛を吹き鳴らさず、そのため民が警告されず、剣が来て彼らの中の一人を討ち取った場合、その者は自分の咎のゆえに討ち取られるが、わたしはその血の責任を見張りに問う。』'),
('JPN', '以西结书', 26, 33, 7, '人の子よ、わたしはあなたをイスラエルの家の見張りとした。あなたは、わたしの口からことばを聞くとき、わたしに代わって彼らに警告を与えよ。'),
('JPN', '以西结书', 26, 33, 8, 'わたしが悪しき者に『悪しき者よ、あなたは必ず死ぬ』と言うとき、もし、あなたがその悪しき者に、その道から離れるように警告しないなら、その悪しき者は自分の咎のゆえに死ぬ。そして、わたしは彼の血の責任をあなたに問う。'),
('JPN', '以西结书', 26, 33, 9, 'あなたが、悪しき者にその道から立ち返るよう警告しても、彼がその道から立ち返らないなら、彼は自分の咎のゆえに死ななければならない。しかし、あなたは自分のいのちを救うことになる。'),
('JPN', '以西结书', 26, 33, 10, '人の子よ、あなたはイスラエルの家に言え。『あなたがたは「私たちの背きと罪は私たちの上にのしかかり、そのため私たちは朽ち果てた。私たちはどうして生きられよう」と言っている。』'),
('JPN', '以西结书', 26, 33, 11, '彼らにこう言え。『わたしは生きている──神である主のことば──。わたしは決して悪しき者の死を喜ばない。悪しき者がその道から立ち返り、生きることを喜ぶ。立ち返れ。悪の道から立ち返れ。イスラエルの家よ、なぜ、あなたがたは死のうとするのか。』'),
('JPN', '以西结书', 26, 33, 12, '人の子よ、あなたは自分の民の者たちにこう言え。『正しい人の正しさも、その人が背いたときには、それが彼を救うことはない。悪しき者も、その者がその悪から立ち返るときには、その悪につまずき倒れることはない。正しい人でも、罪ある者となるとき、自分の正しさによって生きることはできない。'),
('JPN', '以西结书', 26, 33, 13, 'わたしが正しい人に「あなたは必ず生きる」と言っても、もし彼が自分の正しさに拠り頼み、不正を行うなら、彼の正しい行いは何一つ覚えられず、自分の行った不正によって死ななければならない。'),
('JPN', '以西结书', 26, 33, 14, 'わたしが悪しき者に「あなたは必ず死ぬ」と言っても、もし彼が自分の罪から立ち返り、公正と義を行い、'),
('JPN', '以西结书', 26, 33, 15, 'その悪しき者が質物を返し、かすめた物を償い、不正を行わず、いのちの掟に従って歩むなら、彼は必ず生き、死ぬことはない。'),
('JPN', '以西结书', 26, 33, 16, '彼が犯した罪は何一つ覚えられず、公正と義を行った彼は必ず生きる。』'),
('JPN', '以西结书', 26, 33, 17, 'あなたの民の者たちは『主の道は公正でない』と言っている。しかし、彼らの道こそ公正ではない。'),
('JPN', '以西结书', 26, 33, 18, '正しい人でも、自分の正しい行いから離れ、不正を行うなら、彼はそのことのゆえに死ぬ。'),
('JPN', '以西结书', 26, 33, 19, '悪しき者でも、自分の悪から離れ、公正と義を行うなら、そのことのゆえに彼は生きる。'),
('JPN', '以西结书', 26, 33, 20, 'それでも、あなたがたは『主の道は公正でない』と言う。イスラエルの家よ。わたしはあなたがたを、それぞれの生き方にしたがってさばく。」'),
('JPN', '以西结书', 26, 33, 21, '私たちが捕囚となって十二年目の第十の月の五日、エルサレムから逃れた者が私のもとに来て、「都は占領された」と言った。'),
('JPN', '以西结书', 26, 33, 22, 'その逃れた者が来る前の夕方に、主の御手が私の上にあり、朝になって彼が私のもとに来る前に、私の口は開かれた。こうして私の口は開かれて、もはや私は黙っていなかった。'),
('JPN', '以西结书', 26, 33, 23, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 33, 24, '「人の子よ。イスラエルの地の廃墟に住むこれらの者たちは、『アブラハムは一人でこの地を所有した。私たちは多い。当然、この地はわれわれの所有地として与えられている』と言っている。'),
('JPN', '以西结书', 26, 33, 25, 'それゆえ、彼らに言え。『神である主はこう言われる。あなたがたは血がついたままで食べ、自分たちの偶像を仰ぎ見、人の血を流しているのに、この地を所有しようとするのか。'),
('JPN', '以西结书', 26, 33, 26, 'あなたがたは自分の剣に拠り頼み、忌み嫌うべきことをし、それぞれ隣人の妻を汚しながら、この地を所有しようとするのか。』'),
('JPN', '以西结书', 26, 33, 27, 'あなたは彼らにこう言え。『神である主はこう言われる。わたしは生きている。あの廃墟にいる者は必ず剣に倒れる。野にいる者も、わたしは獣に与えて、その餌食とする。要害と洞穴にいる者は疫病で死ぬ。'),
('JPN', '以西结书', 26, 33, 28, 'わたしはその地を荒れ果てさせ、荒廃した地とする。その力強い誇りは失せ、イスラエルの山々は荒れ果て、だれもそこを通らなくなる。'),
('JPN', '以西结书', 26, 33, 29, 'わたしが、彼らの行ったすべての忌み嫌うべきわざのために、その地を荒れ果てさせて荒廃した地とするとき、彼らは、わたしが主であることを知る。』'),
('JPN', '以西结书', 26, 33, 30, '人の子よ。あなたの民の者たちは城壁のそばや家々の戸口で、あなたについてこう語り合っている。『さあ、どんなことばが主から出るか聞きに行こう。』'),
('JPN', '以西结书', 26, 33, 31, '彼らは群れをなしてあなたのもとにやって来る。そして、わたしの民はあなたの前に座り、あなたのことばを聞く。しかし、それを実行しようとはしない。彼らは口で甘いことばを語り、心で利得を追っている。'),
('JPN', '以西结书', 26, 33, 32, 'あなたは彼らにとっては、音楽に合わせて美しく歌う恋の歌のようだ。彼らはあなたのことばを聞くが、それを実行しようとはしない。'),
('JPN', '以西结书', 26, 33, 33, 'しかし、あのことは起こり、もう来ている。彼らは、自分たちの間に一人の預言者がいたことを知る。」'),
('JPN', '以西结书', 26, 34, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 34, 2, '「人の子よ、イスラエルの牧者たちに向かって預言せよ。預言して、牧者である彼らに言え。『神である主はこう言われる。わざわいだ。自分を養っているイスラエルの牧者たち。牧者が養わなければならないのは羊ではないか。'),
('JPN', '以西结书', 26, 34, 3, 'あなたがたは脂肪を食べ、羊の毛を身にまとい、肥えた羊を屠るが、羊は養わない。'),
('JPN', '以西结书', 26, 34, 4, '弱った羊を強めず、病気のものを癒やさず、傷ついたものを介抱せず、追いやられたものを連れ戻さず、失われたものを捜さず、かえって力ずくで、しかも過酷な仕方で彼らを支配した。'),
('JPN', '以西结书', 26, 34, 5, '彼らは牧者がいないので散らされ、あらゆる野の獣の餌食となった。こうして彼らは散らされた。'),
('JPN', '以西结书', 26, 34, 6, 'わたしの羊はすべての山々、すべての高い丘をさまよった。わたしの羊は地の全面に散らされ、尋ね求める者もなく、捜す者もない。'),
('JPN', '以西结书', 26, 34, 7, 'それゆえ、牧者たちよ、主のことばを聞け。'),
('JPN', '以西结书', 26, 34, 8, 'わたしは生きている──神である主のことば──。わたしの羊はかすめ奪われ、牧者がいないために、あらゆる野の獣の餌食となってきた。それなのに、わたしの牧者たちはわたしの羊を捜し求めず、かえって自分自身を養って、わたしの羊を養ってこなかった。'),
('JPN', '以西结书', 26, 34, 9, 'それゆえ、牧者たちよ、主のことばを聞け。'),
('JPN', '以西结书', 26, 34, 10, '神である主はこう言う。わたしは牧者たちを敵とし、彼らの手からわたしの羊を取り返し、彼らに羊を飼うのをやめさせる。もはや牧者たちが自分自身を養うことはなくなる。わたしは彼らの口からわたしの羊を救い出し、彼らの餌食にさせない。』」'),
('JPN', '以西结书', 26, 34, 11, 'まことに、神である主はこう言われる。「見よ。わたしは自分でわたしの羊の群れを捜し求め、これを捜し出す。'),
('JPN', '以西结书', 26, 34, 12, '牧者が、散らされた羊の群れのただ中にいるときに、その群れの羊を確かめるように、わたしはわたしの羊を確かめ、雲と暗黒の日に散らされたすべての場所から彼らを救い出す。'),
('JPN', '以西结书', 26, 34, 13, 'わたしは諸国の民の中から彼らを導き出し、国々から彼らを集め、彼らの地に連れて行き、イスラエルの山々や谷川のほとり、またその地のすべての居住地で彼らを養う。'),
('JPN', '以西结书', 26, 34, 14, 'わたしは良い牧草地で彼らを養い、イスラエルの高い山々が彼らの牧場となる。彼らはその良い牧場に伏し、イスラエルの山々の肥えた牧草地で養われる。'),
('JPN', '以西结书', 26, 34, 15, 'わたしがわたしの羊を飼い、わたしが彼らを憩わせる──神である主のことば──。'),
('JPN', '以西结书', 26, 34, 16, 'わたしは失われたものを捜し、追いやられたものを連れ戻し、傷ついたものを介抱し、病気のものを力づける。肥えたものと強いものは根絶やしにする。わたしは正しいさばきをもって彼らを養う。'),
('JPN', '以西结书', 26, 34, 17, 'わたしの群れよ。あなたがたについて、神である主はこう言う。見よ、わたしは羊と羊、雄羊と雄やぎの間をさばく。'),
('JPN', '以西结书', 26, 34, 18, 'あなたがたは良い牧草地で草を食べていながら、それでも足りないのか。その牧草地の残りを足で踏み荒らすとは。澄んだ水を飲みながら、その残りを足で濁すとは。'),
('JPN', '以西结书', 26, 34, 19, 'わたしの群れは、あなたがたの足が踏み荒らした草を食べ、あなたがたの足が濁した水を飲んでいる。」'),
('JPN', '以西结书', 26, 34, 20, 'それゆえ、神である主は彼らにこう言われる。「見よ、わたし自身が、肥えた羊と痩せた羊との間をさばく。'),
('JPN', '以西结书', 26, 34, 21, 'あなたがたが脇腹と肩で押しのけ、その角ですべての弱いものを突き倒し、ついに彼らを外に追い散らしてしまったので、'),
('JPN', '以西结书', 26, 34, 22, 'わたしはわたしの群れを救い、彼らが再び餌食とならないようにする。そして、わたしは羊と羊の間をさばく。'),
('JPN', '以西结书', 26, 34, 23, 'わたしは、彼らを牧する一人の牧者、わたしのしもべダビデを起こす。彼は彼らを養い、その牧者となる。'),
('JPN', '以西结书', 26, 34, 24, '主であるわたしが彼らの神となり、わたしのしもべダビデが彼らのただ中で君主となる。わたしは主である。わたしが語る。'),
('JPN', '以西结书', 26, 34, 25, 'わたしは彼らと平和の契約を結び、悪い獣をその地から取り除く。彼らは安らかに荒野に住み、森の中で眠る。'),
('JPN', '以西结书', 26, 34, 26, 'わたしは、彼らにも、わたしの丘の周りにも祝福を与え、時にかなって雨を降らせる。それは祝福の雨となる。'),
('JPN', '以西结书', 26, 34, 27, '野の木は実を実らせ、地は産物を生じ、彼らは心安らかに自分たちの土地にいるようになる。わたしが彼らのくびきの横木を砕き、彼らを奴隷にした者たちの手から救い出すとき、彼らは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 34, 28, '彼らは二度と国々の餌食とならず、その地の獣も彼らを食い殺さない。彼らは安らかに住み、もう彼らを脅かす者はいない。'),
('JPN', '以西结书', 26, 34, 29, 'わたしは彼らのために立派な耕作地を開く。彼らは、再びその地で飢饉にあうこともなく、再び国々の侮辱を受けることもない。'),
('JPN', '以西结书', 26, 34, 30, 'このとき彼らは、わたしが、彼らとともにいる彼らの神、主であり、彼らイスラエルの家がわたしの民であることを知る──神である主のことば──。'),
('JPN', '以西结书', 26, 34, 31, 'あなたがたはわたしの羊、わたしの牧場の羊である。あなたがたは人間で、わたしはあなたがたの神である──神である主のことば。」'),
('JPN', '以西结书', 26, 35, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 35, 2, '「人の子よ。セイルの山に顔を向け、これについて預言せよ。'),
('JPN', '以西结书', 26, 35, 3, '神である主はこう言われる。セイルの山よ。わたしはおまえを敵とする。わたしはおまえに手を伸ばし、おまえを全き荒廃の地とする。'),
('JPN', '以西结书', 26, 35, 4, 'わたしがおまえの町々を廃墟にし、おまえを荒れ果てさせるとき、おまえは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 35, 5, 'おまえはいつまでも敵意を抱き、イスラエル人の災難の時、すなわち彼らの最後の刑罰の時、彼らを剣の力に引き渡した。'),
('JPN', '以西结书', 26, 35, 6, 'それゆえ──神である主のことば──わたしは生きている。わたしは必ずおまえを血に渡す。血はおまえを追う。おまえは血を憎むことがなかった。だから、血がおまえを追いかける。'),
('JPN', '以西结书', 26, 35, 7, 'わたしはセイルの山を全くの廃墟とし、そこから人の往来を絶つ。'),
('JPN', '以西结书', 26, 35, 8, 'わたしはその山々を、刺し殺された者で満たし、おまえの丘、谷、すべての谷川に、剣で刺し殺された者たちが倒れる。'),
('JPN', '以西结书', 26, 35, 9, 'わたしはおまえを永遠に荒れ果てさせる。おまえの町々には住む者がいなくなる。そのときおまえたちは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 35, 10, 'おまえは、『これら二つの民、二つの国は、われわれのものだ。われわれはそれを占領しよう』と言った。しかし、そこには主がいたのである。'),
('JPN', '以西结书', 26, 35, 11, 'それゆえ──神である主のことば──わたしは生きている。わたしは必ずおまえを罰する。おまえが憎しみから彼らに対してふるまったのと、同じほどの怒りとねたみをもって。わたしがおまえをさばくとき、わたしは彼らに対して自らを現す。'),
('JPN', '以西结书', 26, 35, 12, 'そのときおまえは、わたしが主であることを知る。わたしは、おまえがイスラエルの山々に向かって『これは荒れ果てて、われわれの餌食となった』と言って侮辱したのをすべて聞いている。'),
('JPN', '以西结书', 26, 35, 13, 'おまえたちはわたしに向かって豪語し、わたしに向かってことばを重ねたが、わたしはそれを聞いている。'),
('JPN', '以西结书', 26, 35, 14, '神である主はこう言う。全地が喜ぶほどに、わたしはおまえを荒れ果てさせる。'),
('JPN', '以西结书', 26, 35, 15, 'おまえは、イスラエルの家のゆずりの地が荒れ果てたことを喜んだが、わたしはおまえに同じようにする。セイルの山よ。おまえは荒れ果て、エドム全体もそうなる。そのとき彼らは、わたしが主であることを知る。」'),
('JPN', '以西结书', 26, 36, 1, '「人の子よ、あなたはイスラエルの山々に預言せよ。イスラエルの山々よ、主のことばを聞け。'),
('JPN', '以西结书', 26, 36, 2, '神である主はこう言われる。敵がおまえたちに向かって『あはは、昔からの高き所がわれわれの所有となった』と言っている。'),
('JPN', '以西结书', 26, 36, 3, 'それゆえ、預言せよ。神である主はこう言われる。おまえたちは周りの民に荒らされ、踏みつけられ、ほかの国々の所有とされた、まさにその理由で、おまえたちは人々の語りぐさとなり、そしりの的となった。'),
('JPN', '以西结书', 26, 36, 4, 'それゆえ、イスラエルの山々よ、神である主のことばを聞け。神である主はこう言われる。山や丘、谷川や谷、荒れ果てた廃墟、また、ほかの周囲の国々にかすめ奪われ、嘲られて見捨てられた町々に向かって。'),
('JPN', '以西结书', 26, 36, 5, 'それゆえ、神である主はこう言われる。わたしは燃えるねたみをもって、ほかの国々とエドム全土に告げる。彼らは心の底から喜び、思い切り嘲って、わたしの国を自分たちの所有とし、牧場をかすめ奪ったのだ。'),
('JPN', '以西结书', 26, 36, 6, 'それゆえ、イスラエルの地について預言し、山や丘、谷川や谷に向かって言え。神である主はこう言われる。見よ。おまえたちが国々の侮辱を受けてきたので、わたしはねたみと憤りをもって告げる。'),
('JPN', '以西结书', 26, 36, 7, 'それゆえ、神である主はこう言われる。わたしは手を上げて厳かに誓う。おまえたちを取り囲む諸国の民は、必ず恥辱を負う。'),
('JPN', '以西结书', 26, 36, 8, 'だが、おまえたち、イスラエルの山々よ。おまえたちは枝を出し、わたしの民イスラエルのために実を結ぶ。彼らが帰って来るのが近いからだ。'),
('JPN', '以西结书', 26, 36, 9, 'というのは、わたしがおまえたちのところに行き、おまえたちのところに向かうからだ。おまえたちは耕され、種を蒔かれる。'),
('JPN', '以西结书', 26, 36, 10, 'わたしはおまえたちの上、イスラエルの全家に人を増やす。町々は住む所となり、廃墟は建て直される。'),
('JPN', '以西结书', 26, 36, 11, 'わたしはおまえたちの上に人と家畜を増やす。彼らは増えて、多くの子を生む。わたしはおまえたちを、昔のように人の住む所とし、以前よりも栄えさせる。そのときおまえたちは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 36, 12, 'わたしはおまえたちの上に人を、わたしの民イスラエルを歩かせる。彼らはおまえを所有し、おまえは彼らの相続地となる。おまえは二度と彼らに子を失わせることはない。'),
('JPN', '以西结书', 26, 36, 13, '神である主はこう言われる。彼らはおまえたちに、『おまえは人間を食らい、自分の国民に子を失わせている』と言っている。'),
('JPN', '以西结书', 26, 36, 14, 'それゆえ、おまえは二度と人間を食らわず、二度とおまえの国民に子を失わせることはない──神である主のことば──。'),
('JPN', '以西结书', 26, 36, 15, 'わたしは二度と国々の侮辱をおまえに聞こえさせない。おまえは国々の民のそしりを二度と受けない。二度とおまえの国民をつまずかせることはない──神である主のことば。」'),
('JPN', '以西结书', 26, 36, 16, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 36, 17, '「人の子よ。イスラエルの家が自分の土地に住んでいたとき、彼らはその生き方と行いによって、その地を汚した。その生き方は、わたしの前では、月のさわりのある女の汚れのようであった。'),
('JPN', '以西结书', 26, 36, 18, 'それでわたしは、彼らがその地に流した血のために、また偶像でこれを汚したことのゆえに、わたしの憤りを彼らに注いだ。'),
('JPN', '以西结书', 26, 36, 19, 'わたしは彼らを諸国の間に散らし、彼らを国々に追い散らし、彼らの生き方と行いにしたがって彼らをさばいた。'),
('JPN', '以西结书', 26, 36, 20, '彼らはどの国々に行っても、わたしの聖なる名を汚した。人々は彼らについて、『この人々は主の民なのに、主の国から出されたのだ』と言ったのだ。'),
('JPN', '以西结书', 26, 36, 21, 'わたしは、イスラエルの家がその行った国々の間で汚した、わたしの聖なる名を惜しんだ。'),
('JPN', '以西结书', 26, 36, 22, 'それゆえ、イスラエルの家に言え。神である主はこう言われる。イスラエルの家よ。わたしが事を行うのは、あなたがたのためではなく、あなたがたが行った国々の間であなたがたが汚した、わたしの聖なる名のためである。'),
('JPN', '以西结书', 26, 36, 23, 'わたしは、あなたがたが国々の間で汚したわたしの大いなる名が、聖であることを示す。あなたがたが彼らのただ中で汚した名である。わたしが彼らの目の前に、わたしがあなたがたのうちで聖であることを示すとき、国々は、わたしが主であることを知る──神である主のことば──。'),
('JPN', '以西结书', 26, 36, 24, 'わたしはあなたがたを諸国の間から導き出し、すべての国々から集め、あなたがたの地に連れて行く。'),
('JPN', '以西结书', 26, 36, 25, 'わたしがきよい水をあなたがたの上に振りかけるそのとき、あなたがたはすべての汚れからきよくなる。わたしはすべての偶像の汚れからあなたがたをきよめ、'),
('JPN', '以西结书', 26, 36, 26, 'あなたがたに新しい心を与え、あなたがたのうちに新しい霊を与える。わたしはあなたがたのからだから石の心を取り除き、あなたがたに肉の心を与える。'),
('JPN', '以西结书', 26, 36, 27, 'わたしの霊をあなたがたのうちに授けて、わたしの掟に従って歩み、わたしの定めを守り行うようにする。'),
('JPN', '以西结书', 26, 36, 28, 'あなたがたは、わたしがあなたがたの先祖に与えた地に住み、あなたがたはわたしの民となり、わたしはあなたがたの神となる。'),
('JPN', '以西结书', 26, 36, 29, 'わたしはあなたがたをすべての汚れから救い、穀物を呼び寄せて増やし、飢えをあなたがたに送らない。'),
('JPN', '以西结书', 26, 36, 30, 'わたしは木の実と畑の産物を増やす。それであなたがたは、もう国々の間で飢饉のために恥辱を受けることはない。'),
('JPN', '以西结书', 26, 36, 31, 'あなたがたは自分たちの悪しき生き方と、良くなかった行いを思い出し、自分たちの不義と忌み嫌うべきわざを憎むようになる。'),
('JPN', '以西结书', 26, 36, 32, 'わたしが事を行うのは、あなたがたのためではない──神である主のことば──。そのことをあなたがたは知っていなければならない。イスラエルの家よ、恥じよ。あなたがたの生き方のゆえに辱めを受けよ。」'),
('JPN', '以西结书', 26, 36, 33, '神である主はこう言われる。「わたしがあなたがたをすべての不義からきよめる日に、わたしは町々を人の住めるところとし、廃墟は建て直される。'),
('JPN', '以西结书', 26, 36, 34, '荒れ果てた地は、通り過ぎるすべての者に荒れ野と見なされていたが、耕されるようになる。'),
('JPN', '以西结书', 26, 36, 35, 'このとき、人々はこう言うだろう。『あの荒れ果てていた地はエデンの園のようになった。廃墟となり、荒れ果て、破壊されていた町々も城壁が築かれ、人が住むようになった』と。'),
('JPN', '以西结书', 26, 36, 36, 'あなたがたの周りに残された諸国の民も、主であるわたしが破壊されていたところを建て直し、荒れ果てていたところに木を植えたことを知るようになる。主であるわたしが語り、これを行う。」'),
('JPN', '以西结书', 26, 36, 37, '神である主はこう言われる。「わたしはイスラエルの家の求めに応じ、このことを彼らのためにする。わたしは人を羊の群れのように増やす。'),
('JPN', '以西结书', 26, 36, 38, 'ちょうど、聖なるものとして献げられる羊の群れのように、例祭のときのエルサレムの羊の群れのように、廃墟であった町々を人の群れで満たす。そのとき彼らは、わたしが主であることを知る。」'),
('JPN', '以西结书', 26, 37, 1, '主の御手が私の上にあった。私は主の霊によって連れ出され、平地の真ん中に置かれた。そこには骨が満ちていた。'),
('JPN', '以西结书', 26, 37, 2, '主は私にその周囲をくまなく行き巡らせた。見よ、その平地には非常に多くの骨があった。しかも見よ、それらはすっかり干からびていた。'),
('JPN', '以西结书', 26, 37, 3, '主は私に言われた。「人の子よ、これらの骨は生き返ることができるだろうか。」私は答えた。「神、主よ、あなたがよくご存じです。」'),
('JPN', '以西结书', 26, 37, 4, '主は私に言われた。「これらの骨に預言せよ。『干からびた骨よ、主のことばを聞け。'),
('JPN', '以西结书', 26, 37, 5, '神である主はこれらの骨にこう言う。見よ。わたしがおまえたちに息を吹き入れるので、おまえたちは生き返る。'),
('JPN', '以西结书', 26, 37, 6, 'わたしはおまえたちに筋をつけ、肉を生じさせ、皮膚でおおい、おまえたちのうちに息を与え、おまえたちは生き返る。そのときおまえたちは、わたしが主であることを知る。』」'),
('JPN', '以西结书', 26, 37, 7, '私は命じられたように預言した。私が預言していると、なんと、ガラガラと音がして、骨と骨とが互いにつながった。'),
('JPN', '以西结书', 26, 37, 8, '私が見ていると、なんと、その上に筋がつき、肉が生じ、皮膚がその上をすっかりおおった。しかし、その中に息はなかった。'),
('JPN', '以西结书', 26, 37, 9, 'そのとき、主は言われた。「息に預言せよ。人の子よ、預言してその息に言え。『神である主はこう言われる。息よ、四方から吹いて来い。この殺された者たちに吹きつけて、彼らを生き返らせよ。』」'),
('JPN', '以西结书', 26, 37, 10, '私が命じられたとおりに預言すると、息が彼らの中に入った。そして彼らは生き返り、自分の足で立った。非常に大きな集団であった。'),
('JPN', '以西结书', 26, 37, 11, '主は私に言われた。「人の子よ、これらの骨はイスラエルの全家である。見よ、彼らは言っている。『私たちの骨は干からび、望みは消え失せ、私たちは断ち切られた』と。'),
('JPN', '以西结书', 26, 37, 12, 'それゆえ、預言して彼らに言え。『神である主はこう言われる。わたしの民よ、見よ。わたしはあなたがたの墓を開き、あなたがたをその墓から引き上げて、イスラエルの地に連れて行く。'),
('JPN', '以西结书', 26, 37, 13, 'わたしの民よ。わたしがあなたがたの墓を開き、あなたがたを墓から引き上げるとき、あなたがたは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 37, 14, 'また、わたしがあなたがたのうちにわたしの霊を入れると、あなたがたは生き返る。わたしはあなたがたを、あなたがたの地に住まわせる。このとき、あなたがたは、主であるわたしが語り、これを成し遂げたことを知る──主のことば。』」'),
('JPN', '以西结书', 26, 37, 15, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 37, 16, '「人の子よ。あなたは一本の杖を取り、その上に『ユダと、それにつくイスラエルの人々のために』と書き記せ。もう一本の杖を取り、その上に『エフライムの杖、ヨセフと、それにつくイスラエルの全家のために』と書き記せ。'),
('JPN', '以西结书', 26, 37, 17, 'その両方をつなぎ、一本の杖とし、あなたの手の中で一つとなるようにせよ。'),
('JPN', '以西结书', 26, 37, 18, 'あなたの民の者たちがあなたに向かって、『これがあなたにとって何を意味するのか、私たちに説明してくれませんか』と言うとき、'),
('JPN', '以西结书', 26, 37, 19, '彼らに告げよ。『神である主はこう言われる。見よ。わたしは、エフライムの手にあるヨセフの杖と、それにつくイスラエルの諸部族を取り、それらをユダの杖に合わせて一本の杖とし、わたしの手の中で一つとする。』'),
('JPN', '以西结书', 26, 37, 20, 'あなたが書き記した杖を、彼らの見ている前で手に取り、'),
('JPN', '以西结书', 26, 37, 21, '彼らに告げよ。『神である主はこう言われる。見よ。わたしはイスラエルの子らを、彼らが行っていた国々の間から取り、四方から集めて彼らの地に導いて行く。'),
('JPN', '以西结书', 26, 37, 22, 'わたしが彼らを、その地、イスラエルの山々で一つの国とするとき、一人の王が彼ら全体の王となる。彼らは再び二つの国となることはなく、決して再び二つの王国に分かれることはない。'),
('JPN', '以西结书', 26, 37, 23, '彼らは再び、その偶像や忌まわしいもの、またあらゆる背きによって身を汚すことはない。わたしは、彼らがかつて罪に陥ることになった背信から彼らを救い、彼らをきよめる。彼らはわたしの民となり、わたしは彼らの神となる。'),
('JPN', '以西结书', 26, 37, 24, 'わたしのしもべダビデが彼らの王となり、彼ら全体のただ一人の牧者となる。彼らはわたしの定めに従って歩み、わたしの掟を守り行う。'),
('JPN', '以西结书', 26, 37, 25, '彼らは、わたしがわたしのしもべヤコブに与え、あなたがたの先祖が住んだ地に住むようになる。そこには彼らとその子らとその子孫たちが、とこしえに住み、わたしのしもべダビデが永遠に彼らの君主となる。'),
('JPN', '以西结书', 26, 37, 26, 'わたしは彼らと平和の契約を結ぶ。これは彼らとの永遠の契約となる。わたしはそれを彼らに与え、彼らを増やし、わたしの聖所を彼らのうちに永遠に置く。'),
('JPN', '以西结书', 26, 37, 27, 'わたしの住まいは彼らとともにあり、わたしは彼らの神となり、彼らはわたしの民となる。'),
('JPN', '以西结书', 26, 37, 28, 'わたしの聖所が永遠に彼らのうちにあるとき、諸国の民は、わたしがイスラエルを聖なる者とする主であることを知る。』」'),
('JPN', '以西结书', 26, 38, 1, '次のような主のことばが私にあった。'),
('JPN', '以西结书', 26, 38, 2, '「人の子よ。メシェクとトバルの大首長である、マゴグの地のゴグに顔を向け、彼に預言せよ。'),
('JPN', '以西结书', 26, 38, 3, '『神である主はこう言われる。メシェクとトバルの大首長であるゴグよ。今、わたしはおまえを敵とする。'),
('JPN', '以西结书', 26, 38, 4, 'わたしはおまえを引き回し、おまえのあごに鉤をかけ、おまえと、おまえの全軍勢を出陣させる。それはみな完全に武装した馬や騎兵、大盾と盾を持ち、みな剣を取る大集団だ。'),
('JPN', '以西结书', 26, 38, 5, 'ペルシアとクシュとプテも彼らとともにいて、みな盾を持ち、かぶとを着けている。'),
('JPN', '以西结书', 26, 38, 6, 'ゴメルとそのすべての軍隊、北の果てのベテ・トガルマとそのすべての軍隊、それに多くの国々の民がおまえとともにいる。'),
('JPN', '以西结书', 26, 38, 7, '備えをせよ。おまえも、おまえのもとに召集された全集団も構えよ。おまえは彼らを統率せよ。'),
('JPN', '以西结书', 26, 38, 8, '多くの日が過ぎて、おまえは徴集され、多くの年月の後、おまえは、一つの国に侵入する。そこは剣から立ち直り、多くの国々の民の中から、久しく廃墟であったイスラエルの山々に集められた者たちの国である。その民は国々の民の中から導き出され、みな安らかに住んでいる。'),
('JPN', '以西结书', 26, 38, 9, 'おまえは嵐のように攻め上り、おまえと、おまえの全部隊、それに、おまえにつく多くの国々の民は、地をおおう雲のようになる。'),
('JPN', '以西结书', 26, 38, 10, '神である主はこう言う。その日には、おまえの心に様々なことが思い浮かぶ。おまえは悪巧みをめぐらして、'),
('JPN', '以西结书', 26, 38, 11, 'こう言うだろう。「私は無防備な国に攻め上ろう。安心して暮らす平穏な者たちのところに侵入しよう。彼らはみな城壁もなく住んでいる。かんぬきも門もない」と。'),
('JPN', '以西结书', 26, 38, 12, 'それは、おまえが略奪し、獲物をかすめ奪うため、また今は人の住むようになった廃墟と、国々から集められて地の中心に住み、家畜と財産を所有した民とに向かって手を伸ばすためだ。'),
('JPN', '以西结书', 26, 38, 13, 'シェバやデダンやタルシシュの商人たち、およびそのすべての若い獅子たちは、おまえに言うだろう。「おまえは分捕るために来たのか。獲物をかすめ奪うために隊を構えたのか。銀や金を運び去り、家畜や財産を取り、大いに略奪しようとするつもりか」と。』'),
('JPN', '以西结书', 26, 38, 14, 'それゆえ、人の子よ、預言してゴグに言え。『神である主はこう言われる。わたしの民イスラエルが安心して住んでいるとき、まさに、その日、おまえは知ることになる。'),
('JPN', '以西结书', 26, 38, 15, 'おまえは北の果てのおまえの国から、多くの国々の民とともに来る。彼らはみな馬に乗る者で、大集団、大軍勢だ。'),
('JPN', '以西结书', 26, 38, 16, 'おまえはわたしの民イスラエルを攻めに上り、地をおおう雲のようになる。終わりの日に、そのことは起こる。ゴグよ、わたしはおまえに、わたしの地を攻めさせる。それは、わたしがおまえを使って、国々の目の前にわたしが聖であることを示し、彼らがわたしを知るためだ。'),
('JPN', '以西结书', 26, 38, 17, '神である主はこう言う。おまえは、わたしが昔、わたしのしもべであるイスラエルの預言者たちを通して語った、まさにその者ではないか。この預言者たちは長年にわたり、わたしがおまえに彼らを攻めさせると預言していたのだ。』'),
('JPN', '以西结书', 26, 38, 18, 'ゴグがイスラエルの地を攻めるその日──神である主のことば──わたしの憤りは激しく燃え上がる。'),
('JPN', '以西结书', 26, 38, 19, 'わたしは、ねたみをもって、激しい怒りの火をもって告げる。その日には必ずイスラエルの地に大きな地震が起こる。'),
('JPN', '以西结书', 26, 38, 20, '海の魚、空の鳥、野の獣、地面を這うすべてのもの、地上のすべての人間は、わたしの前で震え上がり、山々はくつがえり、崖は落ち、すべての城壁は地に倒れる。'),
('JPN', '以西结书', 26, 38, 21, 'わたしは剣を呼び寄せて、わたしのすべての山々でゴグを攻めさせる──神である主のことば──。剣による同士討ちが起こる。'),
('JPN', '以西结书', 26, 38, 22, 'わたしは疫病と流血で彼に罰を下し、彼と、彼の部隊と、彼とともにいる多くの国々の民の上に豪雨、雹、火、硫黄を降らせる。'),
('JPN', '以西结书', 26, 38, 23, 'わたしは、わたしが大いなる者であること、わたしが聖であることを示し、多くの国々の見ている前でわたしを知らせる。そのとき彼らは、わたしが主であることを知る。」'),
('JPN', '以西结书', 26, 39, 1, '「人の子よ、あなたはゴグに向かって預言せよ。『神である主はこう言われる。メシェクとトバルの大首長であるゴグよ、わたしはおまえを敵とする。'),
('JPN', '以西结书', 26, 39, 2, 'わたしはおまえを引き回し、おまえを駆りたて、北の果てから上らせ、イスラエルの山々に連れて来る。'),
('JPN', '以西结书', 26, 39, 3, 'おまえの左の手から弓をたたき落とし、右の手から矢を落とす。'),
('JPN', '以西结书', 26, 39, 4, 'おまえと、おまえのすべての部隊、おまえとともにいる国々の民は、イスラエルの山々に倒れ、わたしはおまえをあらゆる種類の猛禽や野獣の餌食とする。'),
('JPN', '以西结书', 26, 39, 5, 'おまえは野に倒れる。わたしがこれを語るからだ──神である主のことば──。'),
('JPN', '以西结书', 26, 39, 6, 'わたしはマゴグと、島々に安住している者たちに火を放つ。彼らは、わたしが主であることを知る。'),
('JPN', '以西结书', 26, 39, 7, 'わたしは、わたしの聖なる名をわたしの民イスラエルの中に告げ知らせ、二度とわたしの聖なる名を汚させない。諸国の民は、わたしが主であり、イスラエルの聖なる者であることを知る。'),
('JPN', '以西结书', 26, 39, 8, '今、それは来て、成就する──神である主のことば──。それは、わたしが語ってきた日である。'),
('JPN', '以西结书', 26, 39, 9, 'イスラエルの町々の住民は出て来て、武器、すなわち、盾と大盾、弓と矢、手槍と槍を燃やし、それらで火をおこす。彼らは、七年間それらで火を燃やす。'),
('JPN', '以西结书', 26, 39, 10, '彼らは野から薪を運んだり、森から木を切り出したりする必要はない。武器で火を燃やすからだ。彼らは略奪した者たちから略奪し、かすめ奪った者たちからかすめ奪う──神である主のことば。'),
('JPN', '以西结书', 26, 39, 11, 'その日、わたしは、イスラエルのうちに、ゴグのために墓場となる場所を設ける。それは、海の東にある去りゆく者たちのための谷である。そこは通行人の道をふさぐ。そこにゴグと、その大軍すべてが埋められ、そこはハモン・ゴグの谷と呼ばれる。'),
('JPN', '以西结书', 26, 39, 12, '七か月間、イスラエルの家は、その地をきよめるために彼らを埋め続ける。'),
('JPN', '以西结书', 26, 39, 13, 'その国のすべての民が埋める。こうして、わたしの栄光が現されるとき、そのことは彼らにとって名誉となる──神である主のことば──。'),
('JPN', '以西结书', 26, 39, 14, 'すなわち、選り分けられた特定の人々が地を巡り歩き、去りゆく者たち、地の面に取り残されている者たちを埋めて、その地をきよめる。彼らは七か月の終わりまで探し回る。'),
('JPN', '以西结书', 26, 39, 15, '巡り歩く者たちは地を巡り歩き、人間の骨を見ると、埋める者たちがそれをハモン・ゴグの谷に埋めるまで、そのそばに標識を立てておく。'),
('JPN', '以西结书', 26, 39, 16, 'そこの町の名はハモナとも言われる。こうして彼らは地をきよめる。』'),
('JPN', '以西结书', 26, 39, 17, '人の子よ、神である主はこう言う。あらゆる種類の鳥と、あらゆる野の生き物に言え。『集まって来い。わたしがおまえたちのために屠るわたしのいけにえに、イスラエルの山々の上での大いなる祝宴に、四方から集まれ。おまえたちはその肉を食べ、その血を飲め。'),
('JPN', '以西结书', 26, 39, 18, '勇士たちの肉を食べ、地の君主たちの血を飲め。雄羊、子羊、雄やぎ、雄牛、それらはすべてバシャンの肥えたものだ。'),
('JPN', '以西结书', 26, 39, 19, 'わたしがおまえたちのために屠ったいけにえの中から、脂肪をたらふく食べ、その血を酔うほど飲むがよい。'),
('JPN', '以西结书', 26, 39, 20, 'おまえたちはわたしの食卓で、馬や騎手、勇士やすべての戦士をたらふく食べる──神である主のことば。』'),
('JPN', '以西结书', 26, 39, 21, 'わたしが国々の間にわたしの栄光を現すとき、国々の民はみな、わたしが行ったわたしのさばきと、わたしが彼らの上に置いたわたしの手を見る。'),
('JPN', '以西结书', 26, 39, 22, 'その日以降、イスラエルの家は、わたしが彼らの神、主であることを知る。'),
('JPN', '以西结书', 26, 39, 23, '国々の民は、イスラエルの家がわたしの信頼を裏切った咎のゆえに捕らえ移され、わたしが彼らから顔を隠したこと、また彼らを敵の手に渡したゆえに、彼らがみな剣に倒れたことを知る。'),
('JPN', '以西结书', 26, 39, 24, 'わたしは彼らの汚れと背きに応じて彼らを罰し、わたしの顔を彼らから隠した。」'),
('JPN', '以西结书', 26, 39, 25, 'それゆえ、神である主はこう言われる。「今、わたしはヤコブを回復させ、イスラエルの全家をあわれむ。これは、わが聖なる名への、わたしのねたみによる。'),
('JPN', '以西结书', 26, 39, 26, '彼らが自分たちの地に、だれにも脅かされずに安らかに住むとき、彼らは自らの恥辱と、わたしに対するすべての不信との責めを負う。'),
('JPN', '以西结书', 26, 39, 27, 'わたしが彼らを諸国の民の間から帰らせ、彼らの敵の地から集めるとき、多くの国々が見ている前で、わたしは彼らのうちにわたしが聖であることを示す。'),
('JPN', '以西结书', 26, 39, 28, 'わたしは彼らを国々に引いて行かせたが、また彼らを彼らの地に集め、もう国々には一人も残さない。このとき彼らは、わたしが彼らの神、主であることを知る。'),
('JPN', '以西结书', 26, 39, 29, 'わたしは二度と、わたしの顔を彼らから隠すことはない。わたしの霊をイスラエルの家の上に注ぐからである──神である主のことば。」'),
('JPN', '以西结书', 26, 40, 1, '私たちが捕囚となって二十五年目の年の初め、その月の十日、都が占領されてから十四年目のちょうどその日に、主の御手が私の上にあり、私をそこへ連れて行った。'),
('JPN', '以西结书', 26, 40, 2, 'すなわち、神々しい幻のうちに私はイスラエルの地へ連れて行かれ、非常に高い山の上に降ろされた。その南の方に、町のようなものが造られていた。'),
('JPN', '以西结书', 26, 40, 3, '主が私をそこに連れて行くと、そこに一人の人がいた。その姿は青銅でできているようであり、その手に麻のひもと測り竿を持って、門のところに立っていた。'),
('JPN', '以西结书', 26, 40, 4, 'その人は私に話しかけられた。「人の子よ。あなたの目で見、耳で聞き、わたしがあなたに見せるすべてのことを心に留めよ。わたしがあなたを連れて来たのは、あなたにこれを見せるためだ。あなたが見ることをみな、イスラエルの家に告げよ。」'),
('JPN', '以西结书', 26, 40, 5, 'そこに、神殿の外側を囲んでいる壁があった。その人は手に六キュビトの測り竿を持っていた。その一キュビトは、普通の一キュビトに一手幅を足した長さであった。彼がその外壁の厚さを測ると一竿であり、その高さも一竿であった。'),
('JPN', '以西结书', 26, 40, 6, 'それから彼は東側に面した門に行き、その階段を上った。彼が門の敷居を測ると、その幅は一竿で、もう一つの門の敷居も幅は一竿であった。'),
('JPN', '以西结书', 26, 40, 7, '控え室は長さ一竿、幅一竿であり、控え室と控え室の間は五キュビトであった。門の内側の玄関の間のそばにある敷居は一竿であった。'),
('JPN', '以西结书', 26, 40, 8, '彼が門の内側の玄関の間を測ると一竿、'),
('JPN', '以西结书', 26, 40, 9, 'すなわち、門の玄関の間を測ると八キュビト、その壁柱は二キュビトで、門の玄関の間は内側にあった。'),
('JPN', '以西结书', 26, 40, 10, '東門の控え室は両側に三つずつあり、三つとも同じ寸法であった。壁柱も、両側とも同じ寸法であった。'),
('JPN', '以西结书', 26, 40, 11, '門の入り口の幅を測ると十キュビト、門の内のり幅の長さは十三キュビトであった。'),
('JPN', '以西结书', 26, 40, 12, '控え室の前に出た仕切りは、両側ともそれぞれ一キュビトであった。控え室は両側とも六キュビトであった。'),
('JPN', '以西结书', 26, 40, 13, '彼がその門を、控え室の片方の屋根の端からもう片方の屋根の端まで測ると、一つの入り口からもう一つの入り口までの幅は二十五キュビトであった。入り口と入り口は向かい合っていた。'),
('JPN', '以西结书', 26, 40, 14, '壁柱を測ると六十キュビトであった。門の周囲を巡る壁柱は庭に面していた。'),
('JPN', '以西结书', 26, 40, 15, '入り口の門の前から内側の門の玄関の間の前までは五十キュビトであり、'),
('JPN', '以西结书', 26, 40, 16, '門の内側にある控え室と壁柱には格子窓が取り付けられ、玄関の間もそうであった。内側の周りには窓があり、壁柱には、なつめ椰子の木が彫刻してあった。'),
('JPN', '以西结书', 26, 40, 17, 'それから、彼は私を外庭に連れて行った。すると、そこには庭の周りに部屋があり、石畳があった。三十の部屋が石畳に面していた。'),
('JPN', '以西结书', 26, 40, 18, '石畳は門のわきにあり、ちょうど門の長さと同じであった。これは下の石畳である。'),
('JPN', '以西结书', 26, 40, 19, '彼が下の門の端から内庭の外の端までその幅を測ると、東も北も百キュビトであった。'),
('JPN', '以西结书', 26, 40, 20, '彼は外庭にある北向きの門の長さと幅を測った。'),
('JPN', '以西结书', 26, 40, 21, 'それには両側に三つずつ控え室があり、壁柱も玄関の間も先の門と同じ寸法であった。その長さは五十キュビト、幅は二十五キュビトであった。'),
('JPN', '以西结书', 26, 40, 22, 'その窓も玄関の間もなつめ椰子の木の彫刻も、東向きの門と同じ寸法であった。七段の階段を上って行くと、その先に玄関の間があった。'),
('JPN', '以西结书', 26, 40, 23, '東門と同様に、北門にも内庭の門が向かい合っていた。彼が門から門まで測ると、百キュビトであった。'),
('JPN', '以西结书', 26, 40, 24, '次に、彼は私を南の方へ連れて行った。すると、そこに南向きの門があった。その壁柱と玄関の間を彼が測ると、それはほかの門と同じ寸法であった。'),
('JPN', '以西结书', 26, 40, 25, '壁柱と玄関の間の周囲に窓があり、それはほかの窓と同じであった。門の長さは五十キュビト、幅は二十五キュビトであった。'),
('JPN', '以西结书', 26, 40, 26, 'そこに上るのに七段の階段があり、その先に玄関の間があった。その両側の壁柱には、なつめ椰子の木が彫刻してあった。'),
('JPN', '以西结书', 26, 40, 27, '内庭には南向きの門があり、彼が南の方にこの門からもう一つの門まで測ると、百キュビトであった。'),
('JPN', '以西结书', 26, 40, 28, '彼は私を、南門を通って内庭に連れて行った。南門を測ると、ほかの門と同じ寸法であった。'),
('JPN', '以西结书', 26, 40, 29, 'その控え室も壁柱も玄関の間もほかのと同じ寸法で、壁柱と玄関の間の周囲に窓があった。門の長さは五十キュビト、幅は二十五キュビトであった。'),
('JPN', '以西结书', 26, 40, 30, '玄関の間の周囲は長さ二十五キュビト、幅五キュビトであった。'),
('JPN', '以西结书', 26, 40, 31, 'その玄関の間は外庭に面し、その壁柱には、なつめ椰子の木が彫刻してあった。その階段は八段であった。'),
('JPN', '以西结书', 26, 40, 32, '次に、彼は私を内庭の東の方に連れて行った。そこの門を測ると、ほかの門と同じ寸法であった。'),
('JPN', '以西结书', 26, 40, 33, 'その控え室も壁柱も玄関の間もほかのと同じ寸法で、壁柱と玄関の間の周囲に窓があった。門の長さは五十キュビト、幅は二十五キュビトであった。'),
('JPN', '以西结书', 26, 40, 34, 'その玄関の間は外庭に面し、両側の壁柱には、なつめ椰子の木が彫刻してあった。階段は八段であった。'),
('JPN', '以西结书', 26, 40, 35, '彼は私を北の門に連れて行った。それを測ると、ほかの門と同じ寸法であった。'),
('JPN', '以西结书', 26, 40, 36, 'その控え室も壁柱も玄関の間もほかのと同じ寸法で、その周囲に窓があった。門の長さは五十キュビト、幅は二十五キュビトであった。'),
('JPN', '以西结书', 26, 40, 37, 'その玄関の間は外庭に面し、両側の壁柱には、なつめ椰子の木が彫刻してあった。階段は八段であった。'),
('JPN', '以西结书', 26, 40, 38, '門の壁柱のそばには戸のある部屋があり、そこは全焼のささげ物をすすぎ洗う場所であった。'),
('JPN', '以西结书', 26, 40, 39, '門の玄関の間の両側には、全焼のささげ物、罪のきよめのささげ物、代償のささげ物を屠るための台が、それぞれ二つずつあった。'),
('JPN', '以西结书', 26, 40, 40, '北の門の入り口へ上って行くと、外側に二つの台があり、門の玄関の間のもう一つの側にも二つの台があった。'),
('JPN', '以西结书', 26, 40, 41, 'すなわち、門の片側に四つの台があり、もう一つの側に四つの台があり、この八つの台の上でいけにえを屠るのであった。'),
('JPN', '以西结书', 26, 40, 42, 'また、全焼のささげ物のために四つの台があり、長さ一キュビト半、幅一キュビト半、高さ一キュビトの切り石であった。その上に、全焼のささげ物やいけにえを屠るための道具が置かれていた。'),
('JPN', '以西结书', 26, 40, 43, '内側には、周囲に一手幅の鉤が取り付けてあり、ささげ物の肉は台の上に置かれるようになっていた。'),
('JPN', '以西结书', 26, 40, 44, '内門の向こうには歌い手たちの部屋があり、北門のわきにある部屋は南を向き、南門のわきにある部屋は北を向いていた。'),
('JPN', '以西结书', 26, 40, 45, '彼は私に言った。「この南向きの部屋は、神殿の任務に当たる祭司たちのためのものであり、'),
('JPN', '以西结书', 26, 40, 46, '北向きの部屋は、祭壇の任務に当たる祭司たちのためのものである。彼らはツァドクの子孫であり、レビの子孫の中で主に近づいて仕える者たちである。」'),
('JPN', '以西结书', 26, 40, 47, '彼が庭を測ると、長さ百キュビト、幅百キュビトの正方形であった。祭壇は神殿の前にあった。'),
('JPN', '以西结书', 26, 40, 48, '彼が私を神殿の玄関の間に連れて行って、玄関の間の壁柱を測ると、両側とも五キュビトであり、その門の幅は十四キュビト、その門の両脇の壁はそれぞれ三キュビトであった。'),
('JPN', '以西结书', 26, 40, 49, '玄関の間の長さは二十キュビト、奥行は十一キュビトであった。そこへ上るのに階段があり、両側の壁柱のそばにはそれぞれ円柱が立っていた。'),
('JPN', '以西结书', 26, 41, 1, '彼は私を本殿へ連れて行った。その壁柱を測ると、その幅は両側とも六キュビトであった。これが壁柱の幅であった。'),
('JPN', '以西结书', 26, 41, 2, '入り口の幅は十キュビト、入り口の両脇の壁はそれぞれ五キュビトであり、本殿の長さを測ると四十キュビト、幅は二十キュビトであった。'),
('JPN', '以西结书', 26, 41, 3, '彼が奥に入り、入り口の壁柱を測ると二キュビト、入り口は六キュビト、入り口の両脇の壁は七キュビトであった。'),
('JPN', '以西结书', 26, 41, 4, '彼はまた、本殿の奥に長さ二十キュビト、幅二十キュビトを測って、私に「これは最も聖なる所だ」と言った。'),
('JPN', '以西结书', 26, 41, 5, '彼が神殿の壁の厚さを測ると六キュビト、神殿の周囲を囲む脇間の幅は四キュビトであった。'),
('JPN', '以西结书', 26, 41, 6, '脇間は三階建てで、各階に三十あった。それらは神殿の壁に差し込まれていた。脇間がぐるりと取り囲んでいたので、それが支えとなっていた。しかし神殿の壁には、支えが差し込まれていなかった。'),
('JPN', '以西结书', 26, 41, 7, '脇間の幅は、螺旋階段で上に上るごとに広くなっていた。というのは、神殿はその建物の四方を、上の方まで脇間で取り囲まれていたからである。そのため、神殿には、地階から中間の階を通って最上階に上る場合、上の方により広い空間があることになる。'),
('JPN', '以西结书', 26, 41, 8, '私は神殿の周りが高くなっているのを見た。脇間の土台は、長めの六キュビトの測り竿いっぱいであった。'),
('JPN', '以西结书', 26, 41, 9, '脇間の外側の壁の厚さは五キュビトであった。神殿の脇間と'),
('JPN', '以西结书', 26, 41, 10, '部屋との間には空き地があり、それが神殿の周囲を幅二十キュビトで囲んでいた。'),
('JPN', '以西结书', 26, 41, 11, '脇間の入り口は空き地の方を向いていて、一つの入り口は北向き、もう一つの入り口は南向きであった。その空き地は幅五キュビトで周囲を囲んでいた。'),
('JPN', '以西结书', 26, 41, 12, '西側の聖域にある建物は、その奥行が七十キュビト、その建物の周りの壁は、厚さ五キュビト、その間口は九十キュビトであった。'),
('JPN', '以西结书', 26, 41, 13, '彼が神殿を測ると、長さは百キュビトであった。また、その聖域と建物とその壁とで、長さ百キュビトであった。'),
('JPN', '以西结书', 26, 41, 14, 'また、東側の聖域と神殿に面する幅も百キュビトであった。'),
('JPN', '以西结书', 26, 41, 15, '彼が神殿の裏にある聖域に面した建物の長さと、その両側のバルコニーを測ると、百キュビトであった。本殿と、その前の庭の玄関の間、'),
('JPN', '以西结书', 26, 41, 16, '敷居と格子窓と、三階になったバルコニーには、床から窓まで羽目板が張り巡らされ、窓はおおわれ、'),
('JPN', '以西结书', 26, 41, 17, 'それは入り口の上部、神殿の内側と外側に及んでいた。そして、これらを囲むどの壁の内側にも外側にも綿密に考案された図柄があり、'),
('JPN', '以西结书', 26, 41, 18, 'ケルビムとなつめ椰子の木が彫刻してあった。なつめ椰子の木はケルビムとケルビムの間にあり、それぞれのケルビムには二つの顔があった。'),
('JPN', '以西结书', 26, 41, 19, '人間の顔は一方のなつめ椰子の木に向かい、若い獅子の顔はもう一方のなつめ椰子の木に向かい、このように神殿全体の周りに彫刻してあった。'),
('JPN', '以西结书', 26, 41, 20, '床から入り口の上まで、ケルビムとなつめ椰子の木が彫刻してあった。本殿の壁も同様であった。'),
('JPN', '以西结书', 26, 41, 21, '本殿の戸口の柱は四角で、至聖所の前には何か'),
('JPN', '以西结书', 26, 41, 22, '木の祭壇に見えるものがあり、高さは三キュビト、長さは二キュビトで、その四隅も台も側面も木でできていた。彼は私に「これが主の前にある机だ」と言った。'),
('JPN', '以西结书', 26, 41, 23, 'また、本殿と至聖所にそれぞれ二つの扉があり、'),
('JPN', '以西结书', 26, 41, 24, 'それらの扉にはそれぞれ二つの戸が折りたたむようになっていた。すなわち、一つの扉には二枚の戸があり、もう一方の扉にも二枚の戸があった。'),
('JPN', '以西结书', 26, 41, 25, '本殿の扉には、壁に彫刻されていたのと同じような、ケルビムとなつめ椰子の木が彫刻してあった。外側の玄関の間の前には木のひさしがあった。'),
('JPN', '以西结书', 26, 41, 26, '玄関の間の両脇の壁には、格子窓となつめ椰子の木があり、神殿の脇間とひさしも同様であった。'),
('JPN', '以西结书', 26, 42, 1, '彼は私を北の方の外庭に連れ出し、聖域に面し、北方の建物に面している部屋へ連れて行った。'),
('JPN', '以西结书', 26, 42, 2, 'その長さは百キュビト、その端に北の入り口があり、幅は五十キュビトであった。'),
('JPN', '以西结书', 26, 42, 3, '二十キュビトの内庭に面し、また外庭の石畳に面して、三階になったバルコニーが向かい合っていた。'),
('JPN', '以西结书', 26, 42, 4, '部屋の前には内側への通路があり、その幅は十キュビトで、長さは百キュビトであった。その部屋の入り口は北に向いていた。'),
('JPN', '以西结书', 26, 42, 5, '最上階にある部屋は、バルコニーが場所を取ったので、建物の地階の部屋よりも、また中間の階の部屋よりも狭かった。'),
('JPN', '以西结书', 26, 42, 6, 'なぜなら、これらは三階建てであり、庭の柱のような柱がないからである。それで、最上階の部屋は地階の部屋よりも、また中間の階の部屋よりも狭かった。'),
('JPN', '以西结书', 26, 42, 7, 'また、これらの部屋の前の外庭の方に、部屋に沿って外側に石壁があった。その長さは五十キュビトであった。'),
('JPN', '以西结书', 26, 42, 8, 'というのは、外庭に面する部屋の長さは五十キュビトだからである。そこで、本殿に面する側は百キュビトとなる。'),
('JPN', '以西结书', 26, 42, 9, 'これらの部屋の下には、外庭から入れるように、東側に出入り口があった。'),
('JPN', '以西结书', 26, 42, 10, '聖域や建物に面している、南側の庭の厚い石壁の中には、部屋があった。'),
('JPN', '以西结书', 26, 42, 11, 'その部屋の前には通路があった。部屋は北側の部屋と同じように見え、長さも同じ、幅も同じで、そのすべての出口も、その構造において入り口と同様であった。'),
('JPN', '以西结书', 26, 42, 12, '南側の部屋の入り口も同様で、通路の先端に入り口があり、東側の石壁に面し、そこから入れる通路があった。'),
('JPN', '以西结书', 26, 42, 13, '彼は私に言った。「聖域に面している北の部屋と南の部屋は、聖なる部屋であって、主に近づく祭司たちが最も聖なるささげ物を食する所である。彼らはそこに最も聖なるもの、すなわち、穀物のささげ物、罪のきよめのささげ物、代償のささげ物を置く。その場所は聖だからである。'),
('JPN', '以西结书', 26, 42, 14, '祭司たちは、聖所に入ったら、聖所からそのまま外庭に出てはならない。彼らが奉仕に用いる服は聖であるから、そこに置き、ほかの服に着替えてから民に属するところに近づくのである。」'),
('JPN', '以西结书', 26, 42, 15, '彼は神殿の内側を測り終えると、東向きの門に私を連れ出し、神殿の周囲を測った。'),
('JPN', '以西结书', 26, 42, 16, '彼が測り竿で東側を測ると、測り竿で五百竿であった。'),
('JPN', '以西结书', 26, 42, 17, '北側を測ると、測り竿で五百竿であった。'),
('JPN', '以西结书', 26, 42, 18, '南側を測ると、測り竿で五百竿であった。'),
('JPN', '以西结书', 26, 42, 19, '彼が西側に回って測り竿で測ると、五百竿であった。'),
('JPN', '以西结书', 26, 42, 20, '彼が外壁の周りを巡って四方を測ると、その長さは五百竿、幅も五百竿で、聖なるものと俗なるものとを分けていた。'),
('JPN', '以西结书', 26, 43, 1, '彼は私を東向きの門に連れて行った。'),
('JPN', '以西结书', 26, 43, 2, 'すると見よ、イスラエルの神の栄光が東の方から現れた。その音は大水のとどろきのようで、地はその栄光で輝いた。'),
('JPN', '以西结书', 26, 43, 3, '私が見た幻は、かつて主がこの町を滅ぼすために来たときに私が見た幻のようであり、またその幻は、かつて私がケバル川のほとりで見た幻のようでもあった。私はひれ伏した。'),
('JPN', '以西结书', 26, 43, 4, '主の栄光が東向きの門を通って神殿に入って来た。'),
('JPN', '以西结书', 26, 43, 5, '霊が私を引き上げ、私を内庭に連れて行った。なんと、主の栄光が神殿に満ちていた。'),
('JPN', '以西结书', 26, 43, 6, '私のそばに人が立っていたが、私は、神殿の中から声が私に語りかけるのを聞いた。'),
('JPN', '以西结书', 26, 43, 7, 'その声は私に言われた。「人の子よ。ここはわたしの玉座のある場所、わたしの足の踏む場所、わたしが永遠にイスラエルの子らの中で住む場所である。イスラエルの家は、その民もその王たちも、もう二度と、淫行や高き所の王たちの死体で、わたしの聖なる名を汚さない。'),
('JPN', '以西结书', 26, 43, 8, '彼らはかつて、自分たちの敷居をわたしの敷居のそばに設け、自分たちの戸口の柱をわたしの戸口の柱の傍らに立て、わたしと彼らとの間には、ただ壁があるだけであった。そして彼らの忌み嫌うべきわざによって、わたしの聖なる名を汚した。そこでわたしは怒って、彼らを絶ち滅ぼした。'),
('JPN', '以西结书', 26, 43, 9, '今、彼らにその淫行や王たちの死体を、わたしから遠ざけさせなければならない。そのとき、わたしは永遠に彼らの中に住む。'),
('JPN', '以西结书', 26, 43, 10, '人の子よ。あなたは、イスラエルの家が自分たちの不義によって辱められるため、彼らに神殿を示し、彼らにその模型を測らせよ。'),
('JPN', '以西结书', 26, 43, 11, 'もし彼らが、自分たちの行ったあらゆることによって恥じるなら、あなたは彼らに神殿の構造とその模型、その出口と入り口、すなわち、そのすべての構造を、神殿のすべての掟、すべての構造、すべてのおしえとともに示し、彼らの目の前でそれを書き記せ。彼らがそのすべての構造と掟を守り、それらを行うためである。'),
('JPN', '以西结书', 26, 43, 12, '神殿に関するおしえは次のとおりである。山の頂の周囲全体は最も聖なる所である。これが神殿に関するおしえである。'),
('JPN', '以西结书', 26, 43, 13, 'キュビトによる祭壇の寸法は次のとおりである。このキュビトは、普通のキュビトに一手幅足したものである。祭壇の溝は深さ一キュビト、幅は一キュビト、周囲の縁取りは一ゼレトである。祭壇の高さは次のとおりである。'),
('JPN', '以西结书', 26, 43, 14, 'この地面に接する溝から下の台座までは二キュビト、幅は一キュビト。この低いほうの台座から高いほうの台座までは四キュビト、幅は一キュビト。'),
('JPN', '以西结书', 26, 43, 15, '祭壇の炉は高さ四キュビトであり、祭壇の炉から上の方へ四本の角が出ている。'),
('JPN', '以西结书', 26, 43, 16, '祭壇の炉は長さ十二キュビト、幅十二キュビトの正方形である。'),
('JPN', '以西结书', 26, 43, 17, 'その台座は長さ十四キュビト、幅十四キュビトの正方形で、その周囲の縁は半キュビト、周囲の溝は一キュビトであり、その階段は東に面している。」'),
('JPN', '以西结书', 26, 43, 18, 'その声は私に言われた。「人の子よ、神である主はこう言う。祭壇の上で全焼のささげ物を献げ、血を振りかけるための祭壇を造る日には、次のことが祭壇に関する掟となる。'),
('JPN', '以西结书', 26, 43, 19, 'わたしに仕えるためにわたしに近づく、ツァドクの子孫のレビ人の祭司たちに、あなたは罪のきよめのささげ物として若い雄牛一頭を与えよ──神である主のことば──。'),
('JPN', '以西结书', 26, 43, 20, 'あなたはその血を取り、祭壇の四本の角と、台座の四隅と、周りの縁に付けて祭壇から罪を除き、そのための宥めを行う。'),
('JPN', '以西结书', 26, 43, 21, 'また、罪のきよめのささげ物の雄牛を取り、これを聖所の外の、神殿の特定の場所で焼かなければならない。'),
('JPN', '以西结书', 26, 43, 22, '二日目に、傷のない雄やぎを罪のきよめのささげ物として献げ、雄牛で罪を除いたように祭壇から罪を除く。'),
('JPN', '以西结书', 26, 43, 23, '罪を除き終えたら、傷のない若い雄牛と、群れのうちの傷のない雄羊を献げる。'),
('JPN', '以西结书', 26, 43, 24, 'それらを主の前に献げ、祭司たちがそれらの上に塩をまき、全焼のささげ物として主に献げる。'),
('JPN', '以西结书', 26, 43, 25, '七日間、あなたは毎日、罪のきよめのささげ物として雄やぎ一匹を献げ、傷のない若い雄牛一頭と、群れのうちの傷のない雄羊一匹を献げる。'),
('JPN', '以西结书', 26, 43, 26, '七日間にわたって祭壇のための宥めを行い、それをきよめ、聖別する。'),
('JPN', '以西结书', 26, 43, 27, 'この期間が終わり、八日目とその後は、祭司たちが祭壇の上で、あなたがたの全焼のささげ物と交わりのいけにえを献げる。そうすれば、わたしはあなたがたを受け入れる──神である主のことば。」'),
('JPN', '以西结书', 26, 44, 1, '彼が私を聖所の東向きの外の門に連れ戻すと、門は閉じていた。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '以西结书', 26, 44, 2, '主は私に言われた。「この門は閉じたままにしておけ。開けてはならない。だれもここから入ってはならない。イスラエルの神、主がそこから入ったからだ。これは閉じたままにしておかなければならない。'),
('JPN', '以西结书', 26, 44, 3, '君主だけが、君主として主の前でパンを食べるために、そこに座ることができる。彼は門の玄関の間を通って入り、そこを通って出て行く。」'),
('JPN', '以西结书', 26, 44, 4, '彼は私を、北の門を通って神殿の前に連れて行った。私が見ると、なんと、主の栄光が主の宮に満ちていた。私はひれ伏した。'),
('JPN', '以西结书', 26, 44, 5, 'すると、主は私に言われた。「人の子よ。主の宮のすべての掟とそのすべてのおしえについて、わたしがあなたに告げていることをすべて心に留め、それに目を注ぎ、耳を傾けよ。神殿の入り口と、聖所のすべての出口を心に留めよ。'),
('JPN', '以西结书', 26, 44, 6, 'あなたは、反逆のイスラエルの家にこう言え。『神である主はこう言われる。イスラエルの家よ。あなたがたのあらゆる忌み嫌うべきわざは、もう十分だ。'),
('JPN', '以西结书', 26, 44, 7, 'あなたがたは、心に割礼を受けず、肉体にも割礼を受けていない異国の民を連れて来て、わたしの聖所にいさせ、わたしの神殿を汚した。あなたがたは、わたしのパンと脂肪と血を献げたが、あなたがたの行った忌み嫌うべきあらゆるわざによって、わたしとの契約を破った。'),
('JPN', '以西结书', 26, 44, 8, 'あなたがたは、わたしの聖所での任務も果たさず、かえって、自分たちの代わりにほかの者たちを、わたしの聖所で務めを果たす者として置いた。』」'),
('JPN', '以西结书', 26, 44, 9, '神である主はこう言われる。「心に割礼を受けず、肉体にも割礼を受けていない異国の民は、だれもわたしの聖所に入ってはならない。イスラエルの子らの中にいる異国の民はみなそうだ。'),
('JPN', '以西结书', 26, 44, 10, 'イスラエルが迷って自分たちの偶像を慕い、わたしから迷い出たとき、レビ人もわたしから離れ去ったので、彼らは自分たちの咎を負わなければならない。'),
('JPN', '以西结书', 26, 44, 11, '彼らは神殿の門で番をし、神殿で奉仕をして、わたしの聖所で仕え、また、民のために全焼のささげ物といけにえを屠り、こうして民の前に立って、彼らのために仕えるはずなのだ。'),
('JPN', '以西结书', 26, 44, 12, 'レビ人たちは民の偶像の前で民に仕え、そのことでイスラエルの家を不義に引き込むものとなった。それゆえ、わたしは彼らに手を上げて厳かに誓う──神である主のことば──。彼らは自分たちの咎を負わなければならない。'),
('JPN', '以西结书', 26, 44, 13, '彼らは、祭司としてわたしに仕えるために、わたしに近づいてはならない。わたしのあらゆる聖なるもの、また最も聖なるものに近づいてはならない。彼らは、恥辱と、自分たちの行った忌み嫌うべきわざの責めを、負わなければならない。'),
('JPN', '以西结书', 26, 44, 14, 'わたしは彼らに、神殿のあらゆる奉仕と、そこで行われる神殿のすべての任務を果たさせる。'),
('JPN', '以西结书', 26, 44, 15, 'しかし、イスラエルの子らが迷ってわたしから離れたときも、わたしの聖所の任務を果たした、ツァドクの子孫のレビ人の祭司たちは、わたしに近づいてわたしに仕え、わたしの前に立ち、わたしに脂肪と血を献げることができる──神である主のことば──。'),
('JPN', '以西结书', 26, 44, 16, '彼らはわたしの聖所に入ることができる。わたしの机に近づいてわたしに仕え、わたしへの務めを果たすことができる。'),
('JPN', '以西结书', 26, 44, 17, '彼らは、内庭の門に入るときには、亜麻布の服を着なければならない。内庭の門、および神殿の中で務めをするときは、毛織物を身に着けてはならない。'),
('JPN', '以西结书', 26, 44, 18, '頭には亜麻布のターバンをかぶり、腰には亜麻布のももひきをはく。汗の出るようなものを身に着けてはならない。'),
('JPN', '以西结书', 26, 44, 19, '彼らが外庭に出て、外庭の民のところに出て行くときは、務めのときに着ていた服を脱ぎ、それを聖所の部屋に置き、ほかの服を着なければならない。その服によって民を聖なる者とすることのないためである。'),
('JPN', '以西结书', 26, 44, 20, '彼らは頭を剃ってはならない。髪を長く伸ばしすぎてもいけない。頭の毛はきちんと切りそろえなければならない。'),
('JPN', '以西结书', 26, 44, 21, '祭司はだれでも、内庭に入るとき、ぶどう酒を飲んではならない。'),
('JPN', '以西结书', 26, 44, 22, 'やもめや離縁された女を妻にしてはならない。イスラエルの民のうちの処女を妻としなければならない。しかし、やもめでも、それが祭司のやもめであれば、妻としてもよい。'),
('JPN', '以西结书', 26, 44, 23, '彼らはわたしの民に、聖なるものと俗なるものとの違いを教え、汚れたものときよいものとの区別を告げ知らせなければならない。'),
('JPN', '以西结书', 26, 44, 24, '争いがあるときには、わたしの定めにしたがってさばきの座に着き、これをさばかなければならない。わたしのすべての例祭には、わたしのおしえと掟を守り、わたしの安息日を聖なるものとしなければならない。'),
('JPN', '以西结书', 26, 44, 25, '彼らは、死んだ人間に近づいて身を汚してはならない。ただし、自分の父、母、息子、娘、兄弟、未婚の姉妹によって汚れることは許される。'),
('JPN', '以西结书', 26, 44, 26, 'その場合、祭司はきよめられた後、さらに七日を数えなければならない。'),
('JPN', '以西结书', 26, 44, 27, '聖所で仕えるために聖所の内庭に入る日には、罪のきよめのささげ物を献げなければならない──神である主のことば。'),
('JPN', '以西结书', 26, 44, 28, '祭司たちへのゆずりとなるのはこれである。わたしが彼らへのゆずりである。あなたがたはイスラエルの中で彼らに所有地を与えてはならない。わたしが彼らの所有である。'),
('JPN', '以西结书', 26, 44, 29, '彼らの食物は、穀物のささげ物、罪のきよめのささげ物、代償のささげ物である。イスラエルのうちで、聖絶されたものはみな、彼らのものである。'),
('JPN', '以西结书', 26, 44, 30, 'あらゆる種類の初物、あなたがたのあらゆる奉納物のうちの最上の奉納物は、すべて祭司たちのものであり、あなたがたの麦粉の初物も祭司に与えなければならない。あなたの家に祝福が宿るためである。'),
('JPN', '以西结书', 26, 44, 31, '祭司たちは、死んだ動物や、野獣にかみ裂かれたものはすべて、鳥であれ獣であれ、食べてはならない。」'),
('JPN', '以西结书', 26, 45, 1, '「あなたがたが相続地としてその地をくじで分けるときは、その地から奉納地として聖なる区域を主に献げなければならない。その長さは二万五千キュビト、幅は一万キュビト。その全域は聖なる地である。'),
('JPN', '以西结书', 26, 45, 2, 'このうち、縦横五百キュビトの正方形を聖所に充て、五十キュビトの空き地がその周りにあるようにする。'),
('JPN', '以西结书', 26, 45, 3, 'この区域の中から、長さ二万五千キュビト、幅一万キュビトを測り、その中に最も聖なる所、聖所があるようにせよ。'),
('JPN', '以西结书', 26, 45, 4, 'これはこの地の聖なる部分である。これは、聖所で仕え、主に近づいて仕える祭司たちのものとなる。ここを彼らの家の敷地とし、聖所のための聖なる所とする。'),
('JPN', '以西结书', 26, 45, 5, 'また、長さ二万五千キュビト、幅一万キュビトの地は、神殿で奉仕をするレビ人のものとし、二十の部屋を彼らの所有としなければならない。'),
('JPN', '以西结书', 26, 45, 6, '聖なる奉納地に沿って、幅五千キュビト、長さ二万五千キュビトを町の所有とし、これをイスラエルの全家のものとする。'),
('JPN', '以西结书', 26, 45, 7, '君主の土地は、聖なる奉納地と町の所有地との両側にあり、聖なる奉納地と町の所有地に面し、西側は西の方へ、東側は東の方へ延びている。その長さは一つの部族の割り当て地と同じで、西の境界線から東の境界線にまで及んでいる。'),
('JPN', '以西结书', 26, 45, 8, 'これがイスラエルの中の彼の所有地である。わたしの君主たちは二度とわたしの民を虐げることなく、この地は部族ごとに、イスラエルの家に与えられる。」'),
('JPN', '以西结书', 26, 45, 9, '神である主はこう言われる。「イスラエルの君主たちよ、もう十分だ。暴虐と暴行を取り除き、公正と正義を行え。わたしの民を重税で追い立てることをやめよ──神である主のことば──。'),
('JPN', '以西结书', 26, 45, 10, '正しい天秤、正しいエパ升、正しいバテ升を使え。'),
('JPN', '以西结书', 26, 45, 11, 'エパとバテを同一量にせよ。バテはホメルの十分の一、エパもホメルの十分の一とせよ。その量はホメルを単位とせよ。'),
('JPN', '以西结书', 26, 45, 12, '一シェケルは二十ゲラである。二十シェケルと二十五シェケルと十五シェケルとで一ミナとせよ。'),
('JPN', '以西结书', 26, 45, 13, 'あなたがたが献げる奉納物は次のとおりである。小麦一ホメルから六分の一エパ、大麦一ホメルから六分の一エパ。'),
('JPN', '以西结书', 26, 45, 14, 'バテの単位で量られる定められた分は、一コルから十分の一バテである。一コルは一ホメルと同じく十バテである。'),
('JPN', '以西结书', 26, 45, 15, 'さらに、羊の群れから二百匹ごとに一匹の羊。これらをイスラエルの潤った地から得て、穀物のささげ物、全焼のささげ物、交わりのいけにえとし、彼らのために宥めを行え──神である主のことば──。'),
('JPN', '以西结书', 26, 45, 16, '国のすべての民は、この奉納物をイスラエルの君主に納めなければならない。'),
('JPN', '以西结书', 26, 45, 17, '君主は、各種の祭りの日、新月の祭り、安息日、すなわちイスラエルの家のあらゆる例祭に、全焼のささげ物、穀物のささげ物、注ぎのぶどう酒を供える義務がある。彼はイスラエルの家の宥めのために、罪のきよめのささげ物、穀物のささげ物、全焼のささげ物、交わりのいけにえを献げなければならない。」'),
('JPN', '以西结书', 26, 45, 18, '神である主はこう言われる。「第一の月の一日に、あなたは傷のない若い雄牛を取り、聖所から罪を除かなければならない。'),
('JPN', '以西结书', 26, 45, 19, '祭司は罪のきよめのささげ物から血を取り、それを神殿の戸口の柱、祭壇の台座の四隅、そして内庭の門柱に塗る。'),
('JPN', '以西结书', 26, 45, 20, 'その月の七日にも、あなたは、迷い出る者や浅はかな者のゆえにこのように献げ、神殿のために宥めを行わなければならない。'),
('JPN', '以西结书', 26, 45, 21, '第一の月の十四日に、あなたがたは過越の祭りを守り、その祭りの七日間、種なしパンを食べる。'),
('JPN', '以西结书', 26, 45, 22, 'その日に君主は、自分のために、また、国のすべての民のために、罪のきよめのささげ物として雄牛を献げる。'),
('JPN', '以西结书', 26, 45, 23, 'その祭りの七日間、彼は全焼のささげ物として傷のない七頭の雄牛と七匹の雄羊を、七日間、毎日、主に献げなければならない。また一匹の雄やぎを、罪のきよめのささげ物として、毎日、献げなければならない。'),
('JPN', '以西结书', 26, 45, 24, '穀物のささげ物として、雄牛一頭に一エパ、雄羊一匹に一エパを献げる。油は一エパごとに一ヒンとする。'),
('JPN', '以西结书', 26, 45, 25, '第七の月の十五日の祭りにも、七日間、これと同じように献げる。罪のきよめのささげ物、全焼のささげ物、穀物のささげ物、それに油を、同じように献げる。」'),
('JPN', '以西结书', 26, 46, 1, '神である主はこう言われる。「内庭の東向きの門は、仕事をする六日間は閉じられるが、安息日には開けられなければならない。また、新月の祭りの日にも開けられなければならない。'),
('JPN', '以西结书', 26, 46, 2, '君主は外側の門の玄関の間を通って入り、門の戸口の柱のそばに立つ。祭司たちは彼の全焼のささげ物と、交わりのいけにえを献げ、彼は門の敷居のところで礼拝する。それから彼は出て行く。しかし、門は夕暮れまで閉じてはならない。'),
('JPN', '以西结书', 26, 46, 3, '民衆も、安息日と新月の祭りの日には、その門の入り口で主の前に礼拝をする。'),
('JPN', '以西结书', 26, 46, 4, '君主が安息日に主に献げる全焼のささげ物は、傷のない子羊六匹と、傷のない雄羊一匹である。'),
('JPN', '以西结书', 26, 46, 5, 'また、穀物のささげ物は、雄羊一匹について一エパ。子羊については、彼が献げることができる分量の穀物のささげ物。油は一エパごとに一ヒンである。'),
('JPN', '以西结书', 26, 46, 6, '新月の祭りの日には、傷のない若い雄牛一頭と、傷のない子羊六匹と雄羊一匹である。'),
('JPN', '以西结书', 26, 46, 7, '穀物のささげ物をするために、雄牛一頭に一エパ。雄羊一匹に一エパ。子羊については、手に入れることができる分でよい。油は一エパごとに一ヒンである。'),
('JPN', '以西结书', 26, 46, 8, '君主が入るときには門の玄関の間を通って入り、そこを通って出て行かなければならない。'),
('JPN', '以西结书', 26, 46, 9, 'しかし、民衆が例祭の日に主の前に入るとき、北の門を通って礼拝に来る者は南の門を通って出て行き、南の門を通って入る者は北の門を通って出て行かなければならない。自分が入った門を通って帰ってはならない。その反対側から出て行かなければならない。'),
('JPN', '以西结书', 26, 46, 10, '君主は、彼らが入るときに一緒に入り、彼らが出るときに一緒に出なければならない。'),
('JPN', '以西结书', 26, 46, 11, '祭りと例祭での穀物のささげ物は、雄牛一頭に一エパ、雄羊一匹に一エパ。子羊については献げることができる分量。油は一エパごとに一ヒンである。'),
('JPN', '以西结书', 26, 46, 12, 'また君主が、進んで献げるものとして全焼のささげ物を、あるいは、進んで献げるものとして交わりのいけにえを主に献げるときには、彼のために東向きの門を開けなければならない。彼は安息日に献げるのと同じように、全焼のささげ物と交わりのいけにえを献げなければならない。そして彼は出て行くが、出て行った後、その門は閉じられる。'),
('JPN', '以西结书', 26, 46, 13, 'あなたは毎日、傷のない一歳の子羊一匹を、全焼のささげ物として主に献げなければならない。これを毎朝、献げなければならない。'),
('JPN', '以西结书', 26, 46, 14, 'それに添えて、毎朝、六分の一エパの穀物のささげ物、上等の小麦粉に振りかけるための油三分の一ヒンを献げる。これが主への穀物のささげ物であり、永遠に続く掟である。'),
('JPN', '以西结书', 26, 46, 15, 'こうして、子羊、穀物のささげ物、そして油を、常供の全焼のささげ物として、毎朝、献げなければならない。」'),
('JPN', '以西结书', 26, 46, 16, '神である主はこう言われる。「もし君主が、贈り物として自分の相続地を自分の息子たちに与えるなら、それは息子たちのものとなり、それは相続地として彼らの所有地となる。'),
('JPN', '以西结书', 26, 46, 17, 'しかし、もし君主が自分の相続地の一部を、贈り物として奴隷の一人に与えるなら、それは解放の年まではその奴隷のものであるが、その後で君主に返される。ただ息子たちだけが、相続地を自分のものとすることができる。'),
('JPN', '以西结书', 26, 46, 18, '君主は、民の相続地を奪って民をその所有地から追い出してはならない。彼は自分の所有地から、息子たちに相続地を受け継がせなければならない。それは、わたしの民がその所有地から一人でも散らされないようにするためである。」'),
('JPN', '以西结书', 26, 46, 19, 'それから彼は私を、門のわきにある出入り口から、北向きになっている祭司たちの聖所の部屋に連れて行った。すると、西の方の隅に一つの場所があった。'),
('JPN', '以西结书', 26, 46, 20, '彼は私に言った。「ここは祭司たちが、代償のためのささげ物や罪のきよめのささげ物を煮たり、穀物のささげ物を焼いたりする場所である。これらの物を外庭に持ち出して、民を聖なるものとしないためである。」'),
('JPN', '以西结书', 26, 46, 21, '彼は私を外庭に連れ出し、庭の四隅を通らせた。すると庭の隅には、それぞれまた、ほかの庭があった。'),
('JPN', '以西结书', 26, 46, 22, '庭の四隅に仕切られた庭があり、それは長さ四十キュビト、幅三十キュビトで、四つともみな同じ寸法であった。'),
('JPN', '以西结书', 26, 46, 23, 'その四つとも周りは石の壁で囲まれ、石の壁の下の方には調理場が作られていた。'),
('JPN', '以西结书', 26, 46, 24, '彼は私に言った。「これは、神殿で奉仕をしている者が、民からのいけにえを煮る調理場である。」'),
('JPN', '以西结书', 26, 47, 1, '彼は私を神殿の入り口に連れ戻した。見ると、水が神殿の敷居の下から東の方へと流れ出ていた。神殿が東に向いていたからである。その水は祭壇の南、神殿の右側の下から流れていた。'),
('JPN', '以西结书', 26, 47, 2, '次に、彼は私を北の門から連れ出し、外を回らせ、東向きの外門に行かせた。見ると、水は右側から流れ出ていた。'),
('JPN', '以西结书', 26, 47, 3, 'その人は手に測り縄を持って東の方に出て行き、千キュビトを測り、私にその水を渡らせると、それは足首まであった。'),
('JPN', '以西结书', 26, 47, 4, '彼がさらに千キュビトを測り、私にその水を渡らせると、水は膝に達した。彼がさらに千キュビトを測り、私を渡らせると、水は腰に達した。'),
('JPN', '以西结书', 26, 47, 5, '彼がさらに千キュビトを測ると、水かさが増して渡ることのできない川となった。川は泳げるほどになり、渡ることのできない川となった。'),
('JPN', '以西结书', 26, 47, 6, '彼は私に「人の子よ、あなたはこれを見たか」と言って、私を川の岸に連れ帰った。'),
('JPN', '以西结书', 26, 47, 7, '私が帰って来て見ると、川の両岸に非常に多くの木があった。'),
('JPN', '以西结书', 26, 47, 8, '彼は私に言った。「この水は東の地域に流れて行き、アラバに下って海に入る。海に注ぎ込まれると、そこの水は良くなる。'),
('JPN', '以西结书', 26, 47, 9, 'この川が流れて行くどこででも、そこに群がるあらゆる生物は生き、非常に多くの魚がいるようになる。この水が入ると、そこの水が良くなるからである。この川が入るところでは、すべてのものが生きる。'),
('JPN', '以西结书', 26, 47, 10, '漁師たちは、そのほとりに立つ。エン・ゲディからエン・エグライムまでが網を干す場所になる。そこの魚は大海の魚のように、種類が非常に多くなる。'),
('JPN', '以西结书', 26, 47, 11, 'しかし、その沢と沼は水が良くならず、塩を取るのに使われる。'),
('JPN', '以西结书', 26, 47, 12, '川のほとりには、こちら側にもあちら側にも、あらゆる果樹が生長し、その葉も枯れず、実も絶えることがなく、毎月、新しい実をつける。その水が聖所から流れ出ているからである。その実は食物となり、その葉は薬となる。」'),
('JPN', '以西结书', 26, 47, 13, '神である主はこう言われる。「あなたがたがイスラエルの十二の部族に、この地を相続地として与えるときの境界は、次のとおりである。ヨセフには二つ分を与える。'),
('JPN', '以西结书', 26, 47, 14, 'あなたがたは、それを等分に割り当てなければならない。それは、わたしがかつて、あなたがたの父祖たちに与えると誓約したものである。この地は相続地としてあなたがたのものである。'),
('JPN', '以西结书', 26, 47, 15, 'その地の境界線は次のとおりである。北側は、大海からヘテロンの道を経て、レボ・ハマテ、ツェダデ、'),
('JPN', '以西结书', 26, 47, 16, 'ベロタ、および、ダマスコの領土とハマテの領土の間にあるシブライム、さらに、ハウランの領土に面したハツェル・ハ・ティコンに至る。'),
('JPN', '以西结书', 26, 47, 17, 'こうして、境界線は海から始まり、ダマスコの境界のハツァル・エナンに至り、北は北の方へ、ハマテの境界にまで至る。これが北側である。'),
('JPN', '以西结书', 26, 47, 18, '東側は、ハウランとダマスコの間と、ギルアデとイスラエルの地の間のヨルダン川が、東の海を経てタマルに至るまでの境界線である。これが東側である。'),
('JPN', '以西结书', 26, 47, 19, '南側は、タマルから南に向かって、メリバテ・カデシュの泉とエジプト川に至り、大海に至るまでである。これが南側である。'),
('JPN', '以西结书', 26, 47, 20, '西側は、大海が境界となり、レボ・ハマテに面した地点にまで至る。これが西側である。'),
('JPN', '以西结书', 26, 47, 21, 'あなたがたは、この地をイスラエルの部族ごとに割り当てなければならない。'),
('JPN', '以西结书', 26, 47, 22, 'あなたがたと、あなたがたの間で子を生んで、あなたがたの間に寄留している者とに、この地を自分たちの相続地として、くじで割り当てなければならない。あなたがたは彼らを、イスラエルの子らのうちに生まれた者と同じように扱わなければならない。彼らはイスラエルの部族の中にあって、あなたがたと一緒に、くじで相続地の割り当てを受けなければならない。'),
('JPN', '以西结书', 26, 47, 23, '寄留者には、その滞在している部族の中で、その相続地を与えなければならない──神である主のことば。'),
('JPN', '以西结书', 26, 48, 1, '部族の名は次のとおりである。北の端からヘテロンの道を経てレボ・ハマテに至り、北にハマテを望む、ダマスコの境界のハツァル・エナンまで──東側から西側まで──これがダンの分である。'),
('JPN', '以西结书', 26, 48, 2, 'ダンの地域に接して、東側から西側までがアシェルの分。'),
('JPN', '以西结书', 26, 48, 3, 'アシェルの地域に接して、東側から西側までがナフタリの分。'),
('JPN', '以西结书', 26, 48, 4, 'ナフタリの地域に接して、東側から西側までがマナセの分。'),
('JPN', '以西结书', 26, 48, 5, 'マナセの地域に接して、東側から西側までがエフライムの分。'),
('JPN', '以西结书', 26, 48, 6, 'エフライムの地域に接して、東側から西側までがルベンの分。'),
('JPN', '以西结书', 26, 48, 7, 'ルベンの地域に接して、東側から西側までがユダの分である。'),
('JPN', '以西结书', 26, 48, 8, 'ユダの地域に接して、東側から西側までが、あなたがたの献げる奉納地となる。その幅は二万五千キュビト、その長さは、東側から西側に及ぶ部族の割り当て地の一つと同じである。聖所はその中央にある。'),
('JPN', '以西结书', 26, 48, 9, 'あなたがたが主に献げる奉納地は、長さ二万五千キュビト、幅一万キュビトである。'),
('JPN', '以西结书', 26, 48, 10, '祭司たちへの聖なる奉納地は次のとおりである。北側は二万五千キュビト、西側は一万キュビトの幅、東側は一万キュビトの幅、南側は二万五千キュビトの長さである。主の聖所はその中央にある。'),
('JPN', '以西结书', 26, 48, 11, 'この区域は、ツァドクの子孫で聖なる者とされた祭司たちのものである。彼らは、イスラエルの子らが迷い出たとき、レビ人が迷い出たように迷い出ることなく、わたしへの務めを果たした。'),
('JPN', '以西结书', 26, 48, 12, '彼らの地域はレビ部族の地域に接し、奉納地のうちでも最も聖なる地である。'),
('JPN', '以西结书', 26, 48, 13, 'レビ部族の分は、祭司たちの地域に接して、長さ二万五千キュビト、幅一万キュビトである。すなわち、全体の長さは二万五千キュビト、幅は一万キュビトである。'),
('JPN', '以西结书', 26, 48, 14, '彼らはそのどの部分も、売ったり取り替えたりしてはならない。その初めの土地を譲り渡してはならない。主の聖なるものだからである。'),
('JPN', '以西结书', 26, 48, 15, '幅五千キュビト、長さ二万五千キュビトの残りの地所は、町の一般用であり、居住地と放牧地のためである。町はその中央に建てられなければならない。'),
('JPN', '以西结书', 26, 48, 16, 'その大きさは次のとおりである。北側は四千五百キュビト、南側は四千五百キュビト、東側は四千五百キュビト、西側は四千五百キュビトである。'),
('JPN', '以西结书', 26, 48, 17, 'また、町の放牧地は、北へ二百五十キュビト、南へ二百五十キュビト、東へ二百五十キュビト、西へ二百五十キュビトである。'),
('JPN', '以西结书', 26, 48, 18, '残りの地所の長さは、聖なる奉納地に接し、東へ一万キュビト、西へ一万キュビトである。それは聖なる奉納地に接している。そこから収穫した物は町の働き人の食物となる。'),
('JPN', '以西结书', 26, 48, 19, 'その町の働き人はイスラエルの全部族から出て、これを耕す。'),
('JPN', '以西结书', 26, 48, 20, '奉納地の全体は二万五千キュビト四方であり、あなたがたは、聖なる奉納地を町の所有地とともに献げることになる。'),
('JPN', '以西结书', 26, 48, 21, '聖なる奉納地と町の所有地の両側にある残りの地所は、君主のものである。これは二万五千キュビトの奉納地に面し、そこから東の境界までである。西の方も、その二万五千キュビトに面し、そこから西の境界までである。これは部族の割り当て地にも接していて、君主のものである。聖なる奉納地と神殿の聖所とは、その中央にある。'),
('JPN', '以西结书', 26, 48, 22, '君主の所有する地区の中にあるレビ人の所有地と、町の所有地を除いて、ユダの地域とベニヤミンの地域との間にある部分は、君主のものである。'),
('JPN', '以西结书', 26, 48, 23, 'なお、残りの部族は、東側から西側までがベニヤミンの分。'),
('JPN', '以西结书', 26, 48, 24, 'ベニヤミンの地域に接して、東側から西側までがシメオンの分。'),
('JPN', '以西结书', 26, 48, 25, 'シメオンの地域に接して、東側から西側までがイッサカルの分。'),
('JPN', '以西结书', 26, 48, 26, 'イッサカルの地域に接して、東側から西側までがゼブルンの分。'),
('JPN', '以西结书', 26, 48, 27, 'ゼブルンの地域に接して、東側から西側までがガドの分。'),
('JPN', '以西结书', 26, 48, 28, 'その境界線は、ガドの地域の南側を延び、タマルからメリバテ・カデシュの水、さらにエジプト川に沿って大海に至る。'),
('JPN', '以西结书', 26, 48, 29, '以上が、あなたがたがイスラエルの部族ごとに、相続地としてくじで分ける土地であり、以上が彼らの割り当て地である──神である主のことば。'),
('JPN', '以西结书', 26, 48, 30, '町の出口は次のとおりである。北側は四千五百キュビトの長さで、'),
('JPN', '以西结书', 26, 48, 31, '町の門にはイスラエルの部族の名がつけられている。北側の三つの門は、ルベンの門一つ、ユダの門一つ、レビの門一つ。'),
('JPN', '以西结书', 26, 48, 32, '東側も四千五百キュビトで、三つの門がある。ヨセフの門一つ、ベニヤミンの門一つ、ダンの門一つ。'),
('JPN', '以西结书', 26, 48, 33, '南側も四千五百キュビトの長さで、三つの門がある。シメオンの門一つ、イッサカルの門一つ、ゼブルンの門一つ。'),
('JPN', '以西结书', 26, 48, 34, '西側も四千五百キュビトで、三つの門がある。ガドの門一つ、アシェルの門一つ、ナフタリの門一つ。'),
('JPN', '以西结书', 26, 48, 35, '町の周囲は一万八千キュビト。この町の名は、その日から『主はそこにおられる』となる。」'),
('JPN', '但以理书', 27, 1, 1, 'ユダの王エホヤキムの治世の第三年に、バビロンの王ネブカドネツァルがエルサレムに来て、これを包囲した。'),
('JPN', '但以理书', 27, 1, 2, '主は、ユダの王エホヤキムと、神の宮の器の一部を彼の手に渡された。彼は、それをシンアルの地にある自分の神の神殿に持ち帰り、その器を自分の神の宝物倉に納めた。'),
('JPN', '但以理书', 27, 1, 3, '王は宦官の長アシュペナズに命じて、イスラエルの人々の中から、王族や貴族を数人選んで連れて来させた。'),
('JPN', '但以理书', 27, 1, 4, 'それは、その身に何の欠陥もなく、容姿が良く、あらゆる知恵に秀で、知識に通じ、洞察力に富み、王の宮廷に仕えるにふさわしく、また、カルデア人の文学とことばを教えるにふさわしい少年たちであった。'),
('JPN', '但以理书', 27, 1, 5, '王は、王が食べるごちそうや王が飲むぶどう酒から、毎日の分を彼らに割り当てた。三年間、彼らを養育して、その後で王に仕えさせることにした。'),
('JPN', '但以理书', 27, 1, 6, '彼らのうちには、ユダ族のダニエル、ハナンヤ、ミシャエル、アザルヤがいた。'),
('JPN', '但以理书', 27, 1, 7, '宦官の長は彼らに別の名前をつけた。すなわち、ダニエルにはベルテシャツァル、ハナンヤにはシャデラク、ミシャエルにはメシャク、アザルヤにはアベデ・ネゴと名をつけた。'),
('JPN', '但以理书', 27, 1, 8, 'ダニエルは、王が食べるごちそうや王が飲むぶどう酒で身を汚すまいと心に定めた。そして、身を汚さないようにさせてくれ、と宦官の長に願うことにした。'),
('JPN', '但以理书', 27, 1, 9, '神は、ダニエルが宦官の長の前に恵みとあわれみを受けられるようにされた。'),
('JPN', '但以理书', 27, 1, 10, '宦官の長はダニエルに言った。「私は、あなたがたの食べ物と飲み物を定めた王を恐れている。あなたがたの顔色が同年輩の少年たちよりもすぐれないのを、王がご覧になるのはよいことだろうか。あなたがたのせいで、私は王に首を差し出さなければならなくなる。」'),
('JPN', '但以理书', 27, 1, 11, 'そこでダニエルは、宦官の長がダニエル、ハナンヤ、ミシャエル、アザルヤのために任命した世話役に言った。'),
('JPN', '但以理书', 27, 1, 12, '「どうか十日間、しもべたちを試してください。私たちに野菜を与えて食べさせ、水を与えて飲ませてください。'),
('JPN', '但以理书', 27, 1, 13, 'そのようにして、私たちの顔色と、王が食べるごちそうを食べている少年たちの顔色を見比べて、あなたの見るところにしたがって、このしもべたちを扱ってください。」'),
('JPN', '但以理书', 27, 1, 14, '世話役は彼らのこの申し出を聞き入れ、十日間、彼らを試した。'),
('JPN', '但以理书', 27, 1, 15, '十日が終わると、彼らは、王が食べるごちそうを食べているどの少年よりも顔色が良く、からだつきも良かった。'),
('JPN', '但以理书', 27, 1, 16, 'そこで世話役は、彼らが食べるはずだったごちそうと飲むはずだったぶどう酒を取り下げ、彼らに野菜を与えることにした。'),
('JPN', '但以理书', 27, 1, 17, '神はこの四人の少年に、知識と、あらゆる文学を理解する力と、知恵を授けられた。ダニエルは、すべての幻と夢を解くことができた。'),
('JPN', '但以理书', 27, 1, 18, '少年たちを召し入れるために王が命じておいた日数が終わったので、宦官の長は彼らをネブカドネツァルの前に連れて行った。'),
('JPN', '但以理书', 27, 1, 19, '王が彼らと話してみると、すべての者の中でだれもダニエル、ハナンヤ、ミシャエル、アザルヤに並ぶ者はいなかった。そこで四人は王に仕えることになった。'),
('JPN', '但以理书', 27, 1, 20, '王は、知恵と悟りに関わる事柄を彼らに尋ねたが、彼らがそのすべてにおいて、国中のどんな呪法師、呪文師よりも十倍もまさっていることが明らかになった。'),
('JPN', '但以理书', 27, 1, 21, 'ダニエルはキュロス王の元年までそこにいた。'),
('JPN', '但以理书', 27, 2, 1, 'ネブカドネツァルの治世の第二年に、ネブカドネツァルは何度か夢を見た。そしてそのために心が騒ぎ、彼は眠れなかった。'),
('JPN', '但以理书', 27, 2, 2, 'そこで王は命令を出し、呪法師、呪文師、呪術者、カルデア人を呼んで、王にその夢の意味を告げるように命じた。彼らが来て王の前に立つと、'),
('JPN', '但以理书', 27, 2, 3, '王は彼らに言った。「私は夢を見たのだが、その夢の意味を知りたくて私の心は騒いだ。」'),
('JPN', '但以理书', 27, 2, 4, 'カルデア人たちは、アラム語で王に告げた。「王よ、永遠に生きられますように。どうぞその夢をしもべどもにお話しください。そうすれば、私どもはその意味をお示ししましょう。」'),
('JPN', '但以理书', 27, 2, 5, '王はカルデア人たちに答えた。「私の言うことは絶対である。もし、おまえたちが私にその夢とその意味を告げることができなければ、おまえたちは手足をばらばらにされ、おまえたちの家はごみの山となる。'),
('JPN', '但以理书', 27, 2, 6, 'しかし、もし夢とその意味を示せたら、贈り物と報酬と大きな栄誉を私から受けることになる。だから、夢とその意味を私に示せ。」'),
('JPN', '但以理书', 27, 2, 7, '彼らは再び答えた。「王が、しもべどもにその夢をお話しくださいますように。そうすれば、私どもは意味をお示ししましょう。」'),
('JPN', '但以理书', 27, 2, 8, '王は答えた。「私には、はっきり分かっている。おまえたちは私の言うことが絶対であると分かっているので、時をかせごうとしているのだ。'),
('JPN', '但以理书', 27, 2, 9, 'もしおまえたちがその夢を私に告げないなら、おまえたちへの判決はただ一つだ。おまえたちは時が変わるまで、偽りと欺きのことばを私の前に述べようと決めている。だから、どんな夢かを私に言え。そうすれば、おまえたちがその意味を示せるかどうか、私に分かるだろう。」'),
('JPN', '但以理书', 27, 2, 10, 'カルデア人たちは王の前で答えた。「この地上には、王の心のうちを明らかにできる者は一人もおりません。どんな偉大な権力のある王でも、このようなことを呪法師や呪文師、あるいはカルデア人に尋ねたことはかつてありません。'),
('JPN', '但以理书', 27, 2, 11, '王がお求めになっていることは、難しいことです。肉なる者と住まいをともにされない神々以外に、それを王の前に示すことができる者はおりません。」'),
('JPN', '但以理书', 27, 2, 12, '王は怒り、大いにたけり狂い、バビロンの知者をすべて滅ぼせと命じた。'),
('JPN', '但以理书', 27, 2, 13, 'この命令が発せられたので、知者たちは殺されることになった。また人々は、ダニエルとその同僚たちさえ捜して殺そうとした。'),
('JPN', '但以理书', 27, 2, 14, 'そのとき、ダニエルは、バビロンの知者たちを殺すためにやって来た王の親衛隊長アルヨクに、知恵と思慮深さをもって応対した。'),
('JPN', '但以理书', 27, 2, 15, '彼は王の全権を受けたアルヨクにこう言った。「どうしてこんなに急な命令が王から出たのでしょうか。」すると、アルヨクは事の次第をダニエルに知らせた。'),
('JPN', '但以理书', 27, 2, 16, 'そこでダニエルは王のところに行き、王にその夢の意味を示すため、しばらくの時を与えてくれるよう願った。'),
('JPN', '但以理书', 27, 2, 17, 'それからダニエルは自分の家に帰り、自分の同僚のハナンヤ、ミシャエル、アザルヤにこのことを知らせた。'),
('JPN', '但以理书', 27, 2, 18, 'それは、ダニエルとその同僚たちがほかのバビロンの知者たちと一緒に滅ぼされることがないように、この秘密について天の神にあわれみを乞うためであった。'),
('JPN', '但以理书', 27, 2, 19, 'そのとき、夜の幻のうちにこの秘密がダニエルに明らかにされた。ダニエルは天の神をほめたたえた。'),
('JPN', '但以理书', 27, 2, 20, 'ダニエルはこう言った。「神の御名はほむべきかな。とこしえからとこしえまで。知恵と力は神のもの。'),
('JPN', '但以理书', 27, 2, 21, '神は季節と時を変え、王を廃し、王を立てる。知恵を授けて賢者とし、知識を授けて悟りのある者とされる。'),
('JPN', '但以理书', 27, 2, 22, '神は、深遠なこと、隠されていることを明らかにし、闇の中に何があるかを知り、ご自分の内に光を宿される。'),
('JPN', '但以理书', 27, 2, 23, '私の父祖の神よ。私はあなたに感謝し、あなたを賛美します。あなたは私に知恵と力を授け、今、私たちが尋ねたことを私に明かし、王の心のうちを私たちに明かしてくださいました。」'),
('JPN', '但以理书', 27, 2, 24, 'それでダニエルは、王がバビロンの知者たちを滅ぼすために任じたアルヨクのもとに行き、彼にこう言った。「バビロンの知者たちを滅ぼしてはなりません。私を王の前に連れて行ってください。私が王に夢の意味をお示しします。」'),
('JPN', '但以理书', 27, 2, 25, 'そこで、アルヨクは急いでダニエルを王の前に連れて行き、王にこう言った。「ユダからの捕虜の中に、王に夢の意味を告げることができる男を見つけました。」'),
('JPN', '但以理书', 27, 2, 26, 'それで王は、ベルテシャツァルという名のダニエルに言った。「私が見た夢とその意味を、本当に私に告げることができるのか。」'),
('JPN', '但以理书', 27, 2, 27, 'ダニエルは王に答えた。「王が求めておられる秘密を王にお示しすることは、知者や、呪文師、呪法師、占星術師などにはできません。'),
('JPN', '但以理书', 27, 2, 28, 'しかし天に秘密を明らかにするひとりの神がおられます。この方が終わりの日に起こることをネブカドネツァル王に示されたのです。あなたの夢、寝床であなたの頭に浮かんだ幻は次のとおりです。'),
('JPN', '但以理书', 27, 2, 29, '王よ。あなたが寝床で思い浮かべていたのは、これから起こることです。秘密を明らかにされる方が、これから起こることをお示しになったのです。'),
('JPN', '但以理书', 27, 2, 30, 'この秘密が私に明らかにされたのは、すべての生ける者にまさって私に知恵があるからではなく、その意味が王に告げられることによって、あなたの心の思いをご自身がお知りになるためです。'),
('JPN', '但以理书', 27, 2, 31, '王よ。あなたが見ておられると、なんと、一つの巨大な像が現れました。この像は巨大で、異常な輝きを放って、あなたの前に立っていました。その姿は恐ろしいものでした。'),
('JPN', '但以理书', 27, 2, 32, 'その像は、頭は純金、胸と両腕は銀、腹とももは青銅、'),
('JPN', '但以理书', 27, 2, 33, 'すねは鉄、足は一部が鉄、一部が粘土でした。'),
('JPN', '但以理书', 27, 2, 34, 'あなたが見ておられると、一つの石が人手によらずに切り出され、その像の鉄と粘土の足を打ち、これを粉々に砕きました。'),
('JPN', '但以理书', 27, 2, 35, 'そのとき、鉄も粘土も青銅も銀も金も、みなともに砕け、夏の脱穀場の籾殻のようになり、風がそれを運んで跡形もなくなりました。そして、その像を打った石は大きな山となって全土をおおいました。'),
('JPN', '但以理书', 27, 2, 36, 'これがその夢でした。私たちはその意味を王の前に申し上げましょう。'),
('JPN', '但以理书', 27, 2, 37, '王の王である王よ。天の神はあなたに国と権威と力と栄誉を授け、'),
('JPN', '但以理书', 27, 2, 38, 'また人の子ら、野の生き物、空の鳥がどこに住んでいても、これをことごとくあなたの手に与えて、治めさせられました。あなたはあの金の頭です。'),
('JPN', '但以理书', 27, 2, 39, 'あなたの後に、あなたより劣るもう一つの国が起こり、その次の第三の青銅の国が全地を治めるようになります。'),
('JPN', '但以理书', 27, 2, 40, 'そして第四の王国ですが、それは鉄のように強い国です。鉄はすべてのものを砕いてつぶしますが、その国は、打ち砕く鉄のように、先の国々をすべて粉々に砕いてしまいます。'),
('JPN', '但以理书', 27, 2, 41, 'あなたがご覧になった足と足の指は、その一部が陶器師の粘土、一部が鉄でしたが、それは分裂した国のことです。その国にはある程度までは鉄の強さもありますが、あなたがご覧になったように、その鉄は粘土と混じり合っています。'),
('JPN', '但以理书', 27, 2, 42, 'その足の指が一部は鉄、一部は粘土であったように、その国は一部は強く、一部はもろいでしょう。'),
('JPN', '但以理书', 27, 2, 43, '鉄と粘土が混じり合っているのをあなたがご覧になったように、それらは子孫の間で互いに混じり合うでしょう。しかし鉄が粘土と混じり合わないように、それらが互いに団結することはありません。'),
('JPN', '但以理书', 27, 2, 44, 'この王たちの時代に、天の神は一つの国を起こされます。その国は永遠に滅ぼされることがなく、その国はほかの民に渡されず、反対にこれらの国々をことごとく打ち砕いて、滅ぼし尽くします。しかし、この国は永遠に続きます。'),
('JPN', '但以理书', 27, 2, 45, 'それは、一つの石が人手によらずに山から切り出され、その石が鉄と青銅と粘土と銀と金を打ち砕いたのを、あなたがご覧になったとおりです。大いなる神が、これから後に起こることを王に告げられたのです。その夢は正夢で、その意味も確かです。」'),
('JPN', '但以理书', 27, 2, 46, 'それで、ネブカドネツァル王はひれ伏してダニエルを拝し、ささげ物と芳ばしい香りを彼に献げるように命じた。'),
('JPN', '但以理书', 27, 2, 47, '王はダニエルに答えた。「あなたがこの秘密を明らかにすることができたからには、あなたがたの神こそ、神々の中の神、王たちの主、また秘密を明らかにする方であるに違いない。」'),
('JPN', '但以理书', 27, 2, 48, 'そこで王は、ダニエルを高い位に就けて、多くのすばらしい贈り物を与え、バビロン全州を治めさせて、バビロンのすべての知者たちをつかさどる長官とした。'),
('JPN', '但以理书', 27, 2, 49, '王は、ダニエルの願いによって、シャデラク、メシャク、アベデ・ネゴに、バビロン州の行政をつかさどらせた。しかしダニエルは王の宮廷にとどまった。'),
('JPN', '但以理书', 27, 3, 1, 'ネブカドネツァル王は金の像を造った。その高さは六十キュビト、その幅は六キュビトであった。彼はこれをバビロン州のドラの平野に建てた。'),
('JPN', '但以理书', 27, 3, 2, 'そして、ネブカドネツァル王は人を遣わして、太守、長官、総督、参議官、財務官、司法官、保安官、および諸州のすべての高官を召集し、ネブカドネツァル王が建てた像の奉献式に出席させることにした。'),
('JPN', '但以理书', 27, 3, 3, 'そこで太守、長官、総督、参議官、財務官、司法官、保安官、および諸州のすべての高官は、ネブカドネツァル王が建てた像の奉献式に集まり、ネブカドネツァルが建てた像の前に立った。'),
('JPN', '但以理书', 27, 3, 4, '伝令官は力強く叫んだ。「諸民族、諸国民、諸言語の者たちよ。あなたがたはこう命じられている。'),
('JPN', '但以理书', 27, 3, 5, 'あなたがたが角笛、二管の笛、竪琴、三角琴、ハープ、風笛、および、もろもろの楽器の音を聞いたときは、ひれ伏して、ネブカドネツァル王が建てた金の像を拝め。'),
('JPN', '但以理书', 27, 3, 6, 'ひれ伏して拝まない者はだれでも、即刻、火の燃える炉に投げ込まれる。」'),
('JPN', '但以理书', 27, 3, 7, 'それで、すべての民が角笛、二管の笛、竪琴、三角琴、ハープ、および、もろもろの楽器の音を聞いたとき、諸民族、諸国民、諸言語の者たちは、ひれ伏して、ネブカドネツァル王が建てた金の像を拝んだ。'),
('JPN', '但以理书', 27, 3, 8, 'このため、この機会に、あるカルデア人たちが進み出て、ユダヤ人たちを中傷して言った。'),
('JPN', '但以理书', 27, 3, 9, '彼らはネブカドネツァル王に告げた。「王よ、永遠に生きられますように。'),
('JPN', '但以理书', 27, 3, 10, '王よ。王は『角笛、二管の笛、竪琴、三角琴、ハープ、風笛、および、もろもろの楽器の音を聞く者は、すべてひれ伏して金の像を拝め。'),
('JPN', '但以理书', 27, 3, 11, 'ひれ伏して拝まない者はだれでも、火の燃える炉の中へ投げ込め』と命令されました。'),
('JPN', '但以理书', 27, 3, 12, 'あなたがバビロン州の行政をつかさどらせた何人かのユダヤ人がおります。シャデラク、メシャク、アベデ・ネゴです。王よ。この者たちはあなたを無視して、あなたの神々に仕えず、お建てになった金の像を拝みもいたしません。」'),
('JPN', '但以理书', 27, 3, 13, 'ネブカドネツァルは怒り狂い、シャデラク、メシャク、アベデ・ネゴを連れて来るように命じた。それでこの三人は王の前に連れて来られた。'),
('JPN', '但以理书', 27, 3, 14, 'ネブカドネツァルは彼らに対して言った。「シャデラク、メシャク、アベデ・ネゴよ。おまえたちは私の神々に仕えず、また私が建てた金の像を拝みもしないというが、本当か。'),
('JPN', '但以理书', 27, 3, 15, '今、もしおまえたちが、角笛、二管の笛、竪琴、三角琴、ハープ、風笛、および、もろもろの楽器の音を聞いたとき、ひれ伏して、私が造った像を拝むなら、それでよい。しかし、もし拝まないなら、おまえたちは、即刻、火の燃える炉の中に投げ込まれる。どの神が、私の手からおまえたちを救い出せるだろうか。」'),
('JPN', '但以理书', 27, 3, 16, 'シャデラク、メシャク、アベデ・ネゴは王に答えた。「ネブカドネツァル王よ、このことについて、私たちはお答えする必要はありません。'),
('JPN', '但以理书', 27, 3, 17, 'もし、そうなれば、私たちが仕える神は、火の燃える炉から私たちを救い出すことができます。王よ、あなたの手からでも救い出します。'),
('JPN', '但以理书', 27, 3, 18, 'しかし、たとえそうでなくても、王よ、ご承知ください。私たちはあなたの神々には仕えず、あなたが建てた金の像を拝むこともしません。」'),
('JPN', '但以理书', 27, 3, 19, 'すると、ネブカドネツァルは怒りに満ち、シャデラク、メシャク、アベデ・ネゴに対する顔つきが変わった。彼は炉を普通より七倍熱くするように命じた。'),
('JPN', '但以理书', 27, 3, 20, 'また彼の軍隊の中の特に力の強い者たちに、シャデラク、メシャク、アベデ・ネゴを縛って、火の燃える炉に投げ込むように命じた。'),
('JPN', '但以理书', 27, 3, 21, '三人は、上着や下着やかぶり物の衣服を着たまま縛られ、火の燃える炉の中に投げ込まれた。'),
('JPN', '但以理书', 27, 3, 22, '王の命令が急であり、炉が非常に熱かったので、その炎はシャデラク、メシャク、アベデ・ネゴを持ち上げた者たちを焼き殺した。'),
('JPN', '但以理书', 27, 3, 23, 'この三人、シャデラク、メシャク、アベデ・ネゴは、縛られたままで、火の燃える炉の中に落ちて行った。'),
('JPN', '但以理书', 27, 3, 24, 'そのとき、ネブカドネツァル王は驚いて急に立ち上がり、顧問たちに尋ねた。「われわれは三人の者を縛って火の中に投げ込んだのではなかったか。」彼らは王に答えた。「王様、そのとおりでございます。」'),
('JPN', '但以理书', 27, 3, 25, 'すると王は言った。「だが、私には、火の中を縄を解かれて歩いている四人の者が見える。しかも彼らは何の害も受けていない。第四の者の姿は神々の子のようだ。」'),
('JPN', '但以理书', 27, 3, 26, 'それから、ネブカドネツァルは火の燃える炉の口に近づいて言った。「シャデラク、メシャク、アベデ・ネゴ、いと高き神のしもべたちよ、出て来なさい。」そこで、シャデラク、メシャク、アベデ・ネゴは火の中から出た。'),
('JPN', '但以理书', 27, 3, 27, '太守、長官、総督、王の顧問たちが集まり、三人を見たが、火は彼らのからだに及んでおらず、髪の毛も焦げず、上着も以前と変わらず、火の臭いも彼らに移っていなかった。'),
('JPN', '但以理书', 27, 3, 28, 'ネブカドネツァルは言った。「ほむべきかな、シャデラク、メシャク、アベデ・ネゴの神。神は御使いを送って、このしもべたちを救い出された。王の命令に背いて、自分たちのからだを差し出しても神に信頼し、自分たちの神のほかはどんな神にも仕えず、また拝まないこの者たちを。'),
('JPN', '但以理书', 27, 3, 29, 'それゆえ、私は命令する。諸民族、諸国民、諸言語の者のうち、シャデラク、メシャク、アベデ・ネゴの神に対して不敬なことを口にする者はだれでも、八つ裂きにされ、その家はごみの山とされる。このように救い出すことのできる神は、ほかにないからだ。」'),
('JPN', '但以理书', 27, 3, 30, 'それから王は、シャデラク、メシャク、アベデ・ネゴをバビロン州で栄えさせた。'),
('JPN', '但以理书', 27, 4, 1, 'ネブカドネツァル王から、全地に住むすべての民族、国民、言語の者たちへ。あなたがたに平安が豊かにあるように。'),
('JPN', '但以理书', 27, 4, 2, 'いと高き神が私に行われたしるしと奇跡を知らせることは、私の喜びとするところである。'),
('JPN', '但以理书', 27, 4, 3, 'そのしるしのなんと偉大なことよ。その奇跡のなんと力強いことよ。その国は永遠にわたる国、その主権は代々限りなく続く。'),
('JPN', '但以理书', 27, 4, 4, '私ネブカドネツァルが私の家で心安らかに過ごし、私の宮殿で繁栄を極めていたとき、'),
('JPN', '但以理书', 27, 4, 5, '私は一つの夢を見たが、それが私を恐れさせた。私の寝床での、様々な幻想と頭に浮かんだ幻が、私をおびえさせた。'),
('JPN', '但以理书', 27, 4, 6, '私は命令を下し、バビロンの知者をみな、私の前に連れて来て、その夢の意味を告げさせようとした。'),
('JPN', '但以理书', 27, 4, 7, '呪法師、呪文師、カルデア人、占星術師たちが来たとき、私は彼らにその夢のことを話したが、彼らはその意味を私に告げることができなかった。'),
('JPN', '但以理书', 27, 4, 8, '最後にダニエルが私の前に来た。彼の名は私の神の名にちなんでベルテシャツァルと呼ばれ、彼には聖なる神の霊があった。私はその夢を彼に話した。'),
('JPN', '但以理书', 27, 4, 9, '「呪法師の長ベルテシャツァルよ、私は、聖なる神の霊がおまえにあり、どんな秘密もおまえには難しくないことを知っている。私の見た夢の幻はこうだ。その意味を言ってもらいたい。'),
('JPN', '但以理书', 27, 4, 10, '私の寝床で幻が頭に浮かんだ。私が眺めていると、見よ、地の中央に木があった。それは非常に高かった。'),
('JPN', '但以理书', 27, 4, 11, 'その木は生長して強くなり、その高さは天に届いて、地の果てのどこからもそれが見えた。'),
('JPN', '但以理书', 27, 4, 12, '葉は美しく、実も豊かで、その木にはすべてのものの食べ物があった。その木陰では野の獣が憩い、その枝には空の鳥が住み、すべての肉なるものはそれによって養われた。'),
('JPN', '但以理书', 27, 4, 13, '寝床で頭に浮かんだ幻の中で見ていると、見よ、一人の見張りの者、聖なる者が天から降りて来るではないか。'),
('JPN', '但以理书', 27, 4, 14, '彼は力強く叫んで、こう言った。『その木を切り倒し、枝を切り払え。その葉を振り落とし、実を投げ散らせ。獣をその下から、鳥をその枝から追い払え。'),
('JPN', '但以理书', 27, 4, 15, 'ただし、その根株は、鉄と青銅の鎖をかけて、地に、野の若草の中に残せ。天の露にぬれさせて、地の青草を獣と分け合うようにせよ。'),
('JPN', '但以理书', 27, 4, 16, 'その心を、人間の心から変えて、獣の心をそれに与え、七つの時をその上に過ぎ行かせよ。'),
('JPN', '但以理书', 27, 4, 17, 'この宣言は見張りの者たちの決定によるもの、この要請は聖なる者たちのことばによるもの。これは、いと高き方が人間の国を支配し、これをみこころにかなう者に与え、また人間の中の最も低い者をその上に立てることを、いのちある者たちが知るためである。』'),
('JPN', '但以理书', 27, 4, 18, '私ネブカドネツァル王が見た夢とはこれだ。ベルテシャツァルよ、おまえはその意味を述べよ。私の国の知者たちはだれも、その意味を私に告げることができない。しかし、おまえにはできる。おまえには、聖なる神の霊があるからだ。」'),
('JPN', '但以理书', 27, 4, 19, 'そのとき、ベルテシャツァルと呼ばれていたダニエルは、しばらくの間驚きすくみ、いろいろと思い巡らして動揺した。王は話しかけた。「ベルテシャツァルよ、この夢とその意味のことで動揺することはない。」ベルテシャツァルは答えた。「わが主よ、どうか、この夢があなたを憎む者たちに当てはまり、その意味があなたの敵に当てはまりますように。'),
('JPN', '但以理书', 27, 4, 20, 'あなたがご覧になった木、すなわち、生長して強くなり、その高さが天に届いて、地のどこからも見え、'),
('JPN', '但以理书', 27, 4, 21, '葉が美しく実も豊かで、すべてのものの食べ物があり、その下に野の獣が住み、その枝に空の鳥が宿った木、'),
('JPN', '但以理书', 27, 4, 22, '王よ、その木はあなたです。あなたは大きくなって強くなり、あなたの偉大さは増し加わって天に達し、あなたの主権は地の果てにまで及んでいます。'),
('JPN', '但以理书', 27, 4, 23, 'しかし王は、一人の見張りの者、聖なる者が天から降りて来てこう言うのをご覧になりました。『その木を切り倒して滅ぼせ。ただし、その根株は、鉄と青銅の鎖をかけて、地に、野の若草の中に残せ。彼を天の露にぬれさせて、七つの時がその上を過ぎ行くまで野の獣と青草を分け合うようにせよ。』'),
('JPN', '但以理书', 27, 4, 24, '王よ、その意味は次のとおりです。これは、わが主、王に届いた、いと高き方の決定です。'),
('JPN', '但以理书', 27, 4, 25, 'あなたは人間の中から追い出され、野の獣とともに住み、牛のように草を食べて、天の露にぬれることになります。こうして、あなたの上を七つの時が過ぎ行き、ついにあなたは、いと高き方が人間の国を支配し、これをみこころにかなう者にお与えになることを知るようになります。'),
('JPN', '但以理书', 27, 4, 26, '木の根株は残せと命じられていますので、天が支配するということをあなたが知るようになれば、あなたの国はあなたのために堅く立つでしょう。'),
('JPN', '但以理书', 27, 4, 27, 'それゆえ、王よ、私の勧告を快く受け入れて、正しい行いによってあなたの罪を除き、また貧しい者をあわれんであなたの咎を除いてください。そうすれば、あなたの繁栄は長く続くでしょう。」'),
('JPN', '但以理书', 27, 4, 28, 'このことはみな、ネブカドネツァル王の身に起こった。'),
('JPN', '但以理书', 27, 4, 29, '十二か月たって、バビロンにある王の宮殿の屋上を歩きながら、'),
('JPN', '但以理书', 27, 4, 30, '王はこう言っていた。「この大バビロンは、王の家とするために、また、私の威光を輝かすために、私が私の権力によって建てたものではないか。」'),
('JPN', '但以理书', 27, 4, 31, 'このことばがまだ王の口にあるうちに、天から声があった。「ネブカドネツァル王よ、あなたに告げる。国はあなたから取り去られた。'),
('JPN', '但以理书', 27, 4, 32, 'あなたは人間の中から追い出され、野の獣とともに住み、牛のように草を食べるようになり、こうしてあなたの上を七つの時が過ぎ行き、ついにあなたは、いと高き方が人間の国を支配し、これをみこころにかなう者にお与えになることを知るようになる。」'),
('JPN', '但以理书', 27, 4, 33, 'このことばは、ただちにネブカドネツァルの上に成就した。彼は人の中から追い出され、牛のように草を食べ、そのからだは天の露にぬれて、ついに、彼の髪の毛は鷲のように、爪は鳥のように伸びた。'),
('JPN', '但以理书', 27, 4, 34, 'その期間が終わったとき、私ネブカドネツァルは目を上げて天を見た。すると私に理性が戻ってきた。私はいと高き方をほめたたえ、永遠に生きる方を賛美し、ほめたたえた。その主権は永遠の主権。その国は代々限りなく続く。'),
('JPN', '但以理书', 27, 4, 35, '地に住むものはみな、無きものと見なされる。この方は、天の軍勢にも、地に住むものにも、みこころのままに報いる。御手を差し押さえて、「あなたは何をされるのか」と言う者もいない。'),
('JPN', '但以理书', 27, 4, 36, 'ちょうどそのとき私に理性が戻り、私の王国の栄光のために、私の威光と輝きが私に戻ってきた。私の顧問や貴族たちに求められて、私は王位に戻り、こうして絶大な権威が私に加えられた。'),
('JPN', '但以理书', 27, 4, 37, '今、私ネブカドネツァルは、天の王を賛美し、あがめ、ほめたたえる。そのみわざはことごとく真実であり、その道は正義である。また、高ぶって歩む者をへりくだらせることのできる方である。'),
('JPN', '但以理书', 27, 5, 1, 'ベルシャツァル王は、千人の貴族たちのために大宴会を催し、その千人の前でぶどう酒を飲んでいた。'),
('JPN', '但以理书', 27, 5, 2, 'ベルシャツァルは、酒の勢いに任せて、父ネブカドネツァルがエルサレムの宮から持ち出した金や銀の器を持って来るように命じた。王とその貴族たち、および王の側室たちや侍女たちがその器で飲むためであった。'),
('JPN', '但以理书', 27, 5, 3, 'そこで、エルサレムの神の宮の本殿から持ち出した金の器が運ばれて来たので、王とその貴族たち、および王の側室たちや侍女たちはその器で飲んだ。'),
('JPN', '但以理书', 27, 5, 4, '彼らはぶどう酒を飲み、金、銀、青銅、鉄、木、石の神々を賛美した。'),
('JPN', '但以理书', 27, 5, 5, 'ちょうどそのとき、人間の手の指が現れ、王の宮殿の塗り壁の、燭台の向こう側のところに何かを書き始めた。王は、何かを書くその手の先を見ていた。'),
('JPN', '但以理书', 27, 5, 6, 'すると、王の顔色は変わり、いろいろと思い巡らして動揺し、腰の関節はゆるみ、膝はがたがた震えた。'),
('JPN', '但以理书', 27, 5, 7, '王は大声で叫び、呪文師、カルデア人、占星術師たちを連れて来させた。王はバビロンの知者たちに言った。「だれでも、この文字を読んでその意味を私に示す者には、紫の衣を着せて首に金の鎖をかけ、この国の第三の権力を持たせる。」'),
('JPN', '但以理书', 27, 5, 8, 'そのとき王の知者たちがみな入って来たが、彼らは、その文字を読むことも、王にその意味を告げることもできなかった。'),
('JPN', '但以理书', 27, 5, 9, 'それで、ベルシャツァル王はひどくおびえて、顔色が変わり、貴族たちも途方に暮れた。'),
('JPN', '但以理书', 27, 5, 10, '王母は、王とその貴族たちとのやり取りを聞いて、宴会の広間に入って来た。王母は言った。「王よ、永遠に生きられますように。いろいろと思い巡らし動揺してはいけません。顔色を変えてはなりません。'),
('JPN', '但以理书', 27, 5, 11, 'あなたの王国には、聖なる神の霊の宿る人がいます。あなたの父上の時代、彼のうちに、才気と聡明さと、神々の知恵のような知恵があることが分かりました。あなたの父上であるネブカドネツァル王は、彼を呪法師、呪文師、カルデア人、占星術師たちの長として立てられました。'),
('JPN', '但以理书', 27, 5, 12, '王がベルテシャツァルと名づけたダニエルのうちに、夢を解き明かし、謎を解き、難問を解くすぐれた霊と知識と聡明さがあることが分かっていますので、今、ダニエルを召して、その解き明かしをさせましょう。」'),
('JPN', '但以理书', 27, 5, 13, 'そこで、ダニエルが王の前に連れて来られた。王はダニエルに対して言った。「私の父である王がユダから連れて来た、ユダからの捕虜の一人ダニエルとはおまえのことか。'),
('JPN', '但以理书', 27, 5, 14, 'おまえのうちには神々の霊が宿り、また、おまえのうちに、才気と聡明さとすぐれた知恵があることが分かったと聞いている。'),
('JPN', '但以理书', 27, 5, 15, 'ところで、私は、知者、呪文師たちを私の前に召し、この文字を読ませて、その意味を私に告げさせようとしたが、彼らはそのことばの意味を示すことができないでいる。'),
('JPN', '但以理书', 27, 5, 16, 'しかし、おまえは解釈することができ、難問を解くことができると聞いた。今、もしおまえが、その文字を読み、その意味を私に告げることができたなら、おまえに紫の衣を着せて首に金の鎖をかけ、この国の第三の権力を持たせよう。」'),
('JPN', '但以理书', 27, 5, 17, 'そのとき、ダニエルは王の前で答えた。「贈り物はご自分で取っておき、報酬はほかの人にお与えください。しかし私は、その文字を王のために読み、その意味を告げましょう。'),
('JPN', '但以理书', 27, 5, 18, '王よ。いと高き神は、まさしくあなたの父上ネブカドネツァルに、国と偉大さと栄光と威光をお与えになりました。'),
('JPN', '但以理书', 27, 5, 19, '神が父上にお与えになった偉大さによって、諸民族、諸国民、諸言語の者たちはことごとく、父上の前に震えおののきました。彼は思いのままに人を殺し、思いのままに人を生かし、思いのままに人を高め、思いのままに人を低くしました。'),
('JPN', '但以理书', 27, 5, 20, 'こうして彼は、心が高ぶり、霊が頑なになり、高慢にふるまったので、その王座から引きずり降ろされ、栄光を取り上げられました。'),
('JPN', '但以理书', 27, 5, 21, 'そして、人の中から追い出され、心は獣と等しくなり、野ろばとともに住み、牛のように草を食べることになり、からだは天の露にぬれて、ついにこう知るようになりました。いと高き神が人間の国を支配し、みこころにかなう者をその上にお立てになるのだと。'),
('JPN', '但以理书', 27, 5, 22, 'その子であるベルシャツァル王よ、あなたはこれらのことをすべて知っていながら、心を低くしませんでした。'),
('JPN', '但以理书', 27, 5, 23, 'それどころか、天の主に向かって高ぶり、その宮の器を自分の前に持って来させ、あなたと貴族たちとあなたの側室や侍女たちは、それを使ってぶどう酒を飲みました。あなたは、見ることも、聞くことも、知ることもできない銀、金、青銅、鉄、木、石の神々を賛美しました。しかしあなたの息をその手に握り、あなたのすべての道をご自分のものとされる神を、あなたはほめたたえませんでした。'),
('JPN', '但以理书', 27, 5, 24, 'そのため、神の前から手の先が送られて、この文字が書かれたのです。'),
('JPN', '但以理书', 27, 5, 25, 'その書かれた文字はこうです。『メネ、メネ、テケル、ウ・パルシン。』'),
('JPN', '但以理书', 27, 5, 26, 'そのことばの意味はこうです。『メネ』とは、神があなたの治世を数えて終わらせたということです。'),
('JPN', '但以理书', 27, 5, 27, '『テケル』とは、あなたが秤で量られて、目方の足りないことが分かったということです。'),
('JPN', '但以理书', 27, 5, 28, '『パルシン』とは、あなたの国が分割され、メディアとペルシアに与えられるということです。」'),
('JPN', '但以理书', 27, 5, 29, 'そこでベルシャツァルは命じて、ダニエルに紫の衣を着せ、金の鎖を首にかけさせ、彼がこの国の第三の権力者であると布告させた。'),
('JPN', '但以理书', 27, 5, 30, 'その夜、カルデア人の王ベルシャツァルは殺された。'),
('JPN', '但以理书', 27, 5, 31, 'そして、メディア人ダレイオスが、およそ六十二歳でその国を受け継いだ。'),
('JPN', '但以理书', 27, 6, 1, 'ダレイオスは、全国に任地を持つ百二十人の太守を任命して国を治めさせるのがよいと思った。'),
('JPN', '但以理书', 27, 6, 2, '彼はまた、彼らの上にダニエルを含む三人の大臣を置いた。これは、太守たちがこの三人に報告を行い、王が損害を被らないようにするためであった。'),
('JPN', '但以理书', 27, 6, 3, 'さて、このダニエルは、ほかの大臣や太守よりも際立って秀でていた。彼のうちにすぐれた霊が宿っていたからであった。そこで王は、彼を任命して全国を治めさせようと思った。'),
('JPN', '但以理书', 27, 6, 4, '大臣や太守たちは、国政についてダニエルを訴える口実を見つけようとしたが、何の口実も欠点も見つけられなかった。彼は忠実で、何の怠慢も欠点も見つからなかったのである。'),
('JPN', '但以理书', 27, 6, 5, 'そこでこの人たちは言った。「われわれはこのダニエルを訴えるための、いかなる口実も見つけられない。彼の神の律法のことで見つけるしかない。」'),
('JPN', '但以理书', 27, 6, 6, 'それでこの大臣と太守たちは、王のもとに押しかけて来て、こう言った。「ダレイオス王よ、永遠に生きられますように。'),
('JPN', '但以理书', 27, 6, 7, '王よ。国中の大臣、長官、太守、顧問、総督はみな、王が一つの法令を制定し、断固たる禁令を出していただくことに同意しました。すなわち今から三十日間、王よ、いかなる神にでも人にでも、あなた以外に祈願をする者は、だれでも獅子の穴に投げ込まれる、と。'),
('JPN', '但以理书', 27, 6, 8, '王よ、今、その禁令を制定し、変更されることのないようにその文書に署名し、取り消しのできないメディアとペルシアの法律としてください。」'),
('JPN', '但以理书', 27, 6, 9, 'そこで、ダレイオス王はその禁令の文書に署名した。'),
('JPN', '但以理书', 27, 6, 10, 'ダニエルは、その文書に署名されたことを知って自分の家に帰った。その屋上の部屋はエルサレムの方角に窓が開いていた。彼は以前からしていたように、日に三度ひざまずき、自分の神の前に祈って感謝をささげていた。'),
('JPN', '但以理书', 27, 6, 11, 'すると、この者たちが押しかけて来て、ダニエルが神に祈り求め、哀願しているのを見つけた。'),
('JPN', '但以理书', 27, 6, 12, 'そこで彼らは王の前に進み出て、王の禁令について言った。「王よ。王は今から三十日間、いかなる神にでも人にでも、あなた以外に祈願をする者は、だれでも獅子の穴に投げ込まれるという禁令に、署名されたのではありませんか。」王は答えた。「取り消しのできないメディアとペルシアの法律がそうであるように、そのことは確かである。」'),
('JPN', '但以理书', 27, 6, 13, 'そこで、彼らは王に告げた。「王よ。ユダからの捕虜の一人ダニエルは、あなたと、ご署名になった禁令を無視して、日に三度、自分勝手な祈願をしております。」'),
('JPN', '但以理书', 27, 6, 14, 'このことを聞いて王は非常に憂い、ダニエルを救おうと気遣った。そして彼を助け出そうと、日没まで手を尽くした。'),
('JPN', '但以理书', 27, 6, 15, 'そのとき、あの者たちが王のもとに押しかけて来て、王に言った。「王よ。王が制定したいかなる禁令や法令も、決して変更されることはないということが、メディアとペルシアの法律であることをご承知ください。」'),
('JPN', '但以理书', 27, 6, 16, 'それで王は命令を出し、ダニエルは連れて来られて、獅子の穴に投げ込まれた。王はダニエルに話しかけて言った。「おまえがいつも仕えている神が、おまえをお救いになるように。」'),
('JPN', '但以理书', 27, 6, 17, '一つの石が運ばれて来て、その穴の口に置かれた。王は王自身の印と貴族たちの印でそれを封印し、ダニエルについての処置が変えられないようにした。'),
('JPN', '但以理书', 27, 6, 18, 'こうして王は宮殿に帰り、一晩中断食をした。側女も召し寄せず、眠ることもしなかった。'),
('JPN', '但以理书', 27, 6, 19, '王は夜明けに日が輝き出すとすぐ、獅子の穴へ急いで行った。'),
('JPN', '但以理书', 27, 6, 20, 'その穴に近づくと、王はダニエルに悲痛な声で呼びかけ、こうダニエルに言った。「生ける神のしもべダニエルよ。おまえがいつも仕えている神は、おまえを獅子から救うことができたか。」'),
('JPN', '但以理书', 27, 6, 21, 'するとダニエルは王に語った。「王よ、永遠に生きられますように。'),
('JPN', '但以理书', 27, 6, 22, '私の神が御使いを送り、獅子の口をふさいでくださったので、獅子は私に何の危害も加えませんでした。それは、神の前に私が潔白であることが認められたからです。王よ、あなたに対しても、私は何も悪いことはしていません。」'),
('JPN', '但以理书', 27, 6, 23, '王は大いに喜び、ダニエルをその穴から引き上げるように命じた。ダニエルは穴から引き上げられたが、彼に何の傷も認められなかった。彼が神に信頼していたからである。'),
('JPN', '但以理书', 27, 6, 24, '王が命じたので、ダニエルを中傷した者たちが連れて来られて、その妻子とともに獅子の穴に投げ込まれた。彼らが穴の底に達しないうちに、獅子は彼らをわがものにして、その骨をことごとくかみ砕いてしまった。'),
('JPN', '但以理书', 27, 6, 25, 'それから、ダレイオス王は、全土に住むすべての民族、国民、言語の者たちに次のように書き送った。「あなたがたに平安が豊かにあるように。'),
('JPN', '但以理书', 27, 6, 26, '私はここに命じる。私の支配する国においてはどこででも、ダニエルの神の前に震えおののけ。この方こそ生ける神、永遠におられる方。その国は滅びることなく、その主権はいつまでも続く。'),
('JPN', '但以理书', 27, 6, 27, 'この方は人を救い、助け出し、天においても、地においても、しるしと奇跡を行われる。実に、獅子の手からダニエルを救い出された。」'),
('JPN', '但以理书', 27, 6, 28, 'このダニエルは、ダレイオスの治世とペルシア人キュロスの治世に栄えた。'),
('JPN', '但以理书', 27, 7, 1, 'バビロンの王ベルシャツァルの元年に、ダニエルは寝床で、ある夢と、頭に浮かぶ幻を見た。それからその夢を書き記し、事の次第を述べた。'),
('JPN', '但以理书', 27, 7, 2, 'ダニエルは言った。「私が夜、幻を見ていると、なんと、天の四方の風が大海をかき立てていた。'),
('JPN', '但以理书', 27, 7, 3, 'すると、四頭の大きな獣が海から上がって来た。その四頭はそれぞれ異なっていた。'),
('JPN', '但以理书', 27, 7, 4, '第一のものは獅子のようで、鷲の翼をつけていた。見ていると、その翼は抜き取られ、地から身を起こされて人間のように二本の足で立ち、人間の心が与えられた。'),
('JPN', '但以理书', 27, 7, 5, 'すると見よ、熊に似た別の第二の獣が現れた。その獣は横向きに寝ていて、その口の牙の間には三本の肋骨があった。すると、それに『起き上がって、多くの肉を食らえ』との声がかかった。'),
('JPN', '但以理书', 27, 7, 6, 'その後、見ていると、なんと、豹のような別の獣が現れた。その背には四つの鳥の翼があり、その獣には四つの頭があった。そしてそれに主権が与えられた。'),
('JPN', '但以理书', 27, 7, 7, 'その後また夜の幻を見ていると、なんと、第四の獣が現れた。それは恐ろしくて不気味で、非常に強かった。大きな鉄の牙を持っていて、食らってはかみ砕き、その残りを足で踏みつけていた。これは前に現れたすべての獣と異なり、十本の角を持っていた。'),
('JPN', '但以理书', 27, 7, 8, '私がその角を注意深く見ていると、なんと、その間から、もう一本の小さな角が出て来て、その角のために、初めの角のうち三本が引き抜かれた。よく見ると、この角には人間の目のような目があり、大言壮語する口があった。'),
('JPN', '但以理书', 27, 7, 9, '私が見ていると、やがていくつかの御座が備えられ、『年を経た方』が座に着かれた。その衣は雪のように白く、頭髪は混じりけのない羊の毛のよう。御座は火の炎、その車輪は燃える火で、'),
('JPN', '但以理书', 27, 7, 10, '火の流れがこの方の前から出ていた。幾千もの者がこの方に仕え、幾万もの者がその前に立っていた。さばきが始まり、いくつかの文書が開かれた。'),
('JPN', '但以理书', 27, 7, 11, 'そのとき、あの角が大言壮語する声がしたので、私は見続けた。すると、その獣は殺され、からだは滅ぼされて、燃える火に投げ込まれた。'),
('JPN', '但以理书', 27, 7, 12, '残りの獣は主権を奪われたが、定まった時期と季節まで、そのいのちは延ばされた。'),
('JPN', '但以理书', 27, 7, 13, '私がまた、夜の幻を見ていると、見よ、人の子のような方が天の雲とともに来られた。その方は『年を経た方』のもとに進み、その前に導かれた。'),
('JPN', '但以理书', 27, 7, 14, 'この方に、主権と栄誉と国が与えられ、諸民族、諸国民、諸言語の者たちはみな、この方に仕えることになった。その主権は永遠の主権で、過ぎ去ることがなく、その国は滅びることがない。'),
('JPN', '但以理书', 27, 7, 15, '私ダニエルの心は私のうちで悩み、頭に浮かんだ幻は私をおびえさせた。'),
('JPN', '但以理书', 27, 7, 16, '私は、傍らに立っていた者たちの一人に近づき、このことすべてについて、彼に願って確かめようとした。すると彼は私に答えて、そのことの意味を告げてくれた。'),
('JPN', '但以理书', 27, 7, 17, '『これら四頭の大きな獣は、地から起こる四人の王である。'),
('JPN', '但以理书', 27, 7, 18, 'しかし、いと高き方の聖徒たちが国を受け継ぎ、その国を永遠に、世々限りなく保つ。』'),
('JPN', '但以理书', 27, 7, 19, 'それから私は、第四の獣について確かめたいと思った。それは、ほかのすべての獣と異なっていて、非常に恐ろしく、牙は鉄、爪は青銅で、食らってはかみ砕いて、残りを足で踏みつけていた。'),
('JPN', '但以理书', 27, 7, 20, 'その頭には十本の角があり、もう一本の角が出て来て、そのために三本の角が抜け落ちた。その角には目があり、大言壮語する口があった。その角はほかの角よりも大きく見えた。'),
('JPN', '但以理书', 27, 7, 21, '私が見ていると、その角は聖徒たちに戦いを挑み、彼らに打ち勝った。'),
('JPN', '但以理书', 27, 7, 22, 'しかしそれは『年を経た方』が来られるまでのことであり、いと高き方の聖徒たちのためにさばきが行われ、聖徒たちが国を受け継ぐ時期が来た。'),
('JPN', '但以理书', 27, 7, 23, '彼はこう言った。『第四の獣は地に起こる第四の国。これは、ほかのすべての国と異なり、全土を食い尽くし、これを踏みつけ、かみ砕く。'),
('JPN', '但以理书', 27, 7, 24, '十本の角は、この国から立つ十人の王。彼らの後に、もう一人の王が立つ。彼は先の者たちと異なり、三人の王を打ち倒す。'),
('JPN', '但以理书', 27, 7, 25, 'いと高き方に逆らうことばを吐き、いと高き方の聖徒たちを悩ます。彼は時と法則を変えようとする。聖徒たちは、一時と二時と半時の間、彼の手に委ねられる。'),
('JPN', '但以理书', 27, 7, 26, 'しかし、さばきが始まり、彼の主権は奪われて、彼は完全に絶やされ、滅ぼされる。'),
('JPN', '但以理书', 27, 7, 27, '国と、主権と、天下の国々の権威は、いと高き方の聖徒である民に与えられる。その御国は永遠の国。すべての主権は彼らに仕え、服従する。』'),
('JPN', '但以理书', 27, 7, 28, 'ここでこの話は終わる。私ダニエルは、いろいろと思い巡らして動揺し、顔色が変わった。しかし、私はこのことを心にとどめた。」'),
('JPN', '但以理书', 27, 8, 1, 'ベルシャツァル王の治世の第三年、初めに私に幻が現れた後、私ダニエルにもう一つの幻が現れた。'),
('JPN', '但以理书', 27, 8, 2, '私は幻の中で見た。見ていると、私はエラム州にあるスサの城にいた。なお幻を見ていると、私はウライ川のほとりにいた。'),
('JPN', '但以理书', 27, 8, 3, '私が目を上げて見ると、なんと、一匹の雄羊が川岸に立っていた。それには二本の角があって、この二本の角は長かったが、一本はもう一本の角よりも長かった。その長いほうは、後に出て来たのであった。'),
('JPN', '但以理书', 27, 8, 4, '私はその雄羊が、西や、北や、南の方を角で突いているのを見た。どんな獣もそれに立ち向かうことができず、また、それから救い出す者もいなかった。雄羊は思いのままにふるまって、高ぶっていた。'),
('JPN', '但以理书', 27, 8, 5, '私が注意して見ていると、見よ、一匹の雄やぎが、地には触れずに全土を飛び回って、西からやって来た。その雄やぎには、際立った一本の角が額にあった。'),
('JPN', '但以理书', 27, 8, 6, 'この雄やぎは、川岸に立っているのを私が見た、あの二本の角を持つ雄羊に向かって、激しい勢いで突進した。'),
('JPN', '但以理书', 27, 8, 7, '見ていると、この雄やぎは雄羊に近づき、怒り狂って雄羊を打ち倒して、その二本の角をへし折ったが、雄羊にはこれに立ち向かう力がなかった。雄やぎは雄羊を地に投げ倒して踏みつけた。雄羊をこの雄やぎから救い出す者はいなかった。'),
('JPN', '但以理书', 27, 8, 8, 'この雄やぎは非常に高ぶったが、強くなったときにその大きな角が折れた。そしてその代わりに、天の四方に向かって、際立った四本の角が生え出て来た。'),
('JPN', '但以理书', 27, 8, 9, 'そのうちの一本の角から、もう一本の小さな角が生え出て、南と、東と、麗しい国に向かって、非常に大きくなっていった。'),
('JPN', '但以理书', 27, 8, 10, 'それは大きくなって天の軍勢に達し、天の軍勢と星のいくつかを地に落として、これを踏みつけ、'),
('JPN', '但以理书', 27, 8, 11, '軍の長に並ぶほどになり、彼から常供のささげ物を取り上げた。こうして、その聖所の基はくつがえされた。'),
('JPN', '但以理书', 27, 8, 12, '背きの行いにより、軍勢は常供のささげ物とともにその角に引き渡された。その角は真理を地に投げ捨て、事を行って成功した。'),
('JPN', '但以理书', 27, 8, 13, '私は、一人の聖なる者が語っているのを聞いた。すると、もう一人の聖なる者が、その語っている者に言った。「常供のささげ物や、あの荒らす者の背き、そして聖所と軍勢が踏みにじられるという幻は、いつまでのことか。」'),
('JPN', '但以理书', 27, 8, 14, 'すると彼は答えて言った。「二千三百の夕と朝が過ぎるまで。そのとき聖所の正しさが確認される。」'),
('JPN', '但以理书', 27, 8, 15, '私ダニエルは、この幻を見たとき、その意味を理解したいと願った。すると見よ、勇士のように見える者が私の正面に立った。'),
('JPN', '但以理书', 27, 8, 16, '私は、ウライ川の中ほどから「ガブリエルよ、この人にその幻を理解させよ」と呼びかけている人の声を聞いた。'),
('JPN', '但以理书', 27, 8, 17, '彼は私が立っているところに来た。彼が来たとき、私はおびえて、ひれ伏した。すると彼は私に言った。「悟れ、人の子よ。その幻は終わりの時のことである。」'),
('JPN', '但以理书', 27, 8, 18, '彼が私に語りかけたとき、私は地にひれ伏したまま意識を失った。しかし彼は私に触れ、その場に立ち上がらせて、'),
('JPN', '但以理书', 27, 8, 19, 'こう言った。「見よ。私は、終わりの憤りの時に起こることをあなたに知らせる。それは、終わりの定めの時に関わることだ。'),
('JPN', '但以理书', 27, 8, 20, 'あなたが見た二本の角を持つ雄羊は、メディアとペルシアの王である。'),
('JPN', '但以理书', 27, 8, 21, '毛深い雄やぎはギリシアの王であり、その額にある大きな角はその第一の王である。'),
('JPN', '但以理书', 27, 8, 22, 'その角が折れて、代わりに四本の角が生えたが、それは、その国から四つの国が起こるということである。しかし、第一の王のような勢力はない。'),
('JPN', '但以理书', 27, 8, 23, '彼らの治世の終わりに、その背く者たちが行き着くところに至ったとき、横柄で策にたけた一人の王が立つ。'),
('JPN', '但以理书', 27, 8, 24, '彼の力は強くなるが、自分の力によるのではない。彼は、驚くべき破壊を行って成功し、有力者たちと聖なる民を滅ぼす。'),
('JPN', '但以理书', 27, 8, 25, '狡猾さによってその手で欺きを成し遂げ、心は高ぶり、平気で多くの人を滅ぼし、君の君に向かって立ち上がる。しかし、人の手によらずに彼は砕かれる。'),
('JPN', '但以理书', 27, 8, 26, '先に告げられた夕と朝の幻、それは真実である。しかし、あなたはこの幻を秘めておけ。これはまだ、多くの日の後のことだから。」'),
('JPN', '但以理书', 27, 8, 27, '私ダニエルは、何日かの間病気になったままでいた。その後、起きて王の事務を執った。しかし、私はこの幻のことで驚きすくんでいた。それを理解できなかったのである。'),
('JPN', '但以理书', 27, 9, 1, 'メディア族のクセルクセスの子ダレイオスが、カルデア人の国の王となったその元年、'),
('JPN', '但以理书', 27, 9, 2, 'すなわち、その治世の第一年に、私ダニエルは、預言者エレミヤにあった主のことばによって、エルサレムの荒廃の期間が満ちるまでの年数が七十年であることを、文書によって悟った。'),
('JPN', '但以理书', 27, 9, 3, 'そこで私は、顔を神である主に向けて断食をし、粗布をまとって灰をかぶり、祈りと哀願をもって主を求めた。'),
('JPN', '但以理书', 27, 9, 4, '私は、私の神、主に祈り、告白した。「ああ、私の主、大いなる恐るべき神。あなたを愛し、あなたの命令を守る者には、契約を守って恵みを下さる方。'),
('JPN', '但以理书', 27, 9, 5, '私たちは罪ある者で不義をなし、悪を行って逆らい、あなたの命令と定めから外れました。'),
('JPN', '但以理书', 27, 9, 6, '私たちはまた、あなたのしもべである預言者たちが、御名によって私たちの王たち、首長たち、先祖たち、民衆すべてに語ったことばに、聞き従いませんでした。'),
('JPN', '但以理书', 27, 9, 7, '主よ。義はあなたにありますが、顔をおおう恥は私たちにあります。今日あるとおり、それはユダの人々、エルサレムの住民にあり、また、近くであれ遠くであれ、あなたが追い散らされた先のあらゆる国々にいる、すべてのイスラエルにあります。彼らがあなたの信頼を裏切ったためです。'),
('JPN', '但以理书', 27, 9, 8, '主よ。顔をおおう恥は私たちにあり、私たちの王たち、首長たち、および先祖たちにあります。私たちはあなたに対して罪を犯してきました。'),
('JPN', '但以理书', 27, 9, 9, 'あわれみと赦しは、私たちの神、主にあります。まことに、私たちは神に逆らいました。'),
('JPN', '但以理书', 27, 9, 10, '私たちは、私たちの神、主の御声に聞き従わず、しもべである預言者たちによって神が私たちに下さったみおしえにも、従って歩むことをしませんでした。'),
('JPN', '但以理书', 27, 9, 11, 'イスラエルはみな、あなたの律法を犯して離れ去り、御声に聞き従いませんでした。そのため、神のしもべモーセの律法に書かれているのろいの誓いが、私たちの上に降りかかりました。私たちが神の前に罪ある者であったからです。'),
('JPN', '但以理书', 27, 9, 12, '神は、大きなわざわいを私たちにもたらすことで、かつて私たちと、私たちを治めた指導者たちに対して告げられたみことばを成就されたのです。エルサレムの上に下ったほどのわざわいは、今まで天下になかったことです。'),
('JPN', '但以理书', 27, 9, 13, 'このわざわいはすべて、モーセの律法に書かれているとおりに、私たちの上に下りました。しかし私たちは、不義から立ち返って、あなたの真理によってさとくなれるように、自分たちの神、主に願うこともありませんでした。'),
('JPN', '但以理书', 27, 9, 14, '主はそのわざわいを下そうと待ち構えていて、それを私たちの上にもたらされました。私たちの神、主のなさったみわざはすべて正しく、私たちが御声に聞き従わなかったからです。'),
('JPN', '但以理书', 27, 9, 15, 'しかし今、私たちの神、主よ。ご自分の民を力強い御手をもってエジプトの地から導き出し、今日あるとおりに名を成された神よ。私たちは罪を犯して、悪を行いました。'),
('JPN', '但以理书', 27, 9, 16, '主よ。あなたのすべての義のわざにしたがって、どうか御怒りと憤りを、あなたの都エルサレムから、あなたの聖なる山から去らせてください。私たちの罪と私たちの先祖たちの咎のゆえに、エルサレムとあなたの民が、私たちの周囲のすべての者にとってそしりの的となっているからです。'),
('JPN', '但以理书', 27, 9, 17, '私たちの神よ。今、あなたのしもべの祈りと願いを聞き入れ、主ご自身のために、あなたの荒れ果てた聖所に御顔の光を照り輝かせてください。'),
('JPN', '但以理书', 27, 9, 18, '私の神よ。耳を傾けて聞いてください。目を開いて私たちの荒れすさんださまと、あなたの御名がつけられている都をご覧ください。私たちが御前に伏して願いをささげるのは、私たちの正しい行いによるのではなく、あなたの大いなるあわれみによるのです。'),
('JPN', '但以理书', 27, 9, 19, '主よ、聞いてください。主よ、お赦しください。主よ、心に留めて事を行ってください。私の神よ、あなたご自身のために、遅らせないでください。あなたの都と民には、あなたの名がつけられているのですから。」'),
('JPN', '但以理书', 27, 9, 20, '私がまだ語り、祈り、自分の罪と自分の民イスラエルの罪を告白し、私の神の聖なる山のために、私の神、主の前に伏して願いをささげていたとき、'),
('JPN', '但以理书', 27, 9, 21, 'すなわち、私がまだ祈りの中で語っていたとき、私が初めに幻の中で見たあの人ガブリエルが、すばやく飛んで来て私に近づいた。それは夕方のささげ物を献げるころであった。'),
('JPN', '但以理书', 27, 9, 22, '彼は私に悟らせようとしてこう告げた。「ダニエルよ。私は今、悟りによってあなたを賢明にさせようとして出て来た。'),
('JPN', '但以理书', 27, 9, 23, 'あなたが願いの祈りを始めたとき、一つのみことばが出されたので、私はそれを伝えに来た。あなたが特別に愛されている者だからだ。そのみことばを聞き分けて、その幻を理解せよ。'),
('JPN', '但以理书', 27, 9, 24, 'あなたの民とあなたの聖なる都について、七十週が定められている。それは、背きをやめさせ、罪を終わらせ、咎の宥めを行い、永遠の義をもたらし、幻と預言を確証し、至聖所に油注ぎを行うためである。'),
('JPN', '但以理书', 27, 9, 25, 'それゆえ、知れ。悟れ。エルサレムを復興し、再建せよとの命令が出てから、油注がれた者、君主が来るまでが七週。そして苦しみの期間である六十二週の間に、広場と堀が造り直される。'),
('JPN', '但以理书', 27, 9, 26, 'その六十二週の後、油注がれた者は断たれ、彼には何も残らない。次に来る君主の民が、都と聖所を破壊する。その終わりには洪水が伴い、戦いの終わりまで荒廃が定められている。'),
('JPN', '但以理书', 27, 9, 27, '彼は一週の間、多くの者と堅い契約を結び、半週の間、いけにえとささげ物をやめさせる。忌まわしいものの翼の上に、荒らす者が現れる。そしてついには、定められた破滅が、荒らす者の上に降りかかる。」'),
('JPN', '但以理书', 27, 10, 1, 'ペルシアの王キュロスの第三年に、ベルテシャツァルと名づけられていたダニエルに、あることばが示された。そのことばは真実で、大きな戦のことであった。彼はそのことばを理解し、その幻について悟った。'),
('JPN', '但以理书', 27, 10, 2, 'そのころ、私ダニエルは、三週間の喪に服していた。'),
('JPN', '但以理书', 27, 10, 3, '満三週間、ごちそうも食べず、肉もぶどう酒も口にせず、また身に油も塗らなかった。'),
('JPN', '但以理书', 27, 10, 4, '第一の月の二十四日に、私はティグリスという大きな川の岸にいた。'),
('JPN', '但以理书', 27, 10, 5, '私は目を上げた。見ると、そこに一人の人がいて、亜麻布の衣をまとい、腰にウファズの金の帯を締めていた。'),
('JPN', '但以理书', 27, 10, 6, 'そのからだは緑柱石のようで、顔は稲妻のよう、目は燃えるたいまつのようであった。また、腕と足は磨き上げた青銅のようで、彼の語る声は群衆の声のようであった。'),
('JPN', '但以理书', 27, 10, 7, 'この幻は、私ダニエル一人だけが見て、私と一緒にいた人たちはその幻を見なかった。しかし彼らは大きな恐怖に襲われ、身を隠して逃げ去った。'),
('JPN', '但以理书', 27, 10, 8, '私は一人残ってこの大きな幻を見た。内からは力が抜け、顔の輝きも一変して、力も保てなくなった。'),
('JPN', '但以理书', 27, 10, 9, '私は彼の語る声を聞いた。彼の語る声を聞きながら、顔を伏せて地に倒れ、深い眠りに陥った。'),
('JPN', '但以理书', 27, 10, 10, 'ちょうどそのとき、一つの手が私に触れて、膝と手のひらをついていた私を揺さぶった。'),
('JPN', '但以理书', 27, 10, 11, 'それから彼は私に言った。「特別に愛されている人ダニエルよ、私が今から語ることばをよく理解せよ。そこに立ち上がれ。私は今、あなたに遣わされたのだ。」彼がこのことばを私に語っている間に、私は震えながら立ち上がった。'),
('JPN', '但以理书', 27, 10, 12, '彼は私に言った。「恐れるな、ダニエル。あなたが心を定めて、悟りを得ようとし、自分の神の前で自らを戒めようとしたその最初の日から、あなたのことばは聞かれている。私が来たのは、あなたのことばのためだ。'),
('JPN', '但以理书', 27, 10, 13, 'ペルシアの国の君が二十一日間、私に対峙して立っていたが、そこに最高位の君の一人ミカエルが私を助けに来てくれた。私がペルシアの王たちのところに残されていたからだ。'),
('JPN', '但以理书', 27, 10, 14, '私は、終わりの日にあなたの民に起こることを分からせるために来た。その幻は来たるべき日を待たなくてはならないが。」'),
('JPN', '但以理书', 27, 10, 15, '彼が私にこのことを語っている間、私はうつむいて黙っていた。'),
('JPN', '但以理书', 27, 10, 16, 'ちょうどそのとき、人のような姿をした方が私の唇に触れた。それで私は口を開いて話し出し、私に向かって立っていた方に言った。「わが主よ。私はこの幻によって苦痛に襲われ、力を保てなくなりました。'),
('JPN', '但以理书', 27, 10, 17, 'わが主のしもべが、どうしてわが主と話せるでしょう。私には、もはや力はなく、息も残っていません。」'),
('JPN', '但以理书', 27, 10, 18, 'すると、人のように見える方が、再び私に触れて力づけてくれた。'),
('JPN', '但以理书', 27, 10, 19, 'その方は言った。「特別に愛されている人よ、恐れるな。安心せよ。強くあれ。強くあれ。」その方が私にそう言ったとき、私は奮い立って言った。「わが主よ、お話しください。あなたは私を力づけてくださいましたから。」'),
('JPN', '但以理书', 27, 10, 20, 'すると彼は言った。「私がなぜあなたのところに来たか、知っているか。今、私はペルシアの君と戦うために帰って行く。私が去ると、見よ、ギリシアの君がやって来る。'),
('JPN', '但以理书', 27, 10, 21, 'しかし、真理の書に記されていることを、あなたに知らせよう。私とともに奮い立って、彼らに立ち向かう者は、あなたがたの君ミカエルのほかにはいない。'),
('JPN', '但以理书', 27, 11, 1, '私はその彼を強くし、力づけるために、メディア人ダレイオスの元年に立ち上がった。」'),
('JPN', '但以理书', 27, 11, 2, '「今、私はあなたに真理を告げる。見よ。なお三人の王がペルシアに起こり、第四の者は、ほかのだれよりも、はるかに富む者となる。この者がその富によって強力になったとき、全世界を、とりわけギリシアの国を奮い立たせる。'),
('JPN', '但以理书', 27, 11, 3, '一人の勇敢な王が起こり、大きな権力をもって治め、思いのままにふるまう。'),
('JPN', '但以理书', 27, 11, 4, 'しかし彼が起こったとき、その国は崩壊し、天の四方に向けて分割される。その国は彼の子孫のものにはならず、また、彼が支配したほどの権力もなくなる。彼の国は根こそぎにされ、その子孫以外の者のものとなる。'),
('JPN', '但以理书', 27, 11, 5, '南の王が強くなる。しかし、彼よりもその軍の長の一人が強くなり、彼の権力よりも大きな権力をもって治める。'),
('JPN', '但以理书', 27, 11, 6, '何年かたって、彼らは同盟を結ぶ。和睦をするために南の王の娘が北の王に嫁ぐが、彼女の勢力は保たれず、彼の勢力も続かない。彼女は、自分を連れて来た者、自分を生んだ者、そのころ自分を力づけた者とともに引き渡される。'),
('JPN', '但以理书', 27, 11, 7, 'しかし、彼女の根から一つの芽が父に代わって起こる。そして北の王の軍に立ち向かい、その砦に攻め入り、これと戦って勝つ。'),
('JPN', '但以理书', 27, 11, 8, 'なお、彼は彼らの神々を、彼らが鋳た像や、銀と金の尊い器とともにエジプトに捕らえ移す。彼は何年かの間、北の王と関わりを持たない。'),
('JPN', '但以理书', 27, 11, 9, 'しかし、北の王は南の王の国に侵入し、そして自分の地に帰る。'),
('JPN', '但以理书', 27, 11, 10, 'しかし、その息子たちは戦いを仕掛け、おびただしい数の強力な大軍を集める。進みに進んで押し流すように越えて行き、そうしてまた敵の砦に戦いを仕掛ける。'),
('JPN', '但以理书', 27, 11, 11, '南の王は大いに怒って戦いに出て来て、彼と、すなわち北の王と戦う。北の王はおびただしい大軍を起こすが、その大軍は敵の手に渡される。'),
('JPN', '但以理书', 27, 11, 12, 'その大軍を打ち破ると南の王の心は高ぶり、数万人を倒す。しかし、勝利を得ることはない。'),
('JPN', '但以理书', 27, 11, 13, '北の王が再び、以前より大きな、おびただしい大軍を起こして、何年かの後、大軍勢と多くの武器をもって攻めて来るからである。'),
('JPN', '但以理书', 27, 11, 14, 'そのころ、多くの者が南の王に反抗して立ち上がり、あなたの民の暴徒たちも、高ぶって幻を実現させようとするが、失敗する。'),
('JPN', '但以理书', 27, 11, 15, 'しかし、北の王が来て塁を築き、城壁のある町を攻め取ると、南の軍勢は立ち向かうことができず、精兵たちでさえ立ち向かう力がない。'),
('JPN', '但以理书', 27, 11, 16, 'そのようにして、これを攻めて来る者は思いのままにふるまう。彼に立ち向かう者はいない。彼は麗しい国にとどまり、自分の手で滅ぼし尽くそうとする。'),
('JPN', '但以理书', 27, 11, 17, '彼は自分の国の総力を挙げて攻め入ろうと決意し、まず相手と和睦して娘の一人を与え、その国を滅ぼそうとする。しかしそれは成功せず、彼の思いどおりにはならない。'),
('JPN', '但以理书', 27, 11, 18, 'それで彼は島々に顔を向け、その多くを攻め取る。しかし、ある指揮官が彼に侮辱をやめさせるばかりか、かえってその侮辱を彼の上に返す。'),
('JPN', '但以理书', 27, 11, 19, '彼は自分の国の砦に引き返すが、つまずき、倒れていなくなる。'),
('JPN', '但以理书', 27, 11, 20, '彼に代わって、一人の人が起こる。彼は国の栄光のために、税を取り立てる者を行き巡らすが、数日のうちに、怒りにも戦いにもよらずに滅ぼされる。'),
('JPN', '但以理书', 27, 11, 21, '彼に代わって、一人の卑劣な者が起こる。彼には国の権威は与えられないが、不意にやって来て、巧みなことばを使って国を奪い取る。'),
('JPN', '但以理书', 27, 11, 22, '彼の前では、洪水のような軍勢も、契約の君主さえも一掃されて打ち砕かれる。'),
('JPN', '但以理书', 27, 11, 23, '彼は同盟を組んだ後で欺き、少ない人数で勢力を増していく。'),
('JPN', '但以理书', 27, 11, 24, '彼は不意にその州の肥沃な地域に侵入し、彼の父たちも、父の父たちもしなかったことを行う。彼は、そのかすめ奪った物、分捕り物、財宝を、自分たちの間で分け合う。彼は計略をめぐらして要塞を攻めるが、それは、時が来るまでのことである。'),
('JPN', '但以理书', 27, 11, 25, '彼は勢力と勇気を駆り立て、大軍勢を率いて南の王に立ち向かう。南の王も非常に強い大軍勢を率い、奮い立ってこれと戦うが、抵抗することができなくなる。南の王に対して計略をめぐらす者たちがいるからである。'),
('JPN', '但以理书', 27, 11, 26, '彼のごちそうにあずかる者たちが彼を滅ぼし、彼の軍勢は押し流され、多くの者が刺し殺されて倒れる。'),
('JPN', '但以理书', 27, 11, 27, 'この二人の王は、心で悪事を謀りながらも、一つの食卓に着いて、まやかしを言い合う。しかし、成功はしない。終わりは、まだ定めの時を待たなくてはならないからだ。'),
('JPN', '但以理书', 27, 11, 28, '彼は多くの財宝を携えて自分の国に帰る。彼の心は聖なる契約に敵対して事を行い、彼は自分の国に帰って行く。'),
('JPN', '但以理书', 27, 11, 29, '定めの時に、彼は再び南へ攻めて行くが、この二度目は初めの時のようではない。'),
('JPN', '但以理书', 27, 11, 30, 'キティムの船が彼に立ち向かって来るので、彼は落胆して引き返し、聖なる契約にいきりたって事を行う。彼は帰って行って、その聖なる契約を捨てた者たちに心を向けるようになる。'),
('JPN', '但以理书', 27, 11, 31, '彼の軍隊は立ち上がり、砦である聖所を冒し、常供のささげ物を取り払い、荒らす忌まわしいものを据える。'),
('JPN', '但以理书', 27, 11, 32, '彼は、契約に対して不誠実にふるまう者たちを巧言をもって堕落させるが、自分の神を知る人たちは堅く立って事を行う。'),
('JPN', '但以理书', 27, 11, 33, '民の中の賢明な者たちは、多くの人を悟らせる。彼らは、一時は剣にかかり、火に焼かれ、捕らわれの身となり、かすめ奪われて倒れる。'),
('JPN', '但以理书', 27, 11, 34, '彼らが倒れるとき、彼らへの助けは少なく、彼らにくみする者には巧みなことばを使う者が多い。'),
('JPN', '但以理书', 27, 11, 35, '賢明な者たちのうちには倒れる者もあるが、それは終わりの時までに、彼らが錬られ、清められ、白くされるためである。それは、定めの時がまだ来ないからである。'),
('JPN', '但以理书', 27, 11, 36, 'この王は思いのままにふるまい、すべての神よりも自分を高く上げて大いなるものとし、神々の神に向かって驚くべきことを語る。彼は栄えるが、ついには神の憤りで滅ぼし尽くされる。定められていることがなされるからである。'),
('JPN', '但以理书', 27, 11, 37, '彼は先祖の神々を心にかけず、女たちの慕うものも、どんな神々も心にかけない。すべてにまさって自分を大いなるものとするからだ。'),
('JPN', '但以理书', 27, 11, 38, 'その代わりに彼は砦の神をあがめ、金、銀、宝石、宝物をもって、彼の先祖たちが知らなかった神をあがめる。'),
('JPN', '但以理书', 27, 11, 39, '彼は異国の神の助けによって城壁のある砦を取り、彼が認める者には栄誉を増し加え、多くのものを治めさせて、代価として国土を分け与える。'),
('JPN', '但以理书', 27, 11, 40, '終わりの時に、南の王が彼と戦いを交える。北の王は戦車、騎兵、および大船団を率いて南の王を襲撃し、国々に侵入し、洪水のように通り過ぎる。'),
('JPN', '但以理书', 27, 11, 41, '彼は麗しい国に攻め入り、多くの者が倒れる。しかし、エドムとモアブ、またアンモン人のおもだった人々は、彼の手から逃げる。'),
('JPN', '但以理书', 27, 11, 42, '彼は国々に手を伸ばす。エジプトの地もその手を免れることはない。'),
('JPN', '但以理书', 27, 11, 43, '彼は金や銀の秘蔵物と、エジプトのすべての宝物を手に入れ、ルブ人とクシュ人が彼につき従う。'),
('JPN', '但以理书', 27, 11, 44, 'しかし、東と北からの知らせが彼をおびえさせる。彼は多くのものを絶滅させようとして、激しく怒って戦いに出て行く。'),
('JPN', '但以理书', 27, 11, 45, '彼は、海と聖なる麗しい山との間に、本営の天幕を張る。しかし、だれも助ける者はなく、ついに彼は終わりを迎える。'),
('JPN', '但以理书', 27, 12, 1, 'その時、あなたの国の人々を守る大いなる君ミカエルが立ち上がる。国が始まって以来その時まで、かつてなかったほどの苦難の時が来る。しかしその時、あなたの民で、あの書に記されている者はみな救われる。'),
('JPN', '但以理书', 27, 12, 2, 'ちりの大地の中に眠っている者のうち、多くの者が目を覚ます。ある者は永遠のいのちに、ある者は恥辱と、永遠の嫌悪に。'),
('JPN', '但以理书', 27, 12, 3, '賢明な者たちは大空の輝きのように輝き、多くの者を義に導いた者は、世々限りなく、星のようになる。'),
('JPN', '但以理书', 27, 12, 4, 'ダニエルよ。あなたは終わりの時まで、このことばを秘めておき、この書を封じておけ。多くの者は知識を増そうと捜し回る。」'),
('JPN', '但以理书', 27, 12, 5, '私ダニエルが見ていると、見よ、二人の人が立っていた。一人は川のこちら岸に、もう一人は川の向こう岸にいた。'),
('JPN', '但以理书', 27, 12, 6, 'その一人が、川の水の上にいる、あの亜麻布の衣を着た人に言った。「この不思議なことは、いつになると終わるのですか。」'),
('JPN', '但以理书', 27, 12, 7, 'すると私は、川の水の上にいる、あの亜麻布の衣を着た人が語るのを聞いた。彼はその右手と左手を天に向けて上げ、永遠に生きる方にかけて誓った。「それは、一時と二時と半時である。聖なる民の力を打ち砕くことが終わるとき、これらすべてのことが成就する。」'),
('JPN', '但以理书', 27, 12, 8, '私はこれを聞いたが、理解することができなかった。そこで私は尋ねた。「わが主よ、この終わりはどうなるのでしょう。」'),
('JPN', '但以理书', 27, 12, 9, '彼は言った。「ダニエルよ、行け。このことばは終わりの時まで秘められ、封じられているからだ。'),
('JPN', '但以理书', 27, 12, 10, '多くの者は身を清めて白くし、そうして錬られる。悪しき者どもは悪を行い、悪しき者どものだれも理解することがない。しかし、賢明な者たちは理解する。'),
('JPN', '但以理书', 27, 12, 11, '常供のささげ物が取り払われ、荒らす忌まわしいものが据えられる時から、千二百九十日がある。'),
('JPN', '但以理书', 27, 12, 12, '幸いなことよ。忍んで待ち、千三百三十五日に達する者は。'),
('JPN', '但以理书', 27, 12, 13, 'あなたは終わりまで歩み、休みに入れ。あなたは時の終わりに、あなたの割り当ての地に立つ。」'),
('JPN', '何西阿书', 28, 1, 1, 'ユダの王ウジヤ、ヨタム、アハズ、ヒゼキヤの時代、イスラエルの王、ヨアシュの子ヤロブアムの時代に、ベエリの子ホセアにあった主のことば。'),
('JPN', '何西阿书', 28, 1, 2, '主がホセアに語られたことのはじめ。主はホセアに言われた。「行って、姦淫の女と姦淫の子らを引き取れ。この国は主に背を向け、淫行にふけっているからだ。」'),
('JPN', '何西阿书', 28, 1, 3, '彼は行って、ディブライムの娘ゴメルを妻とした。彼女は身ごもって、彼に男の子を産んだ。'),
('JPN', '何西阿书', 28, 1, 4, '主は彼に言われた。「その子をイズレエルと名づけよ。しばらくすれば、わたしがイズレエルでの流血のゆえにエフーの家を罰し、イスラエルの家の王国を終わらせるからだ。'),
('JPN', '何西阿书', 28, 1, 5, 'その日、わたしはイズレエルの平原で、イスラエルの弓を折る。」'),
('JPN', '何西阿书', 28, 1, 6, 'ゴメルはまた身ごもって、女の子を産んだ。主は彼に言われた。「その子をロ・ルハマと名づけよ。わたしはもう二度とイスラエルの家をあわれむことはなく、決して彼らを赦さないからだ。'),
('JPN', '何西阿书', 28, 1, 7, 'しかし、わたしはユダの家をあわれみ、彼らの神、主として、彼らを救う。ただし、弓、剣、戦い、あるいは馬、騎兵によって救うのではない。」'),
('JPN', '何西阿书', 28, 1, 8, '彼女はロ・ルハマを乳離れさせると、身ごもって男の子を産んだ。'),
('JPN', '何西阿书', 28, 1, 9, '主は言われた。「その子をロ・アンミと名づけよ。あなたがたはわたしの民ではなく、わたしはあなたがたの神ではないからだ。」'),
('JPN', '何西阿书', 28, 1, 10, 'イスラエルの子らの数は、量ることも数えることもできない海の砂のようになる。「あなたがたはわたしの民ではない」と言われたその場所で、彼らは「生ける神の子ら」と言われる。'),
('JPN', '何西阿书', 28, 1, 11, 'ユダの人々とイスラエルの人々は一つに集められ、一人のかしらを立ててその地から上って来る。まことに、イズレエルの日は大いなるものとなる。'),
('JPN', '何西阿书', 28, 2, 1, '言え。あなたがたの兄弟には、「わたしの民」と。あなたがたの姉妹には、「あわれまれる者」と。'),
('JPN', '何西阿书', 28, 2, 2, '「問いただせ。あなたがたの母を問いただせ。彼女はわたしの妻ではなく、わたしは彼女の夫ではないから。その顔から淫行を、その乳房の間から姦淫を取り除け。'),
('JPN', '何西阿书', 28, 2, 3, 'そうでなければ、わたしは彼女の衣をはぎ取って裸にし、生まれた日のようにして彼女をさらし、荒野のようにし、砂漠の地のようにして、渇きで彼女を死なせる。'),
('JPN', '何西阿书', 28, 2, 4, '彼女の子らを、わたしはあわれまない。彼らは姦淫の子らだから。'),
('JPN', '何西阿书', 28, 2, 5, '彼らの母は姦淫を行い、彼らをはらんで恥をさらした。彼女は言ったものだ。『私の愛人たちの後について行こう。彼らはパンと水、羊毛と麻、油と飲み物をくれる』と。'),
('JPN', '何西阿书', 28, 2, 6, 'それゆえ、わたしは茨で彼女の道に垣根を巡らし、彼女が通い路を見つけないように石垣を積む。'),
('JPN', '何西阿书', 28, 2, 7, '彼女は愛人たちの後を追っても、追いつけない。彼らを捜し求めても、見つけられない。彼女は言う。『私は初めの夫のところに戻ろう。あのころは今よりも幸せだったから』と。'),
('JPN', '何西阿书', 28, 2, 8, 'しかし彼女は知らない。このわたしが、穀物と新しいぶどう酒と油を彼女に与えたのを。わたしが銀と金を多く与えると、彼らはそれをバアルに造り上げたのだ。'),
('JPN', '何西阿书', 28, 2, 9, 'それゆえ、わたしはその時になれば、わたしの穀物を取り返す。その時期になれば、わたしの新しいぶどう酒を。また、彼女の裸をおおっているわたしの羊毛と麻をはぎ取る。'),
('JPN', '何西阿书', 28, 2, 10, '今、わたしは彼女の恥を、愛人たちの目の前で暴く。彼女をわたしの手から救い出せる者はいない。'),
('JPN', '何西阿书', 28, 2, 11, 'わたしは彼女のすべての喜びを、祭り、新月祭、安息日、すべての例祭を終わらせる。'),
('JPN', '何西阿书', 28, 2, 12, '『これは、愛人たちが払ってくれた私への報酬』と彼女が言った、あのぶどうの木といちじくの木を荒れすたらせる。わたしはこれを林に変えて、野の獣が貪り食うようにする。'),
('JPN', '何西阿书', 28, 2, 13, '彼女がバアルの神々に仕えた日々のゆえに、わたしは彼女を罰する。彼女はバアルの神々に香をたき、耳輪や飾りを付けて愛人たちの後について行き、このわたしを忘れた。──主のことば。'),
('JPN', '何西阿书', 28, 2, 14, 'それゆえ、見よ、わたしは彼女を誘い、荒野に連れて行って優しく彼女に語ろう。'),
('JPN', '何西阿书', 28, 2, 15, 'わたしはそこを彼女のためにぶどう畑にし、アコルの谷を望みの門とする。その場所で彼女は答える。若いころのように、エジプトの地から上って来たときのように。'),
('JPN', '何西阿书', 28, 2, 16, 'その日になると──主のことば──あなたはわたしを『私の夫』と呼び、もう『私のバアル』とは呼ばない。'),
('JPN', '何西阿书', 28, 2, 17, 'わたしがもろもろのバアルの名を彼女の口から取り除く。その名はもう覚えられることはない。'),
('JPN', '何西阿书', 28, 2, 18, 'その日、わたしは彼らのために、野の獣、空の鳥、地面を這うものと契約を結ぶ。わたしは弓と剣と戦いを地から絶やし、彼らを安らかに休ませる。'),
('JPN', '何西阿书', 28, 2, 19, 'わたしは永遠に、あなたと契りを結ぶ。義とさばきと、恵みとあわれみをもって、あなたと契りを結ぶ。'),
('JPN', '何西阿书', 28, 2, 20, '真実をもって、あなたと契りを結ぶ。このとき、あなたは主を知る。'),
('JPN', '何西阿书', 28, 2, 21, 'その日、わたしは応えて言う。──主のことば──わたしは天に応え、天は地に応え、'),
('JPN', '何西阿书', 28, 2, 22, '地は、穀物と新しいぶどう酒と油に応え、それらはイズレエルに応える。'),
('JPN', '何西阿书', 28, 2, 23, 'わたしは、わたしのために地に彼女を蒔き、あわれまれない者をあわれむ。わたしは、わたしの民ではない者に『あなたはわたしの民』と言い、彼は『あなたは私の神』と応える。」'),
('JPN', '何西阿书', 28, 3, 1, '主は私に言われた。「再び行って、夫に愛されていながら姦通している女を愛しなさい。ちょうど、ほかの神々の方を向いて干しぶどうの菓子を愛しているイスラエルの子らを、主が愛しているように。」'),
('JPN', '何西阿书', 28, 3, 2, 'それで私は、銀十五シェケルと、大麦一ホメルと大麦一レテクで彼女を買い取り、'),
('JPN', '何西阿书', 28, 3, 3, '彼女に言った。「これから長く、私のところにとどまりなさい。もう姦淫をしたり、ほかの男と通じたりしてはいけない。私も、あなたにとどまろう。」'),
('JPN', '何西阿书', 28, 3, 4, 'これは、イスラエルの子らが、これから長く、王もなく、首長もなく、いけにえも石の柱もないところに、エポデもテラフィムもないところにとどまるからだ。'),
('JPN', '何西阿书', 28, 3, 5, 'その後で、イスラエルの子らは帰って来て、自分たちの神である主と、自分たちの王ダビデを尋ね求める。そして終わりの日には、主とそのすばらしさにおののく。'),
('JPN', '何西阿书', 28, 4, 1, 'イスラエルの子らよ、主のことばを聞け。主はこの地に住む者を訴えられる。この地には真実もなく、誠実さもなく、神を知ることもないからだ。'),
('JPN', '何西阿书', 28, 4, 2, '呪いと、欺きと、人殺しと、盗みと、姦通がはびこり、流血に流血が続いている。'),
('JPN', '何西阿书', 28, 4, 3, 'それゆえ、この地は喪に服し、そこに住む者はみな、野の獣、空の鳥とともに衰え果て、海の魚さえも一掃される。'),
('JPN', '何西阿书', 28, 4, 4, '「だれも口論してはならない。だれも人を責めてはならない。あなたの民は、祭司と口論する者のようだ。'),
('JPN', '何西阿书', 28, 4, 5, 'あなたは昼つまずき、預言者も、あなたとともに夜つまずく。わたしはあなたの母を滅ぼす。'),
('JPN', '何西阿书', 28, 4, 6, 'わたしの民は知識がないので滅ぼされる。あなたが知識を退けたので、わたしもあなたを退け、わたしの祭司としない。あなたがあなたの神のおしえを忘れたので、わたしもまた、あなたの子らを忘れる。'),
('JPN', '何西阿书', 28, 4, 7, '彼らは増えるにしたがって、ますますわたしに罪を犯した。わたしは彼らの栄光を恥に変える。'),
('JPN', '何西阿书', 28, 4, 8, '彼らは、わたしの民の罪のきよめのささげ物を貪り食い、民の咎に望みをかけている。'),
('JPN', '何西阿书', 28, 4, 9, '民も祭司も同じようになる。わたしはその生き方のゆえに彼らを罰し、その行いのゆえに彼らに報復する。'),
('JPN', '何西阿书', 28, 4, 10, '彼らは食べても満たされず、姦淫しても増えることはない。彼らが主を捨てて、姦淫を続けるからだ。'),
('JPN', '何西阿书', 28, 4, 11, 'ぶどう酒、新しいぶどう酒は良識を失わせる。'),
('JPN', '何西阿书', 28, 4, 12, 'わたしの民は木に伺いを立て、棒が彼らに事を告げる。これは、姦淫の霊が彼らを迷わせ、彼らが自分の神のもとを離れて、姦淫したからだ。'),
('JPN', '何西阿书', 28, 4, 13, '彼らは山々の頂でいけにえを献げ、丘の上で犠牲を供える。樫の木、ポプラ、テレビンの木の下で。その木陰が心地よいからだ。それで、あなたがたの娘は淫行をし、あなたがたの嫁は姦通をする。'),
('JPN', '何西阿书', 28, 4, 14, 'わたしは、あなたがたの娘が姦淫をしても、あなたがたの嫁が姦通をしても、罰しない。男たちは遊女とともに離れ去り、神殿娼婦とともにいけにえを献げている。悟ることのない民は滅びに落ちる。'),
('JPN', '何西阿书', 28, 4, 15, 'イスラエルよ。あなたが淫行をしても、ユダを咎ある者にさせてはならない。ギルガルに行ってはならない。ベテ・アベンに上ってはならない。『主は生きておられる』と誓ってはならない。'),
('JPN', '何西阿书', 28, 4, 16, 'まことに、頑なな雌牛のようにイスラエルは頑迷だ。今、主は彼らを広いところにいる子羊のように養うだろうか。'),
('JPN', '何西阿书', 28, 4, 17, 'エフライムは偶像にくみしている。そのなすに任せるがよい。'),
('JPN', '何西阿书', 28, 4, 18, '彼らは酒を飲んでは、淫行にふけり、淫らなふるまいで恥を愛してやまない。'),
('JPN', '何西阿书', 28, 4, 19, '風はその翼で彼らを巻き込む。彼らは自分たちのいけにえのゆえに恥を見る。」'),
('JPN', '何西阿书', 28, 5, 1, '「祭司たちよ、これを聞け。イスラエルの家よ、心せよ。王の家よ、耳を傾けよ。あなたがたにさばきが下る。あなたがたはミツパで罠となり、タボルの上に張られた網となったからだ。'),
('JPN', '何西阿书', 28, 5, 2, '曲がった者たちは殺戮を極めた。しかし、わたしは彼らすべてを懲らしめる。'),
('JPN', '何西阿书', 28, 5, 3, 'わたしはエフライムをよく知っている。イスラエルはわたしに隠されていない。今や、エフライムよ、あなたは姦淫をし、イスラエルは汚れてしまった。'),
('JPN', '何西阿书', 28, 5, 4, '彼らは、自分の悪行を捨てて自分の神に帰ろうとしない。姦淫の霊が彼らのうちにあり、彼らが主を知らないからだ。'),
('JPN', '何西阿书', 28, 5, 5, 'イスラエルの高慢はその顔に表れている。イスラエルとエフライムは、自分の不義につまずき、ユダも彼らとともにつまずく。'),
('JPN', '何西阿书', 28, 5, 6, '彼らは羊の群れ、牛の群れを連れて行き、主を尋ね求めるが、見つけることはない。主が彼らから離れ去ったのだ。'),
('JPN', '何西阿书', 28, 5, 7, '彼らは主を裏切り、他国人の子を生んだ。今や、新月の祭りが彼らとその地所を食い尽くす。'),
('JPN', '何西阿书', 28, 5, 8, 'ギブアで角笛を、ラマでラッパを吹き鳴らせ。ベテ・アベンでときの声をあげよ。ベニヤミンよ、うしろを警戒せよ。'),
('JPN', '何西阿书', 28, 5, 9, 'エフライムは懲らしめの日に、恐怖のもととなる。わたしはイスラエルの諸部族に、確かに起こることを知らせる。'),
('JPN', '何西阿书', 28, 5, 10, 'ユダの首長たちは、地境を移す者のようになった。わたしは彼らの上に激しい怒りを水のように注ぐ。'),
('JPN', '何西阿书', 28, 5, 11, 'エフライムは虐げられ、さばかれて打ち砕かれる。彼が自ら進んで人の決め事に従って歩んだからだ。'),
('JPN', '何西阿书', 28, 5, 12, 'わたしはエフライムにはシミのようになり、ユダの家には腐れのようになる。'),
('JPN', '何西阿书', 28, 5, 13, 'エフライムは自分の病を見た。ユダは自分の腫れものを。エフライムはアッシリアに行き、大王に人を遣わした。しかし、彼はあなたがたを癒やすことができず、あなたがたの腫れものも治せない。'),
('JPN', '何西阿书', 28, 5, 14, 'わたしが、エフライムには獅子のようになり、ユダの家には若い獅子のようになるからだ。わたし、このわたしが引き裂いて歩き、さらって行くが、助け出す者はだれもいない。'),
('JPN', '何西阿书', 28, 5, 15, 'わたしは自分のところに戻っていよう。彼らが罰を受け、わたしの顔を慕い求めるまで。彼らは苦しみながら、わたしを捜し求める。」'),
('JPN', '何西阿书', 28, 6, 1, 'さあ、主に立ち返ろう。主は私たちを引き裂いたが、また、癒やし、私たちを打ったが、包んでくださるからだ。'),
('JPN', '何西阿书', 28, 6, 2, '主は二日の後に私たちを生き返らせ、三日目に立ち上がらせてくださる。私たちは御前に生きる。'),
('JPN', '何西阿书', 28, 6, 3, '私たちは知ろう。主を知ることを切に追い求めよう。主は暁のように確かに現れ、大雨のように私たちのところに来られる。地を潤す、後の雨のように。'),
('JPN', '何西阿书', 28, 6, 4, '「エフライムよ、わたしはあなたに何をしようか。ユダよ、わたしはあなたに何をしようか。あなたがたの真実の愛は朝もやのよう、朝早く消え去る露のようだ。'),
('JPN', '何西阿书', 28, 6, 5, 'それゆえ、わたしは預言者たちによって彼らを切り倒し、わたしの口のことばで彼らを殺す。あなたへのさばきが、光のように出て行く。'),
('JPN', '何西阿书', 28, 6, 6, 'わたしが喜びとするのは真実の愛。いけにえではない。全焼のささげ物よりむしろ、神を知ることである。'),
('JPN', '何西阿书', 28, 6, 7, 'ところが、彼らはアダムのように契約を破り、そこでわたしを裏切った。'),
('JPN', '何西阿书', 28, 6, 8, 'ギルアデは不法を行う者の町、血の足跡に満ちている。'),
('JPN', '何西阿书', 28, 6, 9, '盗賊が人を待ち伏せするように、祭司たちは徒党を組み、シェケムへの道で人を殺す。彼らは実に淫らなことを行う。'),
('JPN', '何西阿书', 28, 6, 10, 'イスラエルの家にわたしはおぞましいことを見た。エフライムはそこで姦淫をし、イスラエルは汚れてしまった。'),
('JPN', '何西阿书', 28, 6, 11, 'ユダよ、あなたにも刈り入れが定まっている。わたしが、わたしの民を元どおりにするときに。」'),
('JPN', '何西阿书', 28, 7, 1, '「わたしがイスラエルを癒やすとき、エフライムの咎、サマリアの悪はあらわになる。彼らが偽りを行い、盗人が押し入り、外では略奪隊が襲うからだ。'),
('JPN', '何西阿书', 28, 7, 2, 'しかし、彼らは考えもしない。わたしが彼らのすべての悪を覚えていることを。今、彼らの悪行は彼らを取り囲んで、わたしの面前にある。'),
('JPN', '何西阿书', 28, 7, 3, '彼らは悪事によって王を、偽りによって首長たちを喜ばせる。'),
('JPN', '何西阿书', 28, 7, 4, '彼らはみな姦通する者。パンを焼くときの燃えるかまどのようだ。生地がこねられてから、ふくらむまでは、燃え立つことをやめている。'),
('JPN', '何西阿书', 28, 7, 5, 'われわれの王の日に、首長たちは酒の熱で気分が悪くなり、王は嘲る者たちと手を握る。'),
('JPN', '何西阿书', 28, 7, 6, '彼らは心をかまどのようにして、陰謀を企てる。夜通し、パンを焼く者は眠るが、朝になると、かまどは燃え立つ火のように燃えるのだ。'),
('JPN', '何西阿书', 28, 7, 7, '彼らはみな、かまどのように熱くなって、自分をさばく者たちを食い尽くす。自分の王たちもみな倒れる。彼らのうちだれ一人、わたしを呼び求める者はいない。'),
('JPN', '何西阿书', 28, 7, 8, 'エフライムは、もろもろの民の中に混じり込む。エフライムは、片面しか焼けていないパンだ。'),
('JPN', '何西阿书', 28, 7, 9, '他国人が彼の力を食い尽くしても、彼はそれに気づかない。白髪が生えても、彼はそれに気づかない。'),
('JPN', '何西阿书', 28, 7, 10, 'イスラエルの高慢はその顔に表れている。彼らは、自分たちの神、主に立ち返らず、このすべてがあっても、主を尋ね求めない。'),
('JPN', '何西阿书', 28, 7, 11, 'エフライムは愚かな鳩のようで、良識がない。エジプトを呼び求め、アッシリアに飛んで行く。'),
('JPN', '何西阿书', 28, 7, 12, '彼らが赴くとき、わたしは彼らの上に網を張り、空の鳥のように彼らを引き降ろす。彼らの群れの音を聞くとき、わたしは彼らを懲らしめる。'),
('JPN', '何西阿书', 28, 7, 13, 'わざわいだ、彼らは。わたしから離れ去ったのだから。彼らは、踏みにじられるがよい。わたしに背いたのだから。わたしが贖い出そうとしているのに、彼らはわたしに向かってまやかしを言う。'),
('JPN', '何西阿书', 28, 7, 14, '心からわたしに向かって叫ばずに、自分たちの床の上で泣きわめいている。穀物と新しいぶどう酒のためには群がって来る。しかし、わたしからは離れて行く。'),
('JPN', '何西阿书', 28, 7, 15, 'わたしが訓戒し、彼らの腕を強くしたのに、このわたしに対して悪事を企む。'),
('JPN', '何西阿书', 28, 7, 16, '彼らはいと高き方に立ち返らない。彼らは欺きの弓のようだ。彼らの首長たちは、ののしったために剣に倒れる。これはエジプトの地で、嘲りのもととなる。」'),
('JPN', '何西阿书', 28, 8, 1, '「あなたの口に角笛を当てよ。鷲のようなものが、主の宮の上にいる。彼らがわたしの契約を破り、わたしのおしえに背いたからだ。'),
('JPN', '何西阿书', 28, 8, 2, '彼らはわたしに向かって叫ぶ。『わが神よ、私たちイスラエルは、あなたを知っています』と。'),
('JPN', '何西阿书', 28, 8, 3, 'イスラエルは善を退けた。敵は彼らに追い迫る。'),
('JPN', '何西阿书', 28, 8, 4, '彼らは王を立てたが、わたしによってではない。首長を立てたが、わたしは知らない。彼らは自分の銀や金で自分のために偶像を造った。ただ断ち切られるために。'),
('JPN', '何西阿书', 28, 8, 5, 'サマリアよ、あなたの子牛は退けられる。わたしは彼らに向かって怒りを燃やす。いつになれば、彼らは罪のない者となれるのか。'),
('JPN', '何西阿书', 28, 8, 6, 'それはイスラエルから出たもの。それは職人が造ったもので、神ではない。サマリアの子牛は粉々に砕かれる。'),
('JPN', '何西阿书', 28, 8, 7, '彼らは風を蒔いて、つむじ風を刈り取る。麦には穂が出ないので、麦粉を作れない。作れたとしても、他国人がこれを食い尽くす。'),
('JPN', '何西阿书', 28, 8, 8, 'イスラエルは吞み込まれた。今や、彼らは国々の間にあって、だれにも喜ばれない器のようになった。'),
('JPN', '何西阿书', 28, 8, 9, '彼らは、ひとりぼっちの野ろばで、アッシリアへ上って行った。エフライムは愛を求めて贈り物をした。'),
('JPN', '何西阿书', 28, 8, 10, '彼らが諸国の民に物を贈っても、今、わたしはそれらを集める。彼らは、王や首長への貢ぎによって間もなく汚されることになる。'),
('JPN', '何西阿书', 28, 8, 11, 'エフライムは祭壇を増やして罪を犯すようになった。それらは彼にとって罪を犯すための祭壇となった。'),
('JPN', '何西阿书', 28, 8, 12, 'わたしが彼のために、多くのおしえを書いても、彼らはこれを他国人のもののように見なす。'),
('JPN', '何西阿书', 28, 8, 13, 'わたしへのささげ物のいけにえとして彼らが肉を献げて食べたとしても、主はこれを喜ばない。今、主は彼らの不義を覚え、その罪を罰する。彼らはエジプトに帰る。'),
('JPN', '何西阿书', 28, 8, 14, 'イスラエルは自分の造り主を忘れ、神殿をいくつも建てた。ユダは、城壁のある町々を増し加えた。しかし、わたしはその町々に火を放つ。火はその宮殿を焼き尽くす。」'),
('JPN', '何西阿书', 28, 9, 1, 'イスラエルよ、喜ぶな。諸国の民のように楽しむな。あなたは自分の神に背いて姦淫したからだ。あなたはすべての麦打ち場で姦淫の報酬を愛した。'),
('JPN', '何西阿书', 28, 9, 2, '打ち場も踏み場も彼らを養わない。新しいぶどう酒も彼らを裏切る。'),
('JPN', '何西阿书', 28, 9, 3, '彼らは主の地に住むことはない。エフライムはエジプトに帰り、また、アッシリアで汚れた物を食べる。'),
('JPN', '何西阿书', 28, 9, 4, '彼らは主にぶどう酒を注がず、自分たちのいけにえで主を喜ばせない。彼らのパンは喪中のパンのようで、これを食べる者はみな身を汚す。彼らのパンは自分のためだけ。主の宮に持ち込むことはできない。'),
('JPN', '何西阿书', 28, 9, 5, '例祭の日、主の祭りの日に、あなたがたは何をするのか。'),
('JPN', '何西阿书', 28, 9, 6, '見よ。彼らが破壊を逃れても、エジプトが彼らを集め、メンフィスが彼らを葬る。彼らが慕う銀には、いらくさが、彼らの天幕には、あざみがはびこる。'),
('JPN', '何西阿书', 28, 9, 7, '刑罰の日が来た。報復の日が来た。イスラエルに知らせよ。預言者は愚か者、霊の人は気のふれた者だ。これは、あなたの大きな不義のゆえ、激しい敵意のゆえである。'),
('JPN', '何西阿书', 28, 9, 8, 'エフライムの見張りは、私の神とともにいる。しかし預言者には、すべての道に罠が仕掛けられ、彼の神の家には憎しみがある。'),
('JPN', '何西阿书', 28, 9, 9, '彼らはギブアの日のように、心底まで堕落した。主は彼らの咎を心に留め、その罪を罰する。'),
('JPN', '何西阿书', 28, 9, 10, '「わたしはイスラエルを、荒野のぶどうのように見出し、あなたがたの先祖を、いちじくの木の初なりの実のように見ていた。バアル・ペオルにやって来たとき、彼らは恥ずべきものに身を委ね、自分たちが愛しているものと同じように、彼ら自身も忌まわしいものとなった。'),
('JPN', '何西阿书', 28, 9, 11, 'エフライム。その栄光は鳥のように飛び去り、産むことも、身ごもることも、宿すこともない。'),
('JPN', '何西阿书', 28, 9, 12, 'たとえ彼らが子どもを育てても、わたしは彼らに子を失わせ、人がいなくなるようにする。わたしが彼らを離れるとき、まことに、彼らにわざわいが来る。'),
('JPN', '何西阿书', 28, 9, 13, 'エフライムは、わたしが見たところ、牧場に植えられたツロのようであった。しかし今や、エフライムはその子らを屠り場に連れ出さなければならない。」'),
('JPN', '何西阿书', 28, 9, 14, '主よ、彼らに与えてください。あなたは何をお与えになりますか。彼らに与えてください。死産の胎を、涸れた乳房を。'),
('JPN', '何西阿书', 28, 9, 15, '「彼らのすべての悪はギルガルにある。わたしはそこで彼らを憎んだのだ。彼らの悪い行いのゆえに、わたしは彼らをわたしの宮から追い出し、もはや彼らを愛さない。その首長たちはみな頑迷な者だ。'),
('JPN', '何西阿书', 28, 9, 16, 'エフライムは打たれ、その根は枯れて、実も結ばない。たとえ子を産んでも、わたしはその胎の実である、いとし子を殺す。」'),
('JPN', '何西阿书', 28, 9, 17, '私の神は彼らを退ける。彼らが神に聞き従わなかったからだ。彼らは国々の間で、さすらい人となる。'),
('JPN', '何西阿书', 28, 10, 1, 'イスラエルは生い茂るぶどうの木。それは多くの実をつけた。実が増えるにしたがって祭壇の数を増やし、その地が豊かになるにしたがって石の柱を豊かにした。'),
('JPN', '何西阿书', 28, 10, 2, '彼らの心は偽りだ。今、彼らはその罰を受ける。主が彼らの祭壇を壊し、彼らの石の柱を踏みにじられる。'),
('JPN', '何西阿书', 28, 10, 3, '今、彼らは言う。「私たちに王はいない。私たちが主を恐れていないからだ。王がいても、私たちに何ができるだろうか。」'),
('JPN', '何西阿书', 28, 10, 4, '彼らは無駄口をきき、むなしい誓いを立てて契約を結ぶ。さばきは、畑の畝の毒草のように生い出る。'),
('JPN', '何西阿书', 28, 10, 5, 'サマリアの住民は、ベテ・アベンの子牛のことでおののく。その民はそのことで喪に服し、偶像に仕える祭司たち、その栄光を喜んでいた者たちも喪に服す。栄光が子牛から去ったからだ。'),
('JPN', '何西阿书', 28, 10, 6, 'それはアッシリアに持ち去られ、大王への贈り物となる。エフライムは恥を受け、イスラエルは自分のはかりごとで恥を見る。'),
('JPN', '何西阿书', 28, 10, 7, 'サマリアは滅び失せ、その王は水の面の木片のようだ。'),
('JPN', '何西阿书', 28, 10, 8, 'イスラエルの罪であるアベンの高き所は滅ぼし尽くされる。茨とあざみが彼らの祭壇の上に生い茂る。彼らは山々に向かって「私たちをおおえ」と言い、丘に向かって「私たちの上に崩れ落ちよ」と言う。'),
('JPN', '何西阿书', 28, 10, 9, '「イスラエルよ。ギブアの日以来、あなたは罪を犯してきた。そこで彼らは同じことを行っている。ギブアで、戦いがこの不法の民を襲わないだろうか。'),
('JPN', '何西阿书', 28, 10, 10, '彼らを懲らしめることがわたしの願いだ。二つの不義のために彼らが捕らえられるとき、諸国の民が集められて彼らに敵対する。'),
('JPN', '何西阿书', 28, 10, 11, 'エフライムは飼いならされた雌の子牛、麦打ち場で踏むことを好む。しかし、わたしはその美しい首にくびきを掛ける。わたしがエフライムに乗り、ユダが耕し、ヤコブが馬ぐわを引くようになる。'),
('JPN', '何西阿书', 28, 10, 12, 'あなたがたは正義の種を蒔き、誠実の実を刈り入れ、耕地を開拓せよ。今が主を求める時だ。ついに主は来て、正義の雨をあなたがたの上に降らせる。」'),
('JPN', '何西阿书', 28, 10, 13, 'あなたがたは悪を耕し、不正を刈り取り、偽りの実を食べた。それはあなたが自分の力に、自分の勇士の数に拠り頼んだからだ。'),
('JPN', '何西阿书', 28, 10, 14, 'あなたの民の中で戦塵が起こり、要塞はみな打ち滅ぼされる。戦いの日にシャルマンがベテ・アルベルを踏みにじったように、母親は子どもたちのそばで八つ裂きにされる。'),
('JPN', '何西阿书', 28, 10, 15, 'ベテルよ。あなたがたの悪があまりにもひどいので、このようなことがあなたがたになされる。夜明けには、イスラエルの王は全く滅ぼされる。'),
('JPN', '何西阿书', 28, 11, 1, '「イスラエルが幼いころ、わたしは彼を愛し、エジプトからわたしの子を呼び出した。'),
('JPN', '何西阿书', 28, 11, 2, '彼らは、呼べば呼ぶほどますます離れて行き、もろもろのバアルにいけにえを献げて、刻んだ像に犠牲を供えた。'),
('JPN', '何西阿书', 28, 11, 3, 'このわたしがエフライムに歩くことを教え、彼らを腕に抱いたのだ。しかし、わたしが彼らを癒やしたことを彼らは知らなかった。'),
('JPN', '何西阿书', 28, 11, 4, 'わたしは人間の綱、愛の絆で彼らを引いてきた。わたしは彼らにとってあごの口籠を外す者のようになり、彼らに手を伸ばして食べさせてきた。'),
('JPN', '何西阿书', 28, 11, 5, '彼はエジプトの地には帰らない。アッシリアが彼の王となる。彼らがわたしに立ち返ることを拒んだからだ。'),
('JPN', '何西阿书', 28, 11, 6, '剣は、その町々に対して荒れ狂い、かんぬきの取っ手を打ち砕き、彼らのはかりごとのゆえに、町々を食い尽くす。'),
('JPN', '何西阿书', 28, 11, 7, 'わたしの民は頑なにわたしに背いている。いと高き方に呼ばれても、ともにあがめようとはしない。'),
('JPN', '何西阿书', 28, 11, 8, 'エフライムよ。わたしはどうしてあなたを引き渡すことができるだろうか。イスラエルよ。どうしてあなたを見捨てることができるだろうか。どうしてあなたをアデマのように引き渡すことができるだろうか。どうしてあなたをツェボイムのようにすることができるだろうか。わたしの心はわたしのうちで沸き返り、わたしはあわれみで胸が熱くなっている。'),
('JPN', '何西阿书', 28, 11, 9, 'わたしは怒りを燃やして再びエフライムを滅ぼすことはしない。わたしは神であって、人ではなく、あなたがたのうちにいる聖なる者だ。わたしは町に入ることはしない。'),
('JPN', '何西阿书', 28, 11, 10, '彼らは主の後について行く。主は獅子のようにほえる。まことに主がほえると、子らは西から震えながらやって来る。'),
('JPN', '何西阿书', 28, 11, 11, '鳥のようにエジプトから、鳩のようにアッシリアの地から、彼らは震えながらやって来る。わたしは彼らを自分たちの家に住ませよう。──主のことば。'),
('JPN', '何西阿书', 28, 11, 12, 'わたしは、エフライムの偽りと、イスラエルの家の欺きで囲まれている。しかしユダは、なお神とともに歩み、聖なる方に対して忠実である。」'),
('JPN', '何西阿书', 28, 12, 1, 'エフライムは風を飼い、一日中、東風の後を追う。重ねるのは虚偽と暴行。アッシリアと契約を結び、エジプトに油を送る。'),
('JPN', '何西阿书', 28, 12, 2, '主には、ユダに対して言い分がある。主は、生き方に応じてヤコブを罰し、行いに応じて彼に報いる。'),
('JPN', '何西阿书', 28, 12, 3, 'ヤコブは母の胎で兄のかかとをつかみ、その力で神と争った。'),
('JPN', '何西阿书', 28, 12, 4, '御使いと格闘して勝ったが、泣いてこれに願った。ベテルでは神に出会い、神はそこで彼に語りかけた。'),
('JPN', '何西阿书', 28, 12, 5, '主は万軍の神。その呼び名は主。'),
('JPN', '何西阿书', 28, 12, 6, 'あなたは、あなたの神に立ち返り、誠実と公正を守り、絶えずあなたの神を待ち望め。'),
('JPN', '何西阿书', 28, 12, 7, '商人は手に欺きの秤を持ち、虐げることを好む。'),
('JPN', '何西阿书', 28, 12, 8, 'エフライムは言った。「確かに私は富んでいる。私には力がある。私のすべての勤労の実があれば、私のうちに、罪となる不義は見つからない。」'),
('JPN', '何西阿书', 28, 12, 9, '「しかしわたしは、エジプトの地にいたときから、あなたの神、主である。例祭の日のように、再びあなたを天幕に住まわせる。'),
('JPN', '何西阿书', 28, 12, 10, 'わたしは預言者たちに語ってきた。わたしが多くの幻を示し、預言者たちによってたとえを示したのだ。」'),
('JPN', '何西阿书', 28, 12, 11, 'ギルアデは不法そのもの。いや、彼らはむなしいものとなった。ギルガルで雄牛が献げられたが、その祭壇も、畑の畝の石くれの山になる。'),
('JPN', '何西阿书', 28, 12, 12, 'ヤコブはアラムの地に逃げて行き、イスラエルは妻を迎えるために働いた。妻を迎えるために羊の番をした。'),
('JPN', '何西阿书', 28, 12, 13, '主は一人の預言者によって、イスラエルをエジプトから連れ上り、一人の預言者によって、これを守られた。'),
('JPN', '何西阿书', 28, 12, 14, 'エフライムは主の激しい怒りを引き起こした。彼の主は、その血の責任を彼の上に下し、彼のそしりに報いを返される。'),
('JPN', '何西阿书', 28, 13, 1, '「エフライムは震えながら語ったとき、イスラエルの中であがめられた。しかし、バアルのことで咎ある者となって死んだ。'),
('JPN', '何西阿书', 28, 13, 2, '今、彼らは罪を重ね、自分のために銀で鋳物の像を造り、自分の考えで偶像を造った。これはみな、職人のわざ。彼らはこれについて言う。『人を献げる者たちは、子牛に口づけせよ』と。'),
('JPN', '何西阿书', 28, 13, 3, 'それゆえ、彼らは朝もやのように、朝早く消え去る露のようになる。打ち場から吹き散らされる籾殻のように、また、穴から出る煙のようになる。'),
('JPN', '何西阿书', 28, 13, 4, 'しかしわたしは、エジプトの地にいたときから、あなたの神、主である。あなたはわたしのほかに神を知らない。わたしのほかに救う者はいない。'),
('JPN', '何西阿书', 28, 13, 5, 'このわたしは荒野で、干ばつの地であなたを知っていた。'),
('JPN', '何西阿书', 28, 13, 6, 'しかし牧草で満腹したとき、彼らは満ち足り、心は高ぶり、そうしてわたしを忘れた。'),
('JPN', '何西阿书', 28, 13, 7, 'わたしは彼らに対して獅子のようになり、豹のように道端で待ち伏せる。'),
('JPN', '何西阿书', 28, 13, 8, '子を奪われた雌熊のように彼らに襲いかかり、彼らの胸をかき裂いて、その場で雌獅子のように食らう。野の獣は彼らを引き裂く。'),
('JPN', '何西阿书', 28, 13, 9, 'イスラエルよ、あなたは滅ぼされる。あなたの助け手である、わたしに背いたからだ。'),
('JPN', '何西阿书', 28, 13, 10, 'では、あなたの王はどこにいるのか。すべての町のうちで、あなたを救う者は。あなたをさばく者たちはどこにいるのか。かつてあなたが『私に王と高官たちを与えよ』と言った者たちは。'),
('JPN', '何西阿书', 28, 13, 11, 'わたしは、怒ってあなたに王を与え、また憤ってこれを奪い取る。'),
('JPN', '何西阿书', 28, 13, 12, 'エフライムの不義は束ねられ、その罪は蓄えられている。'),
('JPN', '何西阿书', 28, 13, 13, '子を産む女の激しい痛みが彼のところに来るが、彼は知恵のない子で、時が来ても、母の胎から出て来ない。'),
('JPN', '何西阿书', 28, 13, 14, 'わたしはよみの力から彼らを贖い出し、死から彼らを贖う。死よ、おまえのとげはどこにあるのか。よみよ、おまえの針はどこにあるのか。あわれみはわたしの目から隠されている。'),
('JPN', '何西阿书', 28, 13, 15, '彼は兄弟たちの中で栄えている。だが、東風が吹いて来て、主の息が荒野から立ち上り、水源は涸れ、泉は干上がる。それはすべての尊い器がある宝物倉を略奪する。'),
('JPN', '何西阿书', 28, 13, 16, 'サマリアは咎ある者となる。自分の神に逆らったからだ。彼らは剣に倒れ、幼子たちは八つ裂きにされ、妊婦たちは切り裂かれる。」'),
('JPN', '何西阿书', 28, 14, 1, 'イスラエルよ。あなたの神、主に立ち返れ。あなたは自分の不義につまずいたのだ。'),
('JPN', '何西阿书', 28, 14, 2, 'あなたがたはことばを用意し、主に立ち返れ。主に言え。「すべての不義を赦し、良きものを受け入れてください。私たちは唇の果実をささげます。'),
('JPN', '何西阿书', 28, 14, 3, 'アッシリアは私たちを救えません。私たちはもう馬に乗らず、自分たちの手で造った物に『私たちの神』と言いません。みなしごがあわれまれるのは、あなたによってです。」'),
('JPN', '何西阿书', 28, 14, 4, '「わたしは彼らの背信を癒やし、喜びをもって彼らを愛する。わたしの怒りが彼らから離れ去ったからだ。'),
('JPN', '何西阿书', 28, 14, 5, 'わたしはイスラエルにとって露のようになる。彼はゆりのように花咲き、レバノン杉のように根を張る。'),
('JPN', '何西阿书', 28, 14, 6, 'その若枝は伸び、その輝きはオリーブの木のように、その香りはレバノン杉のようになる。'),
('JPN', '何西阿书', 28, 14, 7, 'その陰に住むものたちは、穀物のように生き返り、ぶどうの木のように芽をふく。その名声はレバノンのぶどう酒のようになる。'),
('JPN', '何西阿书', 28, 14, 8, 'エフライムよ。わたしと偶像との間に、どういう関わりがあるか。わたしが応え、わたしが世話をする。わたしは緑のもみの木のようだ。わたしから、あなたは実を得るのだ。」'),
('JPN', '何西阿书', 28, 14, 9, '知恵ある者はだれか。その人はこれらのことを悟れ。悟りのある者はだれか。その人はそれらのことをよく知れ。主の道は平らだ。正しい者はこれを歩み、背く者はこれにつまずく。'),
('JPN', '约珥书', 29, 1, 1, 'ペトエルの子ヨエルにあった主のことば。'),
('JPN', '约珥书', 29, 1, 2, '「長老たちよ、これを聞け。この地に住む者もみな、耳を傾けよ。このようなことが、あなたがたの時代に、また先祖の時代にあっただろうか。'),
('JPN', '约珥书', 29, 1, 3, 'これをあなたがたの子どもたちに伝え、子どもたちはその子どもたちに、その子どもたちは後の世代に伝えよ。'),
('JPN', '约珥书', 29, 1, 4, '噛みいなごが残した物は、いなごが食い、いなごが残した物は、バッタが食い、バッタが残した物は、その若虫が食った。'),
('JPN', '约珥书', 29, 1, 5, '目を覚ませ、酔いどれよ。泣け。泣き叫べ、すべてぶどう酒を飲む者よ。甘いぶどう酒があなたがたの口から断たれたからだ。'),
('JPN', '约珥书', 29, 1, 6, 'ある国民がわたしの国に攻め上って来た。それは力強く、数えきれない。その歯は雄獅子の歯、それには雌獅子の牙がある。'),
('JPN', '约珥书', 29, 1, 7, 'それはわたしのぶどうの木を荒れすたらせ、わたしのいちじくの木を木っ端にした。これを丸裸に引きむき、投げ倒し、その枝々を真っ白にした。'),
('JPN', '约珥书', 29, 1, 8, '悼み悲しめ。粗布をまとったおとめが、その若いときの夫のためにするように。'),
('JPN', '约珥书', 29, 1, 9, '穀物と注ぎのささげ物は主の宮から断たれ、主に仕える祭司たちは喪に服す。'),
('JPN', '约珥书', 29, 1, 10, '畑は荒らされ、地も喪に服す。穀物が荒らされ、新しいぶどう酒も干上がり、油も涸れるからだ。'),
('JPN', '约珥书', 29, 1, 11, '恥を見よ、農夫たち。泣き叫べ、ぶどう作りたち。小麦と大麦のために。畑の刈り入れがなくなったからだ。'),
('JPN', '约珥书', 29, 1, 12, 'ぶどうの木は枯れ、いちじくの木はしおれた。ざくろも、なつめ椰子も、りんごも、野のすべての木々は枯れた。喜びが人の子らから消え去った。」'),
('JPN', '约珥书', 29, 1, 13, '粗布をまとって悼み悲しめ、祭司たちよ。泣き叫べ、祭壇に仕える者たちよ。私の神に仕える者たちよ、行って粗布をまとって夜を過ごせ。穀物と注ぎのささげ物があなたがたの神の宮から退けられたからだ。'),
('JPN', '约珥书', 29, 1, 14, '断食を布告し、きよめの集会を召集せよ。長老たちとこの国に住むすべての者を、あなたがたの神、主の宮に集め、主に向かって叫び求めよ。'),
('JPN', '约珥书', 29, 1, 15, 'ああ、その日よ。主の日は近い。全能者による破壊の日として、その日は来る。'),
('JPN', '约珥书', 29, 1, 16, '私たちの目の前で、食物が断たれ、私たちの神の宮から喜びも楽しみも消え失せたではないか。'),
('JPN', '约珥书', 29, 1, 17, '穀物の種は土の下で干からび、倉は荒れ果て、穴蔵は崩れた。穀物がしなびたからだ。'),
('JPN', '约珥书', 29, 1, 18, 'ああ、なんと家畜がうめいていることか。牛の群れはさまよう。牧場がないからだ。羊の群れも滅びる。'),
('JPN', '约珥书', 29, 1, 19, 'あなたに、主よ、私は呼び求めます。火が荒野の牧場を焼き尽くし、野のすべての木を炎がなめ尽くしました。'),
('JPN', '约珥书', 29, 1, 20, '野の獣も、あなたをあえぎ求めています。水の流れが涸れ、火が荒野の牧場を焼き尽くしたからです。'),
('JPN', '约珥书', 29, 2, 1, '「シオンで角笛を吹き鳴らし、わたしの聖なる山でときの声をあげよ。」地に住むすべての者は、恐れおののけ。主の日が来るからだ。その日は近い。'),
('JPN', '约珥书', 29, 2, 2, 'それは闇と暗闇の日。雲と暗黒の日。数が多く、力の強い民が、暁とともに山々の上に進んで来る。このようなことは、昔から起こったことがなく、これから後、代々の時代までも再び起こることはない。'),
('JPN', '约珥书', 29, 2, 3, '彼らの前は火が焼き尽くし、うしろは炎がなめ尽くす。彼らが来る前は、この地はエデンの園のよう。しかし、去った後は、荒れ果てた荒野となる。これから逃れるものは何もない。'),
('JPN', '约珥书', 29, 2, 4, 'その姿は馬さながら、軍馬のように駆け巡る。'),
('JPN', '约珥书', 29, 2, 5, 'その音は戦車のきしり、山々の頂を飛び跳ねる。その音は刈り株を焼き尽くす火の炎、戦いの備えをした強い民のよう。'),
('JPN', '约珥书', 29, 2, 6, '諸国の民はその前でもだえ苦しみ、顔はみな青ざめる。'),
('JPN', '约珥书', 29, 2, 7, 'それは勇士のように走り、戦士のように城壁をよじ登る。それぞれ自分の道を進み、進路を乱さない。'),
('JPN', '约珥书', 29, 2, 8, '互いに押し合わず、それぞれ自分の大路を進む。投げ槍が降りかかっても、止まらない。'),
('JPN', '约珥书', 29, 2, 9, '町に襲いかかり、城壁の上を走り、家々によじ登り、盗人のように窓から入り込む。'),
('JPN', '约珥书', 29, 2, 10, '地はその前で震え、天も揺れる。太陽も月も暗くなり、星もその輝きを失う。'),
('JPN', '约珥书', 29, 2, 11, '主はご自分の軍隊の先頭に立って声をあげられる。その陣営は非常に大きく、主のことばを行う者は強い。主の日は偉大で、非常に恐ろしい。だれがこの日に耐えられるだろう。'),
('JPN', '约珥书', 29, 2, 12, '「しかし、今でも──主のことば──心のすべてをもって、断食と涙と嘆きをもって、わたしのもとに帰れ。」'),
('JPN', '约珥书', 29, 2, 13, '衣ではなく、あなたがたの心を引き裂け。あなたがたの神、主に立ち返れ。主は情け深く、あわれみ深い。怒るのに遅く、恵み豊かで、わざわいを思い直してくださる。'),
('JPN', '约珥书', 29, 2, 14, 'もしかすると、主が思い直してあわれみ、祝福を後に残しておいてくださるかもしれない。あなたがたの神、主への穀物と注ぎのささげ物を。'),
('JPN', '约珥书', 29, 2, 15, 'シオンで角笛を吹き鳴らせ。断食を布告し、きよめの集会を召集せよ。'),
('JPN', '约珥书', 29, 2, 16, '民を集め、会衆を聖別せよ。老人たちを呼び集め、幼子と乳飲み子たちを集めよ。花婿を寝室から、花嫁を自分の部屋から呼び出せ。'),
('JPN', '约珥书', 29, 2, 17, '神殿の玄関と祭壇の間で、主に仕える祭司たちは泣いてこう言え。「主よ、あなたの民にあわれみをかけてください。あなたのゆずりの地を、国々のそしりの的、物笑いの種としないでください。諸国の民の間で、『彼らの神はどこにいるのか』と言わせておいてよいのでしょうか。」'),
('JPN', '约珥书', 29, 2, 18, '主はご自分の地をねたむほど愛し、ご自分の民を深くあわれまれた。'),
('JPN', '约珥书', 29, 2, 19, '主は民に答えられた。「今、わたしは穀物と新しいぶどう酒と油をあなたがたに送る。あなたがたはそれで満ち足りる。わたしは二度とあなたがたを、国々の間でそしりの的としない。'),
('JPN', '约珥书', 29, 2, 20, 'わたしは、北から来るものをあなたがたから遠ざけ、それを荒廃した砂漠の地へ追いやる。その前衛を東の海に、その後衛を西の海に。その悪臭は立ち上り、その腐った臭いは立ちこめる。主が大いなることを行ったからだ。」'),
('JPN', '约珥书', 29, 2, 21, '地よ、恐れるな。楽しみ、喜べ。主が大いなることを行われたからだ。'),
('JPN', '约珥书', 29, 2, 22, '野の獣たちよ、恐れるな。荒野の牧草が萌え出で、木が実を実らせ、いちじくとぶどうの木が豊かに実る。'),
('JPN', '约珥书', 29, 2, 23, 'シオンの子らよ。あなたがたの神、主にあって、楽しみ喜べ。主は、義のわざとして、初めの雨を与え、かつてのように、あなたがたに大雨を降らせ、初めの雨と後の雨を降らせてくださる。'),
('JPN', '约珥书', 29, 2, 24, '打ち場は穀物で満ち、石がめは新しいぶどう酒と油であふれる。'),
('JPN', '约珥书', 29, 2, 25, '「いなご、あるいは、バッタ、その若虫、噛みいなご、わたしがあなたがたの間に送った大軍勢が食い尽くした年々に対して、わたしはあなたがたに償う。'),
('JPN', '约珥书', 29, 2, 26, 'あなたがたは食べて満ち足り、あなたがたの神、主の名をほめたたえる。主があなたがたに不思議なことをするのだ。わたしの民は永遠に恥を見ることがない。'),
('JPN', '约珥书', 29, 2, 27, 'あなたがたは、イスラエルの真ん中にわたしがいることを知り、わたしがあなたがたの神、主であり、ほかにはいないことを知る。わたしの民は永遠に恥を見ることはない。'),
('JPN', '约珥书', 29, 2, 28, 'その後、わたしはすべての人にわたしの霊を注ぐ。あなたがたの息子や娘は預言し、老人は夢を見、青年は幻を見る。'),
('JPN', '约珥书', 29, 2, 29, 'その日わたしは、男奴隷にも女奴隷にも、わたしの霊を注ぐ。'),
('JPN', '约珥书', 29, 2, 30, 'わたしは天と地に、しるしを現れさせる。それは血と火と煙の柱。'),
('JPN', '约珥书', 29, 2, 31, '主の大いなる恐るべき日が来る前に、太陽は闇に、月は血に変わる。'),
('JPN', '约珥书', 29, 2, 32, 'しかし、主の御名を呼び求める者はみな救われる。主が言ったように、シオンの山、エルサレムには逃れの者がいるからだ。生き残った者たちのうちに、主が呼び出す者がいる。」'),
('JPN', '约珥书', 29, 3, 1, '「見よ。わたしがユダとエルサレムを回復させるその日、その時、'),
('JPN', '约珥书', 29, 3, 2, 'わたしはすべての国々を集め、彼らをヨシャファテの谷に連れ下り、わたしの民、わたしのゆずりイスラエルのために、そこで彼らをさばく。彼らはわたしの民を国々の間に散らし、わたしの地を自分たちの間で分配したのだ。'),
('JPN', '约珥书', 29, 3, 3, '彼らはわたしの民をくじ引きにし、少年を渡して、遊女を得、少女を売って、酒を得て飲んだ。'),
('JPN', '约珥书', 29, 3, 4, 'ツロとシドン、またペリシテの全地域よ。おまえたちは、わたしにとって何なのか。わたしに報復しようとするのか。もしわたしに報復しようとしているなら、わたしはただちに、速やかに、おまえたちへの報いをおまえたちの頭上に返す。'),
('JPN', '约珥书', 29, 3, 5, 'わたしの銀と金をおまえたちが奪い、わたしのすばらしい財宝をおまえたちの神殿へ運び、'),
('JPN', '约珥书', 29, 3, 6, 'ユダの人々とエルサレムの人々をギリシア人に売って、彼らの領土から遠く離れさせたからだ。'),
('JPN', '约珥书', 29, 3, 7, '見よ。わたしは、おまえたちが彼らを売ったその場所から彼らを呼び戻して、おまえたちへの報いをおまえたちの頭上に返し、'),
('JPN', '约珥书', 29, 3, 8, 'おまえたちの息子、娘たちをユダの人々に売り渡す。彼らはこれを、遠くの異邦の民シェバ人に売る。──主は言われる。」'),
('JPN', '约珥书', 29, 3, 9, '「国々の間で、こう叫べ。聖戦を布告せよ。勇士たちを奮い立たせよ。すべての戦士たちを集めて上らせよ。'),
('JPN', '约珥书', 29, 3, 10, 'あなたがたの鋤を剣に、あなたがたの鎌を槍に打ち直せ。弱い者に『私は勇士だ』と言わせよ。'),
('JPN', '约珥书', 29, 3, 11, '周りのすべての国々よ。急いで来て、そこに集まれ。──主よ、あなたの勇士たちを下らせてください──'),
('JPN', '约珥书', 29, 3, 12, '諸国の民は立ち上がり、ヨシャファテの谷に上って来い。わたしがそこで、周辺のすべての国々をさばくために、座に着くからだ。」'),
('JPN', '约珥书', 29, 3, 13, '鎌を入れよ。刈り入れの機は熟した。来て、踏め。踏み場は満ちた。石がめはあふれている。彼らの悪がひどいから。'),
('JPN', '约珥书', 29, 3, 14, '判決の谷には、群衆また群衆。主の日が判決の谷に近づくからだ。'),
('JPN', '约珥书', 29, 3, 15, '太陽も月も暗くなり、星もその輝きを失う。'),
('JPN', '约珥书', 29, 3, 16, '主はシオンからほえ、エルサレムから声をあげられる。天も地も震える。主はその民の避け所、イスラエルの人々の砦である。'),
('JPN', '约珥书', 29, 3, 17, '「あなたがたは知るようになる。あなたがたの神、主であるこのわたしが、わが聖なる山、シオンに住むことを。エルサレムは聖なる所となり、他国人が再びそこを通ることはない。'),
('JPN', '约珥书', 29, 3, 18, 'その日には、山に甘いぶどう酒が滴り、丘には乳が流れ、ユダの谷川のすべてに水が流れ、泉が主の宮から湧き出て、シティムの渓流を潤す。'),
('JPN', '约珥书', 29, 3, 19, 'エジプトは荒れ果てた地となり、エドムは荒れ果てた荒野となる。彼らの、ユダの人々への暴虐のためだ。彼らはその地で、咎なき者の血を流した。'),
('JPN', '约珥书', 29, 3, 20, 'しかし、ユダは永遠に、エルサレムは代々にわたって人の住む所となる。'),
('JPN', '约珥书', 29, 3, 21, 'わたしは彼らの血の復讐をし、罰せずにはおかない。主はシオンに住む。」'),
('JPN', '阿摩司书', 30, 1, 1, 'テコア出身の牧者の一人であったアモスのことば。これはユダの王ウジヤの時代、イスラエルの王、ヨアシュの子ヤロブアムの時代、あの地震の二年前に、イスラエルについて彼が見た幻である。'),
('JPN', '阿摩司书', 30, 1, 2, '彼は言った。主はシオンからほえ、エルサレムから声をあげられる。羊飼いの牧場は乾き、カルメルの頂は枯れる。'),
('JPN', '阿摩司书', 30, 1, 3, '主はこう言われる。「ダマスコの三つの背き、四つの背きのゆえに、わたしは彼らを顧みない。彼らが鉄の打穀機でギルアデを踏みにじったからだ。'),
('JPN', '阿摩司书', 30, 1, 4, 'わたしはハザエルの家に火を送る。その火はベン・ハダドの宮殿を焼き尽くす。'),
('JPN', '阿摩司书', 30, 1, 5, 'わたしはダマスコのかんぬきを打ち壊す。王座に着いている者をアベンの谷から、王笏を持っている者をベテ・エデンから断つ。こうしてアラムの民はキルへ捕らえ移される。──主は言われる。」'),
('JPN', '阿摩司书', 30, 1, 6, '主はこう言われる。「ガザの三つの背き、四つの背きのゆえに、わたしは彼らを顧みない。彼らがすべての者を捕囚の民として捕らえ移し、エドムに引き渡したからだ。'),
('JPN', '阿摩司书', 30, 1, 7, 'わたしはガザの城壁に火を送る。その火はその宮殿を焼き尽くす。'),
('JPN', '阿摩司书', 30, 1, 8, 'わたしは、王座に着いている者をアシュドデから、王笏を持つ者をアシュケロンから断つ。わたしはエクロンに手を向け、ペリシテ人の残った者は滅びる。──神である主は言われる。」'),
('JPN', '阿摩司书', 30, 1, 9, '主はこう言われる。「ツロの三つの背き、四つの背きのゆえに、わたしは彼らを顧みない。彼らがすべての者を捕囚の民としてエドムに引き渡し、兄弟の契りを覚えていなかったからだ。'),
('JPN', '阿摩司书', 30, 1, 10, 'わたしはツロの城壁に火を送る。その火はその宮殿を焼き尽くす。」'),
('JPN', '阿摩司书', 30, 1, 11, '主はこう言われる。「エドムの三つの背き、四つの背きのゆえに、わたしは彼らを顧みない。彼らが剣で自分の兄弟を追い、あわれみを断ち、いつまでも怒り、どこまでも激しい怒りを保ち続けたからだ。'),
('JPN', '阿摩司书', 30, 1, 12, 'わたしはテマンに火を送る。その火はボツラの宮殿を焼き尽くす。」'),
('JPN', '阿摩司书', 30, 1, 13, '主はこう言われる。「アンモン人の三つの背き、四つの背きのゆえに、わたしは彼らを顧みない。彼らがギルアデの妊婦たちを切り裂いて、自分の領土を広げたからだ。'),
('JPN', '阿摩司书', 30, 1, 14, 'わたしはラバの城壁に火を放つ。その火はその宮殿を焼き尽くす。戦いの日の、ときの声のうちに、つむじ風の日の突風とともに。'),
('JPN', '阿摩司书', 30, 1, 15, '彼らの王は、その高官たちとともに捕囚の身となる。──主は言われる。」'),
('JPN', '阿摩司书', 30, 2, 1, '主はこう言われる。「モアブの三つの背き、四つの背きのゆえに、わたしは彼らを顧みない。彼がエドムの王の骨を焼いて灰にしたからだ。'),
('JPN', '阿摩司书', 30, 2, 2, 'わたしはモアブに火を送る。その火はケリヨテの宮殿を焼き尽くす。モアブは、どよめきのうちに、ときの声と角笛の音のうちに死ぬ。'),
('JPN', '阿摩司书', 30, 2, 3, 'わたしはさばく者を町の真っただ中で滅ぼし、そのすべての高官たちを彼とともに切り殺す。──主は言われる。」'),
('JPN', '阿摩司书', 30, 2, 4, '主はこう言われる。「ユダの三つの背き、四つの背きのゆえに、わたしは彼らを顧みない。彼らが主のおしえを捨てて、その掟を守らず、先祖がつき従ったまやかしものが彼らを惑わしたからだ。'),
('JPN', '阿摩司书', 30, 2, 5, 'わたしはユダに火を送る。その火はエルサレムの宮殿を焼き尽くす。」'),
('JPN', '阿摩司书', 30, 2, 6, '主はこう言われる。「イスラエルの三つの背き、四つの背きのゆえに、わたしは彼らを顧みない。彼らが金と引き換えに正しい者を売り、履き物一足のために貧しい者を売ったからだ。'),
('JPN', '阿摩司书', 30, 2, 7, '彼らは、弱い者の頭を地のちりに踏みつけ、貧しい者の道を曲げている。子とその父が同じ女のもとに通って、わたしの聖なる名を汚している。'),
('JPN', '阿摩司书', 30, 2, 8, '彼らは、すべての祭壇のそばで、質に取った衣服の上に横たわり、罰金で取り立てたぶどう酒を自分たちの神の宮で飲んでいる。'),
('JPN', '阿摩司书', 30, 2, 9, '彼らの前からアモリ人を滅ぼし尽くしたのは、このわたしだ。彼らは杉の木のように背が高く、樫の木のように強かった。わたしは、その上の実も下の根も滅ぼし尽くした。'),
('JPN', '阿摩司书', 30, 2, 10, 'あなたがたをエジプトの地から連れ上り、四十年の間、荒野の中であなたがたを導き、アモリ人の地を所有させたのは、このわたしだ。'),
('JPN', '阿摩司书', 30, 2, 11, 'わたしが、あなたがたの息子たちから預言者を、あなたがたの若者からナジル人を起こしたのだ。そうではなかったか。イスラエルの子らよ。──主のことば──'),
('JPN', '阿摩司书', 30, 2, 12, 'しかし、あなたがたはナジル人に酒を飲ませ、預言者には『預言するな』と命じた。'),
('JPN', '阿摩司书', 30, 2, 13, '見よ。このわたしが、あなたがたを押しつぶす。束を満載した荷車が押しつぶすように。'),
('JPN', '阿摩司书', 30, 2, 14, '足の速い者も逃げ場を失い、強い者も力をふるえず、勇士も自分を救えない。'),
('JPN', '阿摩司书', 30, 2, 15, '射手も立ちおおせず、足の速い者も逃れられず、騎手も自分を救えない。'),
('JPN', '阿摩司书', 30, 2, 16, '勇士のうちの、心の強い者も、その日には裸で逃げるようになる。──主のことば。」'),
('JPN', '阿摩司书', 30, 3, 1, '「イスラエルの子らよ、聞け。主があなたがたについて告げた、このことばを。わたしがエジプトの地から連れ上った、あなたがたすべての部族についてのことばを。'),
('JPN', '阿摩司书', 30, 3, 2, 'わたしは、地のすべての種族の中から、あなたがただけを選び出した。それゆえ、あなたがたのすべての咎のゆえにわたしはあなたがたを罰する。」'),
('JPN', '阿摩司书', 30, 3, 3, '約束もしていないのに、二人の者が一緒に歩くだろうか。'),
('JPN', '阿摩司书', 30, 3, 4, '獲物もないのに、獅子が森の中で吼えるだろうか。何も捕らえていないのに、若獅子がその洞穴で声をあげるだろうか。'),
('JPN', '阿摩司书', 30, 3, 5, '罠も仕掛けられていないのに、鳥が地の鳥網にかかるだろうか。何も捕らえていないのに、鳥網が地面から跳ね上がるだろうか。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '阿摩司书', 30, 3, 6, '角笛が町で鳴らされたら、民は驚かないだろうか。町にわざわいが起こったら、主がそれをなされたのではないか。'),
('JPN', '阿摩司书', 30, 3, 7, 'まことに、神である主は、ご自分の計画を、そのしもべである預言者たちに示さずには、何事もなさらない。'),
('JPN', '阿摩司书', 30, 3, 8, '獅子が吼える。だれが恐れないでいられよう。神である主が語られる。だれが預言しないでいられよう。'),
('JPN', '阿摩司书', 30, 3, 9, '「アシュドデの宮殿とエジプトの地の宮殿に告げよ。『サマリアの山々の上に集まり、その町の大いなる混乱と、そのただ中の抑圧を見よ。』'),
('JPN', '阿摩司书', 30, 3, 10, '彼らは正直に事を行うことを知らない。──主のことば──彼らは自分たちの宮殿に、暴虐と暴行を宝物のように蓄えている。」'),
('JPN', '阿摩司书', 30, 3, 11, 'それゆえ、神である主はこう言われる。「敵が、この地を取り囲み、あなたの権威を地に落とす。あなたの宮殿はかすめ奪われる。」'),
('JPN', '阿摩司书', 30, 3, 12, '主はこう言われる。「羊飼いが獅子の口から二本の足、あるいは耳たぶだけでも取り戻すように、サマリアに住むイスラエルの子らは、寝台の隅やダマスコの長椅子とともに救い出される。'),
('JPN', '阿摩司书', 30, 3, 13, '聞け。ヤコブの家に証言せよ。──神である主、万軍の神のことば──'),
('JPN', '阿摩司书', 30, 3, 14, 'まことに、イスラエルの背きのゆえにわたしが彼の上に報いる日に、わたしはベテルの祭壇を罰する。その祭壇の角は折られ、地に落ちる。'),
('JPN', '阿摩司书', 30, 3, 15, 'わたしは冬の家と夏の家を打つ。象牙の家は滅び、大邸宅も消え失せる。──主のことば。」'),
('JPN', '阿摩司书', 30, 4, 1, 'このことばを聞け。サマリアの山にいるバシャンの雌牛どもよ。おまえたちは弱い者を虐げ、貧しい者を迫害し、自分の主人に「何か持って来て、飲ませよ」と言っている。'),
('JPN', '阿摩司书', 30, 4, 2, '神である主は、ご自分の聖にかけて誓われる。「見よ、その時代がおまえたちに来る。おまえたちは釣り針にかけて引き上げられる。最後の一人までが、銛で突かれる。'),
('JPN', '阿摩司书', 30, 4, 3, 'おまえたちは、城壁の破れ口からそれぞれまっすぐに出て行き、ハルモンに放り出される。──主のことば。'),
('JPN', '阿摩司书', 30, 4, 4, 'ベテルに行って背け。ギルガルに行って、ますます背け。朝ごとにあなたがたのいけにえを献げよ。三日ごとに十分の一を献げるがよい。'),
('JPN', '阿摩司书', 30, 4, 5, '感謝のささげ物として、種入りのパンを焼き、進んで献げるものを布告し、ふれ知らせるがよい。イスラエルの子らよ、あなたがたはそうすることを好んでいる。──神である主のことば。'),
('JPN', '阿摩司书', 30, 4, 6, 'わたしは、あなたがたのすべての町で、あなたがたの歯を汚さず、すべての場所で、パンを欠乏させた。それでも、あなたがたはわたしのもとに帰って来なかった。──主のことば──'),
('JPN', '阿摩司书', 30, 4, 7, 'わたしはまた、刈り入れまでなお三か月あるのに、あなたがたに雨をとどめた。ある町には雨を降らせ、ほかの町には雨を降らせなかった。ある畑には雨が降ったが、雨の降らなかった畑は乾ききった。'),
('JPN', '阿摩司书', 30, 4, 8, '二、三の町は水を飲むために、よろめきながら一つの町に行った。しかし、満ち足りることはなかった。それでも、あなたがたはわたしのもとに帰って来なかった──主のことば。'),
('JPN', '阿摩司书', 30, 4, 9, 'わたしは立ち枯れと黒穂病で、あなたがたを打った。あなたがたの果樹園とぶどう畑、いちじくの木とオリーブの木が増えても、噛みいなごが食い荒らした。それでも、あなたがたはわたしのもとに帰って来なかった。──主のことば──'),
('JPN', '阿摩司书', 30, 4, 10, 'わたしは、エジプトにしたように、疫病をあなたがたに送った。剣であなたがたの若者を殺し、あなたがたの馬を奪い去った。あなたがたの陣営に悪臭を上らせ、あなたがたの鼻をつくようにした。それでも、あなたがたはわたしのもとに帰って来なかった。──主のことば──'),
('JPN', '阿摩司书', 30, 4, 11, 'わたしは、あなたがたをくつがえした。神がソドムとゴモラをくつがえしたように。あなたがたは、炎の中から取り出された燃えさしのようになった。それでも、あなたがたはわたしのもとに帰って来なかった。──主のことば。'),
('JPN', '阿摩司书', 30, 4, 12, 'それゆえイスラエルよ、わたしはあなたにこのようにする。わたしがあなたにこうするから、イスラエルよ、あなたの神に会う備えをせよ。」'),
('JPN', '阿摩司书', 30, 4, 13, '見よ、山々を形造り、風を創造した方。その御思いが何であるかを人間に告げる方。暁と暗闇を造り、地の高き所を歩まれる方。その名は万軍の神、主。'),
('JPN', '阿摩司书', 30, 5, 1, 'イスラエルの家よ、このことばを聞け。私はあなたがたについて哀歌を歌う。'),
('JPN', '阿摩司书', 30, 5, 2, 'おとめイスラエルは倒れて、二度と起き上がれない。彼女は自分の地に捨て置かれ、これを起こす者もいない。'),
('JPN', '阿摩司书', 30, 5, 3, 'まことに、神である主はこう言われる。「イスラエルの家の、千人を出征させていた町には百人が残り、百人を出征させていた町には十人が残る。」'),
('JPN', '阿摩司书', 30, 5, 4, '主はイスラエルの家にこう言われる。「わたしを求めて生きよ。'),
('JPN', '阿摩司书', 30, 5, 5, 'ベテルを求めるな。ギルガルに行くな。ベエル・シェバに赴くな。ギルガルは必ず捕らえ移され、ベテルは無に帰するからだ。」'),
('JPN', '阿摩司书', 30, 5, 6, '主を求めて生きよ。そうでないと、主は火のように、ヨセフの家に激しく下る。火はこれを焼き尽くし、ベテルにはそれを消す者がいなくなる。'),
('JPN', '阿摩司书', 30, 5, 7, '彼らは、公正を苦よもぎに変え、正義を地に投げ捨てている。'),
('JPN', '阿摩司书', 30, 5, 8, 'すばるやオリオン座を造り、暗黒を朝に変え、昼を暗くして夜にし、海の水を呼び集めて、それを地の面に注ぐ方。その名は主。'),
('JPN', '阿摩司书', 30, 5, 9, '主は、強い者を踏みにじり、要塞を破壊する。'),
('JPN', '阿摩司书', 30, 5, 10, '彼らは門でさばきをする者を憎み、まっすぐに語る者を忌み嫌う。'),
('JPN', '阿摩司书', 30, 5, 11, 'あなたがたは貧しい者を踏みつけ、彼から小作料を取り立てている。それゆえ、切り石の家々を建てても、あなたがたはその中に住めない。麗しいぶどう畑を作っても、そのぶどう酒を飲めない。'),
('JPN', '阿摩司书', 30, 5, 12, '私は、あなたがたの背きが多く、あなたがたの罪が重いことをよく知っている。正しい者を迫害する者、賄賂を受け取る者。彼らは門で、貧しい者を押しのけている。'),
('JPN', '阿摩司书', 30, 5, 13, 'それゆえ、このようなときには、賢い者は沈黙を守る。時が悪いからだ。'),
('JPN', '阿摩司书', 30, 5, 14, '善を求めよ。悪を求めるな。そうすれば、あなたがたは生き、あなたがたが言うように、万軍の神、主が、ともにいてくださる。'),
('JPN', '阿摩司书', 30, 5, 15, '悪を憎み、善を愛し門で正しいさばきを行え。もしかすると、万軍の神、主はヨセフの残りの者をあわれんでくださるかもしれない。'),
('JPN', '阿摩司书', 30, 5, 16, 'それゆえ、主なる万軍の神、主はこう言われる。「すべての広場に嘆きが起こる。すべての通りで、人々は『ああ、ああ』と叫ぶ。農夫を呼んで来て泣かせ、泣き方を心得た者を呼んで来て嘆かせる。'),
('JPN', '阿摩司书', 30, 5, 17, 'すべてのぶどう畑に嘆きが起こる。それは、わたしがあなたがたの中を通り過ぎるからだ。──主は言われる。」'),
('JPN', '阿摩司书', 30, 5, 18, 'ああ。主の日を切に望む者。主の日はあなたがたにとって何になろう。それは闇であって、光ではない。'),
('JPN', '阿摩司书', 30, 5, 19, '人が獅子の前を逃げても、熊が彼に会い、家の中に入っても、手で壁に寄りかかると、蛇が彼にかみつくようなものだ。'),
('JPN', '阿摩司书', 30, 5, 20, '主の日は闇であって、光ではない。暗闇であって、そこには輝きはない。'),
('JPN', '阿摩司书', 30, 5, 21, '「わたしはあなたがたの祭りを憎み、退ける。あなたがたのきよめの集会のときの香りも、わたしはかぎたくない。'),
('JPN', '阿摩司书', 30, 5, 22, 'たとえ、あなたがたが、全焼のささげ物や穀物のささげ物をわたしに献げても、わたしはこれらを受け入れない。肥えた家畜の交わりのいけにえを献げても、わたしは目を留めない。'),
('JPN', '阿摩司书', 30, 5, 23, 'あなたがたの歌の騒ぎを、わたしから遠ざけよ。あなたがたの琴の音を、わたしは聞きたくない。'),
('JPN', '阿摩司书', 30, 5, 24, '公正を水のように、義を、絶えず流れる谷川のように、流れさせよ。'),
('JPN', '阿摩司书', 30, 5, 25, 'イスラエルの家よ。あなたがたは荒野にいた四十年の間に、いけにえとささげ物を、わたしのところに携えて来たことがあったか。'),
('JPN', '阿摩司书', 30, 5, 26, 'あなたがたは自分たちの王シクテと自分たちの像キユン、自分たちのために造った神々の星を担いで来た。'),
('JPN', '阿摩司书', 30, 5, 27, 'わたしはあなたがたを、ダマスコのかなたへ捕らえ移す──その名が万軍の神である主が言われる。」'),
('JPN', '阿摩司书', 30, 6, 1, 'わざわいだ。シオンで安逸を貪る者、サマリアの山に信頼している者。イスラエルの家が頼って行く、国々の最高の首長たち。'),
('JPN', '阿摩司书', 30, 6, 2, 'カルネに渡って行って見よ。そこから大ハマテに行け。またペリシテ人のガテに下って行け。あなたがたはこれらの王国よりすぐれているのか。彼らの領土はあなたがたの領土より大きいのか。'),
('JPN', '阿摩司书', 30, 6, 3, 'あなたがたは、わざわいの日を遠ざけているつもりで、暴虐の時代を近づけている。'),
('JPN', '阿摩司书', 30, 6, 4, '象牙の寝台に横たわり長椅子でからだを伸ばし、群れのうちから子羊を、牛舎の中から子牛を取って食べている者、'),
('JPN', '阿摩司书', 30, 6, 5, '琴の音にのせて即興の歌を作り、ダビデに倣って自分たちの楽器を考え出す者。'),
('JPN', '阿摩司书', 30, 6, 6, '彼らは鉢から酒を飲み、最上の香油を身に塗り、ヨセフの破滅のことで嘆き悲しむことがない。'),
('JPN', '阿摩司书', 30, 6, 7, 'それゆえ、今、彼らは最初の捕囚の民として引いて行かれる。大の字になった者どもの、弔いの酒宴は除かれる。'),
('JPN', '阿摩司书', 30, 6, 8, '神である主は、ご自分にかけて誓われる。──万軍の神、主のことば──「わたしはヤコブの誇りを忌み嫌い、その宮殿を憎む。わたしはこの都と、その中のすべての者を引き渡す。」'),
('JPN', '阿摩司书', 30, 6, 9, 'たとえ、一つの家に十人が残っても、彼らもまた死ぬ。'),
('JPN', '阿摩司书', 30, 6, 10, '親戚の一人でこれを焼く者が、家から死体を持ち出すためにこれを取り上げ、その家の奥にいる人に向かって言う。「あなたのところには、まだいるか。」彼は言う。「だれもいない。」また言う。「口をつぐめ。主の名を口にするな。」'),
('JPN', '阿摩司书', 30, 6, 11, 'まことに、見よ、主は命じられる。「大きな家を打ち砕き、小さな家を粉々にせよ。」'),
('JPN', '阿摩司书', 30, 6, 12, '馬が岩の上を走るだろうか。人がそこを牛で耕すだろうか。しかしあなたがたは、公正を毒に変え、正義の実を苦よもぎに変えた。'),
('JPN', '阿摩司书', 30, 6, 13, 'あなたがたは、ロ・ダバルを喜び、こう言う。「私たちは自分たちの力でカルナイムを取ったではないか」と。'),
('JPN', '阿摩司书', 30, 6, 14, '「しかし、イスラエルの家よ、今わたしは、あなたがたに敵対する一つの国を起こす。──万軍の神、主のことば──彼らはレボ・ハマテからアラバの水無し川まで、あなたがたを虐げる。」'),
('JPN', '阿摩司书', 30, 7, 1, '神である主は私に示された。見よ。王が刈り取った後の二番草が生え始めたころ、主はいなごを備えられた。'),
('JPN', '阿摩司书', 30, 7, 2, 'そのいなごが地の青草を食い尽くそうとしたとき、私は言った。「神、主よ。どうかお赦しください。ヤコブはどうして生き残れるでしょう。彼は小さいのです。」'),
('JPN', '阿摩司书', 30, 7, 3, '主はこれを思い直された。そして「そのことは起こらない」と主は言われた。'),
('JPN', '阿摩司书', 30, 7, 4, '神である主は私に示された。見よ、神である主は、責める火を呼ばれた。火は大いなる淵を吞み込み、割り当て地を焼き尽くそうとしていた。'),
('JPN', '阿摩司书', 30, 7, 5, '私は言った。「神、主よ。どうかおやめください。ヤコブはどうして生き残れるでしょう。彼は小さいのです。」'),
('JPN', '阿摩司书', 30, 7, 6, '主はこれを思い直された。そして「そのことも起こらない」と神である主は言われた。'),
('JPN', '阿摩司书', 30, 7, 7, '主は私に示された。見よ。主は下げ振りを手に持って、下げ振りを使って築かれた城壁の上に立っておられた。'),
('JPN', '阿摩司书', 30, 7, 8, '主は私に言われた。「アモス、何を見ているのか。」私が「下げ振りです」と言うと、主は言われた。「見よ。わたしは下げ振りを、わたしの民イスラエルの真ん中に垂れ下げる。わたしはもう二度と彼らを見過ごさない。'),
('JPN', '阿摩司书', 30, 7, 9, 'イサクの高き所は荒らされ、イスラエルの聖所は廃墟となる。わたしは剣をもって、ヤロブアムの家に向かって立ち上がる。」'),
('JPN', '阿摩司书', 30, 7, 10, 'ベテルの祭司アマツヤは、イスラエルの王ヤロブアムに人を遣わして言った。「アモスは、イスラエルの家のただ中で、あなたに謀反を企てています。この国は彼のどのことばも受け入れることができません。'),
('JPN', '阿摩司书', 30, 7, 11, 'アモスはこう言っています。『ヤロブアムは剣で死に、イスラエルはその土地から必ず捕らえられて行く。』」'),
('JPN', '阿摩司书', 30, 7, 12, 'アマツヤはアモスに言った。「先見者よ。さあ、ユダの地へ逃げるがよい。そこでパンを食べ、その地で預言するがよい。'),
('JPN', '阿摩司书', 30, 7, 13, 'ベテルでは二度と預言するな。ここは王の聖所、王国の宮だからだ。」'),
('JPN', '阿摩司书', 30, 7, 14, 'アモスはアマツヤに答えた。「私は預言者ではなかったし、預言者の仲間でもなかった。私は牧者であり、いちじく桑の木を栽培していた。'),
('JPN', '阿摩司书', 30, 7, 15, 'しかし、主が、群れの世話をしていたところから私を取り、主が私にこう言われた。『行って、わたしの民イスラエルに預言せよ』と。'),
('JPN', '阿摩司书', 30, 7, 16, '今、主のことばを聞け。あなたは『イスラエルに向かって預言するな。イサクの家に向かって戯言を言うな』と言っている。'),
('JPN', '阿摩司书', 30, 7, 17, 'それゆえ、主はこう言われる。『あなたの妻は町で遊女となり、あなたの息子、娘たちは剣に倒れ、あなたの土地は測り縄で分割される。あなたは汚れた土地で死に、イスラエルはその土地から必ず捕らえられて行く。』」'),
('JPN', '阿摩司书', 30, 8, 1, '神である主は私に示された。そこには一かごの夏の果物があった。'),
('JPN', '阿摩司书', 30, 8, 2, '主は言われた。「アモス。何を見ているのか。」私が、「一かごの夏の果物です」と言うと、主は私に言われた。「わたしの民イスラエルに終わりが来た。わたしはもう二度と彼らを見過ごさない。'),
('JPN', '阿摩司书', 30, 8, 3, 'その日には、神殿の歌声は悲鳴に変わる。──神である主のことば──多くの屍が、いたるところに投げ捨てられる。口をつぐめ。」'),
('JPN', '阿摩司书', 30, 8, 4, '聞け。貧しい者たちを踏みつけ、地で苦しむ者たちを消し去ろうとする者よ。'),
('JPN', '阿摩司书', 30, 8, 5, 'あなたがたは言っている。「新月の祭りはいつ終わるのか。私たちは穀物を売りたいのだが。安息日はいつ終わるのか。麦を売りに出したいのだが。エパを小さくし、シェケルを重くし、欺きの秤で欺こう。'),
('JPN', '阿摩司书', 30, 8, 6, '弱い者を金で買い、貧しい者を履き物一足分で買おう。屑麦を売ろう。」'),
('JPN', '阿摩司书', 30, 8, 7, '主はヤコブの誇りにかけて誓われる。「わたしは、彼らのしていることをみな、いつまでも決して忘れない。'),
('JPN', '阿摩司书', 30, 8, 8, '地はこのために震えないだろうか。地に住むすべての者は喪に服さないだろうか。地のすべてのものはナイル川のように持ち上がり、エジプトの大河のように、うねっては沈まないだろうか。'),
('JPN', '阿摩司书', 30, 8, 9, 'その日には、──神である主のことば──わたしは真昼に太陽を沈ませ、白昼に地を暗くする。'),
('JPN', '阿摩司书', 30, 8, 10, 'あなたがたの祭りを喪に変え、あなたがたの歌をすべて哀歌に変える。すべての腰に粗布をまとわせ、頭を剃らせる。その時をひとり子を失ったときの喪のように、その終わりを苦渋の日のようにする。'),
('JPN', '阿摩司书', 30, 8, 11, '見よ、その時代が来る。──神である主のことば──そのとき、わたしはこの地に飢饉を送る。パンに飢えるのではない。水に渇くのでもない。実に、主のことばを聞くことの飢饉である。'),
('JPN', '阿摩司书', 30, 8, 12, '彼らは海から海へと、北から東へとさまよい歩く。主のことばを探し求めて行き巡る。しかし、それを見出すことはない。'),
('JPN', '阿摩司书', 30, 8, 13, 'その日には、美しい若い女も、若い男も、渇きのために衰え果てる。'),
('JPN', '阿摩司书', 30, 8, 14, '彼らは、サマリアの罪過にかけてこう誓う。『ダンよ、あなたの神は生きている。』『ベエル・シェバの道は生きている。』しかし、彼らは倒れて二度と起き上がれない。」'),
('JPN', '阿摩司书', 30, 9, 1, '私は、祭壇の傍らに主が立っておられるのを見た。すると、主は言われた。「柱頭を打ちたたき、敷居が震えるようにせよ。すべての者の頭を打ち砕け。彼らのうち、生き残った者をわたしは剣で殺す。彼らのうち逃げられる者はなく、彼らのうち逃れられる者もない。'),
('JPN', '阿摩司书', 30, 9, 2, 'たとえ、よみに入り込んだとしても、わたしの手が、彼らをそこから引きずり出す。たとえ、天に上ったとしても、わたしが彼らをそこから引きずり降ろす。'),
('JPN', '阿摩司书', 30, 9, 3, 'たとえ、カルメルの頂に身を隠したとしても、わたしが彼らをそこから捜し出して捕まえる。たとえ、わたしの目を避けて海の底に身を隠したとしても、わたしが蛇に命じて彼らをそこでかませる。'),
('JPN', '阿摩司书', 30, 9, 4, 'たとえ、敵の捕虜となって行ったとしても、わたしが剣に命じてそこで彼らを殺させる。わたしは彼らの上に目を注ぐ。それは、わざわいのためであって、幸いのためではない。」'),
('JPN', '阿摩司书', 30, 9, 5, '万軍の神、主が地に触れると、それは溶け去る。そこに住むすべての者は喪に服す。地のすべてのものは、ナイル川のように持ち上がり、エジプトの大河のように沈む。'),
('JPN', '阿摩司书', 30, 9, 6, '天に高殿を建て、地の上に丸天井を据え、海の水を呼んで、地の面に注がれる方、その名は主。'),
('JPN', '阿摩司书', 30, 9, 7, '「イスラエルの子らよ。あなたがたは、わたしにとってクシュ人と同じではないのか。──主のことば──わたしは、イスラエルをエジプトの地から、ペリシテ人をカフトルから、アラムをキルから、連れ上ったではないか。'),
('JPN', '阿摩司书', 30, 9, 8, '見よ。神である主の目が、罪深い王国に向けられている。わたしはこれを地の面から根絶やしにする。しかし、ヤコブの家を根絶やしにすることはない。──主のことば──'),
('JPN', '阿摩司书', 30, 9, 9, '見よ。わたしは命じて、すべての国々の間で、イスラエルの家をふるいにかける。ふるっても、小石は地に落ちないようにする。'),
('JPN', '阿摩司书', 30, 9, 10, 'わたしの民の中の罪人はみな、剣で死ぬ。彼らは『わざわいは私たちに近づかない。私たちまでは及ばない』と言っている。'),
('JPN', '阿摩司书', 30, 9, 11, 'その日、わたしは倒れているダビデの仮庵を起こす。その破れを繕い、その廃墟を起こし、昔の日のようにこれを建て直す。'),
('JPN', '阿摩司书', 30, 9, 12, 'これは、エドムの残りの者とわたしの名で呼ばれるすべての国々を、彼らが所有するためだ。──これを行う主のことば。'),
('JPN', '阿摩司书', 30, 9, 13, '見よ、その時代が来る。──主のことば──そのとき、耕す者が刈る者に追いつき、ぶどうを踏む者が種蒔く者に追いつく。山々は甘いぶどう酒を滴らせ、すべての丘は溶けて流れる。'),
('JPN', '阿摩司书', 30, 9, 14, 'わたしは、わたしの民イスラエルを回復させる。彼らは荒れた町々を建て直して住み、ぶどう畑を作って、そのぶどう酒を飲み、果樹園を作って、その実を食べる。'),
('JPN', '阿摩司书', 30, 9, 15, 'わたしは、彼らを彼らの地に植える。彼らは、わたしが与えたその土地から、もう引き抜かれることはない。──あなたの神、主は言われる。」'),
('JPN', '俄巴底亚书', 31, 1, 1, 'オバデヤの幻。神である主は、エドムについてこう言われる。──私たちは主から知らせを聞いた。使節が国々の間に送られてこう言った、と。「さあ、立ち上がれ。エドムと戦おう」──'),
('JPN', '俄巴底亚书', 31, 1, 2, '「見よ。わたしはおまえを国々の中で小さい者、ひどく蔑まれる者とする。'),
('JPN', '俄巴底亚书', 31, 1, 3, '岩の裂け目に住み、高い所を住まいとする者よ。おまえの高慢は、おまえ自身を欺いている。おまえは心の中で言っている。『だれが私を地に引きずり降ろせるのか』と。'),
('JPN', '俄巴底亚书', 31, 1, 4, '鷲のように高く上っても、星々の間に巣を作っても、わたしは、おまえをそこから引きずり降ろす。──主のことば。'),
('JPN', '俄巴底亚书', 31, 1, 5, '盗人がおまえのところに来るなら、しかも夜に、荒らす者が来るなら、──いかに、おまえは荒らされることか──彼らは欲しい分だけ盗んで行くではないか。ぶどうを収穫する者がおまえのところに来るなら、彼らは取り残しの実を残さないだろうか。'),
('JPN', '俄巴底亚书', 31, 1, 6, 'ああ、エサウは捜し出され、その秘宝は見つけ出される。'),
('JPN', '俄巴底亚书', 31, 1, 7, 'おまえと同盟を組む者たちがみな、おまえを国境まで送り返し、親しい友がおまえを欺いて征服する。おまえのパンを食べていた者が、おまえの足もとに罠を仕掛ける。こんなおまえに英知はない。'),
('JPN', '俄巴底亚书', 31, 1, 8, 'その日には、──主のことば──わたしは、エドムから知恵ある者たちを、エサウの山から英知を消し去らないであろうか。'),
('JPN', '俄巴底亚书', 31, 1, 9, 'テマンよ、おまえの勇士たちは気をくじかれる。虐殺され、エサウの山から一人残らず断ち切られる。'),
('JPN', '俄巴底亚书', 31, 1, 10, 'おまえの兄弟、ヤコブへの暴虐のために、恥がおまえをおおい、おまえは永遠に断たれる。'),
('JPN', '俄巴底亚书', 31, 1, 11, '他国人がエルサレムの財宝を奪い去り、外国人がその門に押し入り、エルサレムをくじ引きにして取ったその日、おまえは素知らぬ顔で立っていた。おまえもまた、彼らのうちの一人のようであった。'),
('JPN', '俄巴底亚书', 31, 1, 12, 'おまえは兄弟の災難の日に、それを見ていてはならない。ユダの子らの滅びの日に、彼らのことで喜んではならない。その苦難の日に大口をたたいてはならない。'),
('JPN', '俄巴底亚书', 31, 1, 13, 'おまえは彼らのわざわいの日に、わたしの民の門に入ってはならない。ほかでもないおまえが、彼の破局の日に、そのわざわいを眺めていてはならない。彼の破局の日に、彼らの財宝に手を伸ばしてはならない。'),
('JPN', '俄巴底亚书', 31, 1, 14, 'その逃れる者を断つために、別れ道に立ちふさがってはならない。その苦難の日に、彼らの生き残った者を引き渡してはならない。'),
('JPN', '俄巴底亚书', 31, 1, 15, 'なぜなら、主の日がすべての国々に近づいているからだ。おまえは、自分がしたように、自分にもされる。おまえの報いは、おまえの頭上に返る。'),
('JPN', '俄巴底亚书', 31, 1, 16, 'おまえたちがわたしの聖なる山で飲んだように、すべての国々も絶えず飲み続け、飲んだり、すすったりする。彼らはまるで、いなかった者のようになる。'),
('JPN', '俄巴底亚书', 31, 1, 17, 'しかし、シオンの山には、逃れの者がいるようになる。そこは聖となり、ヤコブの家は自分の領地を所有するようになる。'),
('JPN', '俄巴底亚书', 31, 1, 18, 'ヤコブの家は火となり、ヨセフの家は炎となる。エサウの家は刈り株となり、火と炎は刈り株に燃えつき、これを焼き尽くす。エサウの家には生き残る者がいなくなる。」主がこう告げられたのである。'),
('JPN', '俄巴底亚书', 31, 1, 19, 'ネゲブの人々はエサウの山を、シェフェラの人々はペリシテ人の地を占領する。また彼らはエフライムの野とサマリアの野を占領し、ベニヤミンはギルアデを占領する。'),
('JPN', '俄巴底亚书', 31, 1, 20, 'イスラエルの人々に属する、この一群の捕囚の民はカナン人の地をツァレファテまで占領し、セファラデにいるエルサレムからの捕囚の民はネゲブの町々を占領する。'),
('JPN', '俄巴底亚书', 31, 1, 21, '救う者たちは、エサウの山をさばくため、シオンの山に上る。こうして、王国は主のものとなる。'),
('JPN', '约拿书', 32, 1, 1, 'アミタイの子ヨナに、次のような主のことばがあった。'),
('JPN', '约拿书', 32, 1, 2, '「立ってあの大きな都ニネベに行き、これに向かって叫べ。彼らの悪がわたしの前に上って来たからだ。」'),
('JPN', '约拿书', 32, 1, 3, 'しかし、ヨナは立って、主の御顔を避けてタルシシュへ逃れようとした。彼はヤッファに下り、タルシシュ行きの船を見つけると、船賃を払ってそれに乗り込み、主の御顔を避けて、人々と一緒にタルシシュへ行こうとした。'),
('JPN', '约拿书', 32, 1, 4, 'ところが、主が大風を海に吹きつけられたので、激しい暴風が海に起こった。それで船は難破しそうになった。'),
('JPN', '约拿书', 32, 1, 5, '水夫たちは恐れて、それぞれ自分の神に向かって叫んだ。そして、船を軽くしようと船の積荷を海に投げ捨てた。一方、ヨナは船底に下りていて、横になってぐっすり寝入っていた。'),
('JPN', '约拿书', 32, 1, 6, 'すると船長が近づいて来て、彼に言った。「いったいどうしたのか。眠りこけているとは。起きて、あなたの神に願いなさい。もしかすると、その神が私たちに心を留め、私たちは滅びないですむかもしれない。」'),
('JPN', '约拿书', 32, 1, 7, '人々は互いに言った。「さあ、だれのせいで、このわざわいが私たちに降りかかったのか、くじによって知ろう。」彼らがくじを引くと、そのくじはヨナに当たった。'),
('JPN', '约拿书', 32, 1, 8, 'そこで彼らはヨナに言った。「話してくれ。だれのせいで、このわざわいが私たちに降りかかったのか。あなたの仕事は何か。どこから来たのか。国はどこか。どの民の者か。」'),
('JPN', '约拿书', 32, 1, 9, 'ヨナは彼らに言った。「私はヘブル人です。私は、海と陸を造られた天の神、主を恐れる者です。」'),
('JPN', '约拿书', 32, 1, 10, '人々は非常に恐れて、彼に「何ということをしたのか」と言った。人々は、ヨナが彼らに告げたことによって、彼が主の御顔を避けて逃れようとしていることを知ったからである。'),
('JPN', '约拿书', 32, 1, 11, '彼らはヨナに言った。「私たちのために海が静まるようにするには、あなたをどうすればよいのか。」海がますます荒れてきたからである。'),
('JPN', '约拿书', 32, 1, 12, 'ヨナは彼らに言った。「私を抱え上げて、海に投げ込みなさい。そうすれば、海はあなたがたのために静かになるでしょう。私は分かっています。この激しい暴風は、私のせいであなたがたを襲ったのです。」'),
('JPN', '约拿书', 32, 1, 13, 'それでも人々は船を陸に戻そうと漕いだが、そうすることはできなかった。海がますます彼らに向かって荒れてきたからである。'),
('JPN', '约拿书', 32, 1, 14, 'そこで彼らは主に向かって叫んだ。「ああ、主よ。どうか、この男のいのちのことで、私たちが滅びることのないようにしてください。咎なき者の血の報いを、私たちの上に下さないでください。主よ。あなたは、望まれたとおりになさったのですから。」'),
('JPN', '约拿书', 32, 1, 15, 'こうして、彼らはヨナを抱え上げ、海に投げ込んだ。すると激しい怒りがやんで、海は凪になった。'),
('JPN', '约拿书', 32, 1, 16, '人々は非常に主を恐れ、主にいけにえを献げて誓願を立てた。'),
('JPN', '约拿书', 32, 1, 17, '主は大きな魚を備えて、ヨナを吞み込ませた。ヨナは三日三晩、魚の腹の中にいた。'),
('JPN', '约拿书', 32, 2, 1, 'ヨナは魚の腹の中から、自分の神、主に祈った。'),
('JPN', '约拿书', 32, 2, 2, '「苦しみの中から、私は主に叫びました。すると主は、私に答えてくださいました。よみの腹から私が叫び求めると、あなたは私の声を聞いてくださいました。'),
('JPN', '约拿书', 32, 2, 3, 'あなたは私を深いところに、海の真中に投げ込まれました。潮の流れが私を囲み、あなたの波、あなたの大波がみな、私の上を越えて行きました。'),
('JPN', '约拿书', 32, 2, 4, '私は言いました。『私は御目の前から追われました。ただ、もう一度、私はあなたの聖なる宮を仰ぎ見たいのです。』'),
('JPN', '约拿书', 32, 2, 5, '水は私を取り巻き、喉にまで至り、大いなる水が私を囲み、海草は頭に絡みつきました。'),
('JPN', '约拿书', 32, 2, 6, '私は山々の根元まで下り、地のかんぬきは、私のうしろで永遠に下ろされました。しかし、私の神、主よ。あなたは私のいのちを滅びの穴から引き上げてくださいました。'),
('JPN', '约拿书', 32, 2, 7, '私のたましいが私のうちで衰え果てたとき、私は主を思い出しました。私の祈りはあなたに、あなたの聖なる宮に届きました。'),
('JPN', '约拿书', 32, 2, 8, '空しい偶像に心を留める者は、自分への恵みを捨て去ります。'),
('JPN', '约拿书', 32, 2, 9, 'しかし私は、感謝の声をあげて、あなたにいけにえを献げ、私の誓いを果たします。救いは主のものです。」'),
('JPN', '约拿书', 32, 2, 10, '主は魚に命じて、ヨナを陸地に吐き出させた。'),
('JPN', '约拿书', 32, 3, 1, '再びヨナに次のような主のことばがあった。'),
('JPN', '约拿书', 32, 3, 2, '「立ってあの大きな都ニネベに行き、わたしがあなたに伝える宣言をせよ。」'),
('JPN', '约拿书', 32, 3, 3, 'ヨナは、主のことばのとおりに、立ってニネベに行った。ニネベは、行き巡るのに三日かかるほどの非常に大きな都であった。'),
('JPN', '约拿书', 32, 3, 4, 'ヨナはその都に入って、まず一日分の道のりを歩き回って叫んだ。「あと四十日すると、ニネベは滅びる。」'),
('JPN', '约拿书', 32, 3, 5, 'すると、ニネベの人々は神を信じ、断食を呼びかけ、身分の高い者から低い者まで粗布をまとった。'),
('JPN', '约拿书', 32, 3, 6, 'このことがニネベの王の耳に入ると、彼は王座から立ち上がって、王服を脱ぎ捨てて粗布をまとい、灰の上に座った。'),
('JPN', '约拿书', 32, 3, 7, 'そして、王と大臣たちの命令によって、次のような布告がニネベに出された。「人も家畜も、牛も羊もみな、何も味わってはならない。草をはんだり、水を飲んだりしてはならない。'),
('JPN', '约拿书', 32, 3, 8, '人も家畜も、粗布を身にまとい、ひたすら神に願い、それぞれ悪の道と、その横暴な行いから立ち返れ。'),
('JPN', '约拿书', 32, 3, 9, 'もしかすると、神が思い直してあわれみ、その燃える怒りを収められ、私たちは滅びないですむかもしれない。」'),
('JPN', '约拿书', 32, 3, 10, '神は彼らの行いを、すなわち、彼らが悪の道から立ち返ったのをご覧になった。そして神は彼らに下すと言ったわざわいを思い直し、それを行われなかった。'),
('JPN', '约拿书', 32, 4, 1, 'ところが、このことはヨナを非常に不愉快にした。ヨナは怒って、'),
('JPN', '约拿书', 32, 4, 2, '主に祈った。「ああ、主よ。私がまだ国にいたときに、このことを申し上げたではありませんか。それで、私は初めタルシシュへ逃れようとしたのです。あなたが情け深くあわれみ深い神であり、怒るのに遅く、恵み豊かで、わざわいを思い直される方であることを知っていたからです。'),
('JPN', '约拿书', 32, 4, 3, 'ですから、主よ、どうか今、私のいのちを取ってください。私は生きているより死んだほうがましです。」'),
('JPN', '约拿书', 32, 4, 4, '主は言われた。「あなたは当然であるかのように怒るのか。」'),
('JPN', '约拿书', 32, 4, 5, 'ヨナは都から出て、都の東の方に座った。そしてそこに自分で仮小屋を作り、都の中で何が起こるかを見極めようと、その陰のところに座った。'),
('JPN', '约拿书', 32, 4, 6, '神である主は一本の唐胡麻を備えて、ヨナの上をおおうように生えさせ、それを彼の頭の上の陰にして、ヨナの不機嫌を直そうとされた。ヨナはこの唐胡麻を非常に喜んだ。'),
('JPN', '约拿书', 32, 4, 7, 'しかし翌日の夜明けに、神は一匹の虫を備えられた。虫がその唐胡麻をかんだので、唐胡麻は枯れた。'),
('JPN', '约拿书', 32, 4, 8, '太陽が昇ったとき、神は焼けつくような東風を備えられた。太陽がヨナの頭に照りつけたので、彼は弱り果て、自分の死を願って言った。「私は生きているより死んだほうがましだ。」'),
('JPN', '约拿书', 32, 4, 9, 'すると神はヨナに言われた。「この唐胡麻のために、あなたは当然であるかのように怒るのか。」ヨナは言った。「私が死ぬほど怒るのは当然のことです。」'),
('JPN', '约拿书', 32, 4, 10, '主は言われた。「あなたは、自分で労さず、育てもせず、一夜で生えて一夜で滅びたこの唐胡麻を惜しんでいる。'),
('JPN', '约拿书', 32, 4, 11, 'ましてわたしは、この大きな都ニネベを惜しまないでいられるだろうか。そこには、右も左も分からない十二万人以上の人間と、数多くの家畜がいるではないか。」'),
('JPN', '弥迦书', 33, 1, 1, 'モレシェテ人ミカにあった主のことば。これは、ユダの王ヨタム、アハズ、ヒゼキヤの時代に、彼がサマリアとエルサレムについて見た幻である。'),
('JPN', '弥迦书', 33, 1, 2, 'すべての民族よ、聞け。地とそこに満ちているものたちよ、耳を傾けよ。神である主は、あなたがたのうちで証人となり、主はその聖なる宮から来て証人となられる。'),
('JPN', '弥迦书', 33, 1, 3, '見よ。主は御住まいを出、降りて来て、地の高い所を踏まれる。'),
('JPN', '弥迦书', 33, 1, 4, '山々は主の足もとに溶け去り、もろもろの谷は裂ける。まるで、火の前の、ろうのように。坂に注がれた水のように。'),
('JPN', '弥迦书', 33, 1, 5, 'これはみな、ヤコブの背きのゆえ、イスラエルの家の罪のゆえだ。「ヤコブの背きとは何か。サマリアではないか。ユダの高き所とは何か。エルサレムではないか。'),
('JPN', '弥迦书', 33, 1, 6, 'わたしはサマリアを野にある瓦礫の山とし、ぶどうを植える畑とする。その石を谷間に投げ込んで、その基を暴く。'),
('JPN', '弥迦书', 33, 1, 7, 'その刻んだ像はすべて打ち砕かれ、儲けはみな火で焼かれる。わたしはその偶像をすべて荒れすたらせる。それらは遊女の儲けで集められたのだから、遊女の儲けに戻る。」'),
('JPN', '弥迦书', 33, 1, 8, 'このゆえに、私は嘆き、泣き叫び、裸足で、裸で歩く。私はジャッカルのように嘆き、だちょうのように悲しみ泣く。'),
('JPN', '弥迦书', 33, 1, 9, 'まことに、その打ち傷は癒やしがたい。それはユダにまで及び、私の民の門、エルサレムにまで達する。'),
('JPN', '弥迦书', 33, 1, 10, '「ガテで告げるな。決して泣いてはならない。ベテ・レ・アフラでちりの中を転げ回れ。'),
('JPN', '弥迦书', 33, 1, 11, 'シャフィルに住む者よ、裸になって恥じながら通り過ぎよ。ツァアナンに住む者は出て来ない。ベテ・エツェルの嘆きは、あなたがたから、立つところを奪い取る。'),
('JPN', '弥迦书', 33, 1, 12, 'まことに、マロテに住む者は、病むほどに幸せを待ち望む。エルサレムの門に、主からわざわいが下ったのだ。'),
('JPN', '弥迦书', 33, 1, 13, 'ラキシュに住む者よ、戦車に早馬をつなげ。そこは娘シオンにとって罪の始まり。実に、イスラエルの背きが、あなたのうちに見出されたのだ。'),
('JPN', '弥迦书', 33, 1, 14, 'それゆえ、あなたは別れの贈り物をモレシェテ・ガテに与える。アクジブの家々は、イスラエルの王たちにとって欺く者となる。'),
('JPN', '弥迦书', 33, 1, 15, 'マレシャに住む者よ、わたしは再び、侵略者をあなたのところに送る。イスラエルの栄光はアドラムまで行く。'),
('JPN', '弥迦书', 33, 1, 16, '頭を剃れ。あなたが喜びとする子らのために、その剃ったところを、禿鷲のように大きくせよ。彼らは捕らえられて、去って行くからだ。」'),
('JPN', '弥迦书', 33, 2, 1, 'わざわいだ。不法を謀り、寝床の上で悪を行う者。朝の光とともに、彼らはこれを実行する。自分たちの手に力があるからだ。'),
('JPN', '弥迦书', 33, 2, 2, '彼らは畑を欲しがって、これをかすめ、家々を取り上げる。彼らは人とその持ち家を、人とその相続地をゆすり取る。'),
('JPN', '弥迦书', 33, 2, 3, 'それゆえ、主はこう言われる。「見よ。わたしはこういう氏族に、わざわいを下そうと考えている。そこからあなたがたは頭をもたげることもできず、胸を張って歩くこともできなくなる。それは、わざわいの時だからだ。」'),
('JPN', '弥迦书', 33, 2, 4, 'その日、あなたがたについて嘲りの声があがり、嘆きの歌が起こって言う。「われわれはすっかり荒らされてしまった。私の民の割り当て地は替えられてしまった。どのようにして私から移され、われわれの畑が背信の者に分け与えられたのか。」'),
('JPN', '弥迦书', 33, 2, 5, 'それゆえ、主の集会には、あなたのためにくじを引いて測り綱を張る者がいなくなる。'),
('JPN', '弥迦书', 33, 2, 6, '「戯言を言うな」と彼らは戯言を言う。「そんな戯言を言ってはならない。辱めを受けることはない。」'),
('JPN', '弥迦书', 33, 2, 7, 'ヤコブの家がそんなことを言われてよいものか。主がこれを我慢されるだろうか。これは主のみわざだろうか。私のことばは、まっすぐに歩む者に益とならないだろうか。'),
('JPN', '弥迦书', 33, 2, 8, '「近ごろ、わたしの民は敵として立ち上がった。あなたがたは、豪華な上着をはぎ取る。安心して通り過ぎていく者、戦いから帰って来る者たちから。'),
('JPN', '弥迦书', 33, 2, 9, 'あなたがたは、わたしの民の女たちを、その楽しみの家から追い出し、その幼子たちから、わたしの誉れを永遠に取り去る。'),
('JPN', '弥迦书', 33, 2, 10, 'さあ、立ち去れ。ここは憩いの場所ではない。ここは汚れで滅ぼされるからだ。それはひどい滅びだ。'),
('JPN', '弥迦书', 33, 2, 11, 'もし人が風の赴くままに歩き回り、『私はあなたがたに薦めよう。ぶどう酒と強い酒を』と偽って言うなら、その者は、この民に戯言を言う者だ。'),
('JPN', '弥迦书', 33, 2, 12, 'ヤコブよ。わたしは、あなたを必ずみな集め、イスラエルの残りの者を必ず呼び集める。わたしは彼らを、囲いの中の羊のように、牧場の中の群れのように、一つに集める。こうして、人々のざわめきが起こる。'),
('JPN', '弥迦书', 33, 2, 13, '打ち破る者は彼らの先頭に立って上って行く。彼らは門を打ち破って進み、そこを出て行く。彼らの王が彼らの前を、主が彼らの先頭を進む。」'),
('JPN', '弥迦书', 33, 3, 1, '私は言った。「聞け。ヤコブのかしらたち、イスラエルの家の首領たち。あなたがたは公正を知っているはずではないか。'),
('JPN', '弥迦书', 33, 3, 2, 'あなたがたは善を憎んで悪を愛し、人々の皮を剝ぎ、その骨から肉をそぎ取る。'),
('JPN', '弥迦书', 33, 3, 3, 'わたしの民の肉を食らい、皮を剝ぎ取って、骨を打ち砕き、鍋の中のもののように、また大釜の中の肉切れのように、それを切れ切れに裂く。」'),
('JPN', '弥迦书', 33, 3, 4, 'そのため彼らが主に叫んでも、主は彼らに答えない。そのとき、主は彼らから顔を隠される。彼らの行いが悪いからだ。'),
('JPN', '弥迦书', 33, 3, 5, '預言者たちについて、主はこう言われる。「彼らはわたしの民を惑わし、かむ物が歯にあれば『平和があるように』と叫ぶが、口に何も与えない者には聖戦を布告する。」'),
('JPN', '弥迦书', 33, 3, 6, 'それゆえ、あなたがたには、夜にも幻がなく、暗闇にも占いがない。太陽も預言者たちの上に沈み、昼も彼らの上で暗くなる。'),
('JPN', '弥迦书', 33, 3, 7, '先見者たちは恥を見、占い師たちは屈辱を味わう。彼らはみな、口ひげをおおう。神の答えがないからだ。'),
('JPN', '弥迦书', 33, 3, 8, 'しかし、私には力が満ちている。主の霊によって、公正と勇気に満ちている。ヤコブにはその背きを、イスラエルにはその罪を告げる。'),
('JPN', '弥迦书', 33, 3, 9, 'これを聞け。ヤコブの家のかしらたち、イスラエルの家の首領たち。あなたがたは公正を忌み嫌い、あらゆる正しいことを曲げている。'),
('JPN', '弥迦书', 33, 3, 10, '流血でシオンを、不正でエルサレムを建てている。'),
('JPN', '弥迦书', 33, 3, 11, 'そのかしらたちは賄賂を取ってさばき、祭司たちは代金を取って教え、預言者たちは金を取って占いをする。しかもなお、彼らは主を当てにして、「主は私たちの中におられるではないか。わざわいは私たちの上に及ばない」と言う。'),
('JPN', '弥迦书', 33, 3, 12, 'それゆえ、あなたがたゆえにシオンは畑のように耕され、エルサレムは瓦礫の山となり、神殿の山は木々におおわれた丘となる。'),
('JPN', '弥迦书', 33, 4, 1, 'その終わりの日、主の家の山は、山々のかしらとして堅く立ち、もろもろの丘よりも高くそびえ立つ。そこへもろもろの民が流れて来る。'),
('JPN', '弥迦书', 33, 4, 2, '多くの国々が来て言う。「さあ、主の山、ヤコブの神の家に上ろう。主はご自分の道を私たちに教えてくださる。私たちはその道筋を進もう。」それは、シオンからみおしえが、エルサレムから主のことばが出るからだ。'),
('JPN', '弥迦书', 33, 4, 3, '主は多くの民族の間をさばき、遠く離れた強い国々に判決を下す。彼らはその剣を鋤に、その槍を鎌に打ち直す。国は国に向かって剣を上げず、もう戦うことを学ばない。'),
('JPN', '弥迦书', 33, 4, 4, '彼らはみな、それぞれ自分のぶどうの木の下や、いちじくの木の下に座るようになり、彼らを脅かす者はいない。まことに万軍の主の御口が告げる。'),
('JPN', '弥迦书', 33, 4, 5, 'まことに、すべての民族は、それぞれ自分たちの神の名によって歩む。しかし、私たちは、世々限りなく、私たちの神、主の御名によって歩む。'),
('JPN', '弥迦书', 33, 4, 6, '「その日──主のことば──わたしは足を引きずる者を集め、追いやられた者、また、わたしが苦しめた者を呼び集める。'),
('JPN', '弥迦书', 33, 4, 7, 'わたしは足を引きずる者を、残りの者とし、遠くへ移された者を、強い国民とする。主であるわたしが、シオンの山で、今よりとこしえまで、彼らの王となる。'),
('JPN', '弥迦书', 33, 4, 8, 'あなたは、羊の群れのやぐら、娘シオンの丘。あなたには、あのかつての主権、娘エルサレムの王国が戻って来る。」'),
('JPN', '弥迦书', 33, 4, 9, '今、なぜあなたは大声で叫ぶのか。あなたのうちに王がいないのか。あなたの助言者は滅び失せたのか。それで、子を産む女のような激しい痛みがあなたをとらえたのか。'),
('JPN', '弥迦书', 33, 4, 10, '娘シオンよ。子を産む女のように、身もだえして、もがき回れ。今、あなたは町を出て野に宿り、バビロンまで行く。そこで、あなたは助け出される。そこで、主があなたを敵の手から贖い出される。'),
('JPN', '弥迦书', 33, 4, 11, '今、多くの国々があなたに敵対して集まり、そして言う。「シオンは汚されるがよい。われわれはこの目でじっとそれを見ていよう」と。'),
('JPN', '弥迦书', 33, 4, 12, 'しかし彼らは主の御思いを知らず、その御計らいに気づかない。主は、打ち場の麦束のように彼らを集められたのだ。'),
('JPN', '弥迦书', 33, 4, 13, '「娘シオンよ、さあ、脱穀せよ。わたしが、あなたの角を鉄とし、あなたのひづめを青銅とする。あなたは多くの国民を粉々に砕き、彼らの不正な利得を主のために、彼らの財宝を全地の主のために聖絶する。」'),
('JPN', '弥迦书', 33, 5, 1, '今、軍勢をなす娘よ、勢ぞろいせよ。包囲網が私たちに対して設けられた。彼らは、イスラエルをさばく者の頬を杖で打つ。'),
('JPN', '弥迦书', 33, 5, 2, '「ベツレヘム・エフラテよ、あなたはユダの氏族の中で、あまりにも小さい。だが、あなたからわたしのためにイスラエルを治める者が出る。その出現は昔から、永遠の昔から定まっている。」'),
('JPN', '弥迦书', 33, 5, 3, 'それゆえ、彼らはそのままにしておかれる。産婦が子を産む時まで。そのとき、彼の兄弟のほかの者はイスラエルの子らのもとに帰る。'),
('JPN', '弥迦书', 33, 5, 4, '彼は立って、主の力と、彼の神、主の御名の威光によって群れを飼う。そして彼らは安らかに住まう。今や彼の威力が、地の果ての果てまで及ぶからだ。'),
('JPN', '弥迦书', 33, 5, 5, '平和は次のようにして来る。アッシリアが私たちの国に来て、私たちの宮殿を踏みにじるとき、私たちはこれに対抗して七人の牧者、八人の指導者を立てる。'),
('JPN', '弥迦书', 33, 5, 6, '彼らはアッシリアの地を剣で、ニムロデの地を抜き身の剣で飼いならす。アッシリアが私たちの国に来て、私たちの領土に踏み込んで来るとき、彼は、私たちをアッシリアから救い出す。'),
('JPN', '弥迦书', 33, 5, 7, 'そのとき、ヤコブの残りの者は、多くの国々の民のただ中で、主のもとから降りる露、青草に降り注ぐ夕立のようだ。彼らは人に望みを置かず、人の子らに期待をかけない。'),
('JPN', '弥迦书', 33, 5, 8, 'ヤコブの残りの者は異邦の民の中、多くの国々の民のただ中で、森の獣の中の獅子、羊の群れの中の若い獅子のようだ。通り過ぎるときには、踏みにじり、かみ裂けば、助け出す者はいない。'),
('JPN', '弥迦书', 33, 5, 9, 'あなたが敵対する者に向けて御手を上げると、あなたの敵はみな絶ち滅ぼされる。'),
('JPN', '弥迦书', 33, 5, 10, '「その日──主のことば──わたしはあなたのただ中から、あなたの馬を滅ぼし、戦車を打ち壊し、'),
('JPN', '弥迦书', 33, 5, 11, 'あなたの国の町々を絶ち滅ぼし、要塞をみな破壊する。'),
('JPN', '弥迦书', 33, 5, 12, 'わたしはあなたの手から呪術者を断ち、占い師をあなたのところから絶やす。'),
('JPN', '弥迦书', 33, 5, 13, 'わたしは、あなたのただ中から、刻んだ像と石の柱を断ち切る。あなたはもう、自分の手で造った物を拝まない。'),
('JPN', '弥迦书', 33, 5, 14, 'わたしは、あなたのアシェラ像をあなたのただ中から根こそぎにし、あなたの町々を滅ぼし尽くす。'),
('JPN', '弥迦书', 33, 5, 15, 'わたしは怒りと憤りをもって、わたしに聞き従わなかった国々に復讐する。」'),
('JPN', '弥迦书', 33, 6, 1, 'さあ、主の言われることを聞け。立ち上がれ。山々に訴えよ。もろもろの丘にあなたの声を聞かせよ。'),
('JPN', '弥迦书', 33, 6, 2, '山々よ、聞け。主の訴えを。変わることのない地の基よ。主がご自分の民を訴え、イスラエルと論争される。'),
('JPN', '弥迦书', 33, 6, 3, '「わたしの民よ、わたしがあなたに何をしたというのか。どのようにしてあなたを煩わせたというのか。わたしに答えよ。'),
('JPN', '弥迦书', 33, 6, 4, 'わたしはあなたをエジプトの地から上らせ、奴隷の家からあなたを贖い出し、あなたの前にモーセと、アロンと、ミリアムを送った。'),
('JPN', '弥迦书', 33, 6, 5, 'わたしの民よ、思い起こせ。モアブの王バラクが何を企んだか。ベオルの子バラムが彼に何と答えたか。シティムからギルガルまでに何があったか。それは、あなたが主の正しいわざを知るためであった。」'),
('JPN', '弥迦书', 33, 6, 6, '何をもって、私は主の前に進み行き、いと高き神の前にひれ伏そうか。全焼のささげ物、一歳の子牛をもって御前に進み行くべきだろうか。'),
('JPN', '弥迦书', 33, 6, 7, '主は幾千の雄羊、幾万の油を喜ばれるだろうか。私の背きのために、私の長子を、私のたましいの罪のために、胎の実を献げるべきだろうか。'),
('JPN', '弥迦书', 33, 6, 8, '主はあなたに告げられた。人よ、何が良いことなのか、主があなたに何を求めておられるのかを。それは、ただ公正を行い、誠実を愛し、へりくだって、あなたの神とともに歩むことではないか。'),
('JPN', '弥迦书', 33, 6, 9, '主の御声が都に向かって叫ぶ。──あなたの御名を恐れることは英知だ──「聞け、杖のことを。だれがその都を指定したのか。'),
('JPN', '弥迦书', 33, 6, 10, 'まだ、悪しき者の家には、不正の財宝と、のろわれた升目不足の升があるではないか。'),
('JPN', '弥迦书', 33, 6, 11, '不正な秤と、欺きの重り石の袋を、誤りなしとすることが、わたしにできるだろうか。'),
('JPN', '弥迦书', 33, 6, 12, '富む者たちは不法で満ち、住民は偽りを言う。彼らの口の中で舌が欺く。'),
('JPN', '弥迦书', 33, 6, 13, 'わたしも、あなたを打って痛めつけ、あなたの罪のゆえに荒れ果てるままにする。'),
('JPN', '弥迦书', 33, 6, 14, 'あなたは食べても満ち足りず、あなたの腹は飢える。取っておいても保つことはできず、保っていたものは、わたしが剣に渡す。'),
('JPN', '弥迦书', 33, 6, 15, '種を蒔いても、刈ることがなく、オリーブを搾っても、油を身に塗ることがない。新しいぶどう酒も、それを飲むことがない。'),
('JPN', '弥迦书', 33, 6, 16, 'あなたはオムリの掟と、アハブの家のすべての慣わしを守った。あなたがたは、彼らのはかりごとに従って歩んだ。それは、わたしがあなたを恐怖のもととし、住民を嘲りの的とするためだ。あなたがたは、わたしの民へのそしりを負う。」'),
('JPN', '弥迦书', 33, 7, 1, 'ああ、なんと悲しいことだ。私は夏の果物を集める者のよう、ぶどうの取り残しの実を取り入れる時のようになった。食べられる房は一つもなく、私の好きな初なりのいちじくの実もない。'),
('JPN', '弥迦书', 33, 7, 2, '敬虔な者はこの地から消え失せ、人々の間に、心の直ぐな者は一人もいない。みな血を流そうと待ち伏せし、互いに網をかけ合って捕らえようとする。'),
('JPN', '弥迦书', 33, 7, 3, '彼らの手は悪事を働くのに巧みで、役人もさばき人も賄賂を求める。有力者は自分の欲するままを語り、こうして事をねじ曲げている。'),
('JPN', '弥迦书', 33, 7, 4, '彼らのうちの善良な人も茨のようだ。心の直ぐな者も茨の生け垣に劣る。あなたを見張る者の日、あなたの刑罰の日が来る。今、彼らに混乱が起きる。'),
('JPN', '弥迦书', 33, 7, 5, 'あなたがたは友を信用するな。親しい友も信頼するな。あなたの懐に寝る者からも、あなたの口の戸を守れ。'),
('JPN', '弥迦书', 33, 7, 6, '子は父を侮り、娘はその母に、嫁はその姑に逆らい、それぞれ自分の家の者を敵とする。'),
('JPN', '弥迦书', 33, 7, 7, 'しかし、私は主を仰ぎ見、私の救いの神を待ち望む。私の神は私の言うことを聞いてくださる。'),
('JPN', '弥迦书', 33, 7, 8, '私の敵よ、私のことで喜ぶな。私は倒れても起き上がる。私は闇の中に座しても、主が私の光だ。'),
('JPN', '弥迦书', 33, 7, 9, '私は主の激しい怒りを身に受けている。私が主の前に罪ある者だからだ。しかし、それは、主が私の訴えを取り上げ、私を正しくさばいてくださるまでだ。主は私を光に連れ出してくださる。私は、その義を見る。'),
('JPN', '弥迦书', 33, 7, 10, '私の敵はこれを見て恥におおわれる。彼らは、私に向かって「あなたの神、主は、どこにいるのか」と言った者たちだ。私の目は、確かに見る。今に、敵は道の泥のように踏みつけられる。'),
('JPN', '弥迦书', 33, 7, 11, 'あなたの石垣を建て直す日、その日、国境が広げられる。'),
('JPN', '弥迦书', 33, 7, 12, 'その日、アッシリアとエジプトの町々から、エジプトから大河まで、海から海まで、山から山まで、あなたのところに人々がやって来る。'),
('JPN', '弥迦书', 33, 7, 13, 'しかし、その地は、そこに住む者たちのゆえに、彼らの行いの実によって荒れ果てる。'),
('JPN', '弥迦书', 33, 7, 14, 'どうか、あなたの杖で、あなたの民を、あなたのゆずりの群れを牧してください。彼らは林の中、果樹園の中に、ひとり離れて住んでいます。どうか、彼らが昔の日のように、バシャンとギルアデで草をはむようにしてください。'),
('JPN', '弥迦书', 33, 7, 15, '「あなたがエジプトの地から出た日のように、わたしは奇しいわざを彼らに見せる。」'),
('JPN', '弥迦书', 33, 7, 16, '諸国の民は見て、自分たちのすべての力を恥じ、手を口に当て、彼らの耳は聞こえなくなります。'),
('JPN', '弥迦书', 33, 7, 17, '彼らは、蛇のように、地を這うもののように土をなめ、震えながら自分たちの洞穴から出て来ます。そして、私たちの神、主のみもとで、おじ惑い、あなたを恐れます。'),
('JPN', '弥迦书', 33, 7, 18, 'あなたのような神が、ほかにあるでしょうか。あなたは咎を除き、ご自分のゆずりである残りの者のために、背きを見過ごしてくださる神。いつまでも怒り続けることはありません。神は、恵みを喜ばれるからです。'),
('JPN', '弥迦书', 33, 7, 19, 'もう一度、私たちをあわれみ、私たちの咎を踏みつけて、すべての罪を海の深みに投げ込んでください。'),
('JPN', '弥迦书', 33, 7, 20, '昔、私たちの父祖たちに誓われたように、ヤコブにまことを、アブラハムに恵みをお与えください。'),
('JPN', '那鸿书', 34, 1, 1, 'ニネベについての宣告。エルコシュ人ナホムの幻の記録。'),
('JPN', '那鸿书', 34, 1, 2, '主はねたんで復讐する神。主は復讐し、憤る方。主はご自分に逆らう者に復讐し、敵に対して怒る方。'),
('JPN', '那鸿书', 34, 1, 3, '主は怒るのに遅く、力強い方。決して罰せずにおかれることはない。主は、その道がつむじ風と嵐の中にあり、雲は、御足がかき立てるほこりである。'),
('JPN', '那鸿书', 34, 1, 4, '主は海を叱って干上がらせ、すべての川を涸らされる。バシャンとカルメルはしおれ、レバノンの花もしおれる。'),
('JPN', '那鸿书', 34, 1, 5, '山々は主の前に揺れ動き、もろもろの丘は溶け去る。地は御前でくつがえる。世界とその中に住むすべてのものも。'),
('JPN', '那鸿书', 34, 1, 6, '主の激しい憤りの前に、だれが立てるだろうか。だれが、その燃える怒りに耐えられるだろうか。主の憤りは火のように注がれ、岩々は御前に打ち砕かれる。'),
('JPN', '那鸿书', 34, 1, 7, '主はいつくしみ深く、苦難の日の砦。ご自分に身を避ける者を知っていてくださる。'),
('JPN', '那鸿书', 34, 1, 8, 'しかし、押し流す大水でその場所を滅ぼし尽くし、敵どもを闇に追いやられる。'),
('JPN', '那鸿书', 34, 1, 9, 'おまえたちは主に対して何を企むのか。主は滅ぼし尽くす方。敵対する者は二度と立ち上がれない。'),
('JPN', '那鸿书', 34, 1, 10, '彼らは、絡みついた茨。大酒飲みの酔っぱらいのようだ。乾ききった刈り株のように焼き尽くされる。'),
('JPN', '那鸿书', 34, 1, 11, 'おまえたちの中から、主に対して悪を謀り、よこしまなことを企てる者が出た。'),
('JPN', '那鸿书', 34, 1, 12, '主はこう言われる。「彼らが壮健で、数が多くても、それでも、刈り取られて去って行く。わたしはあなたを苦しめたが、もう苦しめない。'),
('JPN', '那鸿书', 34, 1, 13, '今、わたしは彼のくびきを砕いてあなたから外し、あなたのかせを打ち砕く。」'),
('JPN', '那鸿书', 34, 1, 14, '主はおまえについて命じられる。「もはや子が宿ることなく、おまえの名は絶える。おまえの神々の宮から、わたしは彫像や鋳像を断ち切る。わたしはおまえの墓を造る。おまえが取るに足りない者となったからだ。」'),
('JPN', '那鸿书', 34, 1, 15, '見よ。良い知らせを伝える人の足が、平和を告げ知らせる人の足が山々の上にある。ユダよ、あなたの祭りを祝い、あなたの誓願を果たせ。よこしまな者たちは、もう二度とあなたの間を通り過ぎることがない。彼らはみな、絶ち滅ぼされた。'),
('JPN', '那鸿书', 34, 2, 1, '追い散らす者が、おまえに向かって上って来る。塁を見守り、道を見張れ。腰を強くし、大いに力を奮い立たせよ。'),
('JPN', '那鸿书', 34, 2, 2, '主がヤコブの威光を、イスラエルの威光のように回復されるからだ。まことに、荒らす者が彼らを荒らし、彼らのぶどうの枝を損なう。'),
('JPN', '那鸿书', 34, 2, 3, '勇士の盾は赤く染まり、兵士は緋色に包まれる。戦車は、それが整えられる日、鋼の火を通され、槍は振り回される。'),
('JPN', '那鸿书', 34, 2, 4, '戦車は通りを走り狂い、広場を駆け巡る。その有様はたいまつのようで、稲妻のように走る。'),
('JPN', '那鸿书', 34, 2, 5, '高貴な人は呼び出されるが、途中でつまずき倒れる。人々は町の城壁へ急ぐが、そこに外から柵が設けられる。'),
('JPN', '那鸿书', 34, 2, 6, 'いくつもの川の水門が開かれ、宮殿は消え去る。'),
('JPN', '那鸿书', 34, 2, 7, '王妃は捕らえられ、連れ去られる。女奴隷たちは鳩のような声でつぶやき、胸をたたいて悲しむ。'),
('JPN', '那鸿书', 34, 2, 8, 'ニネベは、水が流れ出る池のようだ。「止まれ、止まれ」と言っても、向きを変える者はいない。'),
('JPN', '那鸿书', 34, 2, 9, '銀を奪え。金も奪え。その財宝には限りがない。あらゆる尊い品々があふれている。'),
('JPN', '那鸿书', 34, 2, 10, '不毛、空虚、そして荒廃。心は萎え、膝は震える。どの腰もわななき、どの顔も青ざめる。'),
('JPN', '那鸿书', 34, 2, 11, '獅子の住みかはどこか。若い獅子にとっての餌場は。雄獅子と雌獅子が出歩くときに、子獅子がだれにも脅かされない住みかは。'),
('JPN', '那鸿书', 34, 2, 12, '獅子は、十分な獲物を子獅子のために引き裂き、雌獅子のためにかみ殺し、獲物でその穴を、かみ裂かれた物でその巣を満たす。'),
('JPN', '那鸿书', 34, 2, 13, '「見よ、わたしはおまえを敵とする。──万軍の主のことば──おまえの戦車を燃やして煙にし、若い獅子を剣が食い尽くす。おまえの獲物を地から絶やし、おまえの使者たちの声はもう聞かれない。」'),
('JPN', '那鸿书', 34, 3, 1, 'わざわいだ、流血の町。すべては偽りで略奪に満ち、強奪はやまない。'),
('JPN', '那鸿书', 34, 3, 2, 'むちの音。車輪の響き。駆ける馬。飛び跳ねる戦車。'),
('JPN', '那鸿书', 34, 3, 3, '突進する騎兵。剣のきらめき。槍のひらめき。おびただしい戦死者。山なす屍。数えきれない死体。死体に人はつまずく。'),
('JPN', '那鸿书', 34, 3, 4, 'これは、遊女の淫行の数々に、呪術を行う女の麗しさによるものだ。彼女はその淫行によって国々を、その呪術によって諸部族を売り渡した。'),
('JPN', '那鸿书', 34, 3, 5, '「見よ、わたしはおまえを敵とする。──万軍の主のことば──わたしはおまえの裾を顔の上にまでまくり上げ、諸国の民におまえの裸を見せる。諸国の王におまえの恥を。'),
('JPN', '那鸿书', 34, 3, 6, 'おまえの上に忌まわしいものを投げかけ、おまえを愚弄し、おまえを見せ物にする。'),
('JPN', '那鸿书', 34, 3, 7, 'おまえを見る者はみな、おまえから逃げて言う。『ニネベは荒れ果てた。だれが彼女のために嘆くのか。』わたしはどこからおまえを慰める者を探して来られようか。'),
('JPN', '那鸿书', 34, 3, 8, 'おまえはテーベよりもすぐれているのか。それはナイル川のほとりにあり、水がそれを取り囲んでいる。その塁壁は海、海がその城壁。'),
('JPN', '那鸿书', 34, 3, 9, 'クシュとエジプトはその力。その力には限りがない。プテもルブ人もその助け手。'),
('JPN', '那鸿书', 34, 3, 10, 'しかし、それもまた捕囚となり、捕らわれの身となって出て行く。その幼子たちはあらゆる街角で八つ裂きにされ、高貴な人たちはくじで分けられ、おもだった者たちはみな、鎖につながれる。'),
('JPN', '那鸿书', 34, 3, 11, 'おまえもまた、酔いしれて意識を失う。おまえもまた、敵から逃げて砦を探し求める。'),
('JPN', '那鸿书', 34, 3, 12, 'おまえのすべての要塞は、初なりの実をつけたいちじくの木のようだ。揺さぶると、食べる者の口に実が落ちる。'),
('JPN', '那鸿书', 34, 3, 13, '見よ、おまえの兵隊はおまえの中にいる女たち。敵に向かっておまえの国の門は広く開け放たれ、火がかんぬきを焼き尽くす。'),
('JPN', '那鸿书', 34, 3, 14, '包囲の日に備えて水を汲み、おまえの要塞を強固にせよ。泥の中に入り、粘土を踏みつけ、れんがの型を取れ。'),
('JPN', '那鸿书', 34, 3, 15, 'その場所で、火はおまえを食い尽くす。剣はおまえを切り倒し、バッタのように火がおまえを食い尽くす。バッタのように数を増し、いなごのように増えよ。'),
('JPN', '那鸿书', 34, 3, 16, 'おまえは商人を天の星より多くした。しかし、バッタがこれを襲って飛び去る。'),
('JPN', '那鸿书', 34, 3, 17, 'おまえの廷臣たちは、いなごのよう、司令官たちは、群がるいなごのようだ。寒い日には城壁の上でたむろし、日が昇ると逃げ去って、どこへ行くか、行く先をだれも知らない。'),
('JPN', '那鸿书', 34, 3, 18, 'アッシリアの王よ。おまえの牧者たちは眠り、高貴な者たちはじっととどまっている。おまえの民は山々の上に散らされ、集める者はだれもいない。'),
('JPN', '那鸿书', 34, 3, 19, 'おまえの傷は癒えることがなく、打ち傷は癒やしがたい。おまえのうわさを聞く者はみな、おまえのことで手をたたく。おまえの絶え間ない悪事が及ばなかった者がいるだろうか。」'),
('JPN', '哈巴谷书', 35, 1, 1, '宣告。これは預言者ハバククが見たものである。'),
('JPN', '哈巴谷书', 35, 1, 2, 'いつまでですか、主よ。私が叫び求めているのに、あなたが聞いてくださらないのは。「暴虐だ」とあなたに叫んでいるのに、救ってくださらないのは。'),
('JPN', '哈巴谷书', 35, 1, 3, 'なぜ、あなたは私に不法を見させ、苦悩を眺めておられるのですか。暴行と暴虐が私のそばにあり、争い事があり、いさかいが起こっています。'),
('JPN', '哈巴谷书', 35, 1, 4, 'そのため、みおしえは麻痺し、さばきが全く行われていません。悪しき者が正しい者を取り囲んでいるからです。そのため、曲がったさばきが行われているのです。'),
('JPN', '哈巴谷书', 35, 1, 5, '「異邦の民を見、目を留めよ。驚き、たじろげ。わたしは一つの事をあなたがたの時代に行うからだ。それが告げられても、あなたがたは信じない。'),
('JPN', '哈巴谷书', 35, 1, 6, '見よ、わたしはカルデア人を起こす。あの強暴で俊敏な国民だ。彼らは地を広く行き巡り、自分のものでない領土を占領する。'),
('JPN', '哈巴谷书', 35, 1, 7, 'それは凄惨そのもの。彼らはさばきと宣告を自ら下す。'),
('JPN', '哈巴谷书', 35, 1, 8, 'その馬は豹より速く、日暮れの狼より敏捷だ。その軍馬は跳ね回り、その騎兵は遠くから来て、鷲のように、獲物にさっと舞い降りる。'),
('JPN', '哈巴谷书', 35, 1, 9, '彼らはみな暴虐を行うためにやって来る。そろって顔を前方に向け、砂のように捕らわれ人を集める。'),
('JPN', '哈巴谷书', 35, 1, 10, '王たちを嘲り、君主たちを笑いものにし、すべての要塞をあざ笑い、土を積み上げて町を攻め取る。'),
('JPN', '哈巴谷书', 35, 1, 11, 'こうして、風のようにやって来て過ぎ去る。しかし自分の力を神とする者は、責めを負う。」'),
('JPN', '哈巴谷书', 35, 1, 12, 'あなたは昔から主ではありませんか。私の神、私の聖なる方よ、私たちが死ぬことはありません。主よ、あなたはさばきのために、彼を立てられました。岩なる方よ、あなたは懲らしめるために、彼を据えられました。'),
('JPN', '哈巴谷书', 35, 1, 13, 'あなたの目は、悪を見るにはあまりにきよくて、苦悩を見つめることができないのでしょう。なぜ、裏切り者を眺めて、黙っておられるのですか。悪しき者が自分より正しい者を吞み込もうとしているときに。'),
('JPN', '哈巴谷书', 35, 1, 14, 'あなたは人を海の魚のように、治める者のない、這う虫のようにされました。'),
('JPN', '哈巴谷书', 35, 1, 15, '彼は、このすべての者を釣り針で釣り上げ、自分の網で引き上げ、自分の引き網で集めます。こうして、彼は喜び楽しみます。'),
('JPN', '哈巴谷书', 35, 1, 16, 'そのため、彼は自分の網に、自分の引き網にいけにえを献げ、焼いて煙にします。これらにより、彼の分け前が豊かになり、食物が豊富になるからです。'),
('JPN', '哈巴谷书', 35, 1, 17, 'そのため、彼は自分の網を空にし続けながら、諸国の民を容赦なく殺すのでしょうか。'),
('JPN', '哈巴谷书', 35, 2, 1, '私は、自分の物見のやぐらに立ち、砦にしかと立って見張り、私の訴えについて、主が私に何を語られるか、私がそれにどう応じるべきかを見よう。'),
('JPN', '哈巴谷书', 35, 2, 2, '主は私に答えられた。「幻を板の上に書き記して、確認せよ。これを読む者が急使として走るために。'),
('JPN', '哈巴谷书', 35, 2, 3, 'この幻は、定めの時について証言し、終わりについて告げ、偽ってはいない。もし遅くなっても、それを待て。必ず来る。遅れることはない。'),
('JPN', '哈巴谷书', 35, 2, 4, '見よ。彼の心はうぬぼれていて直ぐでない。しかし、正しい人はその信仰によって生きる。」'),
('JPN', '哈巴谷书', 35, 2, 5, '実にぶどう酒は裏切るもの。勇士は高ぶっていて、定まることを知らない。彼はよみのように喉を広げ、死のように、満ち足りることを知らない。彼は自分のもとに、すべての国々を集め、あらゆる民をかき集める。'),
('JPN', '哈巴谷书', 35, 2, 6, 'これらはみな、彼に対して嘲りの声をあげ、皮肉たっぷりに、風刺して言わないだろうか。「わざわいだ。いつまでなのか。自分のものでないものを増し加え、その上に担保を重くする者」と。'),
('JPN', '哈巴谷书', 35, 2, 7, 'おまえにかみつく者が突然起き上がり、揺り動かす者が目覚めて、おまえは彼らに略奪されないだろうか。'),
('JPN', '哈巴谷书', 35, 2, 8, 'おまえが多くの国々を略奪したので、ほかのあらゆる民がおまえを略奪する。おまえは人の血を流し、地に暴虐を行った。町々とそのすべての住民に対して。'),
('JPN', '哈巴谷书', 35, 2, 9, 'わざわいだ。自分の家のために不正な利得を貪り、悪の力から逃れるために、自分の巣を高い所に構える者。'),
('JPN', '哈巴谷书', 35, 2, 10, 'おまえは自分の家のために恥ずべきことを謀り、多くの国の民を滅ぼした。おまえのたましいは罪を犯した。'),
('JPN', '哈巴谷书', 35, 2, 11, 'まことに、石は石垣から叫び、梁は家からこれに答える。'),
('JPN', '哈巴谷书', 35, 2, 12, 'わざわいだ。血によって町を建て、不正で都を築き上げる者。'),
('JPN', '哈巴谷书', 35, 2, 13, '見よ、万軍の主によるのではないのか。諸国の民が、ただ火で焼かれるために労し、国々が、ただ無駄に疲れ果てるのは。'),
('JPN', '哈巴谷书', 35, 2, 14, 'まことに、水が海をおおうように、地は、主の栄光を知ることで満たされる。'),
('JPN', '哈巴谷书', 35, 2, 15, 'わざわいだ。その裸を見ようと、友に酒を飲ませ、毒を混ぜて酔わせる者。'),
('JPN', '哈巴谷书', 35, 2, 16, 'おまえは栄光ではなく恥で満ちている。おまえも飲んで、陽の皮を見せよ。主の右の手の杯は、おまえの上に巡り来る。恥辱が、おまえの栄光の上に。'),
('JPN', '哈巴谷书', 35, 2, 17, 'レバノンへの暴虐がおまえをおおい、獣への暴行がおまえを脅かす。おまえは人の血を流し、地に暴虐を行った。町々とそのすべての住民に対して。'),
('JPN', '哈巴谷书', 35, 2, 18, '彫像はいったい何の役に立つのか。彫刻師がそれを刻んだところで。鋳像や、偽りを教える物は何の役に立つのか。これを造った者がそれに頼ったところで。その者は、もの言わぬ偽りの神々を造ったのだ。'),
('JPN', '哈巴谷书', 35, 2, 19, 'わざわいだ。木に向かって目を覚ませと言い、黙っている石に起きろと言う者。これが教えることができるというのか。見よ、それは金や銀をかぶせたもの。その中には何の息もない。'),
('JPN', '哈巴谷书', 35, 2, 20, 'しかし主は、その聖なる宮におられる。全地よ、主の御前に静まれ。'),
('JPN', '哈巴谷书', 35, 3, 1, '預言者ハバククの祈り。シグヨノテの調べにのせて。'),
('JPN', '哈巴谷书', 35, 3, 2, '主よ、私はあなたのうわさを聞きました。主よ、あなたのみわざを恐れています。この数年のうちに、それを繰り返してください。この数年のうちに、それを示してください。激しい怒りのうちにも、あわれみを忘れないでください。'),
('JPN', '哈巴谷书', 35, 3, 3, '神はテマンから、聖なる方はパランの山から来られる。セラその威光は天をおおい、その賛美は地に満ちている。'),
('JPN', '哈巴谷书', 35, 3, 4, 'その輝きは光のよう。ひらめきが御手から上り、そこに御力が隠されている。'),
('JPN', '哈巴谷书', 35, 3, 5, '疫病はその前を行き、熱病がうしろに従う。'),
('JPN', '哈巴谷书', 35, 3, 6, '神が立ってご覧になると、地は揺るぎ、国々は震え上がる。とこしえの山は打ち砕かれ、永遠の丘は低くされる。しかし、その道筋は永遠だ。'),
('JPN', '哈巴谷书', 35, 3, 7, '私が見ると、クシャンの天幕は不法の下にあり、ミディアンの地の幕屋はわなないていた。'),
('JPN', '哈巴谷书', 35, 3, 8, '主よ、川に対して怒りを燃やされるのですか。川に対してあなたの怒りを、海に対して激しい憤りを。確かに、あなたは馬に、あなたの救いの戦車に乗っておられます。'),
('JPN', '哈巴谷书', 35, 3, 9, 'あなたの弓は覆いを取り払われ、ことばの杖による誓いが果たされます。セラあなたは地を裂き、いくつもの川とされます。'),
('JPN', '哈巴谷书', 35, 3, 10, '山々はあなたを見て震え、あふれる水が押し寄せます。深い淵は声を出して、その手を高く上げます。'),
('JPN', '哈巴谷书', 35, 3, 11, '太陽と月は、その住む所にとどまり、あなたの矢の光によって進みます。あなたのきらめく槍のひらめきによって。'),
('JPN', '哈巴谷书', 35, 3, 12, 'あなたは、激しい憤りをもって地を行き巡り、怒りをもって国々を踏みつけられます。'),
('JPN', '哈巴谷书', 35, 3, 13, 'あなたは御民を救うために、油注がれた者を救うために出て来られます。あなたは悪しき者の頭を打ち砕いて首までにし、彼の家の基をあらわにされます。セラ'),
('JPN', '哈巴谷书', 35, 3, 14, 'あなたは杖で戦士たちの頭を突き刺されます。彼らは、苦しむ者をひそかに食い尽くすように、ほしいままに私を追い散らそうと荒れ狂います。'),
('JPN', '哈巴谷书', 35, 3, 15, 'あなたは馬で海を、大水の泡立ちを踏みつけられます。'),
('JPN', '哈巴谷书', 35, 3, 16, 'その音を聞いたとき、私のはらわたはわななき、唇は震えました。腐れは私の骨の内に入り、足もとはぐらつきました。攻めて来る民に臨む苦しみの日を、私は静かに待ちます。'),
('JPN', '哈巴谷书', 35, 3, 17, 'いちじくの木は花を咲かせず、ぶどうの木には実りがなく、オリーブの木も実がなく、畑は食物を生み出さない。羊は囲いから絶え、牛は牛舎にいなくなる。'),
('JPN', '哈巴谷书', 35, 3, 18, 'しかし、私は主にあって喜び躍り、わが救いの神にあって楽しもう。'),
('JPN', '哈巴谷书', 35, 3, 19, '私の主、神は、私の力。私の足を雌鹿のようにし、私に高い所を歩ませる。指揮者のために。弦楽器に合わせて。'),
('JPN', '西番雅书', 36, 1, 1, 'ユダの王、アモンの子ヨシヤの時代に、クシの子ゼパニヤにあった主のことば。クシはゲダルヤの子、ゲダルヤはアマルヤの子、アマルヤはヒゼキヤの子である。'),
('JPN', '西番雅书', 36, 1, 2, '「わたしは必ず、すべてのものを大地の面から取り除く。──主のことば──'),
('JPN', '西番雅书', 36, 1, 3, 'わたしは人と獣を取り除き、空の鳥と海の魚を取り除く。悪者どもをつまずかせ、人を大地の面から断ち切る。──主のことば──'),
('JPN', '西番雅书', 36, 1, 4, 'わたしは手をユダの上に、エルサレムのすべての住民の上に伸ばす。その場所からバアルの残りを、偶像の祭司たちの名を、その祭司らとともに断つ。'),
('JPN', '西番雅书', 36, 1, 5, 'そして、屋上で天の万象を拝む者どもを、また、主に誓いを立てて礼拝しながら、ミルコムに誓いを立てる者どもを、'),
('JPN', '西番雅书', 36, 1, 6, '主に従うことをやめた者ども、主を尋ねず求めない者どもを断ち切る。」'),
('JPN', '西番雅书', 36, 1, 7, '口をつぐめ。神である主の前で。主の日は近い。主はいけにえを備え、招いた者たちを聖別されたからだ。'),
('JPN', '西番雅书', 36, 1, 8, '「主であるわたしが獣を屠る日に、わたしは首長たち、王子たち、すべて外国の服をまとった者たちを罰する。'),
('JPN', '西番雅书', 36, 1, 9, 'その日、わたしは罰する。すべて神殿の敷居を跳び越える者、主人の家を暴虐と欺きで満たす者どもを。'),
('JPN', '西番雅书', 36, 1, 10, 'その日には──主のことば──魚の門から叫び声が、第二区から嘆きの声が、もろもろの丘から大いなる破滅の響きが起こる。'),
('JPN', '西番雅书', 36, 1, 11, '泣き叫べ、マクテシュ区に住む者どもよ。商人はみな滅び失せ、すべて銀を量る者は断ち切られるからだ。'),
('JPN', '西番雅书', 36, 1, 12, 'そのときわたしは、ともしびをかざしてエルサレム中を捜す。そして、ぶどう酒のかすの上によどみつつ、心の中で『主は良いことも、悪いこともしない』と言っている者どもを罰する。'),
('JPN', '西番雅书', 36, 1, 13, '彼らの財産は略奪され、家は荒れ果てる。家を建てても、そこに住めず、ぶどう畑を作っても、ぶどう酒を飲めない。」'),
('JPN', '西番雅书', 36, 1, 14, '主の大いなる日は近い。それは近く、すぐにも来る。主の日に声がする。勇士の悲痛な叫び声が。'),
('JPN', '西番雅书', 36, 1, 15, 'その日は激しい怒りの日、苦難と苦悩の日、荒廃と滅亡の日、闇と暗黒の日、雲と暗闇の日、'),
('JPN', '西番雅书', 36, 1, 16, '角笛と、ときの声の日、城壁のある町々と高い四隅の塔が襲われる日だ。'),
('JPN', '西番雅书', 36, 1, 17, '「わたしが人を苦しめるので、人々は目の見えない人のように歩く。主に対して罪を犯したからだ。彼らの血は、ちりのように、はらわたは、糞のようにまき散らされる。'),
('JPN', '西番雅书', 36, 1, 18, '彼らの銀も、彼らの金も、主の激しい怒りの日に彼らを救い出せない。主のねたみの火で、全土は焼き払われる。主が地に住むすべての人をたちまちのうちに滅ぼし尽くすからだ。」'),
('JPN', '西番雅书', 36, 2, 1, 'ともに集まれ、集まれ。恥知らずの国民よ。'),
('JPN', '西番雅书', 36, 2, 2, '御定めが行われて、その日が籾殻のように過ぎ去らないうちに。主の燃える怒りが、まだあなたがたを襲わないうちに。主の怒りの日が、まだあなたがたを襲わないうちに。'),
('JPN', '西番雅书', 36, 2, 3, 'すべてこの国の、主のさばきを行う柔和な者たちよ、主を尋ね求めよ。義を尋ね求めよ。柔和さを尋ね求めよ。そうすれば、主の怒りの日に、かくまってもらえるかもしれない。'),
('JPN', '西番雅书', 36, 2, 4, 'まことに、ガザは捨てられ、アシュケロンは荒れ果てる。アシュドデは真昼に追い払われ、エクロンは根こそぎにされる。'),
('JPN', '西番雅书', 36, 2, 5, 'わざわいだ、海辺に住む者たち、クレタ人の国。主のことばはおまえたちに向けられている。「ペリシテ人の地、カナンよ。わたしはおまえを消し去って、住む者がいないようにする。」'),
('JPN', '西番雅书', 36, 2, 6, '海辺よ。おまえは牧場となり、牧者たちの牧草地となり、羊の囲い場となる。'),
('JPN', '西番雅书', 36, 2, 7, '海辺はユダの家の残りの者の所有となる。彼らは海辺で羊を飼い、日が暮れると、アシュケロンの家々で横になる。彼らの神、主が彼らを顧みて、彼らを元どおりにされるからだ。'),
('JPN', '西番雅书', 36, 2, 8, '「わたしはモアブのそしりと、アンモン人の、ののしりを聞いた。彼らはわたしの民をそしり、自分の領土のことで高ぶった。'),
('JPN', '西番雅书', 36, 2, 9, 'わたしは生きている。──イスラエルの神、万軍の主のことば──それゆえ、モアブは必ずソドムのようになり、アンモン人はゴモラのようになり、いらくさの茂る所、塩の穴、とこしえに荒れ果てた地となる。わたしの民の残りの者が、そこをかすめ奪う。わたしの国民の生き残りが、そこを受け継ぐ。」'),
('JPN', '西番雅书', 36, 2, 10, 'これは彼らの高慢のためだ。彼らが万軍の主の民をそしり、これに向かって高ぶったからだ。'),
('JPN', '西番雅书', 36, 2, 11, '主への恐れが彼らに下る。主が地のすべての神々を消し去られるからだ。人々はそれぞれ、自分のところで主を礼拝する。異国のすべての島々も。'),
('JPN', '西番雅书', 36, 2, 12, '「あなたがた、クシュ人も、わたしの剣で刺し殺される。」'),
('JPN', '西番雅书', 36, 2, 13, '主は手を北に向けて伸ばし、アッシリアを滅ぼし、ニネベを荒れ果てた地とし、荒野のようにし、砂漠とされる。'),
('JPN', '西番雅书', 36, 2, 14, 'その中に、獣の群れが、あらゆる地の獣が伏す。ふくろうと針ねずみは、その柱頭をねぐらとし、その鳴き声は窓に響き渡り、荒廃は敷居に及ぶ。まことに、その杉材が剝がされる。'),
('JPN', '西番雅书', 36, 2, 15, 'これが、安心して過ごし、「私だけは特別だ」と心の中で言っていた、あのおごった都だ。ああ、その都は荒れ果て、動物の伏す所となる。そこを通り過ぎる者はみな、嘲って手を振る。'),
('JPN', '西番雅书', 36, 3, 1, 'わざわいだ、反逆と汚れに満ちた暴虐の都。'),
('JPN', '西番雅书', 36, 3, 2, '呼びかけを聞こうともせず、戒めを受け入れようともせず、主に拠り頼まず、神に近づこうともしない。'),
('JPN', '西番雅书', 36, 3, 3, 'その都の高官たちは都の中で吼えたける雄獅子。その都をさばく者たちは夕暮れの狼。朝まで骨をかじってはいない。'),
('JPN', '西番雅书', 36, 3, 4, '預言者たちは、ふしだらで裏切る者。祭司たちは聖なるものを冒して、みおしえを冒瀆する。'),
('JPN', '西番雅书', 36, 3, 5, '主は、そのただ中にあって正しく、決して不正を行われない。ご自分の公正を、朝ごとにくまなく照らす光とされる。しかし、不正を働く者は恥を知らない。'),
('JPN', '西番雅书', 36, 3, 6, '「わたしは諸国の民を断ち切った。その四隅の塔は荒れ果てた。わたしは彼らの通りを廃墟とした。通り過ぎる者はだれもいない。彼らの町々は荒れすたれた。人は一人もおらず、住む者もいない。'),
('JPN', '西番雅书', 36, 3, 7, 'わたしは言った。『あなたはただ、わたしを恐れ、戒めを受け入れよ。そうすれば、わたしがこの都をどれほど罰しても、その住まいは断ち切られない。確かに彼らは、繰り返してあらゆる悪事を行ったが。』'),
('JPN', '西番雅书', 36, 3, 8, 'それゆえ、わたしを待て。──主のことば──わたしが証人として立つ日を待て。わたしは諸国の民を集め、もろもろの王国をかき集め、わたしの激しい憤りと燃える怒りをことごとく彼らに注いで、わたしのさばきを下すからだ。全地は、わたしのねたみの火で焼き尽くされる。'),
('JPN', '西番雅书', 36, 3, 9, 'そのとき、わたしは諸国の民の唇を変えて清くする。彼らはみな主の御名を呼び求め、一つになって主に仕える。'),
('JPN', '西番雅书', 36, 3, 10, 'クシュの川の向こうから、わたしに願い事をする者、わたしに散らされた者たちがわたしへの贈り物を携えて来る。'),
('JPN', '西番雅书', 36, 3, 11, 'その日、あなたはわたしに背いて行ったすべての行いのことで、恥を見ることはない。そのとき、わたしがあなたのただ中から、おごり高ぶる者どもを取り除くからだ。あなたはわたしの聖なる山で、二度と高ぶることはない。'),
('JPN', '西番雅书', 36, 3, 12, 'わたしはあなたのただ中に、へりくだった、貧しい民を残す。彼らは主の名に身を避ける。'),
('JPN', '西番雅书', 36, 3, 13, 'イスラエルの残りの者は不正を行わず、偽りを言わない。その口の中に欺きの舌は見つからない。まことに彼らは草を食べて伏す。彼らを脅かす者はいない。」'),
('JPN', '西番雅书', 36, 3, 14, '娘シオンよ、喜び歌え。イスラエルよ、喜び叫べ。娘エルサレムよ、心の底から喜び躍れ。'),
('JPN', '西番雅书', 36, 3, 15, '主はあなたへのさばきを取り除き、あなたの敵を追い払われた。イスラエルの王、主は、あなたのただ中におられる。あなたはもう、わざわいを恐れることはない。'),
('JPN', '西番雅书', 36, 3, 16, 'その日、エルサレムは次のように言われる。「シオンよ、恐れるな。気力を失うな。'),
('JPN', '西番雅书', 36, 3, 17, 'あなたの神、主は、あなたのただ中にあって救いの勇士だ。主はあなたのことを大いに喜び、その愛によってあなたに安らぎを与え、高らかに歌ってあなたのことを喜ばれる」と。'),
('JPN', '西番雅书', 36, 3, 18, '「例祭から離れて悲しむ者たちをわたしは集める。彼らはあなたから離れていた。そしりがシオンへの重荷であった。'),
('JPN', '西番雅书', 36, 3, 19, '見よ。わたしはそのとき、あなたを苦しめたすべての者を罰する。わたしは足を引きずる者を救い、散らされた者を集め、彼らの恥を全地で栄誉ある名に変える。'),
('JPN', '西番雅书', 36, 3, 20, 'そのとき、わたしはあなたがたを連れ帰る。そのとき、わたしはあなたがたを集める。まことに、あなたがたの目の前でわたしがあなたがたを元どおりにするとき、わたしは、地のあらゆる民の間であなたがたに栄誉ある名を与える。──主は言われる。」'),
('JPN', '哈该书', 37, 1, 1, 'ダレイオス王の第二年、第六の月の一日に、預言者ハガイを通して、シェアルティエルの子、ユダの総督ゼルバベルと、エホツァダクの子、大祭司ヨシュアに、主のことばがあった。'),
('JPN', '哈该书', 37, 1, 2, '万軍の主はこう言われる。「この民は『時はまだ来ていない。主の宮を建てる時は』と言っている。」'),
('JPN', '哈该书', 37, 1, 3, 'すると預言者ハガイを通して、次のような主のことばがあった。'),
('JPN', '哈该书', 37, 1, 4, '「この宮が廃墟となっているのに、あなたがただけが板張りの家に住む時だろうか。」'),
('JPN', '哈该书', 37, 1, 5, '今、万軍の主はこう言われる。「あなたがたの歩みをよく考えよ。'),
('JPN', '哈该书', 37, 1, 6, '多くの種を蒔いても収穫はわずか。食べても満ち足りることがなく、飲んでも酔うことがなく、衣を着ても温まることがない。金を稼ぐ者が稼いでも、穴の開いた袋に入れるだけ。」'),
('JPN', '哈该书', 37, 1, 7, '万軍の主はこう言われる。「あなたがたの歩みをよく考えよ。'),
('JPN', '哈该书', 37, 1, 8, '山に登り、木を運んで来て、宮を建てよ。そうすれば、わたしはそれを喜び、栄光を現す。──主は言われる──'),
('JPN', '哈该书', 37, 1, 9, 'あなたがたは多くを期待したが、見よ、得た物はわずか。あなたがたが家に持ち帰ったとき、わたしはそれを吹き飛ばした。それはなぜか。──万軍の主のことば──それは、廃墟となったわたしの宮のためだ。あなたがたがそれぞれ、自分の家のために走り回っていたからだ。'),
('JPN', '哈该书', 37, 1, 10, 'それゆえ、あなたがたゆえに、天は露を滴らすのをやめ、地はその産物を出すのをやめた。'),
('JPN', '哈该书', 37, 1, 11, 'わたしはまた、日照りを呼び寄せた。地にも山々にも、穀物にも新しいぶどう酒にも油にも、地が産み出す物にも、また人にも家畜にも、手によるすべての労苦の実にも。」'),
('JPN', '哈该书', 37, 1, 12, 'シェアルティエルの子ゼルバベルと、エホツァダクの子、大祭司ヨシュアと、民の残りの者すべては、彼らの神、主が預言者ハガイを遣わされたとき、彼らの神、主の御声と、ハガイのことばに聞き従った。民は主の前で恐れた。'),
('JPN', '哈该书', 37, 1, 13, '主の使者ハガイは主の使命を受けて、民にこう言った。「わたしは、あなたがたとともにいる──主のことば。」'),
('JPN', '哈该书', 37, 1, 14, '主が、シェアルティエルの子、ユダの総督ゼルバベルの霊と、エホツァダクの子、大祭司ヨシュアの霊と、民の残りの者すべての霊を奮い立たせたので、彼らは自分たちの神、万軍の主の宮に行き、仕事に取りかかった。'),
('JPN', '哈该书', 37, 1, 15, 'それは第六の月の二十四日のことであった。ダレイオス王の第二年、'),
('JPN', '哈该书', 37, 2, 1, '第七の月の二十一日に、預言者ハガイを通して、次のような主のことばがあった。'),
('JPN', '哈该书', 37, 2, 2, '「シェアルティエルの子、ユダの総督ゼルバベルと、エホツァダクの子、大祭司ヨシュアと、民の残りの者に次のように言え。'),
('JPN', '哈该书', 37, 2, 3, '『あなたがたの中で、かつての栄光に輝くこの宮を見たことがある、生き残りの者はだれか。あなたがたは今、これをどう見ているのか。あなたがたの目には、まるで無いに等しいのではないか。'),
('JPN', '哈该书', 37, 2, 4, 'しかし今、ゼルバベルよ、強くあれ。──主のことば──エホツァダクの子、大祭司ヨシュアよ、強くあれ。この国のすべての民よ、強くあれ。──主のことば──仕事に取りかかれ。わたしがあなたがたとともにいるからだ。──万軍の主のことば──'),
('JPN', '哈该书', 37, 2, 5, 'あなたがたがエジプトから出て来たとき、わたしがあなたがたと結んだ約束により、わたしの霊はあなたがたの間にとどまっている。恐れるな。』'),
('JPN', '哈该书', 37, 2, 6, 'まことに、万軍の主はこう言われる。『間もなく、もう一度、わたしは天と地、海と陸を揺り動かす。'),
('JPN', '哈该书', 37, 2, 7, 'わたしはすべての国々を揺り動かす。すべての国々の宝物がもたらされ、わたしはこの宮を栄光で満たす。──万軍の主は言われる──'),
('JPN', '哈该书', 37, 2, 8, '銀はわたしのもの。金もわたしのもの。──万軍の主のことば──'),
('JPN', '哈该书', 37, 2, 9, 'この宮のこれから後の栄光は、先のものにまさる。──万軍の主は言われる──この場所にわたしは平和を与える。──万軍の主のことば。』」'),
('JPN', '哈该书', 37, 2, 10, 'ダレイオスの第二年の第九の月の二十四日、預言者ハガイに次のような主のことばがあった。'),
('JPN', '哈该书', 37, 2, 11, '「万軍の主はこう言われる。律法について、祭司たちに尋ねよ。'),
('JPN', '哈该书', 37, 2, 12, '人が聖なる肉を自分の衣の裾に入れて運び、その裾がパンや煮物、ぶどう酒や油、またはどんな食物にでも触れた場合、それは聖なるものとなるか。」祭司たちは「否」と答えた。'),
('JPN', '哈该书', 37, 2, 13, 'そこでハガイは言った。「もし死体によって汚れた人が、これらのどれかに触れたら、それは汚れるか。」祭司たちは「汚れる」と答えた。'),
('JPN', '哈该书', 37, 2, 14, 'それに応じてハガイは言った。「この民も、この国も、わたしにとってはそれと同じ。──主のことば──彼らの手が作ったすべての物もそれと同じ。そこで彼らが献げる物も汚れている。'),
('JPN', '哈该书', 37, 2, 15, 'さあ今、あなたがたは、今日から後のことをよく考えよ。主の神殿で石が積み重ねられる前、'),
('JPN', '哈该书', 37, 2, 16, 'あなたがたはどうであったか。二十の麦束が積んであるところに行っても、あるのは十束。ぶどう酒五十杯を汲もうと石がめに行っても、あるのは二十杯。'),
('JPN', '哈该书', 37, 2, 17, 'わたしはあなたがたを、あなたがたの手が作ったすべての物を、立ち枯れと黒穂病と雹で打った。しかし、だれ一人わたしに帰って来なかった。──主のことば──'),
('JPN', '哈该书', 37, 2, 18, 'さあ、あなたがたは今日から後のことをよく考えよ。第九の月の二十四日、主の神殿の基が据えられた日から後のことをよく考えよ。'),
('JPN', '哈该书', 37, 2, 19, '種はまだ穀物倉にあるのか。ぶどうの木、いちじくの木、ざくろの木、オリーブの木は、まだ実を結ばないのか。今日から後、わたしは祝福する。」'),
('JPN', '哈该书', 37, 2, 20, 'その月の二十四日、ハガイに再び次のような主のことばがあった。'),
('JPN', '哈该书', 37, 2, 21, '「ユダの総督ゼルバベルに次のように言え。『わたしは天と地を揺り動かし、'),
('JPN', '哈该书', 37, 2, 22, 'もろもろの王国の王座を倒し、異邦の民の王国の力を滅ぼし尽くし、戦車とその乗り手をくつがえす。馬とその乗り手は味方の剣によって倒れる。'),
('JPN', '哈该书', 37, 2, 23, 'その日、──万軍の主のことば──シェアルティエルの子、わたしのしもべゼルバベルよ、──主のことば──わたしはあなたを選んで印章とする。わたしがあなたを選んだからだ。──万軍の主のことば。』」'),
('JPN', '撒迦利亚书', 38, 1, 1, 'ダレイオスの第二年、第八の月に、イドの子ベレクヤの子、預言者ゼカリヤに、次のような主のことばがあった。'),
('JPN', '撒迦利亚书', 38, 1, 2, '「主はあなたがたの先祖に激しく怒った。'),
('JPN', '撒迦利亚书', 38, 1, 3, 'あなたは人々に言え。『万軍の主はこう言われる。わたしに帰れ。──万軍の主のことば──そうすれば、わたしもあなたがたに帰る。──万軍の主は言われる。』'),
('JPN', '撒迦利亚书', 38, 1, 4, 'あなたがたの先祖のようであってはならない。先の預言者たちは彼らに叫んで言った。『万軍の主はこう言われる。あなたがたは悪の道と悪しきわざから立ち返れ。』しかし、彼らはわたしに聞かず、わたしに耳を傾けもしなかった。──主のことば──'),
('JPN', '撒迦利亚书', 38, 1, 5, 'あなたがたの先祖たちは、今どこにいるのか。預言者たちは永遠に生きるだろうか。'),
('JPN', '撒迦利亚书', 38, 1, 6, 'しかし、わたしのしもべである預言者たちにわたしが命じた、わたしのことばと掟は、あなたがたの先祖に追い迫ったではないか。それで彼らは立ち返って言ったのだ。『万軍の主は、私たちの生き方と行いに応じて、私たちにしようと考えたことをそのとおりになさった』と。」'),
('JPN', '撒迦利亚书', 38, 1, 7, 'ダレイオスの第二年、シェバテの月である第十一の月の二十四日に、イドの子ベレクヤの子、預言者ゼカリヤに、次のような主のことばがあった。'),
('JPN', '撒迦利亚书', 38, 1, 8, '夜、私が見ると、なんと、一人の人が赤い馬に乗っていた。その人は、谷底にあるミルトスの木の間に立っていた。そのうしろには、赤毛や栗毛や白い馬がいた。'),
('JPN', '撒迦利亚书', 38, 1, 9, '私は「主よ、これらの馬は何ですか」と尋ねた。すると、私と話していた御使いが「これらが何なのか、あなたに示そう」と言った。'),
('JPN', '撒迦利亚书', 38, 1, 10, 'すると、ミルトスの木の間に立っていた人が答えた。「これらは、地を行き巡るために主が遣わされた者たちだ。」'),
('JPN', '撒迦利亚书', 38, 1, 11, 'すると彼らは、ミルトスの木の間に立っている主の使いに答えた。「私たちは地を行き巡りましたが、まさに全地は安らかで穏やかでした。」'),
('JPN', '撒迦利亚书', 38, 1, 12, 'それに答えて主の使いは言った。「万軍の主よ。いつまで、あなたはエルサレムとユダの町々に、あわれみを施されないのですか。あなたが憤られて七十年になります。」'),
('JPN', '撒迦利亚书', 38, 1, 13, 'すると主は、私と話していた御使いに、恵みのことば、慰めのことばで答えられた。'),
('JPN', '撒迦利亚书', 38, 1, 14, '私と話していた御使いは私に言った。「叫んで言え。『万軍の主はこう言われる。わたしは、エルサレムとシオンを、ねたむほど激しく愛した。'),
('JPN', '撒迦利亚书', 38, 1, 15, 'しかし、わたしは大いに怒る。安逸を貪っている国々に対して。わたしが少ししか怒らないでいると、彼らは欲するままに悪事を行った。』'),
('JPN', '撒迦利亚书', 38, 1, 16, 'それゆえ、主はこう言われる。『わたしは、あわれみをもってエルサレムに帰る。そこにわたしの宮が建て直される。──万軍の主のことば──測り縄がエルサレムの上に張られる。』'),
('JPN', '撒迦利亚书', 38, 1, 17, 'もう一度叫んで言え。『万軍の主はこう言われる。わたしの町々には、再び良いものが満ちあふれ、主は再びシオンを慰め、再びエルサレムを選ぶ。』」'),
('JPN', '撒迦利亚书', 38, 1, 18, '私が目を上げて見ると、なんと、四つの角があった。'),
('JPN', '撒迦利亚书', 38, 1, 19, '私と話していた御使いに「これらは何ですか」と尋ねると、彼は言った。「これらは、ユダとイスラエルとエルサレムを散らした角だ。」'),
('JPN', '撒迦利亚书', 38, 1, 20, 'そのとき、主は四人の職人を私に見せてくださった。'),
('JPN', '撒迦利亚书', 38, 1, 21, '私が「この人たちは、何をしに来たのですか」と尋ねると、主は次のように言われた。「これらはユダを散らして、だれにも頭をもたげさせなかったあの角だ。この人たちは、これらの角を震え上がらせるために、やって来たのだ。ユダの地を散らそうと角をもたげる国々の角を打ち滅ぼすためだ。」'),
('JPN', '撒迦利亚书', 38, 2, 1, '私が目を上げて見ると、なんと、一人の人がいた。その手には、一本の測り綱があった。'),
('JPN', '撒迦利亚书', 38, 2, 2, '私が「あなたはどこへ行くのですか」と尋ねると、彼は私に「エルサレムを測りに。その幅と長さがどれほどあるかを見るために」と答えた。'),
('JPN', '撒迦利亚书', 38, 2, 3, 'すると見よ、私と話していた御使いが出て行った。また、もう一人の御使いが、その御使いに会うために出て行き、'),
('JPN', '撒迦利亚书', 38, 2, 4, '彼に言った。「走って行って、あの若い者にこう告げよ。『エルサレムは、その中に人と家畜があふれ、城壁のない町のようになる。'),
('JPN', '撒迦利亚书', 38, 2, 5, 'わたしが──主のことば──それを取り巻く火の城壁となる。わたしがそのただ中で栄光となる。'),
('JPN', '撒迦利亚书', 38, 2, 6, 'さあ、すぐに、北の国から逃げよ。──主のことば──天の四方の風のように、わたしがあなたがたを散らしたのだ。──主のことば──'),
('JPN', '撒迦利亚书', 38, 2, 7, 'さあ、シオンに逃れよ。娘バビロンとともに住む者よ。』'),
('JPN', '撒迦利亚书', 38, 2, 8, 'あなたがたを略奪した国々に主の栄光が私を遣わした後、万軍の主がこう言われたからだ。『あなたがたに触れる者は、わたしの瞳に触れる者。'),
('JPN', '撒迦利亚书', 38, 2, 9, '見よ、わたしは彼らに手を振り上げる。彼らは自分に仕えた者たちに略奪される』と。このときあなたがたは、万軍の主が私を遣わされたことを知る。'),
('JPN', '撒迦利亚书', 38, 2, 10, '『娘シオンよ、喜び歌え。楽しめ。見よ。わたしは来て、あなたのただ中に住む。──主のことば──'),
('JPN', '撒迦利亚书', 38, 2, 11, 'その日、多くの国々が主に連なり、わたしの民となり、わたしはあなたのただ中に住む。』このときあなたは、万軍の主が私をあなたに遣わされたことを知る。'),
('JPN', '撒迦利亚书', 38, 2, 12, '主は聖なる土地で、ユダをご自分の受ける分とし、エルサレムを再び選ばれる。'),
('JPN', '撒迦利亚书', 38, 2, 13, 'すべての肉なる者よ、主の前で静まれ。主が聖なる御住まいから立ち上がられるからだ。」'),
('JPN', '撒迦利亚书', 38, 3, 1, '主は、主の使いの前に立っている大祭司ヨシュアを私にお見せになった。サタンが彼を訴えようとしてその右手に立っていた。'),
('JPN', '撒迦利亚书', 38, 3, 2, '主はサタンに言われた。「サタンよ、主がおまえをとがめる。エルサレムを選んだ主が、おまえをとがめる。この者は、火から取り出した燃えさしではないか。」'),
('JPN', '撒迦利亚书', 38, 3, 3, 'ヨシュアは汚れた服を着て、主の使いの前に立っていた。'),
('JPN', '撒迦利亚书', 38, 3, 4, '御使いは、自分の前に立っている者たちにこう答えた。「彼の汚れた服を脱がせよ。」そしてヨシュアに言った。「見よ、わたしはあなたの咎を除いた。あなたに礼服を着せよう。」'),
('JPN', '撒迦利亚书', 38, 3, 5, '私は言った。「彼の頭に、きよいターバンをかぶらせなければなりません。」すると彼らは、彼の頭にきよいターバンをかぶらせ、服を着せた。そのとき、主の使いはそばに立っていた。'),
('JPN', '撒迦利亚书', 38, 3, 6, '主の使いはヨシュアを諭して言った。'),
('JPN', '撒迦利亚书', 38, 3, 7, '「万軍の主はこう言われる。『もし、あなたがわたしの道に歩み、わたしの戒めを守るなら、あなたもまた、わたしの家を治め、わたしの庭を守るようになる。この立っている者たちの間に出入りすることをわたしはあなたに許す。'),
('JPN', '撒迦利亚书', 38, 3, 8, '聞け、大祭司ヨシュアよ。あなたも、あなたの前に座している同僚たちも。彼らはしるしとなる人たちだ。見よ、わたしはわたしのしもべ、若枝を来させる。'),
('JPN', '撒迦利亚书', 38, 3, 9, '見よ、わたしがヨシュアの前に置いた石を。一つの石の上には、七つの目がある。見よ、わたしはそれに文字を彫る。──万軍の主のことば──一日のうちに、わたしはその地の咎を取り除く。'),
('JPN', '撒迦利亚书', 38, 3, 10, 'その日には、──万軍の主のことば──あなたがたは互いに自分の友を、ぶどうの木といちじくの木の下に招き合う。』」'),
('JPN', '撒迦利亚书', 38, 4, 1, '私と話していた御使いが戻って来て、私を呼び起こした。私は眠りから覚まされた人のようであった。'),
('JPN', '撒迦利亚书', 38, 4, 2, '彼は私に言った。「あなたは何を見ているのか。」私は答えた。「私が見ると、全体が金でできている一つの燭台があります。その上部には鉢があり、その鉢の上には七つのともしび皿があります。この上部にあるともしび皿には、それぞれ七本の管が付いています。'),
('JPN', '撒迦利亚书', 38, 4, 3, 'また、そのそばには二本のオリーブの木があり、一本はその鉢の右に、もう一本は左にあります。」'),
('JPN', '撒迦利亚书', 38, 4, 4, '私は、私と話していた御使いに言った。「主よ、これらは何ですか。」'),
('JPN', '撒迦利亚书', 38, 4, 5, '私と話していた御使いが答えて言った。「あなたは、これらが何であるかを知らないのか。」私は言った。「主よ、知りません。」'),
('JPN', '撒迦利亚书', 38, 4, 6, '彼は私にこう答えた。「これは、ゼルバベルへの主のことばだ。『権力によらず、能力によらず、わたしの霊によって』と万軍の主は言われる。'),
('JPN', '撒迦利亚书', 38, 4, 7, '大いなる山よ、おまえは何者か。おまえはゼルバベルの前で平らにされる。彼がかしら石を運び出せば、『恵みあれ。これに恵みあれ』と叫び声があがる。」'),
('JPN', '撒迦利亚书', 38, 4, 8, 'また、私に次のような主のことばがあった。'),
('JPN', '撒迦利亚书', 38, 4, 9, '「『ゼルバベルの手がこの宮の礎を据えた。彼の手がそれを完成させる。』そのときあなたは、万軍の主が私をあなたがたに遣わされたことを知る。'),
('JPN', '撒迦利亚书', 38, 4, 10, 'だれが、その日を小さなこととして蔑むのか。人々はゼルバベルの手にある重り縄を見て喜ぶ。これら七つは、全地を行き巡る主の目である。」'),
('JPN', '撒迦利亚书', 38, 4, 11, '私は彼に尋ねた。「燭台の左右にある、この二本のオリーブの木は何ですか。」'),
('JPN', '撒迦利亚书', 38, 4, 12, 'そして再び尋ねた。「二本の金の管によって金の油を注ぎ出す、このオリーブの二本の枝は何ですか。」'),
('JPN', '撒迦利亚书', 38, 4, 13, 'すると彼は私にこう言った。「あなたは、これらが何であるかを知らないのか。」私は言った。「主よ、知りません。」'),
('JPN', '撒迦利亚书', 38, 4, 14, '彼は言った。「これらは、全地の主のそばに立つ、二人の油注がれた者だ。」'),
('JPN', '撒迦利亚书', 38, 5, 1, '私が再び目を上げて見ると、なんと、一つの巻物が飛んでいた。'),
('JPN', '撒迦利亚书', 38, 5, 2, '御使いは私に言った。「あなたは何を見ているのか。」私は答えた。「飛んでいる巻物を見ています。その長さは二十キュビト、幅は十キュビトです。」'),
('JPN', '撒迦利亚书', 38, 5, 3, 'すると彼は私に言った。「これは全地の面に出て行くのろいだ。盗む者はみな、一方の面に照らし合わせて取り除かれ、また、偽って誓う者はみな、もう一方の面に照らし合わせて取り除かれる。」'),
('JPN', '撒迦利亚书', 38, 5, 4, '「わたしがそれを送り出す。──万軍の主のことば──それは盗人の家に、また、わたしの名によって偽りの誓いを立てる者の家に入り、その家の真ん中にとどまって、その家を梁と石とともに絶ち滅ぼす。」'),
('JPN', '撒迦利亚书', 38, 5, 5, '私と話していた御使いが出て来て、私に言った。「目を上げて、この出て行く物が何かを見よ。」'),
('JPN', '撒迦利亚书', 38, 5, 6, '私が「これは何ですか」と尋ねると、彼は言った。「これは、出て行くエパ升だ。」さらに言った。「これは、全地にある彼らの目だ。」'),
('JPN', '撒迦利亚书', 38, 5, 7, '見よ。鉛のふたが持ち上げられると、エパ升の中に一人の女が座っていた。'),
('JPN', '撒迦利亚书', 38, 5, 8, '彼は、「これは邪悪そのものだ」と言って、その女をエパ升の中に閉じ込め、エパ升の口の上に鉛の重しを置いた。'),
('JPN', '撒迦利亚书', 38, 5, 9, 'それから、私が目を上げて見ると、なんと、二人の女が出て来た。その翼は風をはらんでいた。彼女たちには、こうのとりの翼のような翼があり、あのエパ升を地と天の間に持ち上げた。'),
('JPN', '撒迦利亚书', 38, 5, 10, '私は、私と話していた御使いに尋ねた。「この人たちは、エパ升をどこへ持って行くのですか。」'),
('JPN', '撒迦利亚书', 38, 5, 11, '彼は私に言った。「シンアルの地に、あの女のために神殿を建てるためだ。それが整うと、そこの台の上にその升を置くのだ。」'),
('JPN', '撒迦利亚书', 38, 6, 1, '私が再び目を上げて見ると、なんと、四台の戦車が二つの山の間から出て来た。山は青銅の山であった。'),
('JPN', '撒迦利亚书', 38, 6, 2, '第一の戦車には赤い馬が、第二の戦車には黒い馬が、'),
('JPN', '撒迦利亚书', 38, 6, 3, '第三の戦車には白い馬が、第四の戦車には斑毛の強い馬が、数頭ずつつながれていた。'),
('JPN', '撒迦利亚书', 38, 6, 4, '私は、私と話していた御使いに尋ねた。「主よ、これらは何ですか。」'),
('JPN', '撒迦利亚书', 38, 6, 5, '御使いは答えた。「これらは天の四方の風だ。全地の主の前に立った後に、出て行くことになる。'),
('JPN', '撒迦利亚书', 38, 6, 6, 'そのうちの黒い馬は北の地へ出て行き、白い馬は西へ出て行き、斑毛の馬は南の地へ出て行く。」'),
('JPN', '撒迦利亚书', 38, 6, 7, '強い馬たちが出て来た。それらは地を駆け巡ろうとしていたので、彼が「行って、地を駆け巡れ」と言うと、それらは地を駆け巡った。'),
('JPN', '撒迦利亚书', 38, 6, 8, 'そのとき、彼は私に叫んで、次のように告げた。「見よ、北の地へ出て行った馬を。これらは北の地で、わたしの霊を鎮めた。」'),
('JPN', '撒迦利亚书', 38, 6, 9, 'また、私に次のような主のことばがあった。'),
('JPN', '撒迦利亚书', 38, 6, 10, '「捕囚の民であったヘルダイ、トビヤ、エダヤからささげ物を受け取れ。その日あなたは行って、バビロンから帰って来た、ゼパニヤの子ヨシヤの家に入れ。'),
('JPN', '撒迦利亚书', 38, 6, 11, '銀と金を取って冠を作って、エホツァダクの子、大祭司ヨシュアの頭にかぶらせ、'),
('JPN', '撒迦利亚书', 38, 6, 12, '彼にこう言え。『万軍の主はこう言われる。見よ、一人の人を。その名は若枝。彼は自分のいるところから芽を出し、主の神殿を建てる。'),
('JPN', '撒迦利亚书', 38, 6, 13, '彼が主の神殿を建て、彼が威光を帯び、王座に就いて支配する。その王座の傍らに一人の祭司がいて、二人の間には、平和の計画がある。』'),
('JPN', '撒迦利亚书', 38, 6, 14, 'その冠は、ヘルダイ、トビヤ、エダヤ、ゼパニヤの子ヨシヤの記念として、主の神殿の中に残る。'),
('JPN', '撒迦利亚书', 38, 6, 15, 'また、遠く離れていた者たちも来て、主の神殿を建てる。このときあなたがたは、万軍の主が私をあなたがたに遣わしたことを知る。もしあなたがたが自分たちの神、主の声に確かに聞き従うなら、そのようになる。」'),
('JPN', '撒迦利亚书', 38, 7, 1, 'ダレイオス王の第四年、第九の月、すなわち、キスレウの月の四日に、ゼカリヤに主のことばがあった。'),
('JPN', '撒迦利亚书', 38, 7, 2, 'そのとき、ベテルは主の御顔を求めるために、サル・エツェルとレゲム・メレクおよびその従者たちを遣わして、'),
('JPN', '撒迦利亚书', 38, 7, 3, '万軍の主の宮に仕える祭司たちと、預言者たちに尋ねた。「私が長年やってきたように、第五の月にも、断食をして泣かなければならないでしょうか。」'),
('JPN', '撒迦利亚书', 38, 7, 4, 'すると、私に次のような万軍の主のことばがあった。'),
('JPN', '撒迦利亚书', 38, 7, 5, '「この国のすべての民と祭司たちにこう言え。この七十年の間、あなたがたが、第五の月と第七の月に断食して嘆いたとき、本当にこのわたしのために断食したのか。'),
('JPN', '撒迦利亚书', 38, 7, 6, 'あなたがたが食べたり飲んだりするとき、食べるのも飲むのも、自分たちのためではなかったか。'),
('JPN', '撒迦利亚书', 38, 7, 7, 'エルサレムとその周りの町々に人が住み、平和であったとき、またネゲブやシェフェラに人が住んでいたとき、主が先の預言者たちを通して告げたことばは、これらのことではなかったのか。」'),
('JPN', '撒迦利亚书', 38, 7, 8, 'それから、ゼカリヤに次のような主のことばがあった。'),
('JPN', '撒迦利亚书', 38, 7, 9, '万軍の主はこう言われる。「真実のさばきを行い、誠意とあわれみを互いに示せ。'),
('JPN', '撒迦利亚书', 38, 7, 10, 'やもめ、みなしご、寄留者、貧しい者を虐げるな。互いに対して、心の中で悪を企むな。」'),
('JPN', '撒迦利亚书', 38, 7, 11, 'ところが、彼らは拒んでこれを聞こうともせず、肩を怒らせ、その耳を鈍くして聞き入れなかった。'),
('JPN', '撒迦利亚书', 38, 7, 12, '彼らは心を金剛石のようにし、万軍の主がその御霊によって先の預言者たちを通して送られた、みおしえとみことばを聞き入れなかった。そのため、万軍の主から大きな御怒りが下った。'),
('JPN', '撒迦利亚书', 38, 7, 13, '「彼らは呼ばれても聞かなかった。そのように、彼らが呼んでも、わたしは聞かない──万軍の主は言われる──。'),
('JPN', '撒迦利亚书', 38, 7, 14, 'わたしは、彼らを知らないすべての国々に彼らを吹き散らした。この地は、彼らが去った後荒れすたれ、行き来する者もいなくなった。こうして彼らはこの慕わしい国を荒れすたらせた。」'),
('JPN', '撒迦利亚书', 38, 8, 1, '次のような万軍の主のことばがあった。'),
('JPN', '撒迦利亚书', 38, 8, 2, '万軍の主はこう言われる。「わたしは、シオンをねたむほど激しく愛し、激しい憤りをもってこれをねたむ。'),
('JPN', '撒迦利亚书', 38, 8, 3, '──主はこう言われる──わたしはシオンに帰り、エルサレムのただ中に住む。エルサレムは、真実の都と呼ばれ、万軍の主の山は、聖なる山と呼ばれる。'),
('JPN', '撒迦利亚书', 38, 8, 4, '──万軍の主はこう言われる──再び、エルサレムの広場に、老いた男、老いた女が座り、みな長寿で手に杖を持つ。'),
('JPN', '撒迦利亚书', 38, 8, 5, '都の広場は、男の子と女の子でいっぱいになる。子どもたちはその広場で遊ぶ。'),
('JPN', '撒迦利亚书', 38, 8, 6, '──万軍の主はこう言われる──もし、これがその日に、この民の残りの者の目には不思議に見えても、わたしの目には、不思議に見えるだろうか。──万軍の主のことば。」'),
('JPN', '撒迦利亚书', 38, 8, 7, '万軍の主はこう言われる。「見よ。わたしは、わたしの民を日の出る地と日の沈む地から救い、'),
('JPN', '撒迦利亚书', 38, 8, 8, '彼らを連れ帰り、エルサレムのただ中に住まわせる。このとき、彼らはわたしの民となり、わたしは真実と義をもって彼らの神となる。」'),
('JPN', '撒迦利亚书', 38, 8, 9, '万軍の主はこう言われる。「勇気を出せ。万軍の主の家である神殿を建てるために基が据えられた日以来、あなたがたはこれらのことばを、預言者たちの口から聞いてきたではないか。'),
('JPN', '撒迦利亚书', 38, 8, 10, 'その日以前は、人の働きに報酬がなく、家畜の働きにも報酬がなかった。出て行く者にも、帰って来る者にも、敵がいるために平安がなかった。わたしがすべての人を互いに争わせたからだ。'),
('JPN', '撒迦利亚书', 38, 8, 11, 'しかし今、わたしはこの民の残りの者に対して、かつての日々のようではない。──万軍の主のことば──'),
('JPN', '撒迦利亚书', 38, 8, 12, 'それは、平安の種が蒔かれ、ぶどうの木が実を結び、地が産物を出し、天が露を滴らすからだ。わたしはこの民の残りの者に、これらすべてを受け継がせる。'),
('JPN', '撒迦利亚书', 38, 8, 13, 'ユダの家よ、イスラエルの家よ。あなたがたは国々の間でのろいとなったが、同様に、わたしはあなたがたを救う。あなたがたは祝福となる。恐れるな。勇気を出せ。」'),
('JPN', '撒迦利亚书', 38, 8, 14, 'まことに、万軍の主はこう言われる。「あなたがたの先祖がわたしを怒らせたとき、わたしはあなたがたにわざわいを下そうと決意し──万軍の主は言われる──わたしは思い直さなかった。'),
('JPN', '撒迦利亚书', 38, 8, 15, 'そのように、今や再び、わたしはエルサレムとユダの家に幸いを下そうと決意した。恐れるな。'),
('JPN', '撒迦利亚书', 38, 8, 16, 'これがあなたがたのなすべきことだ。あなたがたはそれぞれ隣人に対して真実を語り、真実と平和をもたらす公正さをもって、あなたがたの門の中でさばきを行え。'),
('JPN', '撒迦利亚书', 38, 8, 17, '互いに心の中で悪を謀るな。偽りの誓いを愛するな。これらはみな、わたしが憎むものだからだ。──主のことば。」'),
('JPN', '撒迦利亚书', 38, 8, 18, 'さらに、私に次のような万軍の主のことばがあった。'),
('JPN', '撒迦利亚书', 38, 8, 19, '万軍の主はこう言われる。「第四の月の断食、第五の月の断食、第七の月の断食、第十の月の断食は、ユダの家にとって、楽しみとなり、喜びとなり、うれしい例祭となる。だから、真実と平和を愛しなさい。」'),
('JPN', '撒迦利亚书', 38, 8, 20, '万軍の主はこう言われる。「再び諸国の民がやって来る。多くの町々の住民が。'),
('JPN', '撒迦利亚书', 38, 8, 21, '一つの町の住民はもう一つの町へ行き、『さあ行って、主の御顔を求め、万軍の主を尋ね求めよう。私も行こう』と言う。'),
('JPN', '撒迦利亚书', 38, 8, 22, '多くの国の民、強い国々が、エルサレムで万軍の主を尋ね求め、主の御顔を求めるために来る。」'),
('JPN', '撒迦利亚书', 38, 8, 23, '万軍の主はこう言われる。「その日には、外国語を話すあらゆる民のうちの十人が、一人のユダヤ人の裾を固くつかんで言う。『私たちもあなたがたと一緒に行きたい。神があなたがたとともにおられる、と聞いたから。』」'),
('JPN', '撒迦利亚书', 38, 9, 1, '宣告。主のことばはハデラクの地にあり、ダマスコは、それがとどまる場所。主に向けられるのは、人々の、そしてイスラエルの全部族の目。'),
('JPN', '撒迦利亚书', 38, 9, 2, 'これに境を接するハマテや、非常に知恵のあるツロやシドンの目も。'),
('JPN', '撒迦利亚书', 38, 9, 3, 'ツロは自分のために砦を築き、銀をちりのように、黄金を道端の泥のように積み上げた。'),
('JPN', '撒迦利亚书', 38, 9, 4, '見よ。主はツロを占領し、その富を海に打ち捨てる。ツロは火で焼き尽くされる。'),
('JPN', '撒迦利亚书', 38, 9, 5, 'アシュケロンは見て恐れ、ガザも大いにもだえる。エクロンもだ。自分たちが頼みにしていたものが辱められたからだ。ガザから王が消え失せ、アシュケロンには人が住まなくなる。'),
('JPN', '撒迦利亚书', 38, 9, 6, 'アシュドデには混血の民が住むようになる。わたしはペリシテ人の誇りを断ち切り、'),
('JPN', '撒迦利亚书', 38, 9, 7, 'その口から流血の咎を、その歯の間から忌まわしいものを取り除く。彼も、私たちの神のために残され、ユダの中の一首長のようになる。エクロンもエブス人のようになる。'),
('JPN', '撒迦利亚书', 38, 9, 8, 'わたしは、わたしの家のために、行き来する者の見張りとして衛所に立つ。もはや、虐げる者はそこを通らない。今わたしがこの目で見ているからだ。'),
('JPN', '撒迦利亚书', 38, 9, 9, '娘シオンよ、大いに喜べ。娘エルサレムよ、喜び叫べ。見よ、あなたの王があなたのところに来る。義なる者で、勝利を得、柔和な者で、ろばに乗って。雌ろばの子である、ろばに乗って。'),
('JPN', '撒迦利亚书', 38, 9, 10, 'わたしは戦車をエフライムから、軍馬をエルサレムから絶えさせる。戦いの弓も絶たれる。彼は諸国の民に平和を告げ、その支配は海から海へ、大河から地の果てに至る。'),
('JPN', '撒迦利亚书', 38, 9, 11, 'あなたについても、あなたとの契約の血のゆえに、わたしはあなたの捕らわれ人を、水のない穴から解き放つ。'),
('JPN', '撒迦利亚书', 38, 9, 12, '望みを持つ捕らわれ人よ、砦に帰れ。わたしは今日もまた告げ知らせる。二倍のものをあなたに返す、と。'),
('JPN', '撒迦利亚书', 38, 9, 13, 'わたしは、ユダをわたしの弓として引き絞り、これにエフライムをつがえたのだ。ヤワンよ、おまえの子らに向かって。シオンよ、わたしはあなたの子らを奮い立たせ、あなたを勇士の剣のようにする。'),
('JPN', '撒迦利亚书', 38, 9, 14, '主は彼らの上に現れ、その矢は稲妻のように放たれる。神である主は角笛を吹き鳴らし、南の暴風の中を進まれる。'),
('JPN', '撒迦利亚书', 38, 9, 15, '万軍の主が彼らの盾となる。彼らは石投げの石で滅ぼし、踏みつける。彼らは血をぶどう酒のように飲み、沸き返る。鉢のように、祭壇の四隅のように、満たされる。'),
('JPN', '撒迦利亚书', 38, 9, 16, 'その日、彼らの神、主は、彼らをご自分の民の群れとして救われる。まことに、王冠の宝石がその地できらめく。'),
('JPN', '撒迦利亚书', 38, 9, 17, 'なんという主のいつくしみ。なんという主の麗しさ。穀物は若い男たちを、新しいぶどう酒は若い女たちを栄えさせる。'),
('JPN', '撒迦利亚书', 38, 10, 1, '主に雨を求めよ、後の雨の時に。主は稲光を造り、大雨を人々に、野の草をすべての人に下さる。'),
('JPN', '撒迦利亚书', 38, 10, 2, 'テラフィムは不法を語り、占い師は偽りを見る。夢見る者は意味のないことを語り、空しい慰めを与える。それゆえ、人々は羊のようにさまよい、羊飼いがいないので苦しむ。'),
('JPN', '撒迦利亚书', 38, 10, 3, '「わたしの怒りは羊飼いたちに向かって燃える。わたしは雄やぎを罰する。」万軍の主は、ご自分の群れであるユダの家を訪れ、彼らを戦場の威厳ある馬とされる。'),
('JPN', '撒迦利亚书', 38, 10, 4, 'この群れからかしら石が、この群れから杭が、この群れから戦いの弓が、この群れからすべての指揮する者が、ともどもに出て来る。'),
('JPN', '撒迦利亚书', 38, 10, 5, '彼らは勇士のようになり、戦場で道端の泥を蹴散らして戦う。主が彼らとともにおられるからだ。彼らは馬に乗る者どもを辱める。'),
('JPN', '撒迦利亚书', 38, 10, 6, '「わたしはユダの家を力づけ、ヨセフの家を救う。わたしは彼らを連れ戻す。わたしが彼らをあわれむからだ。彼らは、わたしに捨てられなかった者のようになる。わたしが彼らの神、主であり、彼らに答えるからだ。」'),
('JPN', '撒迦利亚书', 38, 10, 7, 'エフライムは勇士のようになり、その心はぶどう酒に酔ったように喜ぶ。彼らの子らは見て喜び、その心は主にあって大いに楽しむ。'),
('JPN', '撒迦利亚书', 38, 10, 8, '「わたしは合図をして彼らを集める。わたしが彼らを贖ったからだ。彼らは以前のように数を増す。'),
('JPN', '撒迦利亚书', 38, 10, 9, 'わたしは彼らを諸国の民の間にまき散らすが、彼らは遠く離れてわたしを思い出し、その子らとともに生き延びて帰って来る。'),
('JPN', '撒迦利亚书', 38, 10, 10, 'わたしは彼らをエジプトの地から連れ帰り、アッシリアから集める。わたしはギルアデの地とレバノンへ彼らを連れて行くが、そこも彼らには足りなくなる。'),
('JPN', '撒迦利亚书', 38, 10, 11, '彼らは苦難の海を渡る。海では波を打ち破り、ナイル川のすべての淵を涸らす。アッシリアの誇りは低くされ、エジプトの杖は離れ去る。'),
('JPN', '撒迦利亚书', 38, 10, 12, 'わたしは主にあって彼らを力づける。彼らは主の名によって歩き続ける。──主のことば。」'),
('JPN', '撒迦利亚书', 38, 11, 1, 'レバノンよ、おまえの門を開け。火がおまえの杉の木を焼き尽くす。'),
('JPN', '撒迦利亚书', 38, 11, 2, 'もみの木よ、泣き叫べ。杉の木は倒れ、見事な木々が荒らされたから。バシャンの樫の木よ、泣き叫べ。深い森が倒れたから。'),
('JPN', '撒迦利亚书', 38, 11, 3, '牧者たちの嘆きの声がする。彼らの見事な木々が荒らされたから。若い獅子の吼える声がする。ヨルダンの茂みが荒らされたから。'),
('JPN', '撒迦利亚书', 38, 11, 4, '私の神、主はこう言われた。「屠られる羊の群れを飼え。'),
('JPN', '撒迦利亚书', 38, 11, 5, 'これを買った者は、これを屠っても責めを覚えることはなく、これを売る者も、『主がほめたたえられるように。私は豊かになった』と言う。その牧者たちは羊をあわれまない。'),
('JPN', '撒迦利亚书', 38, 11, 6, 'それは、わたしがもはや、この地の住民にあわれみをかけないからだ──主のことば──。見よ、わたしは、人をそれぞれ隣人の手に、また王の手に渡す。彼らはこの地を打ち砕くが、わたしは彼らの手からこれを救い出さない。」'),
('JPN', '撒迦利亚书', 38, 11, 7, '私は羊の商人たちのために、屠られる羊の群れを飼った。私は二本の杖を取り、一本を「慈愛」と名づけ、もう一本を「結合」と名づけた。こうして私は群れを飼った。'),
('JPN', '撒迦利亚书', 38, 11, 8, '私は一月のうちに三人の牧者を退けた。私の心は彼らに我慢できなくなり、彼らの心も私を嫌った。'),
('JPN', '撒迦利亚书', 38, 11, 9, '私は言った。「私はもう、おまえたちを飼わない。死ぬ者は死ね。滅びゆく者は滅びよ。残りの者は、互いに相手の肉を食べるがよい。」'),
('JPN', '撒迦利亚书', 38, 11, 10, '私は、自分の杖、「慈愛」の杖を取って折った。私が諸国の民すべてと結んだ、私の契約を破棄するためであった。'),
('JPN', '撒迦利亚书', 38, 11, 11, 'その日、それは破棄された。そのとき、私を見守っていた羊の商人たちは、それが主のことばであったことを知った。'),
('JPN', '撒迦利亚书', 38, 11, 12, '私は彼らに言った。「あなたがたの目にかなうなら、私に賃金を払え。もしそうでないなら、やめよ。」すると彼らは、私の賃金として銀三十シェケルを量った。'),
('JPN', '撒迦利亚书', 38, 11, 13, '主は私に言われた。「それを陶器師に投げ与えよ。わたしが彼らに値積もりされた、尊い価を。」そこで私は銀三十を取り、それを主の宮の陶器師に投げ与えた。'),
('JPN', '撒迦利亚书', 38, 11, 14, 'そして私は、「結合」というもう一本の杖を折った。ユダとイスラエルとの間の兄弟関係を破棄するためであった。'),
('JPN', '撒迦利亚书', 38, 11, 15, '主は私に言われた。「もう一度、愚かな牧者の道具を取れ。'),
('JPN', '撒迦利亚书', 38, 11, 16, '見よ。それは、わたしが一人の牧者をこの地に起こすからだ。彼は迷い出たものを尋ねず、散らされたものを捜さず、傷ついたものを癒やさず、衰え果てたものに食べ物を与えない。かえって肥えた獣の肉を食らい、そのひづめを裂く。'),
('JPN', '撒迦利亚书', 38, 11, 17, 'わざわいだ。羊の群れを見捨てる、能なしの牧者。剣がその腕と右の目を打ち、その腕はすっかり萎えて、右の目の視力は衰える。」'),
('JPN', '撒迦利亚书', 38, 12, 1, '宣告。イスラエルについての主のことば。天を張り、地の基を定め、人の霊をそのうちに造られた方、主の告げられたことば。'),
('JPN', '撒迦利亚书', 38, 12, 2, '「見よ。わたしはエルサレムを、その周りのあらゆる民をよろめかせる杯とする。エルサレムが包囲されるとき、ユダについてもそうなる。'),
('JPN', '撒迦利亚书', 38, 12, 3, 'その日、わたしはエルサレムを、どの民にとっても重い石とする。すべてそれを担ぐ者は、身にひどい傷を受ける。地のすべての国々は、それに向かって集まって来る。'),
('JPN', '撒迦利亚书', 38, 12, 4, 'その日──主のことば──わたしはすべての馬を打って驚かし、その乗り手を狂わせる。しかし、わたしはユダの家の上に目を見開き、もろもろの民のすべての馬を打ってその目を見えなくする。'),
('JPN', '撒迦利亚书', 38, 12, 5, 'ユダの首長たちは心の中で言う。『エルサレムの住民は、彼らの神、万軍の主によって私の力となる。』'),
('JPN', '撒迦利亚书', 38, 12, 6, 'その日、わたしはユダの首長たちを、薪の中にある火鉢のようにし、麦束の中にある燃えるたいまつのようにする。彼らは右も左も、周りにいるどの民も焼き尽くす。しかしエルサレムはなお、元の場所エルサレムに残る。'),
('JPN', '撒迦利亚书', 38, 12, 7, '主は最初にユダの天幕を救う。ダビデの家の栄えと、エルサレムの住民の栄えが、ユダ以上に大きくならないようにするためである。'),
('JPN', '撒迦利亚书', 38, 12, 8, 'その日、主はエルサレムの住民をかくまう。その日、彼らの中のよろめき倒れる者もダビデのようになり、ダビデの家は神のようになって、彼らの先頭に立つ主の使いのようになる。'),
('JPN', '撒迦利亚书', 38, 12, 9, 'その日、わたしはエルサレムに攻めて来るすべての国々を根絶やしにしよう。'),
('JPN', '撒迦利亚书', 38, 12, 10, 'わたしは、ダビデの家とエルサレムの住民の上に、恵みと嘆願の霊を注ぐ。彼らは、自分たちが突き刺した者、わたしを仰ぎ見て、ひとり子を失って嘆くかのように、その者のために嘆き、長子を失って激しく泣くかのように、その者のために激しく泣く。'),
('JPN', '撒迦利亚书', 38, 12, 11, 'その日、エルサレムでの嘆きは、メギドの平地のハダド・リンモンのための嘆きのように大きくなる。'),
('JPN', '撒迦利亚书', 38, 12, 12, 'この地は、あの氏族もこの氏族もひとり嘆く。ダビデの家の氏族はひとり嘆き、その妻たちもひとり嘆く。ナタンの家の氏族はひとり嘆き、その妻たちもひとり嘆く。'),
('JPN', '撒迦利亚书', 38, 12, 13, 'レビの家の氏族はひとり嘆き、その妻たちもひとり嘆く。シムイの氏族はひとり嘆き、その妻たちもひとり嘆く。'),
('JPN', '撒迦利亚书', 38, 12, 14, '残りのすべての氏族は、あの氏族もこの氏族もひとり嘆き、その妻たちもひとり嘆く。'),
('JPN', '撒迦利亚书', 38, 13, 1, 'その日、ダビデの家とエルサレムの住民のために、罪と汚れをきよめる一つの泉が開かれる。'),
('JPN', '撒迦利亚书', 38, 13, 2, 'その日──万軍の主のことば──わたしはもろもろの偶像の名を、この地から絶ち滅ぼす。それらの名はもう覚えられない。わたしはまた、その預言者たちと汚れの霊をこの国から除く。'),
('JPN', '撒迦利亚书', 38, 13, 3, 'なお預言する者があれば、その人を生んだ父と母が彼に向かって言う。『あなたは生きていてはならない。主の名を使って噓を告げたから。』彼が預言しているときに、彼を生んだ父と母が彼を突き刺す。'),
('JPN', '撒迦利亚书', 38, 13, 4, 'その日、預言者たちはみな、自分が預言する幻を恥じる。彼らはもはや人を欺くための毛衣を着なくなる。'),
('JPN', '撒迦利亚书', 38, 13, 5, 'また彼は、『私は預言者ではない。私は土地を耕す者だ。若いときに人が私を買い取った』と言う。'),
('JPN', '撒迦利亚书', 38, 13, 6, 'だれかが『あなたの両腕の間にある、この打ち傷は何か』と聞くなら、彼は『私の愛人たちの家で打たれたものだ』と言う。'),
('JPN', '撒迦利亚书', 38, 13, 7, '剣よ、目覚めよ。わたしの羊飼いに向かい、わたしの仲間に向かえ──万軍の主のことば──。羊飼いを打て。すると、羊の群れは散らされて行き、わたしは、この手を小さい者たちに向ける。'),
('JPN', '撒迦利亚书', 38, 13, 8, '全地はこうなる──主のことば──。その三分の二は断たれ、死に絶え、三分の一がそこに残る。'),
('JPN', '撒迦利亚书', 38, 13, 9, 'わたしはその三分の一を火の中に入れ、銀を錬るように彼らを錬り、金を試すように彼らを試す。彼らはわたしの名を呼び、わたしは彼らに答える。わたしは『これはわたしの民』と言い、彼らは『主は私の神』と言う。」'),
('JPN', '撒迦利亚书', 38, 14, 1, '見よ、主の日が来る。あなたから奪われた戦利品が、あなたのただ中で分配される。'),
('JPN', '撒迦利亚书', 38, 14, 2, '「わたしはすべての国々を集めて、エルサレムを攻めさせる。都は取られ、家々は略奪され、女たちは犯される。都の半分は捕囚となって出て行く。しかし、残りの民は都から絶ち滅ぼされない。」'),
('JPN', '撒迦利亚书', 38, 14, 3, '主が出て行かれる。決戦の日に戦うように、それらの国々と戦われる。'),
('JPN', '撒迦利亚书', 38, 14, 4, 'その日、主の足はエルサレムの東に面するオリーブ山の上に立つ。オリーブ山はその真ん中で二つに裂け、東西に延びる非常に大きな谷ができる。山の半分は北へ、残りの半分は南へ移る。'),
('JPN', '撒迦利亚书', 38, 14, 5, '「山々の谷がアツァルにまで達するので、あなたがたはわたしの山々の谷に逃げる。ユダの王ウジヤの時に地震を避けて逃げたように、あなたがたは逃げる。」私の神、主が来られる。すべての聖なる者たちも、主とともに来る。'),
('JPN', '撒迦利亚书', 38, 14, 6, 'その日には、光も、寒さも、霜もなくなる。'),
('JPN', '撒迦利亚书', 38, 14, 7, 'これはただ一つの日であり、その日は主に知られている。昼も夜もない。夕暮れ時に光がある。'),
('JPN', '撒迦利亚书', 38, 14, 8, 'その日には、エルサレムからいのちの水が流れ出る。その半分は東の海に、残りの半分は西の海に向かい、夏にも冬にも、それは流れる。'),
('JPN', '撒迦利亚书', 38, 14, 9, '主は地のすべてを治める王となられる。その日には、主は唯一となられ、御名も唯一となる。'),
('JPN', '撒迦利亚书', 38, 14, 10, '全土はゲバからエルサレムの南のリンモンまで、アラバのようになる。しかしエルサレムは高くそびえ、ベニヤミンの門から第一の門のところを経て隅の門まで、またハナンエルのやぐらから王家のぶどうの踏み場まで、元の場所にそのまま残る。'),
('JPN', '撒迦利亚书', 38, 14, 11, 'そこには人々が住み、もはや聖絶の物はなく、エルサレムは安らかに住む。'),
('JPN', '撒迦利亚书', 38, 14, 12, 'これは、主がエルサレムを攻めるどの民にも加えられる疫病である。彼らの肉は、まだ足で立っているうちに腐る。彼らの目はまぶたの中で腐り、彼らの舌は口の中で腐る。'),
('JPN', '撒迦利亚书', 38, 14, 13, 'その日、主からの大いなる混乱が、彼らの間に起こる。彼らは互いに手でつかみ合い、互いに殴りかかる。'),
('JPN', '撒迦利亚书', 38, 14, 14, 'ユダもエルサレムで戦う。周りのすべての国々の財宝は、金、銀、衣服など非常に多く集められる。'),
('JPN', '撒迦利亚书', 38, 14, 15, '馬、らば、らくだ、ろば、彼らの宿営にいるすべての家畜にも、同じような疫病が臨む。'),
('JPN', '撒迦利亚书', 38, 14, 16, 'エルサレムに攻めて来たすべての民のうち、生き残った者はみな、毎年、万軍の主である王を礼拝し、仮庵の祭りを祝うために上って来る。'),
('JPN', '撒迦利亚书', 38, 14, 17, '地上の諸氏族のうち、万軍の主である王を礼拝しにエルサレムに上って来ない氏族の上には、雨が降らない。'),
('JPN', '撒迦利亚书', 38, 14, 18, 'もし、エジプトの氏族が上って来ないなら、雨は彼らの上に降らず、疫病が彼らに下る。これは、仮庵の祭りを祝いに上って来ない諸国の民を主が打つ疫病である。'),
('JPN', '撒迦利亚书', 38, 14, 19, 'これが、エジプトの罪への刑罰となり、仮庵の祭りを祝いに上って来ないすべての国々の罪への刑罰となる。'),
('JPN', '撒迦利亚书', 38, 14, 20, 'その日、馬の鈴の上には「主への聖なるもの」と刻まれ、主の宮の中の鍋は祭壇の前の鉢のようになる。'),
('JPN', '撒迦利亚书', 38, 14, 21, 'エルサレムとユダのすべての鍋は、万軍の主への聖なるものとなる。いけにえを献げる者はみなやって来て、その一つを取ってそれで煮るようになる。その日、万軍の主の宮にはもう商人がいなくなる。'),
('JPN', '玛拉基书', 39, 1, 1, '宣告。マラキを通してイスラエルに臨んだ主のことば。'),
('JPN', '玛拉基书', 39, 1, 2, '「わたしはあなたがたを愛している。──主は言われる──しかし、あなたがたは言う。『どのように、あなたは私たちを愛してくださったのですか』と。エサウはヤコブの兄ではなかったか。──主のことば──しかし、わたしはヤコブを愛した。'),
('JPN', '玛拉基书', 39, 1, 3, 'わたしはエサウを憎み、彼の山を荒れ果てた地とし、彼の相続地を荒野のジャッカルのものとした。'),
('JPN', '玛拉基书', 39, 1, 4, 'たとえエドムが、『私たちは打ち砕かれたが、廃墟を建て直そう』と言っても、──万軍の主はこう言われる──彼らが建てても、わたしが壊す。彼らは悪の領地と呼ばれ、主がとこしえに憤りを向ける民と呼ばれる。'),
('JPN', '玛拉基书', 39, 1, 5, 'あなたがたの目はこれを見る。そして、あなたがたは言う。『主は、イスラエルの地境を越えて、なお大いなる方だ』と。」'),
('JPN', '玛拉基书', 39, 1, 6, '「子は父を、しもべはその主人を敬う。しかし、もし、わたしが父であるなら、どこに、わたしへの尊敬があるのか。もし、わたしが主人であるなら、どこに、わたしへの恐れがあるのか。──万軍の主は言われる──あなたがたのことだ。わたしの名を蔑む祭司たち。しかし、あなたがたは言う。『どのようにして、あなたの名を蔑みましたか』と。'),
('JPN', '玛拉基书', 39, 1, 7, 'あなたがたは、わたしの祭壇に汚れたパンを献げていながら、『どのようにして、私たちがあなたを汚しましたか』と言う。『主の食卓は蔑まれてもよい』とあなたがたは思っている。'),
('JPN', '玛拉基书', 39, 1, 8, 'あなたがたは盲目の動物を献げるが、それは悪いことではないのか。足の萎えたものや病気のものを献げるのは、悪いことではないのか。さあ、あなたの総督のところにそれを差し出してみよ。彼はあなたを受け入れるだろうか。あなたに好意を示すだろうか。──万軍の主は言われる──'),
('JPN', '玛拉基书', 39, 1, 9, 'さあ、今度は神に嘆願したらどうか。『われわれをあわれんでください』と。このことはあなたがたの手によることだ。神があなたがたのうち、だれかを受け入れるだろうか。──万軍の主は言われる──'),
('JPN', '玛拉基书', 39, 1, 10, 'あなたがたのうちには、扉を閉じて、わたしの祭壇にいたずらに火をともせないようにする人が、一人でもいるであろうか。わたしはあなたがたを喜ばない。──万軍の主は言われる──わたしは、あなたがたの手からのささげ物を受け入れない。'),
('JPN', '玛拉基书', 39, 1, 11, '日の昇るところから日の沈むところまで、わたしの名は国々の間で偉大であり、すべての場所で、わたしの名のためにきよいささげ物が献げられ、香がたかれる。まことに、国々の間で偉大なのは、わたしの名。──万軍の主は言われる──'),
('JPN', '玛拉基书', 39, 1, 12, 'しかし、あなたがたは『主の食卓は汚れている。その果実も食物も蔑まれている』と言って、わたしの名を汚している。'),
('JPN', '玛拉基书', 39, 1, 13, 'また、『見よ、なんと煩わしいことか』と言って、それに蔑みのことばを吐いている。──万軍の主は言われる──あなたがたは、かすめたもの、足の萎えたもの、病気のものを連れて来て、ささげ物として献げている。わたしが、それをあなたがたの手から取って、受け入れるだろうか。──主は言われる──'),
('JPN', '玛拉基书', 39, 1, 14, '自分の群れのうちに雄がいて、これを献げると誓いながら、損傷のあるものを主に献げるような、ずるい者はのろわれる。わたしは大いなる王であり、──万軍の主は言われる──わたしの名は諸国の民の間で恐れられているからだ。」'),
('JPN', '玛拉基书', 39, 2, 1, '「祭司たちよ、今、この命令があなたがたに下される。'),
('JPN', '玛拉基书', 39, 2, 2, 'もし、あなたがたが聞き入れず、もし、わたしの名に栄光を帰することを心に留めないなら──万軍の主は言われる──わたしは、あなたがたの中にこののろいを送り、あなたがたの祝福をのろいに変える。もう、それをのろいに変えている。あなたがたがこれを心に留めないからだ。'),
('JPN', '玛拉基书', 39, 2, 3, '見よ。わたしは、あなたがたの子孫を責め、あなたがたの顔に糞をまき散らす。あなたがたの祭りの糞を。あなたがたはそれとともに投げ捨てられる。'),
('JPN', '玛拉基书', 39, 2, 4, 'このときあなたがたは、わたしがレビとの契約を保つために、あなたがたにこの命令を送ったことを知る。──万軍の主は言われる──'),
('JPN', '玛拉基书', 39, 2, 5, 'わたしの、彼との契約は、いのちと平安であった。わたしはそれらを彼に与えた。それは恐れであったので、彼はわたしを恐れ、わたしの名の前に、おののいた。'),
('JPN', '玛拉基书', 39, 2, 6, '彼の口には真理のみおしえがあり、彼の唇には不正がなかった。平和と公平さのうちに、彼はわたしとともに歩み、多くの者を不義から立ち返らせた。'),
('JPN', '玛拉基书', 39, 2, 7, '祭司の唇は知識を守り、人々は彼の口からみおしえを求める。彼が万軍の主の使いだからだ。'),
('JPN', '玛拉基书', 39, 2, 8, 'しかし、あなたがたは道から外れ、多くの者を教えによってつまずかせ、レビとの契約を損なった。──万軍の主は言われる──'),
('JPN', '玛拉基书', 39, 2, 9, 'わたしもまた、あなたがたを、すべての民に蔑まれ、軽んじられる者とする。あなたがたがわたしの道を守らず、えこひいきをしながら教えたからだ。」'),
('JPN', '玛拉基书', 39, 2, 10, '私たちすべてには、唯一の父がいるではないか。唯一の神が、私たちを創造されたではないか。なぜ私たちは、互いに裏切り、私たちの先祖の契約を汚すのか。'),
('JPN', '玛拉基书', 39, 2, 11, 'ユダは裏切り、イスラエルとエルサレムの中で忌まわしいことが行われた。まことにユダは、主が愛された主の聖所を汚し、異国の神の娘をめとった。'),
('JPN', '玛拉基书', 39, 2, 12, 'このようなことをする者を、どうか主がヤコブの天幕から一人残らず断ち切ってくださるように。たとえその者が万軍の主にささげ物を献げても。'),
('JPN', '玛拉基书', 39, 2, 13, 'あなたがたはもう一つのことをしている。あなたがたは、涙と悲鳴と嘆きで、主の祭壇をおおっている。主が、もうささげ物を顧みず、あなたがたの手からそれを喜んで受け取られないからだ。'),
('JPN', '玛拉基书', 39, 2, 14, '「それはなぜなのか」とあなたがたは言う。それは主が、あなたとあなたの若いときの妻との証人であり、あなたがその妻を裏切ったからだ。彼女はあなたの伴侶であり、あなたの契約の妻であるのに。'),
('JPN', '玛拉基书', 39, 2, 15, '神は人を一体に造られたのではないか。そこには、霊の残りがある。その一体の人は何を求めるのか。神の子孫ではないか。あなたがたは、自分の霊に注意せよ。あなたの若いときの妻を裏切ってはならない。'),
('JPN', '玛拉基书', 39, 2, 16, '「妻を憎んで離婚するなら、──イスラエルの神、主は言われる──暴虐がその者の衣をおおう。──万軍の主は言われる。」あなたがたは自分の霊に注意せよ。裏切ってはならない。'),
('JPN', '玛拉基书', 39, 2, 17, 'あなたがたは、自分のことばで主を疲れさせた。あなたがたは言う。「どのようにして、私たちが疲れさせたのか。」それは、あなたがたが「悪を行う者もみな主の目にかなっている。主は彼らを喜ばれる。いったい、さばきの神はどこにいるのか」と言うことによってだ。'),
('JPN', '玛拉基书', 39, 3, 1, '「見よ、わたしはわたしの使いを遣わす。彼は、わたしの前に道を備える。あなたがたが尋ね求めている主が、突然、その神殿に来る。あなたがたが望んでいる契約の使者が、見よ、彼が来る。──万軍の主は言われる。」'),
('JPN', '玛拉基书', 39, 3, 2, 'だれが、この方の来られる日に耐えられよう。だれが、この方の現れるとき立っていられよう。まことに、この方は、精錬する者の火、布をさらす者の灰汁のようだ。'),
('JPN', '玛拉基书', 39, 3, 3, 'この方は、銀を精錬する者、きよめる者として座に着き、レビの子らをきよめて、金や銀にするように、彼らを純粋にする。彼らは主にとって、義によるささげ物を献げる者となる。'),
('JPN', '玛拉基书', 39, 3, 4, 'ユダとエルサレムのささげ物は、昔の日々のように、ずっと以前の年々のように主を喜ばせる。'),
('JPN', '玛拉基书', 39, 3, 5, '「わたしは、さばきのためにあなたがたのところに近づく。わたしは、ためらわずに証人となって敵対する。呪術を行う者、姦淫をする者、偽って誓う者、不正な賃金で雇い人を虐げてやもめやみなしごを苦しめる者、寄留者を押しのけてわたしを恐れない者に。──万軍の主は言われる──'),
('JPN', '玛拉基书', 39, 3, 6, '主であるわたしは変わることがない。そのため、ヤコブの子らよ、あなたがたは絶え果てることはない。'),
('JPN', '玛拉基书', 39, 3, 7, 'あなたがたの先祖の時代から、あなたがたはわたしの掟を離れ、それを守らなかった。わたしに帰れ。そうすれば、わたしもあなたがたに帰る。──万軍の主は言われる──しかし、あなたがたは言う。『どのようにして、私たちは帰ろうか』と。'),
('JPN', '玛拉基书', 39, 3, 8, '人は、神のものを盗むことができるだろうか。だが、あなたがたはわたしのものを盗んでいる。しかも、あなたがたは言う。『どのようにして、私たちはあなたのものを盗んだでしょうか』と。十分の一と奉納物においてだ。'),
('JPN', '玛拉基书', 39, 3, 9, 'あなたがたは、甚だしくのろわれている。あなたがたは、わたしのものを盗んでいる。この民のすべてが盗んでいる。'),
('JPN', '玛拉基书', 39, 3, 10, '十分の一をことごとく、宝物倉に携えて来て、わたしの家の食物とせよ。こうしてわたしを試してみよ。──万軍の主は言われる──わたしがあなたがたのために天の窓を開き、あふれるばかりの祝福をあなたがたに注ぐかどうか。'),
('JPN', '玛拉基书', 39, 3, 11, 'わたしはあなたがたのために、食い荒らすものを叱って、あなたがたの大地の実りを滅ぼさないようにし、畑のぶどうの木が不作とならないようにする。──万軍の主は言われる──'),
('JPN', '玛拉基书', 39, 3, 12, 'すべての国々は、あなたがたを幸せ者と言うようになる。あなたがたが喜びの地となるからだ。──万軍の主は言われる。'),
('JPN', '玛拉基书', 39, 3, 13, 'あなたがたのことばは、わたしに対して度を越している。──主は言われる──あなたがたは言う。『私たちが何と言ったというのですか』と。'),
('JPN', '玛拉基书', 39, 3, 14, 'あなたがたは言う。『神に仕えるのは無駄だ。神の戒めを守っても、万軍の主の前で悲しんで歩いても、何の得になろう。'),
('JPN', '玛拉基书', 39, 3, 15, '今、私たちは高ぶる者を幸せ者と言おう。悪を行っても栄え、神を試みても罰を免れる』と。」'),
('JPN', '玛拉基书', 39, 3, 16, 'そのとき、主を恐れる者たちが互いに語り合った。主は耳を傾けて、これを聞かれた。主を恐れ、主の御名を尊ぶ者たちのために、主の前で記憶の書が記された。'),
('JPN', '玛拉基书', 39, 3, 17, '「彼らは、わたしのものとなる。──万軍の主は言われる──わたしが事を行う日に、わたしの宝となる。人が自分に仕える子をあわれむように、わたしは彼らをあわれむ。'),
('JPN', '玛拉基书', 39, 3, 18, 'あなたがたは再び、正しい人と悪しき者、神に仕える者と仕えない者の違いを見るようになる。」'),
('JPN', '玛拉基书', 39, 4, 1, '「見よ、その日が来る。かまどのように燃えながら。その日、すべて高ぶる者、すべて悪を行う者は藁となる。迫り来るその日は彼らを焼き尽くし、根も枝も残さない。──万軍の主は言われる──'),
('JPN', '玛拉基书', 39, 4, 2, 'しかしあなたがた、わたしの名を恐れる者には、義の太陽が昇る。その翼に癒やしがある。あなたがたは外に出て、牛舎の子牛のように跳ね回る。'),
('JPN', '玛拉基书', 39, 4, 3, 'あなたがたはまた、悪者どもを踏みつける。彼らは、わたしが事を行う日に、あなたがたの足の下で灰となるからだ。──万軍の主は言われる。'),
('JPN', '玛拉基书', 39, 4, 4, 'あなたがたは、わたしのしもべモーセの律法を覚えよ。それは、ホレブでイスラエル全体のために、わたしが彼に命じた掟と定めである。'),
('JPN', '玛拉基书', 39, 4, 5, '見よ。わたしは、主の大いなる恐るべき日が来る前に、預言者エリヤをあなたがたに遣わす。'),
('JPN', '玛拉基书', 39, 4, 6, '彼は、父の心を子に向けさせ、子の心をその父に向けさせる。それは、わたしが来て、この地を聖絶の物として打ち滅ぼすことのないようにするためである。」'),
('JPN', '马太福音', 40, 1, 1, 'アブラハムの子、ダビデの子、イエス・キリストの系図。'),
('JPN', '马太福音', 40, 1, 2, 'アブラハムがイサクを生み、イサクがヤコブを生み、ヤコブがユダとその兄弟たちを生み、'),
('JPN', '马太福音', 40, 1, 3, 'ユダがタマルによってペレツとゼラフを生み、ペレツがヘツロンを生み、ヘツロンがアラムを生み、'),
('JPN', '马太福音', 40, 1, 4, 'アラムがアミナダブを生み、アミナダブがナフションを生み、ナフションがサルマを生み、'),
('JPN', '马太福音', 40, 1, 5, 'サルマがラハブによってボアズを生み、ボアズがルツによってオベデを生み、オベデがエッサイを生み、'),
('JPN', '马太福音', 40, 1, 6, 'エッサイがダビデ王を生んだ。ダビデがウリヤの妻によってソロモンを生み、'),
('JPN', '马太福音', 40, 1, 7, 'ソロモンがレハブアムを生み、レハブアムがアビヤを生み、アビヤがアサを生み、'),
('JPN', '马太福音', 40, 1, 8, 'アサがヨシャファテを生み、ヨシャファテがヨラムを生み、ヨラムがウジヤを生み、'),
('JPN', '马太福音', 40, 1, 9, 'ウジヤがヨタムを生み、ヨタムがアハズを生み、アハズがヒゼキヤを生み、'),
('JPN', '马太福音', 40, 1, 10, 'ヒゼキヤがマナセを生み、マナセがアモンを生み、アモンがヨシヤを生み、'),
('JPN', '马太福音', 40, 1, 11, 'バビロン捕囚のころ、ヨシヤがエコンヤとその兄弟たちを生んだ。'),
('JPN', '马太福音', 40, 1, 12, 'バビロン捕囚の後、エコンヤがシェアルティエルを生み、シェアルティエルがゼルバベルを生み、'),
('JPN', '马太福音', 40, 1, 13, 'ゼルバベルがアビウデを生み、アビウデがエルヤキムを生み、エルヤキムがアゾルを生み、'),
('JPN', '马太福音', 40, 1, 14, 'アゾルがツァドクを生み、ツァドクがアキムを生み、アキムがエリウデを生み、'),
('JPN', '马太福音', 40, 1, 15, 'エリウデがエレアザルを生み、エレアザルがマタンを生み、マタンがヤコブを生み、'),
('JPN', '马太福音', 40, 1, 16, 'ヤコブがマリアの夫ヨセフを生んだ。キリストと呼ばれるイエスは、このマリアからお生まれになった。'),
('JPN', '马太福音', 40, 1, 17, 'それで、アブラハムからダビデまでが全部で十四代、ダビデからバビロン捕囚までが十四代、バビロン捕囚からキリストまでが十四代となる。'),
('JPN', '马太福音', 40, 1, 18, 'イエス・キリストの誕生は次のようであった。母マリアはヨセフと婚約していたが、二人がまだ一緒にならないうちに、聖霊によって身ごもっていることが分かった。'),
('JPN', '马太福音', 40, 1, 19, '夫のヨセフは正しい人で、マリアをさらし者にしたくなかったので、ひそかに離縁しようと思った。'),
('JPN', '马太福音', 40, 1, 20, '彼がこのことを思い巡らしていたところ、見よ、主の使いが夢に現れて言った。「ダビデの子ヨセフよ、恐れずにマリアをあなたの妻として迎えなさい。その胎に宿っている子は聖霊によるのです。'),
('JPN', '马太福音', 40, 1, 21, 'マリアは男の子を産みます。その名をイエスとつけなさい。この方がご自分の民をその罪からお救いになるのです。」'),
('JPN', '马太福音', 40, 1, 22, 'このすべての出来事は、主が預言者を通して語られたことが成就するためであった。'),
('JPN', '马太福音', 40, 1, 23, '「見よ、処女が身ごもっている。そして男の子を産む。その名はインマヌエルと呼ばれる。」それは、訳すと「神が私たちとともにおられる」という意味である。'),
('JPN', '马太福音', 40, 1, 24, 'ヨセフは眠りから覚めると主の使いが命じたとおりにし、自分の妻を迎え入れたが、'),
('JPN', '马太福音', 40, 1, 25, '子を産むまでは彼女を知ることはなかった。そして、その子の名をイエスとつけた。'),
('JPN', '马太福音', 40, 2, 1, 'イエスがヘロデ王の時代に、ユダヤのベツレヘムでお生まれになったとき、見よ、東の方から博士たちがエルサレムにやって来て、こう言った。'),
('JPN', '马太福音', 40, 2, 2, '「ユダヤ人の王としてお生まれになった方は、どこにおられますか。私たちはその方の星が昇るのを見たので、礼拝するために来ました。」'),
('JPN', '马太福音', 40, 2, 3, 'これを聞いてヘロデ王は動揺した。エルサレム中の人々も王と同じであった。'),
('JPN', '马太福音', 40, 2, 4, '王は民の祭司長たち、律法学者たちをみな集め、キリストはどこで生まれるのかと問いただした。'),
('JPN', '马太福音', 40, 2, 5, '彼らは王に言った。「ユダヤのベツレヘムです。預言者によってこう書かれています。'),
('JPN', '马太福音', 40, 2, 6, '『ユダの地、ベツレヘムよ、あなたはユダを治める者たちの中で決して一番小さくはない。あなたから治める者が出て、わたしの民イスラエルを牧するからである。』」'),
('JPN', '马太福音', 40, 2, 7, 'そこでヘロデは博士たちをひそかに呼んで、彼らから、星が現れた時期について詳しく聞いた。'),
('JPN', '马太福音', 40, 2, 8, 'そして、「行って幼子について詳しく調べ、見つけたら知らせてもらいたい。私も行って拝むから」と言って、彼らをベツレヘムに送り出した。'),
('JPN', '马太福音', 40, 2, 9, '博士たちは、王の言ったことを聞いて出て行った。すると見よ。かつて昇るのを見たあの星が、彼らの先に立って進み、ついに幼子のいるところまで来て、その上にとどまった。'),
('JPN', '马太福音', 40, 2, 10, 'その星を見て、彼らはこの上もなく喜んだ。'),
('JPN', '马太福音', 40, 2, 11, 'それから家に入り、母マリアとともにいる幼子を見、ひれ伏して礼拝した。そして宝の箱を開けて、黄金、乳香、没薬を贈り物として献げた。'),
('JPN', '马太福音', 40, 2, 12, '彼らは夢で、ヘロデのところへ戻らないようにと警告されたので、別の道から自分の国に帰って行った。'),
('JPN', '马太福音', 40, 2, 13, '彼らが帰って行くと、見よ、主の使いが夢でヨセフに現れて言った。「立って幼子とその母を連れてエジプトへ逃げなさい。そして、私が知らせるまで、そこにいなさい。ヘロデがこの幼子を捜し出して殺そうとしています。」'),
('JPN', '马太福音', 40, 2, 14, 'そこでヨセフは立って、夜のうちに幼子とその母を連れてエジプトに逃れ、'),
('JPN', '马太福音', 40, 2, 15, 'ヘロデが死ぬまでそこにいた。これは、主が預言者を通して、「わたしは、エジプトからわたしの子を呼び出した」と語られたことが成就するためであった。'),
('JPN', '马太福音', 40, 2, 16, 'ヘロデは、博士たちに欺かれたことが分かると激しく怒った。そして人を遣わし、博士たちから詳しく聞いていた時期に基づいて、ベツレヘムとその周辺一帯の二歳以下の男の子をみな殺させた。'),
('JPN', '马太福音', 40, 2, 17, 'そのとき、預言者エレミヤを通して語られたことが成就した。'),
('JPN', '马太福音', 40, 2, 18, '「ラマで声が聞こえる。むせび泣きと嘆きが。ラケルが泣いている。その子らのゆえに。慰めを拒んでいる。子らがもういないからだ。」'),
('JPN', '马太福音', 40, 2, 19, 'ヘロデが死ぬと、見よ、主の使いが夢で、エジプトにいるヨセフに現れて言った。'),
('JPN', '马太福音', 40, 2, 20, '「立って幼子とその母を連れてイスラエルの地に行きなさい。幼子のいのちを狙っていた者たちは死にました。」'),
('JPN', '马太福音', 40, 2, 21, 'そこで、ヨセフは立って幼子とその母を連れてイスラエルの地に入った。'),
('JPN', '马太福音', 40, 2, 22, 'しかし、アルケラオが父ヘロデに代わってユダヤを治めていると聞いたので、そこに行くのを恐れた。さらに、夢で警告を受けたので、ガリラヤ地方に退いた。'),
('JPN', '马太福音', 40, 2, 23, 'そして、ナザレという町に行って住んだ。これは預言者たちを通して「彼はナザレ人と呼ばれる」と語られたことが成就するためであった。'),
('JPN', '马太福音', 40, 3, 1, 'そのころバプテスマのヨハネが現れ、ユダヤの荒野で教えを宣べ伝えて、'),
('JPN', '马太福音', 40, 3, 2, '「悔い改めなさい。天の御国が近づいたから」と言った。'),
('JPN', '马太福音', 40, 3, 3, 'この人は、預言者イザヤによって「荒野で叫ぶ者の声がする。『主の道を用意せよ。主の通られる道をまっすぐにせよ』」と言われた人である。'),
('JPN', '马太福音', 40, 3, 4, 'このヨハネはらくだの毛の衣をまとい、腰には革の帯を締め、その食べ物はいなごと野蜜であった。'),
('JPN', '马太福音', 40, 3, 5, 'そのころ、エルサレム、ユダヤ全土、ヨルダン川周辺のすべての地域から、人々がヨハネのもとにやって来て、'),
('JPN', '马太福音', 40, 3, 6, '自分の罪を告白し、ヨルダン川で彼からバプテスマを受けていた。'),
('JPN', '马太福音', 40, 3, 7, 'ヨハネは、大勢のパリサイ人やサドカイ人が、バプテスマを受けに来るのを見ると、彼らに言った。「まむしの子孫たち、だれが、迫り来る怒りを逃れるようにと教えたのか。'),
('JPN', '马太福音', 40, 3, 8, 'それなら、悔い改めにふさわしい実を結びなさい。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('JPN', '马太福音', 40, 3, 9, 'あなたがたは、『われわれの父はアブラハムだ』と心の中で思ってはいけません。言っておきますが、神はこれらの石ころからでも、アブラハムの子らを起こすことができるのです。'),
('JPN', '马太福音', 40, 3, 10, '斧はすでに木の根元に置かれています。だから、良い実を結ばない木はすべて切り倒されて、火に投げ込まれます。'),
('JPN', '马太福音', 40, 3, 11, '私はあなたがたに、悔い改めのバプテスマを水で授けていますが、私の後に来られる方は私よりも力のある方です。私には、その方の履き物を脱がせて差し上げる資格もありません。その方は聖霊と火であなたがたにバプテスマを授けられます。'),
('JPN', '马太福音', 40, 3, 12, 'また手に箕を持って、ご自分の脱穀場を隅々まで掃ききよめられます。麦を集めて倉に納め、殻を消えない火で焼き尽くされます。」'),
('JPN', '马太福音', 40, 3, 13, 'そのころ、イエスはガリラヤからヨルダン川のヨハネのもとに来られた。彼からバプテスマを受けるためであった。'),
('JPN', '马太福音', 40, 3, 14, 'しかし、ヨハネはそうさせまいとして言った。「私こそ、あなたからバプテスマを受ける必要があるのに、あなたが私のところにおいでになったのですか。」'),
('JPN', '马太福音', 40, 3, 15, 'しかし、イエスは答えられた。「今はそうさせてほしい。このようにして正しいことをすべて実現することが、わたしたちにはふさわしいのです。」そこでヨハネは言われたとおりにした。'),
('JPN', '马太福音', 40, 3, 16, 'イエスはバプテスマを受けて、すぐに水から上がられた。すると見よ、天が開け、神の御霊が鳩のようにご自分の上に降って来られるのをご覧になった。'),
('JPN', '马太福音', 40, 3, 17, 'そして、見よ、天から声があり、こう告げた。「これはわたしの愛する子。わたしはこれを喜ぶ。」'),
('JPN', '马太福音', 40, 4, 1, 'それからイエスは、悪魔の試みを受けるために、御霊に導かれて荒野に上って行かれた。'),
('JPN', '马太福音', 40, 4, 2, 'そして四十日四十夜、断食をし、その後で空腹を覚えられた。'),
('JPN', '马太福音', 40, 4, 3, 'すると、試みる者が近づいて来て言った。「あなたが神の子なら、これらの石がパンになるように命じなさい。」'),
('JPN', '马太福音', 40, 4, 4, 'イエスは答えられた。「『人はパンだけで生きるのではなく、神の口から出る一つ一つのことばで生きる』と書いてある。」'),
('JPN', '马太福音', 40, 4, 5, 'すると悪魔はイエスを聖なる都に連れて行き、神殿の屋根の端に立たせて、'),
('JPN', '马太福音', 40, 4, 6, 'こう言った。「あなたが神の子なら、下に身を投げなさい。『神はあなたのために御使いたちに命じられる。彼らはその両手にあなたをのせ、あなたの足が石に打ち当たらないようにする』と書いてあるから。」'),
('JPN', '马太福音', 40, 4, 7, 'イエスは言われた。「『あなたの神である主を試みてはならない』とも書いてある。」'),
('JPN', '马太福音', 40, 4, 8, '悪魔はまた、イエスを非常に高い山に連れて行き、この世のすべての王国とその栄華を見せて、'),
('JPN', '马太福音', 40, 4, 9, 'こう言った。「もしひれ伏して私を拝むなら、これをすべてあなたにあげよう。」'),
('JPN', '马太福音', 40, 4, 10, 'そこでイエスは言われた。「下がれ、サタン。『あなたの神である主を礼拝しなさい。主にのみ仕えなさい』と書いてある。」'),
('JPN', '马太福音', 40, 4, 11, 'すると悪魔はイエスを離れた。そして、見よ、御使いたちが近づいて来てイエスに仕えた。'),
('JPN', '马太福音', 40, 4, 12, 'イエスはヨハネが捕らえられたと聞いて、ガリラヤに退かれた。'),
('JPN', '马太福音', 40, 4, 13, 'そしてナザレを離れ、ゼブルンとナフタリの地方にある、湖のほとりの町カペナウムに来て住まわれた。'),
('JPN', '马太福音', 40, 4, 14, 'これは、預言者イザヤを通して語られたことが成就するためであった。'),
('JPN', '马太福音', 40, 4, 15, '「ゼブルンの地とナフタリの地、海沿いの道、ヨルダンの川向こう、異邦人のガリラヤ。'),
('JPN', '马太福音', 40, 4, 16, '闇の中に住んでいた民は大きな光を見る。死の陰の地に住んでいた者たちの上に光が昇る。」'),
('JPN', '马太福音', 40, 4, 17, 'この時からイエスは宣教を開始し、「悔い改めなさい。天の御国が近づいたから」と言われた。'),
('JPN', '马太福音', 40, 4, 18, 'イエスはガリラヤ湖のほとりを歩いておられたとき、二人の兄弟、ペテロと呼ばれるシモンとその兄弟アンデレが、湖で網を打っているのをご覧になった。彼らは漁師であった。'),
('JPN', '马太福音', 40, 4, 19, 'イエスは彼らに言われた。「わたしについて来なさい。人間をとる漁師にしてあげよう。」'),
('JPN', '马太福音', 40, 4, 20, '彼らはすぐに網を捨ててイエスに従った。'),
('JPN', '马太福音', 40, 4, 21, 'イエスはそこから進んで行き、別の二人の兄弟、ゼベダイの子ヤコブとその兄弟ヨハネが、父ゼベダイと一緒に舟の中で網を繕っているのを見ると、二人をお呼びになった。'),
('JPN', '马太福音', 40, 4, 22, '彼らはすぐに舟と父親を残してイエスに従った。'),
('JPN', '马太福音', 40, 4, 23, 'イエスはガリラヤ全域を巡って会堂で教え、御国の福音を宣べ伝え、民の中のあらゆる病、あらゆるわずらいを癒やされた。'),
('JPN', '马太福音', 40, 4, 24, 'イエスの評判はシリア全域に広まった。それで人々は様々な病や痛みに苦しむ人、悪霊につかれた人、てんかんの人、中風の人など病人たちをみな、みもとに連れて来た。イエスは彼らを癒やされた。'),
('JPN', '马太福音', 40, 4, 25, 'こうして大勢の群衆が、ガリラヤ、デカポリス、エルサレム、ユダヤ、およびヨルダンの川向こうから来て、イエスに従った。'),
('JPN', '马太福音', 40, 5, 1, 'その群衆を見て、イエスは山に登られた。そして腰を下ろされると、みもとに弟子たちが来た。'),
('JPN', '马太福音', 40, 5, 2, 'そこでイエスは口を開き、彼らに教え始められた。'),
('JPN', '马太福音', 40, 5, 3, '「心の貧しい者は幸いです。天の御国はその人たちのものだからです。'),
('JPN', '马太福音', 40, 5, 4, '悲しむ者は幸いです。その人たちは慰められるからです。'),
('JPN', '马太福音', 40, 5, 5, '柔和な者は幸いです。その人たちは地を受け継ぐからです。'),
('JPN', '马太福音', 40, 5, 6, '義に飢え渇く者は幸いです。その人たちは満ち足りるからです。'),
('JPN', '马太福音', 40, 5, 7, 'あわれみ深い者は幸いです。その人たちはあわれみを受けるからです。'),
('JPN', '马太福音', 40, 5, 8, '心のきよい者は幸いです。その人たちは神を見るからです。'),
('JPN', '马太福音', 40, 5, 9, '平和をつくる者は幸いです。その人たちは神の子どもと呼ばれるからです。'),
('JPN', '马太福音', 40, 5, 10, '義のために迫害されている者は幸いです。天の御国はその人たちのものだからです。'),
('JPN', '马太福音', 40, 5, 11, 'わたしのために人々があなたがたをののしり、迫害し、ありもしないことで悪口を浴びせるとき、あなたがたは幸いです。'),
('JPN', '马太福音', 40, 5, 12, '喜びなさい。大いに喜びなさい。天においてあなたがたの報いは大きいのですから。あなたがたより前にいた預言者たちを、人々は同じように迫害したのです。'),
('JPN', '马太福音', 40, 5, 13, 'あなたがたは地の塩です。もし塩が塩気をなくしたら、何によって塩気をつけるのでしょうか。もう何の役にも立たず、外に投げ捨てられ、人々に踏みつけられるだけです。'),
('JPN', '马太福音', 40, 5, 14, 'あなたがたは世の光です。山の上にある町は隠れることができません。'),
('JPN', '马太福音', 40, 5, 15, 'また、明かりをともして升の下に置いたりはしません。燭台の上に置きます。そうすれば、家にいるすべての人を照らします。'),
('JPN', '马太福音', 40, 5, 16, 'このように、あなたがたの光を人々の前で輝かせなさい。人々があなたがたの良い行いを見て、天におられるあなたがたの父をあがめるようになるためです。'),
('JPN', '马太福音', 40, 5, 17, 'わたしが律法や預言者を廃棄するために来た、と思ってはなりません。廃棄するためではなく成就するために来たのです。'),
('JPN', '马太福音', 40, 5, 18, 'まことに、あなたがたに言います。天地が消え去るまで、律法の一点一画も決して消え去ることはありません。すべてが実現します。'),
('JPN', '马太福音', 40, 5, 19, 'ですから、これらの戒めの最も小さいものを一つでも破り、また破るように人々に教える者は、天の御国で最も小さい者と呼ばれます。しかし、それを行い、また行うように教える者は天の御国で偉大な者と呼ばれます。'),
('JPN', '马太福音', 40, 5, 20, 'わたしはあなたがたに言います。あなたがたの義が、律法学者やパリサイ人の義にまさっていなければ、あなたがたは決して天の御国に入れません。'),
('JPN', '马太福音', 40, 5, 21, '昔の人々に対して、『殺してはならない。人を殺す者はさばきを受けなければならない』と言われていたのを、あなたがたは聞いています。'),
('JPN', '马太福音', 40, 5, 22, 'しかし、わたしはあなたがたに言います。兄弟に対して怒る者は、だれでもさばきを受けなければなりません。兄弟に『ばか者』と言う者は最高法院でさばかれます。『愚か者』と言う者は火の燃えるゲヘナに投げ込まれます。'),
('JPN', '马太福音', 40, 5, 23, 'ですから、祭壇の上にささげ物を献げようとしているときに、兄弟が自分を恨んでいることを思い出したなら、'),
('JPN', '马太福音', 40, 5, 24, 'ささげ物はそこに、祭壇の前に置き、行って、まずあなたの兄弟と仲直りをしなさい。それから戻って、そのささげ物を献げなさい。'),
('JPN', '马太福音', 40, 5, 25, 'あなたを訴える人とは、一緒に行く途中で早く和解しなさい。そうでないと、訴える人はあなたを裁判官に引き渡し、裁判官は下役に引き渡し、あなたは牢に投げ込まれることになります。'),
('JPN', '马太福音', 40, 5, 26, 'まことに、あなたに言います。最後の一コドラントを支払うまで、そこから決して出ることはできません。'),
('JPN', '马太福音', 40, 5, 27, '『姦淫してはならない』と言われていたのを、あなたがたは聞いています。'),
('JPN', '马太福音', 40, 5, 28, 'しかし、わたしはあなたがたに言います。情欲を抱いて女を見る者はだれでも、心の中ですでに姦淫を犯したのです。'),
('JPN', '马太福音', 40, 5, 29, 'もし右の目があなたをつまずかせるなら、えぐり出して捨てなさい。からだの一部を失っても、全身がゲヘナに投げ込まれないほうがよいのです。'),
('JPN', '马太福音', 40, 5, 30, 'もし右の手があなたをつまずかせるなら、切って捨てなさい。からだの一部を失っても、全身がゲヘナに落ちないほうがよいのです。'),
('JPN', '马太福音', 40, 5, 31, 'また『妻を離縁する者は離縁状を与えよ』と言われていました。'),
('JPN', '马太福音', 40, 5, 32, 'しかし、わたしはあなたがたに言います。だれでも、淫らな行い以外の理由で自分の妻を離縁する者は、妻に姦淫を犯させることになります。また、離縁された女と結婚すれば、姦淫を犯すことになるのです。'),
('JPN', '马太福音', 40, 5, 33, 'また、昔の人々に対して、『偽って誓ってはならない。あなたが誓ったことを主に果たせ』と言われていたのを、あなたがたは聞いています。'),
('JPN', '马太福音', 40, 5, 34, 'しかし、わたしはあなたがたに言います。決して誓ってはいけません。天にかけて誓ってはいけません。そこは神の御座だからです。'),
('JPN', '马太福音', 40, 5, 35, '地にかけて誓ってもいけません。そこは神の足台だからです。エルサレムにかけて誓ってもいけません。そこは偉大な王の都だからです。'),
('JPN', '马太福音', 40, 5, 36, '自分の頭にかけて誓ってもいけません。あなたは髪の毛一本さえ白くも黒くもできないのですから。'),
('JPN', '马太福音', 40, 5, 37, 'あなたがたの言うことばは、『はい』は『はい』、『いいえ』は『いいえ』としなさい。それ以上のことは悪い者から出ているのです。'),
('JPN', '马太福音', 40, 5, 38, '『目には目を、歯には歯を』と言われていたのを、あなたがたは聞いています。'),
('JPN', '马太福音', 40, 5, 39, 'しかし、わたしはあなたがたに言います。悪い者に手向かってはいけません。あなたの右の頬を打つ者には左の頬も向けなさい。'),
('JPN', '马太福音', 40, 5, 40, 'あなたを告訴して下着を取ろうとする者には、上着も取らせなさい。'),
('JPN', '马太福音', 40, 5, 41, 'あなたに一ミリオン行くように強いる者がいれば、一緒に二ミリオン行きなさい。'),
('JPN', '马太福音', 40, 5, 42, '求める者には与えなさい。借りようとする者に背を向けてはいけません。'),
('JPN', '马太福音', 40, 5, 43, '『あなたの隣人を愛し、あなたの敵を憎め』と言われていたのを、あなたがたは聞いています。'),
('JPN', '马太福音', 40, 5, 44, 'しかし、わたしはあなたがたに言います。自分の敵を愛し、自分を迫害する者のために祈りなさい。'),
('JPN', '马太福音', 40, 5, 45, '天におられるあなたがたの父の子どもになるためです。父はご自分の太陽を悪人にも善人にも昇らせ、正しい者にも正しくない者にも雨を降らせてくださるからです。'),
('JPN', '马太福音', 40, 5, 46, '自分を愛してくれる人を愛したとしても、あなたがたに何の報いがあるでしょうか。取税人でも同じことをしているではありませんか。'),
('JPN', '马太福音', 40, 5, 47, 'また、自分の兄弟にだけあいさつしたとしても、どれだけまさったことをしたことになるでしょうか。異邦人でも同じことをしているではありませんか。'),
('JPN', '马太福音', 40, 5, 48, 'ですから、あなたがたの天の父が完全であるように、完全でありなさい。'),
('JPN', '马太福音', 40, 6, 1, '人に見せるために人前で善行をしないように気をつけなさい。そうでないと、天におられるあなたがたの父から報いを受けられません。'),
('JPN', '马太福音', 40, 6, 2, 'ですから、施しをするとき、偽善者たちが人にほめてもらおうと会堂や通りでするように、自分の前でラッパを吹いてはいけません。まことに、あなたがたに言います。彼らはすでに自分の報いを受けているのです。'),
('JPN', '马太福音', 40, 6, 3, 'あなたが施しをするときは、右の手がしていることを左の手に知られないようにしなさい。'),
('JPN', '马太福音', 40, 6, 4, 'あなたの施しが、隠れたところにあるようにするためです。そうすれば、隠れたところで見ておられるあなたの父が、あなたに報いてくださいます。'),
('JPN', '马太福音', 40, 6, 5, 'また、祈るとき偽善者たちのようであってはいけません。彼らは人々に見えるように、会堂や大通りの角に立って祈るのが好きだからです。まことに、あなたがたに言います。彼らはすでに自分の報いを受けているのです。'),
('JPN', '马太福音', 40, 6, 6, 'あなたが祈るときは、家の奥の自分の部屋に入りなさい。そして戸を閉めて、隠れたところにおられるあなたの父に祈りなさい。そうすれば、隠れたところで見ておられるあなたの父が、あなたに報いてくださいます。'),
('JPN', '马太福音', 40, 6, 7, 'また、祈るとき、異邦人のように、同じことばをただ繰り返してはいけません。彼らは、ことば数が多いことで聞かれると思っているのです。'),
('JPN', '马太福音', 40, 6, 8, 'ですから、彼らと同じようにしてはいけません。あなたがたの父は、あなたがたが求める前から、あなたがたに必要なものを知っておられるのです。'),
('JPN', '马太福音', 40, 6, 9, 'ですから、あなたがたはこう祈りなさい。『天にいます私たちの父よ。御名が聖なるものとされますように。'),
('JPN', '马太福音', 40, 6, 10, '御国が来ますように。みこころが天で行われるように、地でも行われますように。'),
('JPN', '马太福音', 40, 6, 11, '私たちの日ごとの糧を、今日もお与えください。'),
('JPN', '马太福音', 40, 6, 12, '私たちの負い目をお赦しください。私たちも、私たちに負い目のある人たちを赦します。'),
('JPN', '马太福音', 40, 6, 13, '私たちを試みにあわせないで、悪からお救いください。』（国と力と栄えは、とこしえにあなたのものだからです。アーメン。）'),
('JPN', '马太福音', 40, 6, 14, 'もし人の過ちを赦すなら、あなたがたの天の父もあなたがたを赦してくださいます。'),
('JPN', '马太福音', 40, 6, 15, 'しかし、人を赦さないなら、あなたがたの父もあなたがたの過ちをお赦しになりません。'),
('JPN', '马太福音', 40, 6, 16, 'あなたがたが断食をするときには、偽善者たちのように暗い顔をしてはいけません。彼らは断食をしていることが人に見えるように、顔をやつれさせるのです。まことに、あなたがたに言います。彼らはすでに自分の報いを受けているのです。'),
('JPN', '马太福音', 40, 6, 17, '断食するときは頭に油を塗り、顔を洗いなさい。'),
('JPN', '马太福音', 40, 6, 18, 'それは、断食していることが、人にではなく、隠れたところにおられるあなたの父に見えるようにするためです。そうすれば、隠れたところで見ておられるあなたの父が報いてくださいます。'),
('JPN', '马太福音', 40, 6, 19, '自分のために、地上に宝を蓄えるのはやめなさい。そこでは虫やさびで傷物になり、盗人が壁に穴を開けて盗みます。'),
('JPN', '马太福音', 40, 6, 20, '自分のために、天に宝を蓄えなさい。そこでは虫やさびで傷物になることはなく、盗人が壁に穴を開けて盗むこともありません。'),
('JPN', '马太福音', 40, 6, 21, 'あなたの宝のあるところ、そこにあなたの心もあるのです。'),
('JPN', '马太福音', 40, 6, 22, 'からだの明かりは目です。ですから、あなたの目が健やかなら全身が明るくなりますが、'),
('JPN', '马太福音', 40, 6, 23, '目が悪ければ全身が暗くなります。ですから、もしあなたのうちにある光が闇なら、その闇はどれほどでしょうか。'),
('JPN', '马太福音', 40, 6, 24, 'だれも二人の主人に仕えることはできません。一方を憎んで他方を愛することになるか、一方を重んじて他方を軽んじることになります。あなたがたは神と富とに仕えることはできません。'),
('JPN', '马太福音', 40, 6, 25, 'ですから、わたしはあなたがたに言います。何を食べようか何を飲もうかと、自分のいのちのことで心配したり、何を着ようかと、自分のからだのことで心配したりするのはやめなさい。いのちは食べ物以上のもの、からだは着る物以上のものではありませんか。'),
('JPN', '马太福音', 40, 6, 26, '空の鳥を見なさい。種蒔きもせず、刈り入れもせず、倉に納めることもしません。それでも、あなたがたの天の父は養っていてくださいます。あなたがたはその鳥よりも、ずっと価値があるではありませんか。'),
('JPN', '马太福音', 40, 6, 27, 'あなたがたのうちだれが、心配したからといって、少しでも自分のいのちを延ばすことができるでしょうか。'),
('JPN', '马太福音', 40, 6, 28, 'なぜ着る物のことで心配するのですか。野の花がどうして育つのか、よく考えなさい。働きもせず、紡ぎもしません。'),
('JPN', '马太福音', 40, 6, 29, 'しかし、わたしはあなたがたに言います。栄華を極めたソロモンでさえ、この花の一つほどにも装っていませんでした。'),
('JPN', '马太福音', 40, 6, 30, '今日あっても明日は炉に投げ込まれる野の草さえ、神はこのように装ってくださるのなら、あなたがたには、もっと良くしてくださらないでしょうか。信仰の薄い人たちよ。'),
('JPN', '马太福音', 40, 6, 31, 'ですから、何を食べようか、何を飲もうか、何を着ようかと言って、心配しなくてよいのです。'),
('JPN', '马太福音', 40, 6, 32, 'これらのものはすべて、異邦人が切に求めているものです。あなたがたにこれらのものすべてが必要であることは、あなたがたの天の父が知っておられます。'),
('JPN', '马太福音', 40, 6, 33, 'まず神の国と神の義を求めなさい。そうすれば、これらのものはすべて、それに加えて与えられます。'),
('JPN', '马太福音', 40, 6, 34, 'ですから、明日のことまで心配しなくてよいのです。明日のことは明日が心配します。苦労はその日その日に十分あります。'),
('JPN', '马太福音', 40, 7, 1, 'さばいてはいけません。自分がさばかれないためです。'),
('JPN', '马太福音', 40, 7, 2, 'あなたがたは、自分がさばく、そのさばきでさばかれ、自分が量るその秤で量り与えられるのです。'),
('JPN', '马太福音', 40, 7, 3, 'あなたは、兄弟の目にあるちりは見えるのに、自分の目にある梁には、なぜ気がつかないのですか。'),
('JPN', '马太福音', 40, 7, 4, '兄弟に向かって、『あなたの目からちりを取り除かせてください』と、どうして言うのですか。見なさい。自分の目には梁があるではありませんか。'),
('JPN', '马太福音', 40, 7, 5, '偽善者よ、まず自分の目から梁を取り除きなさい。そうすれば、はっきり見えるようになって、兄弟の目からちりを取り除くことができます。'),
('JPN', '马太福音', 40, 7, 6, '聖なるものを犬に与えてはいけません。また、真珠を豚の前に投げてはいけません。犬や豚はそれらを足で踏みつけ、向き直って、あなたがたをかみ裂くことになります。'),
('JPN', '马太福音', 40, 7, 7, '求めなさい。そうすれば与えられます。探しなさい。そうすれば見出します。たたきなさい。そうすれば開かれます。'),
('JPN', '马太福音', 40, 7, 8, 'だれでも、求める者は受け、探す者は見出し、たたく者には開かれます。'),
('JPN', '马太福音', 40, 7, 9, 'あなたがたのうちのだれが、自分の子がパンを求めているのに石を与えるでしょうか。'),
('JPN', '马太福音', 40, 7, 10, '魚を求めているのに、蛇を与えるでしょうか。'),
('JPN', '马太福音', 40, 7, 11, 'このように、あなたがたは悪い者であっても、自分の子どもたちには良いものを与えることを知っているのです。それならなおのこと、天におられるあなたがたの父は、ご自分に求める者たちに、良いものを与えてくださらないことがあるでしょうか。'),
('JPN', '马太福音', 40, 7, 12, 'ですから、人からしてもらいたいことは何でも、あなたがたも同じように人にしなさい。これが律法と預言者です。'),
('JPN', '马太福音', 40, 7, 13, '狭い門から入りなさい。滅びに至る門は大きく、その道は広く、そこから入って行く者が多いのです。'),
('JPN', '马太福音', 40, 7, 14, 'いのちに至る門はなんと狭く、その道もなんと細いことでしょう。そして、それを見出す者はわずかです。'),
('JPN', '马太福音', 40, 7, 15, '偽預言者たちに用心しなさい。彼らは羊の衣を着てあなたがたのところに来るが、内側は貪欲な狼です。'),
('JPN', '马太福音', 40, 7, 16, 'あなたがたは彼らを実によって見分けることになります。茨からぶどうが、あざみからいちじくが採れるでしょうか。'),
('JPN', '马太福音', 40, 7, 17, '良い木はみな良い実を結び、悪い木は悪い実を結びます。'),
('JPN', '马太福音', 40, 7, 18, '良い木が悪い実を結ぶことはできず、また、悪い木が良い実を結ぶこともできません。'),
('JPN', '马太福音', 40, 7, 19, '良い実を結ばない木はみな切り倒されて、火に投げ込まれます。'),
('JPN', '马太福音', 40, 7, 20, 'こういうわけで、あなたがたは彼らを実によって見分けることになるのです。'),
('JPN', '马太福音', 40, 7, 21, 'わたしに向かって『主よ、主よ』と言う者がみな天の御国に入るのではなく、天におられるわたしの父のみこころを行う者が入るのです。'),
('JPN', '马太福音', 40, 7, 22, 'その日には多くの者がわたしに言うでしょう。『主よ、主よ。私たちはあなたの名によって預言し、あなたの名によって悪霊を追い出し、あなたの名によって多くの奇跡を行ったではありませんか。』'),
('JPN', '马太福音', 40, 7, 23, 'しかし、わたしはそのとき、彼らにはっきりと言います。『わたしはおまえたちを全く知らない。不法を行う者たち、わたしから離れて行け。』'),
('JPN', '马太福音', 40, 7, 24, 'ですから、わたしのこれらのことばを聞いて、それを行う者はみな、岩の上に自分の家を建てた賢い人にたとえることができます。'),
('JPN', '马太福音', 40, 7, 25, '雨が降って洪水が押し寄せ、風が吹いてその家を襲っても、家は倒れませんでした。岩の上に土台が据えられていたからです。'),
('JPN', '马太福音', 40, 7, 26, 'また、わたしのこれらのことばを聞いて、それを行わない者はみな、砂の上に自分の家を建てた愚かな人にたとえることができます。'),
('JPN', '马太福音', 40, 7, 27, '雨が降って洪水が押し寄せ、風が吹いてその家に打ちつけると、倒れてしまいました。しかもその倒れ方はひどいものでした。」'),
('JPN', '马太福音', 40, 7, 28, 'イエスがこれらのことばを語り終えられると、群衆はその教えに驚いた。'),
('JPN', '马太福音', 40, 7, 29, 'イエスが、彼らの律法学者たちのようにではなく、権威ある者として教えられたからである。'),
('JPN', '马太福音', 40, 8, 1, 'イエスが山から下りて来られると、大勢の群衆がイエスに従った。'),
('JPN', '马太福音', 40, 8, 2, 'すると見よ。ツァラアトに冒された人がみもとに来て、イエスに向かってひれ伏し、「主よ、お心一つで私をきよくすることがおできになります」と言った。'),
('JPN', '马太福音', 40, 8, 3, 'イエスは手を伸ばして彼にさわり、「わたしの心だ。きよくなれ」と言われた。すると、すぐに彼のツァラアトはきよめられた。'),
('JPN', '马太福音', 40, 8, 4, 'イエスは彼に言われた。「だれにも話さないように気をつけなさい。ただ行って自分を祭司に見せなさい。そして、人々への証しのために、モーセが命じたささげ物をしなさい。」'),
('JPN', '马太福音', 40, 8, 5, 'イエスがカペナウムに入られると、一人の百人隊長がみもとに来て懇願し、'),
('JPN', '马太福音', 40, 8, 6, '「主よ、私のしもべが中風のために家で寝込んでいます。ひどく苦しんでいます」と言った。'),
('JPN', '马太福音', 40, 8, 7, 'イエスは彼に「行って彼を治そう」と言われた。'),
('JPN', '马太福音', 40, 8, 8, 'しかし、百人隊長は答えた。「主よ、あなた様を私の屋根の下にお入れする資格は、私にはありません。ただ、おことばを下さい。そうすれば私のしもべは癒やされます。'),
('JPN', '马太福音', 40, 8, 9, 'と申しますのは、私も権威の下にある者だからです。私自身の下にも兵士たちがいて、その一人に『行け』と言えば行きますし、別の者に『来い』と言えば来ます。また、しもべに『これをしろ』と言えば、そのようにします。」'),
('JPN', '马太福音', 40, 8, 10, 'イエスはこれを聞いて驚き、ついて来た人たちに言われた。「まことに、あなたがたに言います。わたしはイスラエルのうちのだれにも、これほどの信仰を見たことがありません。'),
('JPN', '马太福音', 40, 8, 11, 'あなたがたに言いますが、多くの人が東からも西からも来て、天の御国でアブラハム、イサク、ヤコブと一緒に食卓に着きます。'),
('JPN', '马太福音', 40, 8, 12, 'しかし、御国の子らは外の暗闇に放り出されます。そこで泣いて歯ぎしりするのです。」'),
('JPN', '马太福音', 40, 8, 13, 'それからイエスは百人隊長に言われた。「行きなさい。あなたの信じたとおりになるように。」すると、ちょうどそのとき、そのしもべは癒やされた。'),
('JPN', '马太福音', 40, 8, 14, 'それからイエスはペテロの家に入り、彼の姑が熱を出して寝込んでいるのをご覧になった。'),
('JPN', '马太福音', 40, 8, 15, 'イエスは彼女の手に触れられた。すると熱がひき、彼女は起きてイエスをもてなした。'),
('JPN', '马太福音', 40, 8, 16, '夕方になると、人々は悪霊につかれた人を、大勢みもとに連れて来た。イエスはことばをもって悪霊どもを追い出し、病気の人々をみな癒やされた。'),
('JPN', '马太福音', 40, 8, 17, 'これは、預言者イザヤを通して語られたことが成就するためであった。「彼は私たちのわずらいを担い、私たちの病を負った。」'),
('JPN', '马太福音', 40, 8, 18, 'さて、イエスは群衆が自分の周りにいるのを見て、弟子たちに向こう岸に渡るように命じられた。'),
('JPN', '马太福音', 40, 8, 19, 'そこに一人の律法学者が来て言った。「先生。あなたがどこに行かれても、私はついて行きます。」'),
('JPN', '马太福音', 40, 8, 20, 'イエスは彼に言われた。「狐には穴があり、空の鳥には巣があるが、人の子には枕するところもありません。」'),
('JPN', '马太福音', 40, 8, 21, 'また、別の一人の弟子がイエスに言った。「主よ。まず行って父を葬ることをお許しください。」'),
('JPN', '马太福音', 40, 8, 22, 'ところが、イエスは彼に言われた。「わたしに従って来なさい。死人たちに、彼ら自身の死人たちを葬らせなさい。」'),
('JPN', '马太福音', 40, 8, 23, 'それからイエスが舟に乗られると、弟子たちも従った。'),
('JPN', '马太福音', 40, 8, 24, 'すると見よ。湖は大荒れとなり、舟は大波をかぶった。ところがイエスは眠っておられた。'),
('JPN', '马太福音', 40, 8, 25, '弟子たちは近寄ってイエスを起こして、「主よ、助けてください。私たちは死んでしまいます」と言った。'),
('JPN', '马太福音', 40, 8, 26, 'イエスは言われた。「どうして怖がるのか、信仰の薄い者たち。」それから起き上がり、風と湖を叱りつけられた。すると、すっかり凪になった。'),
('JPN', '马太福音', 40, 8, 27, '人々は驚いて言った。「風や湖までが言うことを聞くとは、いったいこの方はどういう方なのだろうか。」'),
('JPN', '马太福音', 40, 8, 28, 'さて、イエスが向こう岸のガダラ人の地にお着きになると、悪霊につかれた人が二人、墓場から出て来てイエスを迎えた。彼らはひどく狂暴で、だれもその道を通れないほどであった。'),
('JPN', '马太福音', 40, 8, 29, 'すると見よ、彼らが叫んだ。「神の子よ、私たちと何の関係があるのですか。まだその時ではないのに、もう私たちを苦しめに来たのですか。」'),
('JPN', '马太福音', 40, 8, 30, 'そこから離れたところに、多くの豚の群れが飼われていた。'),
('JPN', '马太福音', 40, 8, 31, '悪霊どもはイエスに懇願して、「私たちを追い出そうとされるのでしたら、豚の群れの中に送ってください」と言った。'),
('JPN', '马太福音', 40, 8, 32, 'イエスは彼らに「行け」と言われた。それで、悪霊どもは出て行って豚に入った。すると見よ。その群れ全体が崖を下って湖になだれ込み、水におぼれて死んだ。'),
('JPN', '马太福音', 40, 8, 33, '飼っていた人たちは逃げ出して町に行き、悪霊につかれていた人たちのことなどを残らず知らせた。'),
('JPN', '马太福音', 40, 8, 34, 'すると見よ、町中の人がイエスに会いに出て来た。そして、イエスを見ると、その地方から立ち去ってほしいと懇願した。'),
('JPN', '马太福音', 40, 9, 1, 'イエスは舟に乗って湖を渡り、自分の町に帰られた。'),
('JPN', '马太福音', 40, 9, 2, 'すると見よ。人々が中風の人を床に寝かせたまま、みもとに運んで来た。イエスは彼らの信仰を見て、中風の人に「子よ、しっかりしなさい。あなたの罪は赦された」と言われた。'),
('JPN', '马太福音', 40, 9, 3, 'すると、律法学者たちが何人かそこにいて、心の中で「この人は神を冒瀆している」と言った。'),
('JPN', '马太福音', 40, 9, 4, 'イエスは彼らの思いを知って言われた。「なぜ心の中で悪いことを考えているのか。'),
('JPN', '马太福音', 40, 9, 5, '『あなたの罪は赦された』と言うのと、『起きて歩け』と言うのと、どちらが易しいか。'),
('JPN', '马太福音', 40, 9, 6, 'しかし、人の子が地上で罪を赦す権威を持っていることを、あなたがたが知るために──。」そう言って、それから中風の人に「起きて寝床を担ぎ、家に帰りなさい」と言われた。'),
('JPN', '马太福音', 40, 9, 7, 'すると彼は起き上がり、家に帰った。'),
('JPN', '马太福音', 40, 9, 8, '群衆はそれを見て恐ろしくなり、このような権威を人にお与えになった神をあがめた。'),
('JPN', '马太福音', 40, 9, 9, 'イエスはそこから進んで行き、マタイという人が収税所に座っているのを見て、「わたしについて来なさい」と言われた。すると、彼は立ち上がってイエスに従った。'),
('JPN', '马太福音', 40, 9, 10, 'イエスが家の中で食事の席に着いておられたとき、見よ、取税人たちや罪人たちが大勢来て、イエスや弟子たちとともに食卓に着いていた。'),
('JPN', '马太福音', 40, 9, 11, 'これを見たパリサイ人たちは弟子たちに、「なぜあなたがたの先生は、取税人たちや罪人たちと一緒に食事をするのですか」と言った。'),
('JPN', '马太福音', 40, 9, 12, 'イエスはこれを聞いて言われた。「医者を必要とするのは、丈夫な人ではなく病人です。'),
('JPN', '马太福音', 40, 9, 13, '『わたしが喜びとするのは真実の愛。いけにえではない』とはどういう意味か、行って学びなさい。わたしが来たのは、正しい人を招くためではなく、罪人を招くためです。」'),
('JPN', '马太福音', 40, 9, 14, 'それから、ヨハネの弟子たちがイエスのところに来て、「私たちとパリサイ人はたびたび断食をしているのに、なぜあなたの弟子たちは断食をしないのですか」と言った。'),
('JPN', '马太福音', 40, 9, 15, 'イエスは彼らに言われた。「花婿に付き添う友人たちは、花婿が一緒にいる間、悲しむことができるでしょうか。しかし、彼らから花婿が取り去られる日が来ます。そのときには断食をします。'),
('JPN', '马太福音', 40, 9, 16, 'だれも、真新しい布切れで古い衣に継ぎを当てたりはしません。そんな継ぎ切れは衣を引き裂き、破れがもっとひどくなるからです。'),
('JPN', '马太福音', 40, 9, 17, 'また、人は新しいぶどう酒を古い皮袋に入れたりはしません。そんなことをすれば皮袋は裂け、ぶどう酒が流れ出て、皮袋もだめになります。新しいぶどう酒は新しい皮袋に入れます。そうすれば両方とも保てます。」'),
('JPN', '马太福音', 40, 9, 18, 'イエスがこれらのことを話しておられると、見よ、一人の会堂司が来てひれ伏し、「私の娘が今、死にました。でも、おいでになって娘の上に手を置いてやってください。そうすれば娘は生き返ります」と言った。'),
('JPN', '马太福音', 40, 9, 19, 'そこでイエスは立ち上がり、彼について行かれた。弟子たちも従った。'),
('JPN', '马太福音', 40, 9, 20, 'すると見よ。十二年の間長血をわずらっている女の人が、イエスのうしろから近づいて、その衣の房に触れた。'),
('JPN', '马太福音', 40, 9, 21, '「この方の衣に触れさえすれば、私は救われる」と心のうちで考えたからである。'),
('JPN', '马太福音', 40, 9, 22, 'イエスは振り向いて、彼女を見て言われた。「娘よ、しっかりしなさい。あなたの信仰があなたを救ったのです。」すると、その時から彼女は癒やされた。'),
('JPN', '马太福音', 40, 9, 23, 'イエスは会堂司の家に着き、笛吹く者たちや騒いでいる群衆を見て、'),
('JPN', '马太福音', 40, 9, 24, '「出て行きなさい。その少女は死んだのではなく、眠っているのです」と言われた。人々はイエスをあざ笑った。'),
('JPN', '马太福音', 40, 9, 25, '群衆が外に出されると、イエスは中に入り、少女の手を取られた。すると少女は起き上がった。'),
('JPN', '马太福音', 40, 9, 26, 'この話はその地方全体に広まった。'),
('JPN', '马太福音', 40, 9, 27, 'イエスがそこから進んで行くと、目の見えない二人の人が、「ダビデの子よ、私たちをあわれんでください」と叫びながらついて来た。'),
('JPN', '马太福音', 40, 9, 28, 'イエスが家に入られると、その人たちがみもとに来た。イエスが、「わたしにそれができると信じるのか」と言われると、彼らは「はい、主よ」と言った。'),
('JPN', '马太福音', 40, 9, 29, 'そこでイエスは彼らの目にさわって、「あなたがたの信仰のとおりになれ」と言われた。'),
('JPN', '马太福音', 40, 9, 30, 'すると、彼らの目が開いた。イエスは彼らに厳しく命じて、「だれにも知られないように気をつけなさい」と言われた。'),
('JPN', '马太福音', 40, 9, 31, 'しかし、彼らは出て行って、その地方全体にイエスのことを言い広めた。'),
('JPN', '马太福音', 40, 9, 32, 'その人たちが出て行くと、見よ、人々はイエスのもとに、悪霊につかれて口のきけない人を連れて来た。'),
('JPN', '马太福音', 40, 9, 33, '悪霊が追い出されると、口のきけない人がものを言うようになった。群衆は驚いて、「こんなことはイスラエルで、いまだかつて起こったことがない」と言った。'),
('JPN', '马太福音', 40, 9, 34, 'しかし、パリサイ人たちは、「彼は悪霊どものかしらによって悪霊どもを追い出しているのだ」と言った。'),
('JPN', '马太福音', 40, 9, 35, 'それからイエスは、すべての町や村を巡って、会堂で教え、御国の福音を宣べ伝え、あらゆる病気、あらゆるわずらいを癒やされた。'),
('JPN', '马太福音', 40, 9, 36, 'また、群衆を見て深くあわれまれた。彼らが羊飼いのいない羊の群れのように、弱り果てて倒れていたからである。'),
('JPN', '马太福音', 40, 9, 37, 'そこでイエスは弟子たちに言われた。「収穫は多いが、働き手が少ない。'),
('JPN', '马太福音', 40, 9, 38, 'だから、収穫の主に、ご自分の収穫のために働き手を送ってくださるように祈りなさい。」'),
('JPN', '马太福音', 40, 10, 1, 'イエスは十二弟子を呼んで、汚れた霊どもを制する権威をお授けになった。霊どもを追い出し、あらゆる病気、あらゆるわずらいを癒やすためであった。'),
('JPN', '马太福音', 40, 10, 2, '十二使徒の名は次のとおりである。まず、ペテロと呼ばれるシモンとその兄弟アンデレ、ゼベダイの子ヤコブとその兄弟ヨハネ、'),
('JPN', '马太福音', 40, 10, 3, 'ピリポとバルトロマイ、トマスと取税人マタイ、アルパヨの子ヤコブとタダイ、'),
('JPN', '马太福音', 40, 10, 4, '熱心党のシモンと、イエスを裏切ったイスカリオテのユダである。'),
('JPN', '马太福音', 40, 10, 5, 'イエスはこの十二人を遣わす際、彼らにこう命じられた。「異邦人の道に行ってはいけません。また、サマリア人の町に入ってはいけません。'),
('JPN', '马太福音', 40, 10, 6, 'むしろ、イスラエルの家の失われた羊たちのところに行きなさい。'),
('JPN', '马太福音', 40, 10, 7, '行って、『天の御国が近づいた』と宣べ伝えなさい。'),
('JPN', '马太福音', 40, 10, 8, '病人を癒やし、死人を生き返らせ、ツァラアトに冒された者をきよめ、悪霊どもを追い出しなさい。あなたがたはただで受けたのですから、ただで与えなさい。'),
('JPN', '马太福音', 40, 10, 9, '胴巻に金貨も銀貨も銅貨も入れて行ってはいけません。'),
('JPN', '马太福音', 40, 10, 10, '袋も二枚目の下着も履き物も杖も持たずに、旅に出なさい。働く者が食べ物を得るのは当然だからです。'),
('JPN', '马太福音', 40, 10, 11, 'どの町や村に入っても、そこでだれがふさわしい人かをよく調べ、そこを立ち去るまで、その人のところにとどまりなさい。'),
('JPN', '马太福音', 40, 10, 12, 'その家に入るときには、平安を祈るあいさつをしなさい。'),
('JPN', '马太福音', 40, 10, 13, 'その家がそれにふさわしければ、あなたがたの祈る平安がその家に来るようにし、ふさわしくなければ、その平安があなたがたのところに返って来るようにしなさい。'),
('JPN', '马太福音', 40, 10, 14, 'だれかがあなたがたを受け入れず、あなたがたのことばに耳を傾けないなら、その家や町を出て行くときに足のちりを払い落としなさい。'),
('JPN', '马太福音', 40, 10, 15, 'まことに、あなたがたに言います。さばきの日には、ソドムとゴモラの地のほうが、その町よりもさばきに耐えやすいのです。'),
('JPN', '马太福音', 40, 10, 16, 'いいですか。わたしは狼の中に羊を送り出すようにして、あなたがたを遣わします。ですから、蛇のように賢く、鳩のように素直でありなさい。'),
('JPN', '马太福音', 40, 10, 17, '人々には用心しなさい。彼らはあなたがたを地方法院に引き渡し、会堂でむち打ちます。'),
('JPN', '马太福音', 40, 10, 18, 'また、あなたがたは、わたしのために総督たちや王たちの前に連れて行かれ、彼らと異邦人に証しをすることになります。'),
('JPN', '马太福音', 40, 10, 19, '人々があなたがたを引き渡したとき、何をどう話そうかと心配しなくてもよいのです。話すことは、そのとき与えられるからです。'),
('JPN', '马太福音', 40, 10, 20, '話すのはあなたがたではなく、あなたがたのうちにあって話される、あなたがたの父の御霊です。'),
('JPN', '马太福音', 40, 10, 21, '兄弟は兄弟を、父は子を死に渡し、子どもたちは両親に逆らって立ち、死に至らせます。'),
('JPN', '马太福音', 40, 10, 22, 'また、わたしの名のために、あなたがたはすべての人に憎まれます。しかし、最後まで耐え忍ぶ人は救われます。'),
('JPN', '马太福音', 40, 10, 23, '一つの町で人々があなたがたを迫害するなら、別の町へ逃げなさい。まことに、あなたがたに言います。人の子が来るときまでに、あなたがたがイスラエルの町々を巡り終えることは、決してありません。'),
('JPN', '马太福音', 40, 10, 24, '弟子は師以上の者ではなく、しもべも主人以上の者ではありません。'),
('JPN', '马太福音', 40, 10, 25, '弟子は師のように、しもべは主人のようになれば十分です。家の主人がベルゼブルと呼ばれるくらいなら、ましてその家の者たちは、どれほどひどい呼び方をされるでしょうか。'),
('JPN', '马太福音', 40, 10, 26, 'ですから彼らを恐れてはいけません。おおわれているもので現されないものはなく、隠されているもので知られずにすむものはないからです。'),
('JPN', '马太福音', 40, 10, 27, 'わたしが暗闇であなたがたに言うことを、明るみで言いなさい。あなたがたが耳もとで聞いたことを、屋上で言い広めなさい。'),
('JPN', '马太福音', 40, 10, 28, 'からだを殺しても、たましいを殺せない者たちを恐れてはいけません。むしろ、たましいもからだもゲヘナで滅ぼすことができる方を恐れなさい。'),
('JPN', '马太福音', 40, 10, 29, '二羽の雀は一アサリオンで売られているではありませんか。そんな雀の一羽でさえ、あなたがたの父の許しなしに地に落ちることはありません。'),
('JPN', '马太福音', 40, 10, 30, 'あなたがたの髪の毛さえも、すべて数えられています。'),
('JPN', '马太福音', 40, 10, 31, 'ですから恐れてはいけません。あなたがたは多くの雀よりも価値があるのです。'),
('JPN', '马太福音', 40, 10, 32, 'ですから、だれでも人々の前でわたしを認めるなら、わたしも、天におられるわたしの父の前でその人を認めます。'),
('JPN', '马太福音', 40, 10, 33, 'しかし、人々の前でわたしを知らないと言う者は、わたしも、天におられるわたしの父の前で、その人を知らないと言います。'),
('JPN', '马太福音', 40, 10, 34, 'わたしが来たのは地上に平和をもたらすためだ、と思ってはいけません。わたしは、平和ではなく剣をもたらすために来ました。'),
('JPN', '马太福音', 40, 10, 35, 'わたしは、人をその父に、娘をその母に、嫁をその姑に逆らわせるために来たのです。'),
('JPN', '马太福音', 40, 10, 36, 'そのようにして家の者たちがその人の敵となるのです。'),
('JPN', '马太福音', 40, 10, 37, 'わたしよりも父や母を愛する者は、わたしにふさわしい者ではありません。わたしよりも息子や娘を愛する者は、わたしにふさわしい者ではありません。'),
('JPN', '马太福音', 40, 10, 38, '自分の十字架を負ってわたしに従って来ない者は、わたしにふさわしい者ではありません。'),
('JPN', '马太福音', 40, 10, 39, '自分のいのちを得る者はそれを失い、わたしのために自分のいのちを失う者は、それを得るのです。'),
('JPN', '马太福音', 40, 10, 40, 'あなたがたを受け入れる人は、わたしを受け入れるのです。また、わたしを受け入れる人は、わたしを遣わされた方を受け入れるのです。'),
('JPN', '马太福音', 40, 10, 41, '預言者を預言者だからということで受け入れる人は、預言者の受ける報いを受けます。また、義人を義人だからということで受け入れる人は、義人の受ける報いを受けます。'),
('JPN', '马太福音', 40, 10, 42, 'まことに、あなたがたに言います。わたしの弟子だからということで、この小さい者たちの一人に一杯の冷たい水でも飲ませる人は、決して報いを失うことがありません。」'),
('JPN', '马太福音', 40, 11, 1, 'イエスは十二弟子に対する指示を終えると、町々で教え、宣べ伝えるために、そこを立ち去られた。'),
('JPN', '马太福音', 40, 11, 2, 'さて、牢獄でキリストのみわざについて聞いたヨハネは、自分の弟子たちを通じて'),
('JPN', '马太福音', 40, 11, 3, 'イエスにこう言い送った。「おいでになるはずの方はあなたですか。それとも、別の方を待つべきでしょうか。」'),
('JPN', '马太福音', 40, 11, 4, 'イエスは彼らに答えられた。「あなたがたは行って、自分たちが見たり聞いたりしていることをヨハネに伝えなさい。'),
('JPN', '马太福音', 40, 11, 5, '目の見えない者たちが見、足の不自由な者たちが歩き、ツァラアトに冒された者たちがきよめられ、耳の聞こえない者たちが聞き、死人たちが生き返り、貧しい者たちに福音が伝えられています。'),
('JPN', '马太福音', 40, 11, 6, 'だれでも、わたしにつまずかない者は幸いです。」'),
('JPN', '马太福音', 40, 11, 7, 'この人たちが行ってしまうと、イエスはヨハネについて群衆に話し始められた。「あなたがたは何を見に荒野に出て行ったのですか。風に揺れる葦ですか。'),
('JPN', '马太福音', 40, 11, 8, 'そうでなければ、何を見に行ったのですか。柔らかな衣をまとった人ですか。ご覧なさい。柔らかな衣を着た人なら王の宮殿にいます。'),
('JPN', '马太福音', 40, 11, 9, 'そうでなければ、何を見に行ったのですか。預言者ですか。そうです。わたしはあなたがたに言います。預言者よりもすぐれた者を見に行ったのです。'),
('JPN', '马太福音', 40, 11, 10, 'この人こそ、『見よ、わたしはわたしの使いをあなたの前に遣わす。彼は、あなたの前にあなたの道を備える』と書かれているその人です。'),
('JPN', '马太福音', 40, 11, 11, 'まことに、あなたがたに言います。女から生まれた者の中で、バプテスマのヨハネより偉大な者は現れませんでした。しかし、天の御国で一番小さい者でさえ、彼より偉大です。'),
('JPN', '马太福音', 40, 11, 12, 'バプテスマのヨハネの日から今に至るまで、天の御国は激しく攻められています。そして、激しく攻める者たちがそれを奪い取っています。'),
('JPN', '马太福音', 40, 11, 13, 'すべての預言者たちと律法が預言したのは、ヨハネの時まででした。'),
('JPN', '马太福音', 40, 11, 14, 'あなたがたに受け入れる思いがあるなら、この人こそ来たるべきエリヤなのです。'),
('JPN', '马太福音', 40, 11, 15, '耳のある者は聞きなさい。'),
('JPN', '马太福音', 40, 11, 16, 'この時代は何にたとえたらよいでしょうか。広場に座って、ほかの子どもたちにこう呼びかけている子どもたちのようです。'),
('JPN', '马太福音', 40, 11, 17, '『笛を吹いてあげたのに君たちは踊らなかった。弔いの歌を歌ってあげたのに胸をたたいて悲しまなかった。』'),
('JPN', '马太福音', 40, 11, 18, 'ヨハネが来て、食べもせず飲みもしないでいると、『この人は悪霊につかれている』と人々は言い、'),
('JPN', '马太福音', 40, 11, 19, '人の子が来て食べたり飲んだりしていると、『見ろ、大食いの大酒飲み、取税人や罪人の仲間だ』と言うのです。しかし、知恵が正しいことはその行いが証明します。」'),
('JPN', '马太福音', 40, 11, 20, 'それからイエスは、ご自分が力あるわざを数多く行った町々を責め始められた。彼らが悔い改めなかったからである。'),
('JPN', '马太福音', 40, 11, 21, '「ああ、コラジン。ああ、ベツサイダ。おまえたちの間で行われた力あるわざが、ツロとシドンで行われていたら、彼らはとうの昔に粗布をまとい、灰をかぶって悔い改めていたことだろう。'),
('JPN', '马太福音', 40, 11, 22, 'おまえたちに言う。さばきの日には、ツロとシドンのほうが、おまえたちよりもさばきに耐えやすいのだ。'),
('JPN', '马太福音', 40, 11, 23, 'カペナウム、おまえが天に上げられることがあるだろうか。よみにまで落とされるのだ。おまえのうちで行われた力あるわざがソドムで行われていたら、ソドムは今日まで残っていたことだろう。'),
('JPN', '马太福音', 40, 11, 24, 'おまえたちに言う。さばきの日には、ソドムの地のほうが、おまえよりもさばきに耐えやすいのだ。」'),
('JPN', '马太福音', 40, 11, 25, 'そのとき、イエスはこう言われた。「天地の主であられる父よ、あなたをほめたたえます。あなたはこれらのことを、知恵ある者や賢い者には隠して、幼子たちに現してくださいました。'),
('JPN', '马太福音', 40, 11, 26, 'そうです、父よ、これはみこころにかなったことでした。'),
('JPN', '马太福音', 40, 11, 27, 'すべてのことが、わたしの父からわたしに渡されています。父のほかに子を知っている者はなく、子と、子が父を現そうと心に定めた者のほかに、父を知っている者はだれもいません。'),
('JPN', '马太福音', 40, 11, 28, 'すべて疲れた人、重荷を負っている人はわたしのもとに来なさい。わたしがあなたがたを休ませてあげます。'),
('JPN', '马太福音', 40, 11, 29, 'わたしは心が柔和でへりくだっているから、あなたがたもわたしのくびきを負って、わたしから学びなさい。そうすれば、たましいに安らぎを得ます。'),
('JPN', '马太福音', 40, 11, 30, 'わたしのくびきは負いやすく、わたしの荷は軽いからです。」'),
('JPN', '马太福音', 40, 12, 1, 'そのころ、イエスは安息日に麦畑を通られた。弟子たちは空腹だったので、穂を摘んで食べ始めた。'),
('JPN', '马太福音', 40, 12, 2, 'するとパリサイ人たちがそれを見て、イエスに言った。「ご覧なさい。あなたの弟子たちが、安息日にしてはならないことをしています。」'),
('JPN', '马太福音', 40, 12, 3, 'しかし、イエスは言われた。「ダビデと供の者たちが空腹になったときに、ダビデが何をしたか、'),
('JPN', '马太福音', 40, 12, 4, 'どのようにして、神の家に入り、祭司以外は自分も供の者たちも食べてはならない、臨在のパンを食べたか、読んだことがないのですか。'),
('JPN', '马太福音', 40, 12, 5, 'また、安息日に宮にいる祭司たちは安息日を汚しても咎を免れる、ということを律法で読んだことがないのですか。'),
('JPN', '马太福音', 40, 12, 6, 'あなたがたに言いますが、ここに宮よりも大いなるものがあります。'),
('JPN', '马太福音', 40, 12, 7, '『わたしが喜びとするのは真実の愛。いけにえではない』とはどういう意味かを知っていたら、あなたがたは、咎のない者たちを不義に定めはしなかったでしょう。'),
('JPN', '马太福音', 40, 12, 8, '人の子は安息日の主です。」'),
('JPN', '马太福音', 40, 12, 9, 'イエスはそこを去って、彼らの会堂に入られた。'),
('JPN', '马太福音', 40, 12, 10, 'すると見よ、片手の萎えた人がいた。そこで彼らはイエスに「安息日に癒やすのは律法にかなっていますか」と質問した。イエスを訴えるためであった。'),
('JPN', '马太福音', 40, 12, 11, 'イエスは彼らに言われた。「あなたがたのうちのだれかが羊を一匹持っていて、もしその羊が安息日に穴に落ちたら、それをつかんで引き上げてやらないでしょうか。'),
('JPN', '马太福音', 40, 12, 12, '人間は羊よりはるかに価値があります。それなら、安息日に良いことをするのは律法にかなっています。」'),
('JPN', '马太福音', 40, 12, 13, 'それからイエスはその人に「手を伸ばしなさい」と言われた。彼が手を伸ばすと、手は元どおりになり、もう一方の手のように良くなった。'),
('JPN', '马太福音', 40, 12, 14, 'パリサイ人たちは出て行って、どうやってイエスを殺そうかと相談し始めた。'),
('JPN', '马太福音', 40, 12, 15, 'イエスはそれを知って、そこを立ち去られた。すると大勢の群衆がついて来たので、彼らをみな癒やされた。'),
('JPN', '马太福音', 40, 12, 16, 'そして、ご自分のことを人々に知らせないように、彼らを戒められた。'),
('JPN', '马太福音', 40, 12, 17, 'これは、預言者イザヤを通して語られたことが成就するためであった。'),
('JPN', '马太福音', 40, 12, 18, '「見よ。わたしが選んだわたしのしもべ、わたしの心が喜ぶ、わたしの愛する者。わたしは彼の上にわたしの霊を授け、彼は異邦人にさばきを告げる。'),
('JPN', '马太福音', 40, 12, 19, '彼は言い争わず、叫ばず、通りでその声を聞く者もない。'),
('JPN', '马太福音', 40, 12, 20, '傷んだ葦を折ることもなく、くすぶる灯芯を消すこともない。さばきを勝利に導くまで。'),
('JPN', '马太福音', 40, 12, 21, '異邦人は彼の名に望みをかける。」'),
('JPN', '马太福音', 40, 12, 22, 'そのとき、悪霊につかれて目が見えず、口もきけない人が連れて来られた。イエスが癒やされたので、その人はものを言い、目も見えるようになった。'),
('JPN', '马太福音', 40, 12, 23, '群衆はみな驚いて言った。「もしかすると、この人がダビデの子なのではないだろうか。」'),
('JPN', '马太福音', 40, 12, 24, 'これを聞いたパリサイ人たちは言った。「この人が悪霊どもを追い出しているのは、ただ悪霊どものかしらベルゼブルによることだ。」'),
('JPN', '马太福音', 40, 12, 25, 'イエスは彼らの思いを知って言われた。「どんな国でも分裂して争えば荒れすたれ、どんな町でも家でも分裂して争えば立ち行きません。'),
('JPN', '马太福音', 40, 12, 26, 'もし、サタンがサタンを追い出しているのなら、仲間割れしたことになります。それなら、どのようにしてその国は立ち行くのですか。'),
('JPN', '马太福音', 40, 12, 27, 'また、もしわたしが、ベルゼブルによって悪霊どもを追い出しているとしたら、あなたがたの子らが追い出しているのは、だれによってなのですか。そういうわけで、あなたがたの子らが、あなたがたをさばく者となります。'),
('JPN', '马太福音', 40, 12, 28, 'しかし、わたしが神の御霊によって悪霊どもを追い出しているのなら、もう神の国はあなたがたのところに来ているのです。'),
('JPN', '马太福音', 40, 12, 29, 'まず強い者を縛り上げるのでなければ、強い者の家に入って家財を奪い取ることが、どうしてできるでしょうか。縛り上げれば、その家を略奪できます。'),
('JPN', '马太福音', 40, 12, 30, 'わたしに味方しない者はわたしに敵対し、わたしとともに集めない者は散らしているのです。'),
('JPN', '马太福音', 40, 12, 31, 'ですから、わたしはあなたがたに言います。人はどんな罪も冒瀆も赦していただけますが、御霊に対する冒瀆は赦されません。'),
('JPN', '马太福音', 40, 12, 32, 'また、人の子に逆らうことばを口にする者でも赦されます。しかし、聖霊に逆らうことを言う者は、この世でも次に来る世でも赦されません。'),
('JPN', '马太福音', 40, 12, 33, '木を良いとし、その実も良いとするか、木を悪いとし、その実も悪いとするか、どちらかです。木の良し悪しはその実によって分かります。'),
('JPN', '马太福音', 40, 12, 34, 'まむしの子孫たち、おまえたち悪い者に、どうして良いことが言えますか。心に満ちていることを口が話すのです。'),
('JPN', '马太福音', 40, 12, 35, '良い人は良い倉から良い物を取り出し、悪い者は悪い倉から悪い物を取り出します。'),
('JPN', '马太福音', 40, 12, 36, 'わたしはあなたがたに言います。人は、口にするあらゆる無益なことばについて、さばきの日に申し開きをしなければなりません。'),
('JPN', '马太福音', 40, 12, 37, 'あなたは自分のことばによって義とされ、また、自分のことばによって不義に定められるのです。」'),
('JPN', '马太福音', 40, 12, 38, 'そのとき、律法学者、パリサイ人のうちの何人かがイエスに「先生、あなたからしるしを見せていただきたい」と言った。'),
('JPN', '马太福音', 40, 12, 39, 'しかし、イエスは答えられた。「悪い、姦淫の時代はしるしを求めますが、しるしは与えられません。ただし預言者ヨナのしるしは別です。'),
('JPN', '马太福音', 40, 12, 40, 'ヨナが三日三晩、大魚の腹の中にいたように、人の子も三日三晩、地の中にいるからです。'),
('JPN', '马太福音', 40, 12, 41, 'ニネベの人々が、さばきのときにこの時代の人々とともに立って、この時代の人々を罪ありとします。ニネベの人々はヨナの説教で悔い改めたからです。しかし見なさい。ここにヨナにまさるものがあります。'),
('JPN', '马太福音', 40, 12, 42, '南の女王が、さばきのときにこの時代の人々とともに立って、この時代の人々を罪ありとします。彼女はソロモンの知恵を聞くために地の果てから来たからです。しかし見なさい。ここにソロモンにまさるものがあります。'),
('JPN', '马太福音', 40, 12, 43, '汚れた霊は人から出て行くと、水のない地をさまよって休み場を探します。でも見つからず、'),
('JPN', '马太福音', 40, 12, 44, '『出て来た自分の家に帰ろう』と言います。帰って見ると、家は空いていて、掃除されてきちんと片付いています。'),
('JPN', '马太福音', 40, 12, 45, 'そこで出かけて行って、自分よりも悪い、七つのほかの霊を連れて来て、入り込んでそこに住みつきます。そうなると、その人の最後の状態は初めよりも悪くなるのです。この悪い時代にも、そのようなことが起こります。」'),
('JPN', '马太福音', 40, 12, 46, 'イエスがまだ群衆に話しておられるとき、見よ、イエスの母と兄弟たちがイエスに話をしようとして、外に立っていた。'),
('JPN', '马太福音', 40, 12, 47, 'ある人がイエスに「ご覧ください。母上と兄弟方が、お話ししようと外に立っておられます」と言った。'),
('JPN', '马太福音', 40, 12, 48, 'イエスはそう言っている人に答えて、「わたしの母とはだれでしょうか。わたしの兄弟たちとはだれでしょうか」と言われた。'),
('JPN', '马太福音', 40, 12, 49, 'それから、イエスは弟子たちの方に手を伸ばして言われた。「見なさい。わたしの母、わたしの兄弟たちです。'),
('JPN', '马太福音', 40, 12, 50, 'だれでも天におられるわたしの父のみこころを行うなら、その人こそわたしの兄弟、姉妹、母なのです。」'),
('JPN', '马太福音', 40, 13, 1, 'その日、イエスは家を出て、湖のほとりに座っておられた。'),
('JPN', '马太福音', 40, 13, 2, 'すると大勢の群衆がみもとに集まって来たので、イエスは舟に乗って腰を下ろされた。群衆はみな岸辺に立っていた。'),
('JPN', '马太福音', 40, 13, 3, 'イエスは彼らに、多くのことをたとえで語られた。「見よ。種を蒔く人が種蒔きに出かけた。'),
('JPN', '马太福音', 40, 13, 4, '蒔いていると、種がいくつか道端に落ちた。すると鳥が来て食べてしまった。'),
('JPN', '马太福音', 40, 13, 5, 'また、別の種は土の薄い岩地に落ちた。土が深くなかったので、すぐに芽を出した。'),
('JPN', '马太福音', 40, 13, 6, 'しかし、日が昇ると焼けて、根がないために枯れてしまった。'),
('JPN', '马太福音', 40, 13, 7, 'また、別の種は茨の間に落ちたが、茨が伸びてふさいでしまった。'),
('JPN', '马太福音', 40, 13, 8, 'また、別の種は良い地に落ちて実を結び、あるものは百倍、あるものは六十倍、あるものは三十倍になった。'),
('JPN', '马太福音', 40, 13, 9, '耳のある者は聞きなさい。」'),
('JPN', '马太福音', 40, 13, 10, 'すると、弟子たちが近寄って来て、イエスに「なぜ、彼らにたとえでお話しになるのですか」と言った。'),
('JPN', '马太福音', 40, 13, 11, 'イエスは答えられた。「あなたがたには天の御国の奥義を知ることが許されていますが、あの人たちには許されていません。'),
('JPN', '马太福音', 40, 13, 12, '持っている人は与えられてもっと豊かになり、持っていない人は持っているものまで取り上げられるのです。'),
('JPN', '马太福音', 40, 13, 13, 'わたしが彼らにたとえで話すのは、彼らが見てはいるが見ず、聞いてはいるが聞かず、悟ることもしないからです。'),
('JPN', '马太福音', 40, 13, 14, 'こうしてイザヤの告げた預言が、彼らにおいて実現したのです。『あなたがたは聞くには聞くが、決して悟ることはない。見るには見るが、決して知ることはない。'),
('JPN', '马太福音', 40, 13, 15, 'この民の心は鈍くなり、耳は遠くなり、目は閉じているからである。彼らがその目で見ることも、耳で聞くことも、心で悟ることも、立ち返ることもないように。そして、わたしが癒やすこともないように。』'),
('JPN', '马太福音', 40, 13, 16, 'しかし、あなたがたの目は見ているから幸いです。また、あなたがたの耳は聞いているから幸いです。'),
('JPN', '马太福音', 40, 13, 17, 'まことに、あなたがたに言います。多くの預言者や義人たちが、あなたがたが見ているものを見たいと切に願ったのに、見られず、あなたがたが聞いていることを聞きたいと切に願ったのに、聞けませんでした。'),
('JPN', '马太福音', 40, 13, 18, 'ですから、種を蒔く人のたとえを聞きなさい。'),
('JPN', '马太福音', 40, 13, 19, 'だれでも御国のことばを聞いて悟らないと、悪い者が来て、その人の心に蒔かれたものを奪います。道端に蒔かれたものとは、このような人のことです。'),
('JPN', '马太福音', 40, 13, 20, 'また岩地に蒔かれたものとは、みことばを聞くと、すぐに喜んで受け入れる人のことです。'),
('JPN', '马太福音', 40, 13, 21, 'しかし自分の中に根がなく、しばらく続くだけで、みことばのために困難や迫害が起こると、すぐにつまずいてしまいます。'),
('JPN', '马太福音', 40, 13, 22, '茨の中に蒔かれたものとは、みことばを聞くが、この世の思い煩いと富の誘惑がみことばをふさぐため、実を結ばない人のことです。'),
('JPN', '马太福音', 40, 13, 23, '良い地に蒔かれたものとは、みことばを聞いて悟る人のことです。本当に実を結び、あるものは百倍、あるものは六十倍、あるものは三十倍の実を結びます。」'),
('JPN', '马太福音', 40, 13, 24, 'イエスは、また別のたとえを彼らに示して言われた。「天の御国は次のようにたとえられます。ある人が自分の畑に良い種を蒔いた。'),
('JPN', '马太福音', 40, 13, 25, 'ところが人々が眠っている間に敵が来て、麦の中に毒麦を蒔いて立ち去った。'),
('JPN', '马太福音', 40, 13, 26, '麦が芽を出し実ったとき、毒麦も現れた。'),
('JPN', '马太福音', 40, 13, 27, 'それで、しもべたちが主人のところに来て言った。『ご主人様、畑には良い麦を蒔かれたのではなかったでしょうか。どうして毒麦が生えたのでしょう。』'),
('JPN', '马太福音', 40, 13, 28, '主人は言った。『敵がしたことだ。』すると、しもべたちは言った。『それでは、私たちが行って毒麦を抜き集めましょうか。』'),
('JPN', '马太福音', 40, 13, 29, 'しかし、主人は言った。『いや。毒麦を抜き集めるうちに麦も一緒に抜き取るかもしれない。'),
('JPN', '马太福音', 40, 13, 30, 'だから、収穫まで両方とも育つままにしておきなさい。収穫の時に、私は刈る者たちに、まず毒麦を集めて焼くために束にし、麦のほうは集めて私の倉に納めなさい、と言おう。』」'),
('JPN', '马太福音', 40, 13, 31, 'イエスはまた、別のたとえを彼らに示して言われた。「天の御国はからし種に似ています。人はそれを取って畑に蒔きます。'),
('JPN', '马太福音', 40, 13, 32, 'どんな種よりも小さいのですが、生長すると、どの野菜よりも大きくなって木となり、空の鳥が来て、その枝に巣を作るようになります。」'),
('JPN', '马太福音', 40, 13, 33, 'イエスはまた、別のたとえを彼らに話された。「天の御国はパン種に似ています。女の人がそれを取って三サトンの小麦粉の中に混ぜると、全体がふくらみます。」'),
('JPN', '马太福音', 40, 13, 34, 'イエスは、これらのことをみな、たとえで群衆に話された。たとえを使わずには何も話されなかった。'),
('JPN', '马太福音', 40, 13, 35, 'それは、預言者を通して語られたことが、成就するためであった。「私は口を開いて、たとえ話を、世界の基が据えられたときから隠されていることを語ろう。」'),
('JPN', '马太福音', 40, 13, 36, 'それから、イエスは群衆を解散させて家に入られた。すると弟子たちがみもとに来て、「畑の毒麦のたとえを説明してください」と言った。'),
('JPN', '马太福音', 40, 13, 37, 'イエスは答えられた。「良い種を蒔く人は人の子です。'),
('JPN', '马太福音', 40, 13, 38, '畑は世界で、良い種は御国の子ら、毒麦は悪い者の子らです。'),
('JPN', '马太福音', 40, 13, 39, '毒麦を蒔いた敵は悪魔であり、収穫は世の終わり、刈る者は御使いたちです。'),
('JPN', '马太福音', 40, 13, 40, 'ですから、毒麦が集められて火で焼かれるように、世の終わりにもそのようになります。'),
('JPN', '马太福音', 40, 13, 41, '人の子は御使いたちを遣わします。彼らは、すべてのつまずきと、不法を行う者たちを御国から取り集めて、'),
('JPN', '马太福音', 40, 13, 42, '火の燃える炉の中に投げ込みます。彼らはそこで泣いて歯ぎしりするのです。'),
('JPN', '马太福音', 40, 13, 43, 'そのとき、正しい人たちは彼らの父の御国で太陽のように輝きます。耳のある者は聞きなさい。'),
('JPN', '马太福音', 40, 13, 44, '天の御国は畑に隠された宝のようなものです。その宝を見つけた人は、それをそのまま隠しておきます。そして喜びのあまり、行って、持っている物すべてを売り払い、その畑を買います。'),
('JPN', '马太福音', 40, 13, 45, '天の御国はまた、良い真珠を探している商人のようなものです。'),
('JPN', '马太福音', 40, 13, 46, '高価な真珠を一つ見つけた商人は、行って、持っていた物すべてを売り払い、それを買います。'),
('JPN', '马太福音', 40, 13, 47, 'また、天の御国は、海に投げ入れてあらゆる種類の魚を集める網のようなものです。'),
('JPN', '马太福音', 40, 13, 48, '網がいっぱいになると、人々はそれを岸に引き上げ、座って、良いものは入れ物に入れ、悪いものは外に投げ捨てます。'),
('JPN', '马太福音', 40, 13, 49, 'この世の終わりにもそのようになります。御使いたちが来て、正しい者たちの中から悪い者どもをより分け、'),
('JPN', '马太福音', 40, 13, 50, '火の燃える炉に投げ込みます。彼らはそこで泣いて歯ぎしりするのです。'),
('JPN', '马太福音', 40, 13, 51, 'あなたがたは、これらのことがみな分かりましたか。」彼らは「はい」と言った。'),
('JPN', '马太福音', 40, 13, 52, 'そこでイエスは言われた。「こういうわけで、天の御国の弟子となった学者はみな、自分の倉から新しい物と古い物を取り出す、一家の主人のようです。」'),
('JPN', '马太福音', 40, 13, 53, 'イエスはこれらのたとえを話し終えると、そこを立ち去り、'),
('JPN', '马太福音', 40, 13, 54, 'ご自分の郷里に行って、会堂で人々を教え始められた。すると、彼らは驚いて言った。「この人は、こんな知恵と奇跡を行う力をどこから得たのだろう。'),
('JPN', '马太福音', 40, 13, 55, 'この人は大工の息子ではないか。母はマリアといい、弟たちはヤコブ、ヨセフ、シモン、ユダではないか。'),
('JPN', '马太福音', 40, 13, 56, '妹たちもみな私たちと一緒にいるではないか。それなら、この人はこれらのものをみな、どこから得たのだろう。」'),
('JPN', '马太福音', 40, 13, 57, 'こうして彼らはイエスにつまずいた。しかし、イエスは彼らに言われた。「預言者が敬われないのは、自分の郷里、家族の間だけです。」'),
('JPN', '马太福音', 40, 13, 58, 'そして彼らの不信仰のゆえに、そこでは多くの奇跡をなさらなかった。'),
('JPN', '马太福音', 40, 14, 1, 'そのころ、領主ヘロデはイエスのうわさを聞いて、'),
('JPN', '马太福音', 40, 14, 2, '家来たちに言った。「あれはバプテスマのヨハネだ。彼が死人の中からよみがえったのだ。だから、奇跡を行う力が彼のうちに働いているのだ。」'),
('JPN', '马太福音', 40, 14, 3, '実は、以前このヘロデは、自分の兄弟ピリポの妻ヘロディアのことでヨハネを捕らえて縛り、牢に入れていた。'),
('JPN', '马太福音', 40, 14, 4, 'ヨハネが彼に、「あなたが彼女を自分のものにすることは律法にかなっていない」と言い続けたからであった。'),
('JPN', '马太福音', 40, 14, 5, 'ヘロデはヨハネを殺したいと思ったが、民衆を恐れた。彼らがヨハネを預言者と認めていたからであった。'),
('JPN', '马太福音', 40, 14, 6, 'ところが、ヘロデの誕生祝いがあり、ヘロディアの娘が皆の前で踊りを踊ってヘロデを喜ばせた。'),
('JPN', '马太福音', 40, 14, 7, 'それで彼は娘に誓い、求める物は何でも与えると約束した。'),
('JPN', '马太福音', 40, 14, 8, 'すると、娘は母親にそそのかされて、「今ここで、バプテスマのヨハネの首を盆に載せて私に下さい」と言った。'),
('JPN', '马太福音', 40, 14, 9, '王は心を痛めたが、自分が誓ったことであり、列席の人たちの手前もあって、与えるように命じ、'),
('JPN', '马太福音', 40, 14, 10, '人を遣わして、牢の中でヨハネの首をはねさせた。'),
('JPN', '马太福音', 40, 14, 11, 'その首は盆に載せて運ばれ、少女に与えられたので、少女はそれを母親のところに持って行った。'),
('JPN', '马太福音', 40, 14, 12, 'それから、ヨハネの弟子たちがやって来て遺体を引き取り、葬った。そして、イエスのところに行って報告した。'),
('JPN', '马太福音', 40, 14, 13, 'それを聞くと、イエスは舟でそこを去り、自分だけで寂しいところに行かれた。群衆はそれを聞き、町々から歩いてイエスの後を追った。'),
('JPN', '马太福音', 40, 14, 14, 'イエスは舟から上がり、大勢の群衆をご覧になった。そして彼らを深くあわれんで、彼らの中の病人たちを癒やされた。'),
('JPN', '马太福音', 40, 14, 15, '夕方になったので、弟子たちはイエスのところに来て言った。「ここは人里離れたところですし、時刻ももう遅くなっています。村に行って自分たちで食べ物を買うことができるように、群衆を解散させてください。」'),
('JPN', '马太福音', 40, 14, 16, 'しかし、イエスは言われた。「彼らが行く必要はありません。あなたがたがあの人たちに食べる物をあげなさい。」'),
('JPN', '马太福音', 40, 14, 17, '弟子たちは言った。「ここには五つのパンと二匹の魚しかありません。」'),
('JPN', '马太福音', 40, 14, 18, 'するとイエスは「それを、ここに持って来なさい」と言われた。'),
('JPN', '马太福音', 40, 14, 19, 'そして、群衆に草の上に座るように命じられた。それからイエスは、五つのパンと二匹の魚を取り、天を見上げて神をほめたたえ、パンを裂いて弟子たちにお与えになったので、弟子たちは群衆に配った。'),
('JPN', '马太福音', 40, 14, 20, '人々はみな、食べて満腹した。そして余ったパン切れを集めると、十二のかごがいっぱいになった。'),
('JPN', '马太福音', 40, 14, 21, '食べた者は、女と子どもを除いて男五千人ほどであった。'),
('JPN', '马太福音', 40, 14, 22, 'それからすぐに、イエスは弟子たちを舟に乗り込ませて、自分より先に向こう岸に向かわせ、その間に群衆を解散させられた。'),
('JPN', '马太福音', 40, 14, 23, '群衆を解散させてから、イエスは祈るために一人で山に登られた。夕方になっても一人でそこにおられた。'),
('JPN', '马太福音', 40, 14, 24, '舟はすでに陸から何スタディオンも離れていて、向かい風だったので波に悩まされていた。'),
('JPN', '马太福音', 40, 14, 25, '夜明けが近づいたころ、イエスは湖の上を歩いて弟子たちのところに来られた。'),
('JPN', '马太福音', 40, 14, 26, 'イエスが湖の上を歩いておられるのを見た弟子たちは「あれは幽霊だ」と言っておびえ、恐ろしさのあまり叫んだ。'),
('JPN', '马太福音', 40, 14, 27, 'イエスはすぐに彼らに話しかけ、「しっかりしなさい。わたしだ。恐れることはない」と言われた。'),
('JPN', '马太福音', 40, 14, 28, 'するとペテロが答えて、「主よ。あなたでしたら、私に命じて、水の上を歩いてあなたのところに行かせてください」と言った。'),
('JPN', '马太福音', 40, 14, 29, 'イエスは「来なさい」と言われた。そこでペテロは舟から出て、水の上を歩いてイエスの方に行った。'),
('JPN', '马太福音', 40, 14, 30, 'ところが強風を見て怖くなり、沈みかけたので、「主よ、助けてください」と叫んだ。'),
('JPN', '马太福音', 40, 14, 31, 'イエスはすぐに手を伸ばし、彼をつかんで言われた。「信仰の薄い者よ、なぜ疑ったのか。」'),
('JPN', '马太福音', 40, 14, 32, 'そして二人が舟に乗り込むと、風はやんだ。'),
('JPN', '马太福音', 40, 14, 33, '舟の中にいた弟子たちは「まことに、あなたは神の子です」と言って、イエスを礼拝した。'),
('JPN', '马太福音', 40, 14, 34, 'それから彼らは湖を渡り、ゲネサレの地に着いた。'),
('JPN', '马太福音', 40, 14, 35, 'その地の人々はイエスだと気がついて、周辺の地域にくまなく知らせた。そこで人々は病人をみなイエスのもとに連れて来て、'),
('JPN', '马太福音', 40, 14, 36, 'せめて、衣の房にでもさわらせてやってください、とイエスに懇願した。そして、さわった人たちはみな癒やされた。'),
('JPN', '马太福音', 40, 15, 1, 'そのころ、パリサイ人たちや律法学者たちが、エルサレムからイエスのところに来て言った。'),
('JPN', '马太福音', 40, 15, 2, '「なぜ、あなたの弟子たちは長老たちの言い伝えを破るのですか。パンを食べるとき、手を洗っていません。」'),
('JPN', '马太福音', 40, 15, 3, 'そこでイエスは彼らに答えられた。「なぜ、あなたがたも、自分たちの言い伝えのために神の戒めを破るのですか。'),
('JPN', '马太福音', 40, 15, 4, '神は『父と母を敬え』、また『父や母をののしる者は、必ず殺されなければならない』と言われました。'),
('JPN', '马太福音', 40, 15, 5, 'それなのに、あなたがたは言っています。『だれでも父または母に向かって、私からあなたに差し上げるはずの物は神へのささげ物になります、と言う人は、'),
('JPN', '马太福音', 40, 15, 6, 'その物をもって父を敬ってはならない』と。こうしてあなたがたは、自分たちの言い伝えのために神のことばを無にしてしまいました。'),
('JPN', '马太福音', 40, 15, 7, '偽善者たちよ、イザヤはあなたがたについて見事に預言しています。'),
('JPN', '马太福音', 40, 15, 8, '『この民は口先でわたしを敬うが、その心はわたしから遠く離れている。'),
('JPN', '马太福音', 40, 15, 9, '彼らがわたしを礼拝しても、むなしい。人間の命令を、教えとして教えるのだから。』」'),
('JPN', '马太福音', 40, 15, 10, 'イエスは群衆を呼び寄せて言われた。「聞いて悟りなさい。'),
('JPN', '马太福音', 40, 15, 11, '口に入る物は人を汚しません。口から出るもの、それが人を汚すのです。」'),
('JPN', '马太福音', 40, 15, 12, 'そのとき、弟子たちが近寄って来てイエスに言った。「パリサイ人たちがおことばを聞いて腹を立てたのをご存じですか。」'),
('JPN', '马太福音', 40, 15, 13, 'イエスは答えられた。「わたしの天の父が植えなかった木は、すべて根こそぎにされます。'),
('JPN', '马太福音', 40, 15, 14, '彼らのことは放っておきなさい。彼らは盲人を案内する盲人です。もし盲人が盲人を案内すれば、二人とも穴に落ちます。」'),
('JPN', '马太福音', 40, 15, 15, 'そこでペテロがイエスに答えた。「私たちに、そのたとえを説明してください。」'),
('JPN', '马太福音', 40, 15, 16, 'イエスは言われた。「あなたがたも、まだ分からないのですか。'),
('JPN', '马太福音', 40, 15, 17, '口に入る物はみな、腹に入り、排泄されて外に出されることが分からないのですか。'),
('JPN', '马太福音', 40, 15, 18, 'しかし、口から出るものは心から出て来ます。それが人を汚すのです。'),
('JPN', '马太福音', 40, 15, 19, '悪い考え、殺人、姦淫、淫らな行い、盗み、偽証、ののしりは、心から出て来るからです。'),
('JPN', '马太福音', 40, 15, 20, 'これらのものが人を汚します。しかし、洗わない手で食べることは人を汚しません。」'),
('JPN', '马太福音', 40, 15, 21, 'イエスはそこを去ってツロとシドンの地方に退かれた。'),
('JPN', '马太福音', 40, 15, 22, 'すると見よ。その地方のカナン人の女が出て来て、「主よ、ダビデの子よ。私をあわれんでください。娘が悪霊につかれて、ひどく苦しんでいます」と言って叫び続けた。'),
('JPN', '马太福音', 40, 15, 23, 'しかし、イエスは彼女に一言もお答えにならなかった。弟子たちはみもとに来て、イエスに願った。「あの女を去らせてください。後について来て叫んでいます。」'),
('JPN', '马太福音', 40, 15, 24, 'イエスは答えられた。「わたしは、イスラエルの家の失われた羊たち以外のところには、遣わされていません。」'),
('JPN', '马太福音', 40, 15, 25, 'しかし彼女は来て、イエスの前にひれ伏して言った。「主よ、私をお助けください。」'),
('JPN', '马太福音', 40, 15, 26, 'すると、イエスは答えられた。「子どもたちのパンを取り上げて、小犬に投げてやるのは良くないことです。」'),
('JPN', '马太福音', 40, 15, 27, 'しかし、彼女は言った。「主よ、そのとおりです。ただ、小犬でも主人の食卓から落ちるパン屑はいただきます。」'),
('JPN', '马太福音', 40, 15, 28, 'そのとき、イエスは彼女に答えられた。「女の方、あなたの信仰は立派です。あなたが願うとおりになるように。」彼女の娘は、すぐに癒やされた。'),
('JPN', '马太福音', 40, 15, 29, 'それから、イエスはそこを去ってガリラヤ湖のほとりに行かれた。そして山に登り、そこに座っておられた。'),
('JPN', '马太福音', 40, 15, 30, 'すると大勢の群衆が、足の不自由な人たち、目の見えない人たち、手足の曲がった人たち、口のきけない人たち、そのほか多くの人をみもとに連れて来て、イエスの足もとに置いたので、イエスは彼らを癒やされた。'),
('JPN', '马太福音', 40, 15, 31, '群衆は、口のきけない人たちがものを言い、手足の曲がった人たちが治り、足の不自由な人たちが歩き、目の見えない人たちが見えるようになるのを見て驚いた。そしてイスラエルの神をあがめた。'),
('JPN', '马太福音', 40, 15, 32, 'イエスは弟子たちを呼んで言われた。「かわいそうに、この群衆はすでに三日間わたしとともにいて、食べる物を持っていないのです。空腹のまま帰らせたくはありません。途中で動けなくなるといけないから。」'),
('JPN', '马太福音', 40, 15, 33, '弟子たちは言った。「この人里離れたところで、こんなに大勢の人に十分食べさせるほどたくさんのパンを、どこで手に入れることができるでしょう。」'),
('JPN', '马太福音', 40, 15, 34, 'すると、イエスは彼らに言われた。「パンはいくつありますか。」彼らは言った。「七つです。それに、小さい魚が少しあります。」'),
('JPN', '马太福音', 40, 15, 35, 'そこで、イエスは群衆に地面に座るように命じられた。'),
('JPN', '马太福音', 40, 15, 36, 'そして七つのパンと魚を取り、感謝の祈りをささげてからそれを裂き、弟子たちにお与えになったので、弟子たちは群衆に配った。'),
('JPN', '马太福音', 40, 15, 37, '人々はみな、食べて満腹した。そして余ったパン切れを集めると、七つのかごがいっぱいになった。'),
('JPN', '马太福音', 40, 15, 38, '食べた者は、女と子どもを除いて男四千人であった。'),
('JPN', '马太福音', 40, 15, 39, 'それから、イエスは群衆を解散させて舟に乗り、マガダン地方に行かれた。'),
('JPN', '马太福音', 40, 16, 1, 'パリサイ人たちやサドカイ人たちが、イエスを試そうと近づいて来て、天からのしるしを見せてほしいと求めた。'),
('JPN', '马太福音', 40, 16, 2, 'イエスは彼らに答えられた。「夕方になると、あなたがたは『夕焼けだから晴れる』と言い、'),
('JPN', '马太福音', 40, 16, 3, '朝には『朝焼けでどんよりしているから、今日は荒れ模様だ』と言います。空模様を見分けることを知っていながら、時のしるしを見分けることはできないのですか。'),
('JPN', '马太福音', 40, 16, 4, '悪い、姦淫の時代はしるしを求めます。しかし、ヨナのしるしのほかには、しるしは与えられません。」こうしてイエスは彼らを残して去って行かれた。'),
('JPN', '马太福音', 40, 16, 5, 'さて、向こう岸に渡ったとき、弟子たちはパンを持って来るのを忘れてしまっていた。'),
('JPN', '马太福音', 40, 16, 6, 'イエスは彼らに言われた。「パリサイ人たちやサドカイ人たちのパン種に、くれぐれも用心しなさい。」'),
('JPN', '马太福音', 40, 16, 7, 'すると彼らは「私たちがパンを持って来なかったからだ」と言って、自分たちの間で議論を始めた。'),
('JPN', '马太福音', 40, 16, 8, 'イエスはそれに気がついて言われた。「信仰の薄い人たち。パンがないからだなどと、なぜ論じ合っているのですか。'),
('JPN', '马太福音', 40, 16, 9, 'まだ分からないのですか。五つのパンを五千人に分けて何かご集めたか、覚えていないのですか。'),
('JPN', '马太福音', 40, 16, 10, '七つのパンを四千人に分けて何かご集めたか、覚えていないのですか。'),
('JPN', '马太福音', 40, 16, 11, 'わたしが言ったのはパンのことではないと、どうして分からないのですか。パリサイ人たちとサドカイ人たちのパン種に用心しなさい。」'),
('JPN', '马太福音', 40, 16, 12, 'そのとき彼らは、用心するようにとイエスが言われたのはパン種ではなく、パリサイ人たちやサドカイ人たちの教えであることを悟った。'),
('JPN', '马太福音', 40, 16, 13, 'さて、ピリポ・カイサリアの地方に行かれたとき、イエスは弟子たちに「人々は人の子をだれだと言っていますか」とお尋ねになった。'),
('JPN', '马太福音', 40, 16, 14, '彼らは言った。「バプテスマのヨハネだと言う人たちも、エリヤだと言う人たちもいます。またほかの人たちはエレミヤだとか、預言者の一人だとか言っています。」'),
('JPN', '马太福音', 40, 16, 15, 'イエスは彼らに言われた。「あなたがたは、わたしをだれだと言いますか。」'),
('JPN', '马太福音', 40, 16, 16, 'シモン・ペテロが答えた。「あなたは生ける神の子キリストです。」'),
('JPN', '马太福音', 40, 16, 17, 'すると、イエスは彼に答えられた。「バルヨナ・シモン、あなたは幸いです。このことをあなたに明らかにしたのは血肉ではなく、天におられるわたしの父です。'),
('JPN', '马太福音', 40, 16, 18, 'そこで、わたしもあなたに言います。あなたはペテロです。わたしはこの岩の上に、わたしの教会を建てます。よみの門もそれに打ち勝つことはできません。'),
('JPN', '马太福音', 40, 16, 19, 'わたしはあなたに天の御国の鍵を与えます。あなたが地上でつなぐことは天においてもつながれ、あなたが地上で解くことは天においても解かれます。」'),
('JPN', '马太福音', 40, 16, 20, 'そのときイエスは弟子たちに、ご自分がキリストであることをだれにも言ってはならない、と命じられた。'),
('JPN', '马太福音', 40, 16, 21, 'そのときからイエスは、ご自分がエルサレムに行って、長老たち、祭司長たち、律法学者たちから多くの苦しみを受け、殺され、三日目によみがえらなければならないことを、弟子たちに示し始められた。'),
('JPN', '马太福音', 40, 16, 22, 'すると、ペテロはイエスをわきにお連れして、いさめ始めた。「主よ、とんでもないことです。そんなことがあなたに起こるはずがありません。」'),
('JPN', '马太福音', 40, 16, 23, 'しかし、イエスは振り向いてペテロに言われた。「下がれ、サタン。あなたは、わたしをつまずかせるものだ。あなたは神のことを思わないで、人のことを思っている。」'),
('JPN', '马太福音', 40, 16, 24, 'それからイエスは弟子たちに言われた。「だれでもわたしについて来たいと思うなら、自分を捨て、自分の十字架を負って、わたしに従って来なさい。'),
('JPN', '马太福音', 40, 16, 25, '自分のいのちを救おうと思う者はそれを失い、わたしのためにいのちを失う者はそれを見出すのです。'),
('JPN', '马太福音', 40, 16, 26, '人は、たとえ全世界を手に入れても、自分のいのちを失ったら何の益があるでしょうか。そのいのちを買い戻すのに、人は何を差し出せばよいのでしょうか。'),
('JPN', '马太福音', 40, 16, 27, '人の子は、やがて父の栄光を帯びて御使いたちとともに来ます。そしてそのときには、それぞれその行いに応じて報います。'),
('JPN', '马太福音', 40, 16, 28, 'まことに、あなたがたに言います。ここに立っている人たちの中には、人の子が御国とともに来るのを見るまで、決して死を味わわない人たちがいます。」'),
('JPN', '马太福音', 40, 17, 1, 'それから六日目に、イエスはペテロとヤコブとその兄弟ヨハネだけを連れて、高い山に登られた。'),
('JPN', '马太福音', 40, 17, 2, 'すると、弟子たちの目の前でその御姿が変わった。顔は太陽のように輝き、衣は光のように白くなった。'),
('JPN', '马太福音', 40, 17, 3, 'そして、見よ、モーセとエリヤが彼らの前に現れて、イエスと語り合っていた。'),
('JPN', '马太福音', 40, 17, 4, 'そこでペテロがイエスに言った。「主よ、私たちがここにいることはすばらしいことです。よろしければ、私がここに幕屋を三つ造ります。あなたのために一つ、モーセのために一つ、エリヤのために一つ。」'),
('JPN', '马太福音', 40, 17, 5, '彼がまだ話している間に、見よ、光り輝く雲が彼らをおおった。すると見よ、雲の中から「これはわたしの愛する子。わたしはこれを喜ぶ。彼の言うことを聞け」という声がした。'),
('JPN', '马太福音', 40, 17, 6, '弟子たちはこれを聞いて、ひれ伏した。そして非常に恐れた。'),
('JPN', '马太福音', 40, 17, 7, 'するとイエスが近づいて彼らに触れ、「起きなさい。恐れることはない」と言われた。'),
('JPN', '马太福音', 40, 17, 8, '彼らが目を上げると、イエス一人のほかには、だれも見えなかった。'),
('JPN', '马太福音', 40, 17, 9, '彼らが山を下るとき、イエスは彼らに命じられた。「あなたがたが見たことを、だれにも話してはいけません。人の子が死人の中からよみがえるまでは。」'),
('JPN', '马太福音', 40, 17, 10, 'すると、弟子たちはイエスに尋ねた。「そうすると、まずエリヤが来るはずだと律法学者たちが言っているのは、どういうことなのですか。」'),
('JPN', '马太福音', 40, 17, 11, 'イエスは答えられた。「エリヤが来て、すべてを立て直します。'),
('JPN', '马太福音', 40, 17, 12, 'しかし、わたしはあなたがたに言います。エリヤはすでに来たのです。ところが人々はエリヤを認めず、彼に対して好き勝手なことをしました。同じように人の子も、人々から苦しみを受けることになります。」'),
('JPN', '马太福音', 40, 17, 13, 'そのとき弟子たちは、イエスが自分たちに言われたのは、バプテスマのヨハネのことだと気づいた。'),
('JPN', '马太福音', 40, 17, 14, '彼らが群衆のところに行くと、一人の人がイエスに近寄って来て御前にひざまずき、'),
('JPN', '马太福音', 40, 17, 15, 'こう言った。「主よ、私の息子をあわれんでください。てんかんで、たいへん苦しんでいます。何度も火の中に倒れ、また何度も水の中に倒れました。'),
('JPN', '马太福音', 40, 17, 16, 'そこで、息子をあなたのお弟子たちのところに連れて来たのですが、治すことができませんでした。」'),
('JPN', '马太福音', 40, 17, 17, 'イエスは答えられた。「ああ、不信仰な曲がった時代だ。いつまであなたがたと一緒にいなければならないのか。いつまであなたがたに我慢しなければならないのか。その子をわたしのところに連れて来なさい。」'),
('JPN', '马太福音', 40, 17, 18, 'そして、イエスがその子をお叱りになると悪霊は出て行き、すぐにその子は癒やされた。'),
('JPN', '马太福音', 40, 17, 19, 'それから、弟子たちはそっとイエスのもとに来て言った。「なぜ私たちは悪霊を追い出せなかったのですか。」'),
('JPN', '马太福音', 40, 17, 20, 'イエスは言われた。「あなたがたの信仰が薄いからです。まことに、あなたがたに言います。もし、からし種ほどの信仰があるなら、この山に『ここからあそこに移れ』と言えば移ります。あなたがたにできないことは何もありません。」'),
('JPN', '马太福音', 40, 17, 21, '※後代の写本に二一節として〔ただし、この種のものは、祈りと断食によらなければ出て行きません。〕を加えるものもある'),
('JPN', '马太福音', 40, 17, 22, '彼らがガリラヤに集まっていたとき、イエスは言われた。「人の子は、人々の手に渡されようとしています。'),
('JPN', '马太福音', 40, 17, 23, '人の子は彼らに殺されるが、三日目によみがえります。」すると彼らはたいへん悲しんだ。'),
('JPN', '马太福音', 40, 17, 24, '彼らがカペナウムに着いたとき、神殿税を集める人たちがペテロのところに近寄って来て言った。「あなたがたの先生は神殿税を納めないのですか。」'),
('JPN', '马太福音', 40, 17, 25, '彼は「納めます」と言った。そして家に入ると、イエスのほうから先にこう言われた。「シモン、あなたはどう思いますか。地上の王たちはだれから税や貢ぎ物を取りますか。自分の子たちからですか、それとも、ほかの人たちからですか。」'),
('JPN', '马太福音', 40, 17, 26, 'ペテロが「ほかの人たちからです」と言うと、イエスは言われた。「ですから、子たちにはその義務がないのです。'),
('JPN', '马太福音', 40, 17, 27, 'しかし、あの人たちをつまずかせないために、湖に行って釣り糸を垂れ、最初に釣れた魚を取りなさい。その口を開けるとスタテル銀貨一枚が見つかります。それを取って、わたしとあなたの分として納めなさい。」'),
('JPN', '马太福音', 40, 18, 1, 'そのとき、弟子たちがイエスのところに来て言った。「天の御国では、いったいだれが一番偉いのですか。」'),
('JPN', '马太福音', 40, 18, 2, 'イエスは一人の子どもを呼び寄せ、彼らの真ん中に立たせて、'),
('JPN', '马太福音', 40, 18, 3, 'こう言われた。「まことに、あなたがたに言います。向きを変えて子どもたちのようにならなければ、決して天の御国に入れません。'),
('JPN', '马太福音', 40, 18, 4, 'ですから、だれでもこの子どものように自分を低くする人が、天の御国で一番偉いのです。'),
('JPN', '马太福音', 40, 18, 5, 'また、だれでもこのような子どもの一人を、わたしの名のゆえに受け入れる人は、わたしを受け入れるのです。'),
('JPN', '马太福音', 40, 18, 6, 'わたしを信じるこの小さい者たちの一人をつまずかせる者は、大きな石臼を首にかけられて、海の深みに沈められるほうがよいのです。'),
('JPN', '马太福音', 40, 18, 7, 'つまずきを与えるこの世はわざわいです。つまずきが起こるのは避けられませんが、つまずきをもたらす者はわざわいです。'),
('JPN', '马太福音', 40, 18, 8, 'あなたの手か足があなたをつまずかせるなら、それを切って捨てなさい。片手片足でいのちに入るほうが、両手両足そろったままで永遠の火に投げ込まれるよりよいのです。'),
('JPN', '马太福音', 40, 18, 9, 'また、もしあなたの目があなたをつまずかせるなら、それをえぐり出して捨てなさい。片目でいのちに入るほうが、両目そろったままゲヘナの火に投げ込まれるよりよいのです。'),
('JPN', '马太福音', 40, 18, 10, 'あなたがたは、この小さい者たちの一人を軽んじたりしないように気をつけなさい。あなたがたに言いますが、天にいる、彼らの御使いたちは、天におられるわたしの父の御顔をいつも見ているからです。'),
('JPN', '马太福音', 40, 18, 11, '※後代の写本に十一節として〔人の子は、失われている者を救うために来たのです。〕を加えるものもある'),
('JPN', '马太福音', 40, 18, 12, 'あなたがたはどう思いますか。もしある人に羊が百匹いて、そのうちの一匹が迷い出たら、その人は九十九匹を山に残して、迷った一匹を捜しに出かけないでしょうか。'),
('JPN', '马太福音', 40, 18, 13, 'まことに、あなたがたに言います。もしその羊を見つけたなら、その人は、迷わなかった九十九匹の羊以上にこの一匹を喜びます。'),
('JPN', '马太福音', 40, 18, 14, 'このように、この小さい者たちの一人が滅びることは、天におられるあなたがたの父のみこころではありません。'),
('JPN', '马太福音', 40, 18, 15, 'また、もしあなたの兄弟があなたに対して罪を犯したなら、行って二人だけのところで指摘しなさい。その人があなたの言うことを聞き入れるなら、あなたは自分の兄弟を得たことになります。'),
('JPN', '马太福音', 40, 18, 16, 'もし聞き入れないなら、ほかに一人か二人、一緒に連れて行きなさい。二人または三人の証人の証言によって、すべてのことが立証されるようにするためです。'),
('JPN', '马太福音', 40, 18, 17, 'それでもなお、言うことを聞き入れないなら、教会に伝えなさい。教会の言うことさえも聞き入れないなら、彼を異邦人か取税人のように扱いなさい。'),
('JPN', '马太福音', 40, 18, 18, 'まことに、あなたがたに言います。何でもあなたがたが地上でつなぐことは天でもつながれ、何でもあなたがたが地上で解くことは天でも解かれます。'),
('JPN', '马太福音', 40, 18, 19, 'まことに、もう一度あなたがたに言います。あなたがたのうちの二人が、どんなことでも地上で心を一つにして祈るなら、天におられるわたしの父はそれをかなえてくださいます。'),
('JPN', '马太福音', 40, 18, 20, '二人か三人がわたしの名において集まっているところには、わたしもその中にいるのです。」'),
('JPN', '马太福音', 40, 18, 21, 'そのとき、ペテロがみもとに来て言った。「主よ。兄弟が私に対して罪を犯した場合、何回赦すべきでしょうか。七回まででしょうか。」'),
('JPN', '马太福音', 40, 18, 22, 'イエスは言われた。「わたしは七回までとは言いません。七回を七十倍するまでです。'),
('JPN', '马太福音', 40, 18, 23, 'ですから、天の御国は、王である一人の人にたとえることができます。その人は自分の家来たちと清算をしたいと思った。'),
('JPN', '马太福音', 40, 18, 24, '清算が始まると、まず一万タラントの負債のある者が、王のところに連れて来られた。'),
('JPN', '马太福音', 40, 18, 25, '彼は返済することができなかったので、その主君は彼に、自分自身も妻子も、持っている物もすべて売って返済するように命じた。'),
('JPN', '马太福音', 40, 18, 26, 'それで、家来はひれ伏して主君を拝し、『もう少し待ってください。そうすればすべてお返しします』と言った。'),
('JPN', '马太福音', 40, 18, 27, '家来の主君はかわいそうに思って彼を赦し、負債を免除してやった。'),
('JPN', '马太福音', 40, 18, 28, 'ところが、その家来が出て行くと、自分に百デナリの借りがある仲間の一人に出会った。彼はその人を捕まえて首を絞め、『借金を返せ』と言った。'),
('JPN', '马太福音', 40, 18, 29, '彼の仲間はひれ伏して、『もう少し待ってください。そうすればお返しします』と嘆願した。'),
('JPN', '马太福音', 40, 18, 30, 'しかし彼は承知せず、その人を引いて行って、負債を返すまで牢に放り込んだ。'),
('JPN', '马太福音', 40, 18, 31, '彼の仲間たちは事の成り行きを見て非常に心を痛め、行って一部始終を主君に話した。'),
('JPN', '马太福音', 40, 18, 32, 'そこで主君は彼を呼びつけて言った。『悪い家来だ。おまえが私に懇願したから、私はおまえの負債をすべて免除してやったのだ。'),
('JPN', '马太福音', 40, 18, 33, '私がおまえをあわれんでやったように、おまえも自分の仲間をあわれんでやるべきではなかったのか。』'),
('JPN', '马太福音', 40, 18, 34, 'こうして、主君は怒って、負債をすべて返すまで彼を獄吏たちに引き渡した。'),
('JPN', '马太福音', 40, 18, 35, 'あなたがたもそれぞれ自分の兄弟を心から赦さないなら、わたしの天の父もあなたがたに、このようになさるのです。」'),
('JPN', '马太福音', 40, 19, 1, 'イエスはこれらの話を終えると、ガリラヤを去り、ヨルダンの川向こうを経てユダヤ地方へ入られた。'),
('JPN', '马太福音', 40, 19, 2, 'すると大勢の群衆がついて来たので、その場で彼らを癒やされた。'),
('JPN', '马太福音', 40, 19, 3, 'パリサイ人たちがみもとに来て、イエスを試みるために言った。「何か理由があれば、妻を離縁することは律法にかなっているでしょうか。」'),
('JPN', '马太福音', 40, 19, 4, 'イエスは答えられた。「あなたがたは読んだことがないのですか。創造者ははじめの時から『男と女に彼らを創造され』ました。'),
('JPN', '马太福音', 40, 19, 5, 'そして、『それゆえ、男は父と母を離れ、その妻と結ばれ、ふたりは一体となるのである』と言われました。'),
('JPN', '马太福音', 40, 19, 6, 'ですから、彼らはもはやふたりではなく一体なのです。そういうわけで、神が結び合わせたものを人が引き離してはなりません。」'),
('JPN', '马太福音', 40, 19, 7, '彼らはイエスに言った。「それでは、なぜモーセは離縁状を渡して妻を離縁せよと命じたのですか。」'),
('JPN', '马太福音', 40, 19, 8, 'イエスは彼らに言われた。「モーセは、あなたがたの心が頑ななので、あなたがたに妻を離縁することを許したのです。しかし、はじめの時からそうだったのではありません。'),
('JPN', '马太福音', 40, 19, 9, 'あなたがたに言います。だれでも、淫らな行い以外の理由で自分の妻を離縁し、別の女を妻とする者は、姦淫を犯すことになるのです。」'),
('JPN', '马太福音', 40, 19, 10, '弟子たちはイエスに言った。「もし夫と妻の関係がそのようなものなら、結婚しないほうがましです。」'),
('JPN', '马太福音', 40, 19, 11, 'しかし、イエスは言われた。「そのことばは、だれもが受け入れられるわけではありません。ただ、それが許されている人だけができるのです。'),
('JPN', '马太福音', 40, 19, 12, '母の胎から独身者として生まれた人たちがいます。また、人から独身者にさせられた人たちもいます。また、天の御国のために、自分から独身者になった人たちもいます。それを受け入れることができる人は、受け入れなさい。」'),
('JPN', '马太福音', 40, 19, 13, 'そのとき、イエスに手を置いて祈っていただくために、子どもたちがみもとに連れて来られた。すると弟子たちは、連れて来た人たちを叱った。'),
('JPN', '马太福音', 40, 19, 14, 'しかし、イエスは言われた。「子どもたちを来させなさい。わたしのところに来るのを邪魔してはいけません。天の御国はこのような者たちのものなのです。」'),
('JPN', '马太福音', 40, 19, 15, 'そして手を子どもたちの上に置いてから、そこを去って行かれた。'),
('JPN', '马太福音', 40, 19, 16, 'すると見よ、一人の人がイエスに近づいて来て言った。「先生。永遠のいのちを得るためには、どんな良いことをすればよいのでしょうか。」'),
('JPN', '马太福音', 40, 19, 17, 'イエスは彼に言われた。「なぜ、良いことについて、わたしに尋ねるのですか。良い方はおひとりです。いのちに入りたいと思うなら戒めを守りなさい。」'),
('JPN', '马太福音', 40, 19, 18, '彼は「どの戒めですか」と言った。そこでイエスは答えられた。「殺してはならない。姦淫してはならない。盗んではならない。偽りの証言をしてはならない。'),
('JPN', '马太福音', 40, 19, 19, '父と母を敬え。あなたの隣人を自分自身のように愛しなさい。」'),
('JPN', '马太福音', 40, 19, 20, 'この青年はイエスに言った。「私はそれらすべてを守ってきました。何がまだ欠けているのでしょうか。」'),
('JPN', '马太福音', 40, 19, 21, 'イエスは彼に言われた。「完全になりたいのなら、帰って、あなたの財産を売り払って貧しい人たちに与えなさい。そうすれば、あなたは天に宝を持つことになります。そのうえで、わたしに従って来なさい。」'),
('JPN', '马太福音', 40, 19, 22, '青年はこのことばを聞くと、悲しみながら立ち去った。多くの財産を持っていたからである。'),
('JPN', '马太福音', 40, 19, 23, 'そこで、イエスは弟子たちに言われた。「まことに、あなたがたに言います。金持ちが天の御国に入るのは難しいことです。'),
('JPN', '马太福音', 40, 19, 24, 'もう一度あなたがたに言います。金持ちが神の国に入るよりは、らくだが針の穴を通るほうが易しいのです。」'),
('JPN', '马太福音', 40, 19, 25, '弟子たちはこれを聞くと、たいへん驚いて言った。「それでは、だれが救われることができるでしょう。」'),
('JPN', '马太福音', 40, 19, 26, 'イエスは彼らをじっと見つめて言われた。「それは人にはできないことですが、神にはどんなことでもできます。」'),
('JPN', '马太福音', 40, 19, 27, 'そのとき、ペテロはイエスに言った。「ご覧ください。私たちはすべてを捨てて、あなたに従って来ました。それで、私たちは何をいただけるでしょうか。」'),
('JPN', '马太福音', 40, 19, 28, 'そこでイエスは彼らに言われた。「まことに、あなたがたに言います。人の子がその栄光の座に着くとき、その新しい世界で、わたしに従って来たあなたがたも十二の座に着いて、イスラエルの十二の部族を治めます。'),
('JPN', '马太福音', 40, 19, 29, 'また、わたしの名のために、家、兄弟、姉妹、父、母、子ども、畑を捨てた者はみな、その百倍を受け、また永遠のいのちを受け継ぎます。'),
('JPN', '马太福音', 40, 19, 30, 'しかし、先にいる多くの者が後になり、後にいる多くの者が先になります。'),
('JPN', '马太福音', 40, 20, 1, '天の御国は、自分のぶどう園で働く者を雇うために朝早く出かけた、家の主人のようなものです。'),
('JPN', '马太福音', 40, 20, 2, '彼は労働者たちと一日一デナリの約束をすると、彼らをぶどう園に送った。'),
('JPN', '马太福音', 40, 20, 3, '彼はまた、九時ごろ出て行き、別の人たちが市場で何もしないで立っているのを見た。'),
('JPN', '马太福音', 40, 20, 4, 'そこで、その人たちに言った。『あなたがたもぶどう園に行きなさい。相当の賃金を払うから。』'),
('JPN', '马太福音', 40, 20, 5, '彼らは出かけて行った。主人はまた十二時ごろと三時ごろにも出て行って同じようにした。'),
('JPN', '马太福音', 40, 20, 6, 'また、五時ごろ出て行き、別の人たちが立っているのを見つけた。そこで、彼らに言った。『なぜ一日中何もしないでここに立っているのですか。』'),
('JPN', '马太福音', 40, 20, 7, '彼らは言った。『だれも雇ってくれないからです。』主人は言った。『あなたがたもぶどう園に行きなさい。』'),
('JPN', '马太福音', 40, 20, 8, '夕方になったので、ぶどう園の主人は監督に言った。『労働者たちを呼んで、最後に来た者たちから始めて、最初に来た者たちにまで賃金を払ってやりなさい。』'),
('JPN', '马太福音', 40, 20, 9, 'そこで、五時ごろに雇われた者たちが来て、それぞれ一デナリずつ受け取った。'),
('JPN', '马太福音', 40, 20, 10, '最初の者たちが来て、もっと多くもらえるだろうと思ったが、彼らが受け取ったのも一デナリずつであった。'),
('JPN', '马太福音', 40, 20, 11, '彼らはそれを受け取ると、主人に不満をもらした。'),
('JPN', '马太福音', 40, 20, 12, '『最後に来たこの者たちが働いたのは、一時間だけです。それなのにあなたは、一日の労苦と焼けるような暑さを辛抱した私たちと、同じように扱いました。』'),
('JPN', '马太福音', 40, 20, 13, 'しかし、主人はその一人に答えた。『友よ、私はあなたに不当なことはしていません。あなたは私と、一デナリで同意したではありませんか。'),
('JPN', '马太福音', 40, 20, 14, 'あなたの分を取って帰りなさい。私はこの最後の人にも、あなたと同じだけ与えたいのです。'),
('JPN', '马太福音', 40, 20, 15, '自分のもので自分のしたいことをしてはいけませんか。それとも、私が気前がいいので、あなたはねたんでいるのですか。』'),
('JPN', '马太福音', 40, 20, 16, 'このように、後の者が先になり、先の者が後になります。」'),
('JPN', '马太福音', 40, 20, 17, 'さて、イエスはエルサレムに上る途中、十二弟子だけを呼んで、道々彼らに話された。'),
('JPN', '马太福音', 40, 20, 18, '「ご覧なさい。わたしたちはエルサレムに上って行きます。人の子は祭司長たちや律法学者たちに引き渡されます。彼らは人の子を死刑に定め、'),
('JPN', '马太福音', 40, 20, 19, '異邦人に引き渡します。嘲り、むちで打ち、十字架につけるためです。しかし、人の子は三日目によみがえります。」'),
('JPN', '马太福音', 40, 20, 20, 'そのとき、ゼベダイの息子たちの母が、息子たちと一緒にイエスのところに来てひれ伏し、何かを願おうとした。'),
('JPN', '马太福音', 40, 20, 21, 'イエスが彼女に「何を願うのですか」と言われると、彼女は言った。「私のこの二人の息子があなたの御国で、一人はあなたの右に、一人は左に座れるように、おことばを下さい。」'),
('JPN', '马太福音', 40, 20, 22, 'イエスは答えられた。「あなたがたは自分が何を求めているのか分かっていません。わたしが飲もうとしている杯を飲むことができますか。」彼らは「できます」と言った。'),
('JPN', '马太福音', 40, 20, 23, 'イエスは言われた。「あなたがたはわたしの杯を飲むことになります。しかし、わたしの右と左に座ることは、わたしが許すことではありません。わたしの父によって備えられた人たちに与えられるのです。」'),
('JPN', '马太福音', 40, 20, 24, 'ほかの十人はこれを聞いて、この二人の兄弟に腹を立てた。'),
('JPN', '马太福音', 40, 20, 25, 'そこで、イエスは彼らを呼び寄せて言われた。「あなたがたも知っているとおり、異邦人の支配者たちは人々に対して横柄にふるまい、偉い人たちは人々の上に権力をふるっています。'),
('JPN', '马太福音', 40, 20, 26, 'あなたがたの間では、そうであってはなりません。あなたがたの間で偉くなりたいと思う者は、皆に仕える者になりなさい。'),
('JPN', '马太福音', 40, 20, 27, 'あなたがたの間で先頭に立ちたいと思う者は、皆のしもべになりなさい。'),
('JPN', '马太福音', 40, 20, 28, '人の子が、仕えられるためではなく仕えるために、また多くの人のための贖いの代価として、自分のいのちを与えるために来たのと、同じようにしなさい。」'),
('JPN', '马太福音', 40, 20, 29, 'さて、一行がエリコを出て行くと、大勢の群衆がイエスについて行った。'),
('JPN', '马太福音', 40, 20, 30, 'すると見よ。道端に座っていた目の見えない二人の人が、イエスが通られると聞いて、「主よ、ダビデの子よ。私たちをあわれんでください」と叫んだ。'),
('JPN', '马太福音', 40, 20, 31, '群衆は彼らを黙らせようとたしなめたが、彼らはますます、「主よ、ダビデの子よ。私たちをあわれんでください」と叫んだ。'),
('JPN', '马太福音', 40, 20, 32, 'イエスは立ち止まり、彼らを呼んで言われた。「わたしに何をしてほしいのですか。」'),
('JPN', '马太福音', 40, 20, 33, '彼らは言った。「主よ、目を開けていただきたいのです。」'),
('JPN', '马太福音', 40, 20, 34, 'イエスは深くあわれんで、彼らの目に触れられた。すると、すぐに彼らは見えるようになり、イエスについて行った。'),
('JPN', '马太福音', 40, 21, 1, 'さて、一行がエルサレムに近づいて、オリーブ山のふもとのベテパゲまで来たそのとき、イエスはこう言って、二人の弟子を遣わされた。'),
('JPN', '马太福音', 40, 21, 2, '「向こうの村へ行きなさい。そうすればすぐに、ろばがつながれていて、一緒に子ろばがいるのに気がつくでしょう。それをほどいて、わたしのところに連れて来なさい。'),
('JPN', '马太福音', 40, 21, 3, 'もしだれかが何か言ったら、『主がお入り用なのです』と言いなさい。すぐに渡してくれます。」'),
('JPN', '马太福音', 40, 21, 4, 'このことが起こったのは、預言者を通して語られたことが成就するためであった。'),
('JPN', '马太福音', 40, 21, 5, '「娘シオンに言え。『見よ、あなたの王があなたのところに来る。柔和な方で、ろばに乗って。荷ろばの子である、子ろばに乗って。』」'),
('JPN', '马太福音', 40, 21, 6, 'そこで弟子たちは行って、イエスが命じられたとおりにし、'),
('JPN', '马太福音', 40, 21, 7, 'ろばと子ろばを連れて来て、自分たちの上着をその上に掛けた。そこでイエスはその上に座られた。'),
('JPN', '马太福音', 40, 21, 8, 'すると非常に多くの群衆が、自分たちの上着を道に敷いた。また、木の枝を切って道に敷く者たちもいた。'),
('JPN', '马太福音', 40, 21, 9, '群衆は、イエスの前を行く者たちも後に続く者たちも、こう言って叫んだ。「ホサナ、ダビデの子に。祝福あれ、主の御名によって来られる方に。ホサナ、いと高き所に。」'),
('JPN', '马太福音', 40, 21, 10, 'こうしてイエスがエルサレムに入られると、都中が大騒ぎになり、「この人はだれなのか」と言った。'),
('JPN', '马太福音', 40, 21, 11, '群衆は「この人はガリラヤのナザレから出た預言者イエスだ」と言っていた。'),
('JPN', '马太福音', 40, 21, 12, 'それから、イエスは宮に入って、その中で売り買いしている者たちをみな追い出し、両替人の台や、鳩を売る者たちの腰掛けを倒された。'),
('JPN', '马太福音', 40, 21, 13, 'そして彼らに言われた。「『わたしの家は祈りの家と呼ばれる』と書いてある。それなのに、おまえたちはそれを『強盗の巣』にしている。」'),
('JPN', '马太福音', 40, 21, 14, 'また、宮の中で、目の見えない人たちや足の不自由な人たちがみもとに来たので、イエスは彼らを癒やされた。'),
('JPN', '马太福音', 40, 21, 15, 'ところが祭司長たちや律法学者たちは、イエスがなさったいろいろな驚くべきことを見て、また宮の中で子どもたちが「ダビデの子にホサナ」と叫んでいるのを見て腹を立て、'),
('JPN', '马太福音', 40, 21, 16, 'イエスに言った。「子どもたちが何と言っているか、聞いていますか。」イエスは言われた。「聞いています。『幼子たち、乳飲み子たちの口を通して、あなたは誉れを打ち立てられました』とあるのを、あなたがたは読んだことがないのですか。」'),
('JPN', '马太福音', 40, 21, 17, 'イエスは彼らを後に残し、都を出てベタニアに行き、そこに泊まられた。'),
('JPN', '马太福音', 40, 21, 18, 'さて、朝早く都に帰る途中、イエスは空腹を覚えられた。'),
('JPN', '马太福音', 40, 21, 19, '道端に一本のいちじくの木が見えたので、そこに行って見ると、葉があるだけで、ほかには何もなかった。それでイエスはその木に「今後いつまでも、おまえの実はならないように」と言われた。すると、たちまちいちじくの木は枯れた。'),
('JPN', '马太福音', 40, 21, 20, '弟子たちはこれを見て驚き、「どうして、すぐにいちじくの木が枯れたのでしょうか」と言った。'),
('JPN', '马太福音', 40, 21, 21, 'イエスは答えられた。「まことに、あなたがたに言います。もし、あなたがたが信じて疑わないなら、いちじくの木に起こったことを起こせるだけでなく、この山に向かい、『立ち上がって、海に入れ』と言えば、そのとおりになります。'),
('JPN', '马太福音', 40, 21, 22, 'あなたがたは、信じて祈り求めるものは何でも受けることになります。」'),
('JPN', '马太福音', 40, 21, 23, 'それからイエスが宮に入って教えておられると、祭司長たちや民の長老たちがイエスのもとに来て言った。「何の権威によって、これらのことをしているのですか。だれがあなたにその権威を授けたのですか。」'),
('JPN', '马太福音', 40, 21, 24, 'イエスは彼らに答えられた。「わたしも一言尋ねましょう。それにあなたがたが答えるなら、わたしも、何の権威によってこれらのことをしているのか言いましょう。'),
('JPN', '马太福音', 40, 21, 25, 'ヨハネのバプテスマは、どこから来たものですか。天からですか、それとも人からですか。」すると彼らは論じ合った。「もし天からと言えば、それならなぜヨハネを信じなかったのかと言うだろう。'),
('JPN', '马太福音', 40, 21, 26, 'だが、もし人から出たと言えば、群衆が怖い。彼らはみなヨハネを預言者と思っているのだから。」'),
('JPN', '马太福音', 40, 21, 27, 'そこで彼らはイエスに「分かりません」と答えた。イエスもまた、彼らにこう言われた。「わたしも、何の権威によってこれらのことをするのか、あなたがたに言いません。'),
('JPN', '马太福音', 40, 21, 28, 'ところで、あなたがたはどう思いますか。ある人に息子が二人いた。その人は兄のところに来て、『子よ、今日、ぶどう園に行って働いてくれ』と言った。'),
('JPN', '马太福音', 40, 21, 29, '兄は『行きたくありません』と答えたが、後になって思い直し、出かけて行った。'),
('JPN', '马太福音', 40, 21, 30, 'その人は弟のところに来て、同じように言った。弟は『行きます、お父さん』と答えたが、行かなかった。'),
('JPN', '马太福音', 40, 21, 31, '二人のうちのどちらが父の願ったとおりにしたでしょうか。」彼らは言った。「兄です。」イエスは彼らに言われた。「まことに、あなたがたに言います。取税人たちや遊女たちが、あなたがたより先に神の国に入ります。'),
('JPN', '马太福音', 40, 21, 32, 'なぜなら、ヨハネがあなたがたのところに来て義の道を示したのに、あなたがたは信じず、取税人たちや遊女たちは信じたからです。あなたがたはそれを見ても、後で思い直して信じることをしませんでした。'),
('JPN', '马太福音', 40, 21, 33, 'もう一つのたとえを聞きなさい。ある家の主人がいた。彼はぶどう園を造って垣根を巡らし、その中に踏み場を掘り、見張りやぐらを建て、それを農夫たちに貸して旅に出た。'),
('JPN', '马太福音', 40, 21, 34, '収穫の時が近づいたので、主人は自分の収穫を受け取ろうとして、農夫たちのところにしもべたちを遣わした。'),
('JPN', '马太福音', 40, 21, 35, 'ところが、農夫たちはそのしもべたちを捕らえて、一人を打ちたたき、一人を殺し、一人を石打ちにした。'),
('JPN', '马太福音', 40, 21, 36, '主人は、前よりも多くの、別のしもべたちを再び遣わしたが、農夫たちは彼らにも同じようにした。'),
('JPN', '马太福音', 40, 21, 37, 'その後、主人は『私の息子なら敬ってくれるだろう』と言って、息子を彼らのところに遣わした。'),
('JPN', '马太福音', 40, 21, 38, 'すると農夫たちは、その息子を見て、『あれは跡取りだ。さあ、あれを殺して、あれの相続財産を手に入れよう』と話し合った。'),
('JPN', '马太福音', 40, 21, 39, 'そして彼を捕らえ、ぶどう園の外に放り出して殺してしまった。'),
('JPN', '马太福音', 40, 21, 40, 'ぶどう園の主人が帰って来たら、その農夫たちをどうするでしょうか。」'),
('JPN', '马太福音', 40, 21, 41, '彼らはイエスに言った。「その悪者どもを情け容赦なく滅ぼして、そのぶどう園を、収穫の時が来れば収穫を納める別の農夫たちに貸すでしょう。」'),
('JPN', '马太福音', 40, 21, 42, 'イエスは彼らに言われた。「あなたがたは、聖書に次のようにあるのを読んだことがないのですか。『家を建てる者たちが捨てた石、それが要の石となった。これは主がなさったこと。私たちの目には不思議なことだ。』'),
('JPN', '马太福音', 40, 21, 43, 'ですから、わたしは言っておきます。神の国はあなたがたから取り去られ、神の国の実を結ぶ民に与えられます。'),
('JPN', '马太福音', 40, 21, 44, 'また、この石の上に落ちる人は粉々に砕かれ、この石が人の上に落ちれば、その人を押しつぶします。」'),
('JPN', '马太福音', 40, 21, 45, '祭司長たちとパリサイ人たちは、イエスのこれらのたとえを聞いたとき、自分たちについて話しておられることに気づいた。'),
('JPN', '马太福音', 40, 21, 46, 'それでイエスを捕らえようとしたが、群衆を恐れた。群衆はイエスを預言者と認めていたからである。'),
('JPN', '马太福音', 40, 22, 1, 'イエスは彼らに対し、再びたとえをもって話された。'),
('JPN', '马太福音', 40, 22, 2, '「天の御国は、自分の息子のために、結婚の披露宴を催した王にたとえることができます。'),
('JPN', '马太福音', 40, 22, 3, '王は披露宴に招待した客を呼びにしもべたちを遣わしたが、彼らは来ようとしなかった。'),
('JPN', '马太福音', 40, 22, 4, 'それで再び、次のように言って別のしもべたちを遣わした。『招待した客にこう言いなさい。「私は食事を用意しました。私の雄牛や肥えた家畜を屠り、何もかも整いました。どうぞ披露宴においでください」と。』'),
('JPN', '马太福音', 40, 22, 5, 'ところが彼らは気にもかけず、ある者は自分の畑に、別の者は自分の商売に出て行き、'),
('JPN', '马太福音', 40, 22, 6, '残りの者たちは、王のしもべたちを捕まえて侮辱し、殺してしまった。'),
('JPN', '马太福音', 40, 22, 7, '王は怒って軍隊を送り、その人殺しどもを滅ぼして、彼らの町を焼き払った。'),
('JPN', '马太福音', 40, 22, 8, 'それから王はしもべたちに言った。『披露宴の用意はできているが、招待した人たちはふさわしくなかった。'),
('JPN', '马太福音', 40, 22, 9, 'だから大通りに行って、出会った人をみな披露宴に招きなさい。』'),
('JPN', '马太福音', 40, 22, 10, 'しもべたちは通りに出て行って、良い人でも悪い人でも出会った人をみな集めたので、披露宴は客でいっぱいになった。'),
('JPN', '马太福音', 40, 22, 11, '王が客たちを見ようとして入って来ると、そこに婚礼の礼服を着ていない人が一人いた。'),
('JPN', '马太福音', 40, 22, 12, '王はその人に言った。『友よ。どうして婚礼の礼服を着ないで、ここに入って来たのか。』しかし、彼は黙っていた。'),
('JPN', '马太福音', 40, 22, 13, 'そこで、王は召使いたちに言った。『この男の手足を縛って、外の暗闇に放り出せ。この男はそこで泣いて歯ぎしりすることになる。』'),
('JPN', '马太福音', 40, 22, 14, '招かれる人は多いが、選ばれる人は少ないのです。」'),
('JPN', '马太福音', 40, 22, 15, 'そのころ、パリサイ人たちは出て来て、どのようにしてイエスをことばの罠にかけようかと相談した。'),
('JPN', '马太福音', 40, 22, 16, '彼らは自分の弟子たちを、ヘロデ党の者たちと一緒にイエスのもとに遣わして、こう言った。「先生。私たちは、あなたが真実な方で、真理に基づいて神の道を教え、だれにも遠慮しない方だと知っております。あなたは人の顔色を見ないからです。'),
('JPN', '马太福音', 40, 22, 17, 'ですから、どう思われるか、お聞かせください。カエサルに税金を納めることは律法にかなっているでしょうか、いないでしょうか。」'),
('JPN', '马太福音', 40, 22, 18, 'イエスは彼らの悪意を見抜いて言われた。「なぜわたしを試すのですか、偽善者たち。'),
('JPN', '马太福音', 40, 22, 19, '税として納めるお金を見せなさい。」そこで彼らはデナリ銀貨をイエスのもとに持って来た。'),
('JPN', '马太福音', 40, 22, 20, 'イエスは彼らに言われた。「これはだれの肖像と銘ですか。」'),
('JPN', '马太福音', 40, 22, 21, '彼らは「カエサルのです」と言った。そのときイエスは言われた。「それなら、カエサルのものはカエサルに、神のものは神に返しなさい。」'),
('JPN', '马太福音', 40, 22, 22, '彼らはこれを聞いて驚嘆し、イエスを残して立ち去った。'),
('JPN', '马太福音', 40, 22, 23, 'その日、復活はないと言っているサドカイ人たちが、イエスのところに来て質問した。'),
('JPN', '马太福音', 40, 22, 24, '「先生。モーセは、『もしある人が、子がないままで死んだなら、その弟は兄の妻と結婚して、兄のために子孫を起こさなければならない』と言いました。'),
('JPN', '马太福音', 40, 22, 25, 'ところで、私たちの間に七人の兄弟がいました。長男は結婚しましたが死にました。子がいなかったので、その妻を弟に残しました。'),
('JPN', '马太福音', 40, 22, 26, '次男も三男も、そして七人までも同じようになりました。'),
('JPN', '马太福音', 40, 22, 27, 'そして最後に、その妻も死にました。'),
('JPN', '马太福音', 40, 22, 28, 'では復活の際、彼女は七人のうちのだれの妻になるのでしょうか。彼らはみな、彼女を妻にしたのですが。」'),
('JPN', '马太福音', 40, 22, 29, 'イエスは彼らに答えられた。「あなたがたは聖書も神の力も知らないので、思い違いをしています。'),
('JPN', '马太福音', 40, 22, 30, '復活の時には人はめとることも嫁ぐこともなく、天の御使いたちのようです。'),
('JPN', '马太福音', 40, 22, 31, '死人の復活については、神があなたがたにこう語られたのを読んだことがないのですか。'),
('JPN', '马太福音', 40, 22, 32, '『わたしはアブラハムの神、イサクの神、ヤコブの神である。』神は死んだ者の神ではなく、生きている者の神です。」'),
('JPN', '马太福音', 40, 22, 33, '群衆はこれを聞いて、イエスの教えに驚嘆した。'),
('JPN', '马太福音', 40, 22, 34, 'パリサイ人たちはイエスがサドカイ人たちを黙らせたと聞いて、一緒に集まった。'),
('JPN', '马太福音', 40, 22, 35, 'そして彼らのうちの一人、律法の専門家がイエスを試そうとして尋ねた。'),
('JPN', '马太福音', 40, 22, 36, '「先生、律法の中でどの戒めが一番重要ですか。」'),
('JPN', '马太福音', 40, 22, 37, 'イエスは彼に言われた。「『あなたは心を尽くし、いのちを尽くし、知性を尽くして、あなたの神、主を愛しなさい。』'),
('JPN', '马太福音', 40, 22, 38, 'これが、重要な第一の戒めです。'),
('JPN', '马太福音', 40, 22, 39, '『あなたの隣人を自分自身のように愛しなさい』という第二の戒めも、それと同じように重要です。'),
('JPN', '马太福音', 40, 22, 40, 'この二つの戒めに律法と預言者の全体がかかっているのです。」'),
('JPN', '马太福音', 40, 22, 41, 'パリサイ人たちが集まっていたとき、イエスは彼らにお尋ねになった。'),
('JPN', '马太福音', 40, 22, 42, '「あなたがたはキリストについてどう思いますか。彼はだれの子ですか。」彼らはイエスに言った。「ダビデの子です。」'),
('JPN', '马太福音', 40, 22, 43, 'イエスは彼らに言われた。「それでは、どうしてダビデは御霊によってキリストを主と呼び、'),
('JPN', '马太福音', 40, 22, 44, '『主は、私の主に言われた。「あなたは、わたしの右の座に着いていなさい。わたしがあなたの敵をあなたの足台とするまで」』と言っているのですか。'),
('JPN', '马太福音', 40, 22, 45, 'ダビデがキリストを主と呼んでいるのなら、どうしてキリストがダビデの子なのでしょう。」'),
('JPN', '马太福音', 40, 22, 46, 'するとだれ一人、一言もイエスに答えられなかった。その日から、もうだれも、あえてイエスに質問しようとはしなかった。'),
('JPN', '马太福音', 40, 23, 1, 'そのとき、イエスは群衆と弟子たちに語られた。'),
('JPN', '马太福音', 40, 23, 2, '「律法学者たちやパリサイ人たちはモーセの座に着いています。'),
('JPN', '马太福音', 40, 23, 3, 'ですから、彼らがあなたがたに言うことはすべて実行し、守りなさい。しかし、彼らの行いをまねてはいけません。彼らは言うだけで実行しないからです。'),
('JPN', '马太福音', 40, 23, 4, 'また彼らは、重くて負いきれない荷を束ねて人々の肩に載せるが、それを動かすのに自分は指一本貸そうともしません。'),
('JPN', '马太福音', 40, 23, 5, '彼らがしている行いはすべて人に見せるためです。彼らは聖句を入れる小箱を大きくしたり、衣の房を長くしたりするのです。'),
('JPN', '马太福音', 40, 23, 6, '宴会では上座を、会堂では上席を好み、'),
('JPN', '马太福音', 40, 23, 7, '広場であいさつされること、人々から先生と呼ばれることが好きです。'),
('JPN', '马太福音', 40, 23, 8, 'しかし、あなたがたは先生と呼ばれてはいけません。あなたがたの教師はただ一人で、あなたがたはみな兄弟だからです。'),
('JPN', '马太福音', 40, 23, 9, 'あなたがたは地上で、だれかを自分たちの父と呼んではいけません。あなたがたの父はただ一人、天におられる父だけです。'),
('JPN', '马太福音', 40, 23, 10, 'また、師と呼ばれてはいけません。あなたがたの師はただ一人、キリストだけです。'),
('JPN', '马太福音', 40, 23, 11, 'あなたがたのうちで一番偉い者は皆に仕える者になりなさい。'),
('JPN', '马太福音', 40, 23, 12, 'だれでも、自分を高くする者は低くされ、自分を低くする者は高くされます。'),
('JPN', '马太福音', 40, 23, 13, 'わざわいだ、偽善の律法学者、パリサイ人。おまえたちは人々の前で天の御国を閉ざしている。おまえたち自身も入らず、入ろうとしている人々も入らせない。'),
('JPN', '马太福音', 40, 23, 14, '※異本に十四節として以下を加えるものもある。〔わざわいだ、偽善の律法学者、パリサイ人。おまえたちはやもめの家を食いつぶし、見栄のために長い祈りをしている。だから、おまえたちは人一倍ひどい罰を受けるのだ。〕'),
('JPN', '马太福音', 40, 23, 15, 'わざわいだ、偽善の律法学者、パリサイ人。おまえたちは一人の改宗者を得るのに海と陸を巡り歩く。そして改宗者ができると、その人を自分より倍も悪いゲヘナの子にするのだ。'),
('JPN', '马太福音', 40, 23, 16, 'わざわいだ、目の見えない案内人たち。おまえたちは言っている。『だれでも神殿にかけて誓うのであれば、何の義務もない。しかし、神殿の黄金にかけて誓うのであれば、果たす義務がある。』'),
('JPN', '马太福音', 40, 23, 17, '愚かで目の見えない者たち。黄金と、その黄金を聖なるものにする神殿と、どちらが重要なのか。'),
('JPN', '马太福音', 40, 23, 18, 'また、おまえたちは言っている。『だれでも祭壇にかけて誓うのであれば、何の義務もない。しかし、祭壇の上のささげ物にかけて誓うのであれば、果たす義務がある。』'),
('JPN', '马太福音', 40, 23, 19, '目の見えない者たち。ささげ物と、そのささげ物を聖なるものにする祭壇と、どちらが重要なのか。'),
('JPN', '马太福音', 40, 23, 20, '祭壇にかけて誓う者は、祭壇とその上にあるすべてのものにかけて誓っているのだ。'),
('JPN', '马太福音', 40, 23, 21, 'また、神殿にかけて誓う者は、神殿とそこに住まわれる方にかけて誓っているのだ。'),
('JPN', '马太福音', 40, 23, 22, '天にかけて誓う者は、神の御座とそこに座しておられる方にかけて誓っているのだ。'),
('JPN', '马太福音', 40, 23, 23, 'わざわいだ、偽善の律法学者、パリサイ人。おまえたちはミント、イノンド、クミンの十分の一を納めているが、律法の中ではるかに重要なもの、正義とあわれみと誠実をおろそかにしている。十分の一もおろそかにしてはいけないが、これこそしなければならないことだ。'),
('JPN', '马太福音', 40, 23, 24, '目の見えない案内人たち。ブヨはこして除くのに、らくだは飲み込んでいる。'),
('JPN', '马太福音', 40, 23, 25, 'わざわいだ、偽善の律法学者、パリサイ人。おまえたちは杯や皿の外側はきよめるが、内側は強欲と放縦で満ちている。'),
('JPN', '马太福音', 40, 23, 26, '目の見えないパリサイ人。まず、杯の内側をきよめよ。そうすれば外側もきよくなる。'),
('JPN', '马太福音', 40, 23, 27, 'わざわいだ、偽善の律法学者、パリサイ人。おまえたちは白く塗った墓のようなものだ。外側は美しく見えても、内側は死人の骨やあらゆる汚れでいっぱいだ。'),
('JPN', '马太福音', 40, 23, 28, '同じように、おまえたちも外側は人に正しく見えても、内側は偽善と不法でいっぱいだ。'),
('JPN', '马太福音', 40, 23, 29, 'わざわいだ、偽善の律法学者、パリサイ人。おまえたちは預言者たちの墓を建て、義人たちの記念碑を飾って、'),
('JPN', '马太福音', 40, 23, 30, 'こう言う。『もし私たちが先祖の時代に生きていたら、彼らの仲間になって預言者たちの血を流すということはなかっただろう。』'),
('JPN', '马太福音', 40, 23, 31, 'こうして、自分たちが預言者を殺した者たちの子らであることを、自らに対して証言している。'),
('JPN', '马太福音', 40, 23, 32, 'おまえたちは自分の先祖の罪の升を満たすがよい。'),
('JPN', '马太福音', 40, 23, 33, '蛇よ、まむしの子孫よ。おまえたちは、ゲヘナの刑罰をどうして逃れることができるだろうか。'),
('JPN', '马太福音', 40, 23, 34, 'だから、見よ、わたしは預言者、知者、律法学者を遣わすが、おまえたちはそのうちのある者を殺し、十字架につけ、またある者を会堂でむち打ち、町から町へと迫害して回る。'),
('JPN', '马太福音', 40, 23, 35, 'それは、義人アベルの血から、神殿と祭壇の間でおまえたちが殺した、バラキヤの子ザカリヤの血まで、地上で流される正しい人の血が、すべておまえたちに降りかかるようになるためだ。'),
('JPN', '马太福音', 40, 23, 36, 'まことに、おまえたちに言う。これらの報いはすべて、この時代の上に降りかかる。'),
('JPN', '马太福音', 40, 23, 37, 'エルサレム、エルサレム。預言者たちを殺し、自分に遣わされた人たちを石で打つ者よ。わたしは何度、めんどりがひなを翼の下に集めるように、おまえの子らを集めようとしたことか。それなのに、おまえたちはそれを望まなかった。'),
('JPN', '马太福音', 40, 23, 38, '見よ。おまえたちの家は、荒れ果てたまま見捨てられる。'),
('JPN', '马太福音', 40, 23, 39, 'わたしはおまえたちに言う。今から後、『祝福あれ、主の御名によって来られる方に』とおまえたちが言う時が来るまで、決しておまえたちがわたしを見ることはない。」'),
('JPN', '马太福音', 40, 24, 1, 'イエスが宮を出て行かれると、弟子たちが近寄って来て、イエスに向かって宮の建物を指し示した。'),
('JPN', '马太福音', 40, 24, 2, 'すると、イエスは弟子たちに言われた。「あなたがたはこれらの物すべてを見ているのですか。まことに、あなたがたに言います。ここで、どの石も崩されずに、ほかの石の上に残ることは決してありません。」'),
('JPN', '马太福音', 40, 24, 3, 'イエスがオリーブ山で座っておられると、弟子たちがひそかにみもとに来て言った。「お話しください。いつ、そのようなことが起こるのですか。あなたが来られ、世が終わる時のしるしは、どのようなものですか。」'),
('JPN', '马太福音', 40, 24, 4, 'そこでイエスは彼らに答えられた。「人に惑わされないように気をつけなさい。'),
('JPN', '马太福音', 40, 24, 5, 'わたしの名を名乗る者が大勢現れ、『私こそキリストだ』と言って、多くの人を惑わします。'),
('JPN', '马太福音', 40, 24, 6, 'また、戦争や戦争のうわさを聞くことになりますが、気をつけて、うろたえないようにしなさい。そういうことは必ず起こりますが、まだ終わりではありません。'),
('JPN', '马太福音', 40, 24, 7, '民族は民族に、国は国に敵対して立ち上がり、あちこちで飢饉と地震が起こります。'),
('JPN', '马太福音', 40, 24, 8, 'しかし、これらはすべて産みの苦しみの始まりなのです。'),
('JPN', '马太福音', 40, 24, 9, 'そのとき、人々はあなたがたを苦しみにあわせ、殺します。また、わたしの名のために、あなたがたはすべての国の人々に憎まれます。'),
('JPN', '马太福音', 40, 24, 10, 'そのとき多くの人がつまずき、互いに裏切り、憎み合います。'),
('JPN', '马太福音', 40, 24, 11, 'また、偽預言者が大勢現れて、多くの人を惑わします。'),
('JPN', '马太福音', 40, 24, 12, '不法がはびこるので、多くの人の愛が冷えます。'),
('JPN', '马太福音', 40, 24, 13, 'しかし、最後まで耐え忍ぶ人は救われます。'),
('JPN', '马太福音', 40, 24, 14, '御国のこの福音は全世界に宣べ伝えられて、すべての民族に証しされ、それから終わりが来ます。'),
('JPN', '马太福音', 40, 24, 15, 'それゆえ、預言者ダニエルによって語られたあの『荒らす忌まわしいもの』が聖なる所に立っているのを見たら──読者はよく理解せよ──'),
('JPN', '马太福音', 40, 24, 16, 'ユダヤにいる人たちは山へ逃げなさい。'),
('JPN', '马太福音', 40, 24, 17, '屋上にいる人は、家にある物を取り出そうとして下に降りてはいけません。'),
('JPN', '马太福音', 40, 24, 18, '畑にいる人は上着を取りに戻ってはいけません。'),
('JPN', '马太福音', 40, 24, 19, 'それらの日、身重の女たちと乳飲み子を持つ女たちは哀れです。'),
('JPN', '马太福音', 40, 24, 20, 'あなたがたの逃げるのが冬や安息日にならないように祈りなさい。'),
('JPN', '马太福音', 40, 24, 21, 'そのときには、世の始まりから今に至るまでなかったような、また今後も決してないような、大きな苦難があるからです。'),
('JPN', '马太福音', 40, 24, 22, 'もしその日数が少なくされないなら、一人も救われないでしょう。しかし、選ばれた者たちのために、その日数は少なくされます。'),
('JPN', '马太福音', 40, 24, 23, 'そのとき、だれかが『見よ、ここにキリストがいる』とか『そこにいる』とか言っても、信じてはいけません。'),
('JPN', '马太福音', 40, 24, 24, '偽キリストたち、偽預言者たちが現れて、できれば選ばれた者たちをさえ惑わそうと、大きなしるしや不思議を行います。'),
('JPN', '马太福音', 40, 24, 25, 'いいですか。わたしはあなたがたに前もって話しました。'),
('JPN', '马太福音', 40, 24, 26, 'ですから、たとえだれかが『見よ、キリストは荒野にいる』と言っても、出て行ってはいけません。『見よ、奥の部屋にいる』と言っても、信じてはいけません。'),
('JPN', '马太福音', 40, 24, 27, '人の子の到来は、稲妻が東から出て西にひらめくのと同じようにして実現するのです。'),
('JPN', '马太福音', 40, 24, 28, '死体のあるところには、禿鷹が集まります。'),
('JPN', '马太福音', 40, 24, 29, 'そうした苦難の日々の後、ただちに太陽は暗くなり、月は光を放たなくなり、星は天から落ち、天のもろもろの力は揺り動かされます。'),
('JPN', '马太福音', 40, 24, 30, 'そのとき、人の子のしるしが天に現れます。そのとき、地のすべての部族は胸をたたいて悲しみ、人の子が天の雲のうちに、偉大な力と栄光とともに来るのを見るのです。'),
('JPN', '马太福音', 40, 24, 31, '人の子は大きなラッパの響きとともに御使いたちを遣わします。すると御使いたちは、天の果てから果てまで四方から、人の子が選んだ者たちを集めます。'),
('JPN', '马太福音', 40, 24, 32, 'いちじくの木から教訓を学びなさい。枝が柔らかになって葉が出て来ると、夏が近いことが分かります。'),
('JPN', '马太福音', 40, 24, 33, '同じように、これらのことをすべて見たら、あなたがたは人の子が戸口まで近づいていることを知りなさい。'),
('JPN', '马太福音', 40, 24, 34, 'まことに、あなたがたに言います。これらのことがすべて起こるまでは、この時代が過ぎ去ることは決してありません。'),
('JPN', '马太福音', 40, 24, 35, '天地は消え去ります。しかし、わたしのことばは決して消え去ることがありません。'),
('JPN', '马太福音', 40, 24, 36, 'ただし、その日、その時がいつなのかは、だれも知りません。天の御使いたちも子も知りません。ただ父だけが知っておられます。'),
('JPN', '马太福音', 40, 24, 37, '人の子の到来はノアの日と同じように実現するのです。'),
('JPN', '马太福音', 40, 24, 38, '洪水前の日々にはノアが箱舟に入るその日まで、人々は食べたり飲んだり、めとったり嫁いだりしていました。'),
('JPN', '马太福音', 40, 24, 39, '洪水が来て、すべての人をさらってしまうまで、彼らには分かりませんでした。人の子の到来もそのように実現するのです。'),
('JPN', '马太福音', 40, 24, 40, 'そのとき、男が二人畑にいると一人は取られ、一人は残されます。'),
('JPN', '马太福音', 40, 24, 41, '女が二人臼をひいていると一人は取られ、一人は残されます。'),
('JPN', '马太福音', 40, 24, 42, 'ですから、目を覚ましていなさい。あなたがたの主が来られるのがいつの日なのか、あなたがたは知らないのですから。'),
('JPN', '马太福音', 40, 24, 43, '次のことは知っておきなさい。泥棒が夜の何時に来るかを知っていたら、家の主人は目を覚ましているでしょうし、自分の家に穴を開けられることはないでしょう。')
on conflict (version, book, chapter, verse) do nothing;
